/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2013_SEED = {"dse/writing/part-b/2013/Q2":[{"front":"proposal for","meaning":"關於……的建議書","examples":[{"en":"The email is a proposal for a Campus TV programme.","zh":"這封電郵是一份關於校園電視節目的建議書。"},{"en":"A proposal for something is a written suggestion that explains an idea and how it could be carried out.","zh":"proposal for 某事，指一份解釋想法及如何實行的書面建議。"},{"en":"A student may write a proposal for a new school recycling campaign.","zh":"學生可以寫一份關於新校園回收活動的建議書。"},{"en":"A good proposal for a programme should explain the topic, purpose, audience, and plan.","zh":"好的節目建議書應解釋主題、目的、觀眾和計劃。"},{"en":"This phrase is useful when presenting an idea formally before asking for approval.","zh":"這個短語適合在正式提出想法並請求批准時使用。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"Campus TV programme","meaning":"校園電視節目","examples":[{"en":"I would like to produce a 30-minute Campus TV programme.","zh":"我想製作一個三十分鐘的校園電視節目。"},{"en":"A Campus TV programme is a school-based video show made for students, teachers, or the school community.","zh":"Campus TV programme 指為學生、老師或學校社群製作的校本影片節目。"},{"en":"A Campus TV programme may cover school events, interviews, sports, or student opinions.","zh":"校園電視節目可以報道學校活動、訪問、體育或學生意見。"},{"en":"Such a programme can help students learn filming, speaking, planning, and editing.","zh":"這類節目可以幫助學生學習拍攝、說話、規劃和剪接。"},{"en":"A good Campus TV programme should feel relevant to school life, not like a random video.","zh":"好的校園電視節目應與校園生活相關，而不是像隨機影片。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"running Hong Kong together","meaning":"一起跑遍香港","examples":[{"en":"The programme is called “Running Hong Kong Together”.","zh":"這個節目名為「一起跑遍香港」。"},{"en":"Running Hong Kong Together suggests people from different parts of the city joining a shared running event.","zh":"Running Hong Kong Together 暗示來自城市不同地方的人一起參與跑步活動。"},{"en":"A title like Running Hong Kong Together makes the marathon sound communal, not only competitive.","zh":"像「一起跑遍香港」這樣的題目，令馬拉松聽起來有社群感，而不只是競爭。"},{"en":"The phrase connects sport with the city because runners move through familiar public spaces.","zh":"這個短語把運動與城市連接起來，因為跑手穿過熟悉的公共空間。"},{"en":"It also suggests unity, effort, and shared experience.","zh":"它也暗示團結、努力和共同經歷。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"thank you for inviting me to","meaning":"感謝你邀請我……","examples":[{"en":"Thank you for inviting me to produce a 30-minute Campus TV programme.","zh":"感謝你邀請我製作一個三十分鐘的校園電視節目。"},{"en":"Thank you for inviting me to is a polite way to show gratitude for being given a role or opportunity.","zh":"thank you for inviting me to 是表示感謝對方給予角色或機會的禮貌說法。"},{"en":"Thank you for inviting me to speak at the English Society meeting.","zh":"感謝你邀請我在英文學會會議上發言。"},{"en":"This phrase is useful at the beginning of formal emails because it sounds respectful.","zh":"這個短語適合用於正式電郵開首，因為語氣尊重。"},{"en":"It also shows that the writer values the opportunity before explaining their plan.","zh":"它也顯示作者在解釋計劃前重視這次機會。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"produce a 30-minute programme","meaning":"製作一個30分鐘節目","examples":[{"en":"I was invited to produce a 30-minute Campus TV programme.","zh":"我獲邀製作一個三十分鐘的校園電視節目。"},{"en":"To produce a 30-minute programme means to plan, film, organise, and complete a show lasting half an hour.","zh":"produce a 30-minute programme 指計劃、拍攝、組織並完成一個半小時節目。"},{"en":"A media club may produce a 30-minute programme about school life before Speech Day.","zh":"媒體學會可能在 Speech Day 前製作一個關於校園生活的三十分鐘節目。"},{"en":"Producing a programme requires ideas, interviews, filming, editing, and timing.","zh":"製作節目需要構思、訪問、拍攝、剪接和時間控制。"},{"en":"A 30-minute programme needs enough content to be interesting but not too crowded.","zh":"三十分鐘節目需要足夠內容保持有趣，但不能過於擁擠。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"local sporting event","meaning":"本地體育盛事","examples":[{"en":"The programme will cover a local sporting event.","zh":"這個節目會報道一項本地體育盛事。"},{"en":"A local sporting event is a sports activity or competition held in the local community or city.","zh":"local sporting event 指在本地社區或城市舉行的體育活動或比賽。"},{"en":"A school programme may cover a local sporting event such as a charity run or swimming gala.","zh":"學校節目可以報道慈善跑或游泳比賽等本地體育活動。"},{"en":"Local sporting events are useful topics because students may recognise the places and people involved.","zh":"本地體育盛事是有用題材，因為學生可能認得相關地方和人物。"},{"en":"Covering a local event can make sport feel closer to students’ daily lives.","zh":"報道本地活動可以令運動感覺更貼近學生日常生活。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"given that","meaning":"鑑於","examples":[{"en":"Given that many students see sport mainly as PE lessons, I propose covering the marathon.","zh":"鑑於許多學生主要把運動視為體育課，我建議報道馬拉松。"},{"en":"Given that means considering the fact that something is true.","zh":"given that 指考慮到某事是真實情況。"},{"en":"Given that many students dislike long lectures, the programme should include interviews and challenges.","zh":"鑑於許多學生不喜歡長篇說教，節目應包括訪問和挑戰。"},{"en":"Writers use given that to explain why their proposal fits the situation.","zh":"作者使用 given that 來解釋為何建議適合當前情況。"},{"en":"Given that students already know PE, a marathon story can widen their understanding of sport.","zh":"鑑於學生已認識體育課，馬拉松故事可以擴闊他們對運動的理解。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"see sport mainly as","meaning":"主要把運動視為……","examples":[{"en":"Many students see sport mainly as PE lessons or fitness tests.","zh":"許多學生主要把運動視為體育課或體能測試。"},{"en":"To see sport mainly as something means to understand sport mostly through that single idea.","zh":"see sport mainly as something 指主要透過某個單一想法理解運動。"},{"en":"Some students see music mainly as examinations, not as enjoyment or expression.","zh":"有些學生主要把音樂視為考試，而不是享受或表達。"},{"en":"Seeing sport only as school tests may make students miss its wider social meaning.","zh":"只把運動視為學校測試，可能令學生錯過其更廣泛的社會意義。"},{"en":"The programme aims to help students see sport as community, discipline, and personal growth.","zh":"這個節目旨在幫助學生把運動視為社群、紀律和個人成長。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"PE lessons","meaning":"體育課","examples":[{"en":"Many students see sport mainly as PE lessons.","zh":"許多學生主要把運動視為體育課。"},{"en":"PE lessons are school classes where students learn and practise physical education.","zh":"PE lessons 指學生學習和練習體育教育的學校課堂。"},{"en":"PE lessons may include running, ball games, stretching, fitness training, and teamwork.","zh":"體育課可以包括跑步、球類運動、伸展、體能訓練和團隊合作。"},{"en":"Some students connect sport only with PE lessons because that is their main experience of exercise.","zh":"有些學生只把運動與體育課連繫起來，因為那是他們主要的運動經驗。"},{"en":"The programme can show that sport also exists in public events and community life.","zh":"這個節目可以顯示運動也存在於公共活動和社區生活中。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"fitness tests","meaning":"體能測試","examples":[{"en":"Some students associate sport with fitness tests.","zh":"有些學生把運動與體能測試聯繫起來。"},{"en":"Fitness tests are assessments that measure physical ability, such as speed, strength, or endurance.","zh":"fitness tests 指測量速度、力量或耐力等身體能力的評估。"},{"en":"A student may feel nervous before fitness tests if they dislike running.","zh":"如果學生不喜歡跑步，體能測試前可能會緊張。"},{"en":"When students see sport only as fitness tests, sport may feel stressful rather than enjoyable.","zh":"當學生只把運動視為體能測試時，運動可能感覺有壓力，而不是有趣。"},{"en":"A marathon programme can show that sport is also about stories, effort, and support.","zh":"馬拉松節目可以顯示運動也關於故事、努力和支持。"}],"source":"2013 Q2.pdf","sourcePage":1},{"front":"elite athletes","meaning":"精英運動員","examples":[{"en":"Sport is sometimes seen as competition between elite athletes.","zh":"運動有時被視為精英運動員之間的競爭。"},{"en":"Elite athletes are sportspeople who compete at a very high level.","zh":"elite athletes 指在非常高水平比賽的運動員。"},{"en":"Many students watch elite athletes on television but do not see themselves as part of sport.","zh":"許多學生在電視上觀看精英運動員，但不覺得自己也是運動的一部分。"},{"en":"Sport becomes more relatable when programmes also show ordinary participants.","zh":"當節目也展示普通參加者時，運動會變得更容易產生共鳴。"},{"en":"The marathon includes elite athletes, but it also includes office workers, students, and volunteers.","zh":"馬拉松包括精英運動員，但也包括上班族、學生和義工。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"propose covering","meaning":"建議報道","examples":[{"en":"I would like to propose covering the Hong Kong Marathon.","zh":"我想建議報道香港馬拉松。"},{"en":"To propose covering something means to suggest reporting on or making a programme about it.","zh":"propose covering something 指建議報道某事或製作關於它的節目。"},{"en":"A student reporter may propose covering the school music festival.","zh":"學生記者可能建議報道學校音樂節。"},{"en":"This phrase is useful when explaining what topic a programme should focus on.","zh":"這個短語適合用來解釋節目應聚焦甚麼題材。"},{"en":"Proposing a topic should include reasons why it would interest the audience.","zh":"建議一個題材時，應包括它為何能吸引觀眾的理由。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"Hong Kong Marathon","meaning":"香港馬拉松","examples":[{"en":"The programme would cover the Hong Kong Marathon.","zh":"這個節目會報道香港馬拉松。"},{"en":"The Hong Kong Marathon is a running event connected with the city’s roads, runners, and supporters.","zh":"Hong Kong Marathon 指與香港道路、跑手和支持者相連的跑步活動。"},{"en":"A programme about the Hong Kong Marathon can show both sport and city life.","zh":"關於香港馬拉松的節目可以同時展示運動和城市生活。"},{"en":"The event is useful for Campus TV because students may recognise the streets and atmosphere.","zh":"這項活動適合校園電視，因為學生可能認得相關街道和氣氛。"},{"en":"It can be presented as a story of effort, community, and public participation.","zh":"它可以被呈現為努力、社群和公眾參與的故事。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"not just a race","meaning":"不只是一場比賽","examples":[{"en":"The Hong Kong Marathon is not just a race.","zh":"香港馬拉松不只是一場比賽。"},{"en":"Not just a race means the event has meaning beyond deciding who runs fastest.","zh":"not just a race 指活動的意義不只是決定誰跑得最快。"},{"en":"A school sports day is not just a race if it also builds teamwork and confidence.","zh":"如果學校運動日也建立團隊合作和信心，它就不只是一場比賽。"},{"en":"This phrase helps readers look beyond the surface of competition.","zh":"這個短語幫助讀者看見競爭表面以外的東西。"},{"en":"The marathon is also about preparation, courage, volunteering, and community spirit.","zh":"馬拉松也關於準備、勇氣、義工服務和社群精神。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"rather","meaning":"而是","examples":[{"en":"Rather, it is a city-wide story about discipline and community.","zh":"而是，它是一個關於紀律和社群的全城故事。"},{"en":"Rather is used to correct or replace a previous idea with a more accurate one.","zh":"rather 用來修正或取代前一個想法，並提出更準確的說法。"},{"en":"The programme is not only about winners; rather, it is about why ordinary people run.","zh":"這個節目不只是關於勝利者；而是關於為甚麼普通人跑步。"},{"en":"Writers use rather when moving from a narrow view to a fuller explanation.","zh":"作者由狹窄看法轉向更完整解釋時，會使用 rather。"},{"en":"Here, rather turns the marathon from a simple race into a city story.","zh":"在這裏，rather 把馬拉松由簡單比賽變成城市故事。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"city-wide story","meaning":"全城故事","examples":[{"en":"The marathon is a city-wide story about discipline, courage, and community.","zh":"馬拉松是一個關於紀律、勇氣和社群精神的全城故事。"},{"en":"A city-wide story is a story involving many people, places, and feelings across a whole city.","zh":"city-wide story 指涉及整個城市許多人、地方和感受的故事。"},{"en":"A charity walk can become a city-wide story when families, schools, and volunteers join together.","zh":"當家庭、學校和義工一起參與時，慈善步行可以成為全城故事。"},{"en":"The phrase suggests the event belongs to the public, not only to athletes.","zh":"這個短語暗示活動屬於公眾，而不只是屬於運動員。"},{"en":"A city-wide story helps viewers see familiar streets in a new way.","zh":"全城故事幫助觀眾以新方式看見熟悉街道。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"discipline, courage and community","meaning":"紀律、勇氣和社群精神","examples":[{"en":"The marathon shows discipline, courage, and community.","zh":"馬拉松展現紀律、勇氣和社群精神。"},{"en":"Discipline, courage and community mean self-control, bravery, and people supporting one another.","zh":"discipline, courage and community 指自律、勇敢，以及人們互相支持。"},{"en":"A runner shows discipline by training regularly before race day.","zh":"跑手在比賽日前定期訓練，就是展現紀律。"},{"en":"Courage appears when someone keeps going despite tiredness or fear.","zh":"當有人即使疲累或害怕仍繼續時，勇氣就出現。"},{"en":"Community appears when volunteers, supporters, and runners share the event together.","zh":"當義工、支持者和跑手共同參與活動時，社群精神就出現。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"my aim is to","meaning":"我的目標是","examples":[{"en":"My aim is to show how an ordinary street becomes a stage.","zh":"我的目標是展示一條普通街道如何成為舞台。"},{"en":"My aim is to means my purpose or goal is to do something.","zh":"my aim is to 指我的目的或目標是做某事。"},{"en":"My aim is to help students understand that exercise can be part of daily life.","zh":"我的目標是幫助學生明白運動可以成為日常生活的一部分。"},{"en":"This phrase is useful in proposals because it clearly states the writer’s intention.","zh":"這個短語在建議書中很有用，因為它清楚說明作者意圖。"},{"en":"A clear aim helps the audience understand what the programme is trying to achieve.","zh":"清楚目標幫助觀眾理解節目想達成甚麼。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"ordinary Hong Kong street","meaning":"普通香港街道","examples":[{"en":"An ordinary Hong Kong street can become a stage for runners.","zh":"一條普通香港街道可以成為跑手的舞台。"},{"en":"An ordinary Hong Kong street is a familiar local road used for daily transport, shopping, and work.","zh":"ordinary Hong Kong street 指用於日常交通、購物和工作的熟悉本地道路。"},{"en":"Students may pass an ordinary Hong Kong street every day without noticing it.","zh":"學生可能每天經過一條普通香港街道，卻沒有特別留意。"},{"en":"During a marathon, ordinary streets can become meaningful because people gather and cheer there.","zh":"在馬拉松期間，普通街道可以因人們聚集和打氣而變得有意義。"},{"en":"The phrase helps connect the event with everyday city life.","zh":"這個短語幫助把活動與日常城市生活連接起來。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"for one morning","meaning":"在一個早上","examples":[{"en":"For one morning, the street becomes a shared stage.","zh":"在一個早上，街道成為共享舞台。"},{"en":"For one morning means during one particular morning only.","zh":"for one morning 指只在某一個特定早上期間。"},{"en":"For one morning, the school playground became a market for the charity fair.","zh":"在一個早上，學校操場變成慈善市集。"},{"en":"This phrase shows that an ordinary place can temporarily change its meaning.","zh":"這個短語顯示普通地方可以暫時改變意義。"},{"en":"The marathon transforms streets for a short time, but the memory may last longer.","zh":"馬拉松短暫改變街道，但記憶可能持續更久。"}],"source":"2013 Q2.pdf","sourcePage":2},{"front":"become a stage","meaning":"成為舞台","examples":[{"en":"The street can become a stage for professional runners and supporters.","zh":"街道可以成為專業跑手和支持者的舞台。"},{"en":"To become a stage means to become a place where action, attention, and performance happen.","zh":"become a stage 指成為行動、注意力和表現發生的地方。"},{"en":"A classroom can become a stage when students perform a short drama.","zh":"當學生表演短劇時，課室可以成為舞台。"},{"en":"Streets become stages during public events because people watch, move, and participate there.","zh":"公共活動期間，街道會成為舞台，因為人們在那裏觀看、移動和參與。"},{"en":"The phrase makes the city feel active and dramatic.","zh":"這個短語令城市感覺活躍而富戲劇性。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"professional runners","meaning":"專業跑手","examples":[{"en":"Professional runners move towards the same finishing line.","zh":"專業跑手朝着同一條終點線前進。"},{"en":"Professional runners are athletes who train and compete seriously, often as part of their career.","zh":"professional runners 指認真訓練和比賽，並常以此作為職業一部分的運動員。"},{"en":"Professional runners usually follow strict training plans and racing strategies.","zh":"專業跑手通常跟隨嚴格訓練計劃和比賽策略。"},{"en":"They can inspire students by showing what long-term discipline looks like.","zh":"他們可以展示長期紀律的樣子，從而啟發學生。"},{"en":"In the marathon, professional runners share the road with ordinary participants.","zh":"在馬拉松中，專業跑手與普通參加者共享道路。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"office workers","meaning":"上班族","examples":[{"en":"Office workers also take part in the marathon.","zh":"上班族也參加馬拉松。"},{"en":"Office workers are people who usually work in offices, often at desks or computers.","zh":"office workers 指通常在辦公室工作，常坐在桌前或使用電腦的人。"},{"en":"An office worker may train after work to prepare for a weekend race.","zh":"上班族可能下班後訓練，為週末比賽作準備。"},{"en":"Showing office workers in the marathon helps students see that sport is not only for professionals.","zh":"在馬拉松中展示上班族，能幫助學生看見運動不只屬於專業人士。"},{"en":"It also shows how ordinary people can build discipline outside work.","zh":"它也顯示普通人如何在工作以外建立紀律。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"volunteers and supporters","meaning":"義工和支持者","examples":[{"en":"Volunteers and supporters help create the atmosphere of the event.","zh":"義工和支持者幫助營造活動氣氛。"},{"en":"Volunteers and supporters are people who help with the event or cheer for participants.","zh":"volunteers and supporters 指協助活動或為參加者打氣的人。"},{"en":"Volunteers may hand out water, while supporters clap and shout encouragement.","zh":"義工可能派發食水，而支持者會拍手和大聲鼓勵。"},{"en":"Their presence makes a race feel warmer and more human.","zh":"他們的出現令比賽感覺更溫暖、更有人情味。"},{"en":"A marathon depends not only on runners, but also on the people around them.","zh":"馬拉松不只依靠跑手，也依靠他們身邊的人。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"move towards","meaning":"朝着……前進","examples":[{"en":"All participants move towards the same finishing line.","zh":"所有參加者朝着同一條終點線前進。"},{"en":"To move towards something means to go in its direction, physically or as a goal.","zh":"move towards something 指向某方向前進，或朝某目標努力。"},{"en":"Students move towards better English when they read a little every day.","zh":"學生每天閱讀一點，就是朝着更好英文前進。"},{"en":"In a race, moving towards the finishing line shows effort and progress.","zh":"在比賽中，朝着終點線前進顯示努力和進展。"},{"en":"This phrase can describe both physical movement and personal improvement.","zh":"這個短語可以描述身體移動，也可以描述個人成長。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"finishing line","meaning":"終點線","examples":[{"en":"Everyone moves towards the same finishing line.","zh":"每個人都朝着同一條終點線前進。"},{"en":"A finishing line is the point where a race ends.","zh":"finishing line 指比賽結束的位置。"},{"en":"Runners often feel excited when they finally see the finishing line.","zh":"跑手終於看見終點線時，常會感到興奮。"},{"en":"The finishing line symbolises completion after long effort.","zh":"終點線象徵長久努力後的完成。"},{"en":"In a programme, the finishing line can stand for discipline, hope, and achievement.","zh":"在節目中，終點線可以代表紀律、希望和成就。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"in short","meaning":"簡而言之","examples":[{"en":"In short, I hope the programme will encourage schoolmates to see sport differently.","zh":"簡而言之，我希望這個節目能鼓勵同學以不同方式看待運動。"},{"en":"In short means to summarise the main point briefly.","zh":"in short 指簡短總結主要重點。"},{"en":"In short, the event is about people, not only medals.","zh":"簡而言之，這項活動關乎人，而不只是獎牌。"},{"en":"Writers use this phrase to bring several ideas together clearly.","zh":"作者使用這個短語，清楚整合幾個想法。"},{"en":"It helps the audience remember the central purpose of the programme.","zh":"它幫助觀眾記住節目的核心目的。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"encourage schoolmates to","meaning":"鼓勵同學……","examples":[{"en":"The programme will encourage schoolmates to see sport as part of life.","zh":"這個節目會鼓勵同學把運動視為生活的一部分。"},{"en":"To encourage schoolmates to do something means to help fellow students feel willing to do or think about it.","zh":"encourage schoolmates to do something 指幫助同學願意做某事或思考某事。"},{"en":"A video about reading may encourage schoolmates to borrow books from the library.","zh":"關於閱讀的影片可能鼓勵同學到圖書館借書。"},{"en":"Programmes encourage students best when they use familiar examples.","zh":"節目使用熟悉例子時，最能鼓勵學生。"},{"en":"This programme aims to encourage schoolmates to connect sport with their own lives.","zh":"這個節目旨在鼓勵同學把運動與自己的生活連接起來。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"close to their own lives","meaning":"貼近他們自己的生活","examples":[{"en":"Sport can be something close to students’ own lives.","zh":"運動可以是貼近學生自己生活的東西。"},{"en":"Close to their own lives means related to their real experiences, routines, and concerns.","zh":"close to their own lives 指與他們的真實經驗、日常和關注有關。"},{"en":"A story about school stress feels close to students’ lives because they face it daily.","zh":"關於學業壓力的故事貼近學生生活，因為他們每天都面對。"},{"en":"Sport feels closer when students see classmates, teachers, and local streets involved.","zh":"當學生看見同學、老師和本地街道參與其中時，運動會感覺更貼近。"},{"en":"A programme becomes more meaningful when the topic feels close, not distant.","zh":"當主題感覺貼近而不是遙遠時，節目會更有意義。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"rather than","meaning":"而不是","examples":[{"en":"Sport should feel close to students’ lives rather than distant on television.","zh":"運動應感覺貼近學生生活，而不是在電視上遙不可及。"},{"en":"Rather than is used to show contrast between two choices or ideas.","zh":"rather than 用來對比兩個選擇或想法。"},{"en":"The programme should inspire students rather than simply list race results.","zh":"這個節目應啟發學生，而不是單純列出比賽結果。"},{"en":"This phrase helps explain what the writer prefers and what they reject.","zh":"這個短語幫助解釋作者偏好的東西和拒絕的東西。"},{"en":"Here, sport should be presented as lived experience rather than remote entertainment.","zh":"在這裏，運動應被呈現為生活經驗，而不是遙遠娛樂。"}],"source":"2013 Q2.pdf","sourcePage":3},{"front":"distant on television","meaning":"在電視上遙不可及","examples":[{"en":"Sport should not feel distant on television.","zh":"運動不應感覺像在電視上遙不可及。"},{"en":"Distant on television means seeming far away, unrelated, or only for people on screen.","zh":"distant on television 指看起來遙遠、無關，或只屬於螢幕上的人。"},{"en":"Elite sport can feel distant on television if students never see ordinary participants.","zh":"如果學生從未看見普通參加者，精英運動可能在電視上顯得遙不可及。"},{"en":"A local story can make televised sport feel more human and reachable.","zh":"本地故事可以令電視上的運動更有人情味、更可接近。"},{"en":"The programme should reduce this distance by showing familiar places and people.","zh":"這個節目應透過展示熟悉地方和人物來減少這種距離。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"open with","meaning":"以……開場","examples":[{"en":"The programme would open with a two-minute montage.","zh":"這個節目會以兩分鐘蒙太奇片段開場。"},{"en":"To open with something means to begin with that part or scene.","zh":"open with something 指以某部分或場景開始。"},{"en":"A school news video may open with students arriving at the gate in the morning.","zh":"校園新聞影片可能以學生早上到達校門開場。"},{"en":"A strong opening can catch attention before the main explanation begins.","zh":"有力開場可以在主要解釋開始前吸引注意。"},{"en":"Opening with a montage can show atmosphere quickly and visually.","zh":"以蒙太奇片段開場，可以快速而視覺化地展示氣氛。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"two-minute montage","meaning":"兩分鐘蒙太奇片段","examples":[{"en":"The programme would open with a two-minute montage called “Before the Starting Gun”.","zh":"這個節目會以名為「起步槍聲響起之前」的兩分鐘蒙太奇片段開場。"},{"en":"A two-minute montage is a short sequence of different shots edited together for two minutes.","zh":"two-minute montage 指把不同鏡頭剪接在一起、長約兩分鐘的短片段。"},{"en":"A montage may show runners stretching, volunteers preparing, and crowds gathering.","zh":"蒙太奇片段可以展示跑手伸展、義工準備和人群聚集。"},{"en":"Montages are useful because they create mood without needing long explanation.","zh":"蒙太奇很有用，因為它不用長篇解釋也能營造氣氛。"},{"en":"A two-minute montage can introduce the scale and energy of the marathon.","zh":"兩分鐘蒙太奇片段可以介紹馬拉松的規模和能量。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"before the starting gun","meaning":"起步槍聲響起之前","examples":[{"en":"The opening montage is called “Before the Starting Gun”.","zh":"開場蒙太奇名為「起步槍聲響起之前」。"},{"en":"Before the starting gun means the moments before a race officially begins.","zh":"before the starting gun 指比賽正式開始前的時刻。"},{"en":"Before the starting gun, runners may stretch, breathe deeply, and check their shoelaces.","zh":"起步槍聲響起之前，跑手可能伸展、深呼吸和檢查鞋帶。"},{"en":"This phrase creates suspense because viewers know action is about to begin.","zh":"這個短語製造懸念，因為觀眾知道行動即將開始。"},{"en":"It focuses on preparation, nerves, and expectation before the race starts.","zh":"它聚焦於比賽開始前的準備、緊張和期待。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"stretch under the city lights","meaning":"在城市燈光下伸展","examples":[{"en":"We would show runners stretching under the city lights.","zh":"我們會展示跑手在城市燈光下伸展。"},{"en":"Stretch under the city lights means do warm-up movements while surrounded by urban night or early morning lighting.","zh":"stretch under the city lights 指在城市夜晚或清晨燈光下做熱身伸展動作。"},{"en":"Runners may stretch under the city lights before a dawn race begins.","zh":"黎明比賽開始前，跑手可能在城市燈光下伸展。"},{"en":"The image connects physical preparation with the atmosphere of Hong Kong streets.","zh":"這個畫面把身體準備與香港街道氣氛連接起來。"},{"en":"It can make the opening scene feel calm, focused, and cinematic.","zh":"它可以令開場場面感覺平靜、專注而有電影感。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"hand out water","meaning":"派發食水","examples":[{"en":"Volunteers would be shown handing out water.","zh":"節目會展示義工派發食水。"},{"en":"To hand out water means to give bottles or cups of water to people one by one.","zh":"hand out water 指逐一把水樽或水杯分發給人。"},{"en":"At a sports day, students may hand out water to runners after each race.","zh":"在運動日，學生可能在每場比賽後派發食水給跑手。"},{"en":"Water stations support participants because running can make people thirsty and tired.","zh":"水站支援參加者，因為跑步會令人口渴和疲倦。"},{"en":"Showing volunteers handing out water highlights the care behind the event.","zh":"展示義工派發食水，突顯活動背後的照顧。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"road arrangements","meaning":"道路安排","examples":[{"en":"Police officers would prepare road arrangements.","zh":"警員會準備道路安排。"},{"en":"Road arrangements are plans for how traffic, roads, and public movement will be managed.","zh":"road arrangements 指管理交通、道路和公眾通行的計劃。"},{"en":"A parade needs road arrangements so cars and pedestrians can move safely.","zh":"巡遊需要道路安排，讓車輛和行人能安全移動。"},{"en":"Marathon road arrangements may include closures, barriers, and route signs.","zh":"馬拉松道路安排可能包括封路、欄杆和路線指示。"},{"en":"These arrangements show that a sporting event also requires careful city planning.","zh":"這些安排顯示體育活動也需要仔細城市規劃。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"find the best places to cheer","meaning":"找最佳位置打氣","examples":[{"en":"Spectators would find the best places to cheer.","zh":"觀眾會找最佳位置打氣。"},{"en":"To find the best places to cheer means to choose good spots for encouraging runners.","zh":"find the best places to cheer 指選擇鼓勵跑手的好位置。"},{"en":"Families may find the best places to cheer near the final kilometre of a race.","zh":"家人可能在比賽最後一公里附近找最佳位置打氣。"},{"en":"Supporters choose good locations so runners can hear and see them clearly.","zh":"支持者選擇好位置，好讓跑手能清楚聽見和看見他們。"},{"en":"Cheering spots matter because encouragement can help tired runners continue.","zh":"打氣位置很重要，因為鼓勵可以幫助疲倦跑手繼續。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"instead of giving","meaning":"而不是作出……","examples":[{"en":"Instead of giving a dry introduction, the host would ask a question.","zh":"主持人會提問，而不是作出枯燥的介紹。"},{"en":"Instead of giving means choosing not to provide one thing and doing something else instead.","zh":"instead of giving 指不提供某種內容，而選擇做另一件事。"},{"en":"Instead of giving a long lecture, the teacher used a short video to begin the lesson.","zh":"老師用短片開始課堂，而不是作出長篇講課。"},{"en":"This phrase helps contrast a less engaging method with a better method.","zh":"這個短語幫助對比較不吸引的方法和較好的方法。"},{"en":"Asking a question can make viewers curious more quickly than giving facts.","zh":"提問比直接給資料更快令觀眾好奇。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"dry introduction","meaning":"枯燥的介紹","examples":[{"en":"The host would avoid giving a dry introduction.","zh":"主持人會避免作出枯燥的介紹。"},{"en":"A dry introduction is an opening that feels dull because it only gives plain facts.","zh":"dry introduction 指只提供平淡資料、令人覺得沉悶的開場。"},{"en":"A dry introduction may make viewers lose interest before the programme begins properly.","zh":"枯燥的介紹可能令觀眾在節目正式開始前已失去興趣。"},{"en":"A better opening uses images, questions, sounds, or human stories.","zh":"較好的開場會使用影像、問題、聲音或人情故事。"},{"en":"Avoiding a dry introduction helps the programme feel lively from the start.","zh":"避免枯燥介紹能令節目從一開始就有活力。"}],"source":"2013 Q2.pdf","sourcePage":4},{"front":"lead naturally into","meaning":"自然引入","examples":[{"en":"That question would lead naturally into the first main section.","zh":"那個問題會自然引入第一個主要部分。"},{"en":"To lead naturally into something means to move smoothly and logically into the next part.","zh":"lead naturally into something 指順暢而合邏輯地進入下一部分。"},{"en":"A question about daily habits can lead naturally into a discussion of exercise.","zh":"關於日常習慣的問題，可以自然引入關於運動的討論。"},{"en":"Good programme structure avoids sudden jumps between sections.","zh":"好的節目結構會避免部分之間突然跳接。"},{"en":"A natural transition helps viewers follow the story without confusion.","zh":"自然過渡幫助觀眾不混亂地跟隨故事。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"first main section","meaning":"第一個主要部分","examples":[{"en":"The first main section would introduce the event and the city.","zh":"第一個主要部分會介紹活動與城市。"},{"en":"The first main section is the first major part of a programme after the opening.","zh":"first main section 指開場後節目的第一個重要部分。"},{"en":"In a documentary, the first main section may explain the background of the topic.","zh":"在紀錄片中，第一個主要部分可能解釋主題背景。"},{"en":"A clear first section helps viewers understand what the programme is about.","zh":"清楚的第一部分幫助觀眾理解節目關於甚麼。"},{"en":"This section should give enough context before moving to interviews.","zh":"這部分應提供足夠背景，再進入訪問。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"the event and the city","meaning":"活動與城市","examples":[{"en":"The first section is called “The Event and the City”.","zh":"第一部分名為「活動與城市」。"},{"en":"The event and the city means the programme will show both the sporting activity and the urban setting around it.","zh":"the event and the city 指節目會同時展示體育活動及其周圍的城市背景。"},{"en":"A marathon story needs both the race and the streets that shape it.","zh":"馬拉松故事需要比賽，也需要塑造它的街道。"},{"en":"Connecting the event and the city helps viewers see sport as part of public life.","zh":"把活動與城市連接起來，幫助觀眾把運動視為公共生活的一部分。"},{"en":"This title suggests that Hong Kong itself is part of the story.","zh":"這個標題暗示香港本身也是故事的一部分。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"briefly introduce","meaning":"簡略介紹","examples":[{"en":"We would briefly introduce the marathon.","zh":"我們會簡略介紹馬拉松。"},{"en":"To briefly introduce something means to explain it shortly and clearly.","zh":"briefly introduce something 指簡短而清楚地解釋某事。"},{"en":"A host may briefly introduce a guest before the interview begins.","zh":"主持人可能在訪問開始前簡略介紹嘉賓。"},{"en":"Brief introductions are useful when viewers need basic information but not too much detail.","zh":"當觀眾需要基本資訊但不需要太多細節時，簡略介紹很有用。"},{"en":"The programme should briefly introduce the marathon before focusing on people’s stories.","zh":"節目應先簡略介紹馬拉松，再聚焦於人物故事。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"different kinds of runners","meaning":"不同類型的跑手","examples":[{"en":"The section would introduce the different kinds of runners who join it.","zh":"這部分會介紹參與其中的不同類型跑手。"},{"en":"Different kinds of runners means runners with different backgrounds, abilities, purposes, and stories.","zh":"different kinds of runners 指有不同背景、能力、目的和故事的跑手。"},{"en":"A marathon may include professional runners, students, parents, office workers, and charity runners.","zh":"馬拉松可能包括專業跑手、學生、家長、上班族和慈善跑手。"},{"en":"Showing different runners helps viewers understand that sport is not only for one type of person.","zh":"展示不同跑手幫助觀眾理解運動不只屬於一類人。"},{"en":"This variety makes the programme more relatable to schoolmates.","zh":"這種多樣性令節目更容易引起同學共鳴。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"turn familiar roads into","meaning":"把熟悉道路變成……","examples":[{"en":"The event turns familiar roads into a shared sporting arena.","zh":"這項活動把熟悉道路變成共享的體育舞台。"},{"en":"To turn familiar roads into something means to change ordinary streets into a place with a new purpose.","zh":"turn familiar roads into something 指把普通街道改變成有新用途的地方。"},{"en":"A parade can turn familiar roads into a public celebration space.","zh":"巡遊可以把熟悉道路變成公共慶祝空間。"},{"en":"During a marathon, roads used for traffic become places for effort and cheering.","zh":"馬拉松期間，用於交通的道路變成努力和打氣的地方。"},{"en":"This phrase shows how an event can transform everyday city spaces.","zh":"這個短語顯示活動如何改變日常城市空間。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"shared sporting arena","meaning":"共享的體育舞台","examples":[{"en":"The marathon turns familiar roads into a shared sporting arena.","zh":"馬拉松把熟悉道路變成共享的體育舞台。"},{"en":"A shared sporting arena is a space where many people take part in or support sport together.","zh":"shared sporting arena 指許多人一起參與或支持運動的空間。"},{"en":"A school playground becomes a shared sporting arena during Sports Day.","zh":"在運動日，學校操場會變成共享的體育舞台。"},{"en":"The phrase suggests that public roads can become places of common energy and participation.","zh":"這個短語暗示公共道路可以成為共同能量和參與的地方。"},{"en":"It helps viewers see the marathon as a community event, not only a race route.","zh":"它幫助觀眾把馬拉松視為社區活動，而不只是賽道。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"take…for example","meaning":"以……為例","examples":[{"en":"Take Causeway Bay, Tsim Sha Tsui, or the harbourfront, for example.","zh":"以銅鑼灣、尖沙咀或海濱為例。"},{"en":"Take…for example is used to introduce specific cases that support a general point.","zh":"take…for example 用來引入支持一般觀點的具體例子。"},{"en":"Take a school playground, for example: it can be used for sport, ceremonies, and fairs.","zh":"以學校操場為例：它可以用於運動、典禮和市集。"},{"en":"This phrase helps readers imagine the idea through real places or people.","zh":"這個短語幫助讀者透過真實地方或人物想像想法。"},{"en":"In the programme, examples of familiar locations make the city story clearer.","zh":"在節目中，熟悉地點的例子令城市故事更清楚。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"harbourfront","meaning":"海濱","examples":[{"en":"The harbourfront becomes part of the marathon route.","zh":"海濱成為馬拉松路線的一部分。"},{"en":"The harbourfront is the area beside a harbour, often with paths, views, and public space.","zh":"harbourfront 指海港旁邊的地區，常有步道、景觀和公共空間。"},{"en":"People may walk along the harbourfront to enjoy fresh air and city views.","zh":"人們可能沿着海濱散步，享受新鮮空氣和城市景色。"},{"en":"In a marathon, the harbourfront can provide a dramatic and recognisable setting.","zh":"在馬拉松中，海濱可以提供富戲劇性而容易辨認的背景。"},{"en":"Showing the harbourfront connects the race with Hong Kong’s urban scenery.","zh":"展示海濱把比賽與香港城市景色連接起來。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"pass these places for","meaning":"為了……而經過這些地方","examples":[{"en":"Students usually pass these places for shopping or transport.","zh":"學生通常為了購物或交通而經過這些地方。"},{"en":"Pass these places for something means go through or near these places for a particular purpose.","zh":"pass these places for something 指為了某個目的而經過或接近這些地方。"},{"en":"Students may pass the MTR station for school every morning.","zh":"學生每天早上可能為了上學而經過港鐵站。"},{"en":"Familiar places can feel different when people pass them for sport instead of daily errands.","zh":"當人們為了運動而不是日常瑣事經過熟悉地方時，感覺會不同。"},{"en":"This phrase helps compare ordinary use with special event use.","zh":"這個短語幫助比較普通用途與特別活動用途。"}],"source":"2013 Q2.pdf","sourcePage":5},{"front":"become symbols of","meaning":"成為……的象徵","examples":[{"en":"During the marathon, these places become symbols of endurance and public spirit.","zh":"在馬拉松期間，這些地方成為耐力和公共精神的象徵。"},{"en":"To become symbols of something means to represent a larger idea or value.","zh":"become symbols of something 指代表更大的想法或價值。"},{"en":"A school gate can become a symbol of new beginnings on the first day of term.","zh":"在開學第一天，校門可以成為新開始的象徵。"},{"en":"Places become symbolic when important actions or memories happen there.","zh":"當重要行動或記憶在某地發生時，地方就會變得有象徵意義。"},{"en":"Marathon streets can symbolise effort because runners struggle and continue there.","zh":"馬拉松街道可以象徵努力，因為跑手在那裏掙扎並繼續。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"endurance","meaning":"耐力","examples":[{"en":"The marathon is a symbol of endurance.","zh":"馬拉松是耐力的象徵。"},{"en":"Endurance is the ability to continue for a long time despite tiredness or difficulty.","zh":"endurance 指即使疲倦或困難，仍能長時間繼續的能力。"},{"en":"Long-distance running builds endurance because the body learns to keep going.","zh":"長跑建立耐力，因為身體學會持續下去。"},{"en":"Students also need endurance when preparing for long exams or projects.","zh":"學生準備長考試或專題時也需要耐力。"},{"en":"The marathon shows endurance because success depends on lasting effort, not only speed.","zh":"馬拉松展示耐力，因為成功取決於持續努力，而不只是速度。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"public spirit","meaning":"公民精神；公共精神","examples":[{"en":"The marathon can show public spirit.","zh":"馬拉松可以展示公民精神。"},{"en":"Public spirit means people caring about and supporting something shared by the community.","zh":"public spirit 指人們關心並支持社區共同擁有的事情。"},{"en":"Volunteers show public spirit when they help at a charity event without payment.","zh":"義工無償協助慈善活動時，就是展示公民精神。"},{"en":"Public spirit appears when strangers cheer for runners they do not know.","zh":"當陌生人為不認識的跑手打氣時，公共精神就出現。"},{"en":"The marathon shows that sport can bring people together in a public space.","zh":"馬拉松顯示運動可以把人聚集在公共空間中。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"lasting around ten minutes","meaning":"長約十分鐘","examples":[{"en":"The second section, lasting around ten minutes, would focus on people.","zh":"第二部分長約十分鐘，會聚焦於人物。"},{"en":"Lasting around ten minutes means taking about ten minutes from beginning to end.","zh":"lasting around ten minutes 指從開始到結束大約需時十分鐘。"},{"en":"A short interview section lasting around ten minutes can still include several strong stories.","zh":"長約十分鐘的短訪問部分，仍可以包括幾個有力故事。"},{"en":"Stating the length helps the programme feel planned and balanced.","zh":"說明長度能令節目感覺有計劃和平衡。"},{"en":"This phrase tells the reader how much time the section would receive.","zh":"這個短語告訴讀者該部分會獲分配多少時間。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"focus on","meaning":"聚焦於","examples":[{"en":"The second section would focus on the people.","zh":"第二部分會聚焦於人物。"},{"en":"To focus on something means to give main attention to it.","zh":"focus on something 指把主要注意力放在某事物上。"},{"en":"A documentary about school life may focus on students preparing for exams.","zh":"關於校園生活的紀錄片可能聚焦於準備考試的學生。"},{"en":"Focusing on people makes a sports programme more emotional and relatable.","zh":"聚焦於人物令體育節目更有情感和共鳴。"},{"en":"This section focuses on stories rather than only facts and results.","zh":"這部分聚焦於故事，而不只是事實和結果。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"more specifically","meaning":"更具體來說","examples":[{"en":"More specifically, I would interview three individuals.","zh":"更具體來說，我會訪問三位人士。"},{"en":"More specifically means giving clearer and more detailed information about a previous point.","zh":"more specifically 指對前一個重點提供更清楚、更詳細的資訊。"},{"en":"The programme will discuss health; more specifically, it will examine running habits.","zh":"節目會討論健康；更具體來說，它會探討跑步習慣。"},{"en":"This phrase helps move from a general plan to exact details.","zh":"這個短語幫助由一般計劃轉到具體細節。"},{"en":"It makes the proposal sound organised because the writer explains what will actually happen.","zh":"它令建議書聽起來有條理，因為作者解釋實際會發生甚麼。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"interview three individuals","meaning":"訪問三位人士","examples":[{"en":"I would interview three individuals connected to the marathon.","zh":"我會訪問三位與馬拉松相關的人士。"},{"en":"To interview three individuals means to ask three people questions for the programme.","zh":"interview three individuals 指為節目向三個人提問。"},{"en":"A student reporter may interview three individuals after Sports Day: a runner, a teacher, and a volunteer.","zh":"學生記者可能在運動日後訪問三位人士：跑手、老師和義工。"},{"en":"Interviewing different people helps show the event from several angles.","zh":"訪問不同人士有助從幾個角度展示活動。"},{"en":"Three interviews can give the programme variety without making it too crowded.","zh":"三個訪問可以令節目有多樣性，而不會過於擁擠。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"prepare for the race","meaning":"為比賽作準備","examples":[{"en":"One interviewee would be a runner preparing for the race.","zh":"其中一位受訪者會是正在為比賽作準備的跑手。"},{"en":"To prepare for the race means to train, plan, and get ready before race day.","zh":"prepare for the race 指在比賽日前訓練、計劃並作好準備。"},{"en":"A runner may prepare for the race by practising regularly and sleeping well.","zh":"跑手可以透過定期練習和充足睡眠為比賽作準備。"},{"en":"Preparation matters because running well depends on more than race-day excitement.","zh":"準備很重要，因為跑得好不只靠比賽當日的興奮。"},{"en":"Showing preparation helps students understand discipline behind performance.","zh":"展示準備過程幫助學生理解表現背後的紀律。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"support participants","meaning":"支援參加者","examples":[{"en":"One volunteer would explain how they support participants.","zh":"一位義工會解釋他們如何支援參加者。"},{"en":"To support participants means to help people taking part in an event.","zh":"support participants 指幫助參與活動的人。"},{"en":"Volunteers support participants by giving directions, water, encouragement, or first-aid help.","zh":"義工透過指路、派水、鼓勵或急救支援參加者。"},{"en":"Support is important because long events can be tiring and confusing.","zh":"支援很重要，因為長時間活動可能令人疲累和混亂。"},{"en":"A marathon depends on supporters who help runners continue safely.","zh":"馬拉松依靠支援者幫助跑手安全地繼續。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"cheer for","meaning":"為……打氣","examples":[{"en":"A spectator may cheer for a family member or friend.","zh":"觀眾可能為家人或朋友打氣。"},{"en":"To cheer for someone means to shout, clap, or show support for them.","zh":"cheer for someone 指為某人大聲鼓勵、拍手或表示支持。"},{"en":"Students cheer for classmates during Sports Day races.","zh":"學生在運動日比賽中為同學打氣。"},{"en":"Cheering helps participants feel noticed and encouraged.","zh":"打氣幫助參加者感到被看見和被鼓勵。"},{"en":"In a marathon, cheering can give tired runners emotional strength.","zh":"在馬拉松中，打氣可以給疲倦跑手情感力量。"}],"source":"2013 Q2.pdf","sourcePage":6},{"front":"what matters is not only…but also…","meaning":"重要的不只是……還有……","examples":[{"en":"What matters is not only who finishes first, but also why people run.","zh":"重要的不只是誰第一個完成，還有人們為甚麼跑步。"},{"en":"This pattern means the important point includes both the first idea and the second idea.","zh":"這個句式指重要重點包括第一個想法，也包括第二個想法。"},{"en":"What matters is not only exam results, but also how students learn from mistakes.","zh":"重要的不只是考試成績，還有學生如何從錯誤中學習。"},{"en":"The structure helps move attention from surface results to deeper reasons.","zh":"這個結構幫助把注意力由表面結果轉向更深原因。"},{"en":"In the programme, winning matters less than the human reasons behind running.","zh":"在節目中，勝利不如跑步背後的人情原因重要。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"finish first","meaning":"第一個完成","examples":[{"en":"The programme is not only about who finishes first.","zh":"這個節目不只是關於誰第一個完成。"},{"en":"To finish first means to complete a race before all other competitors.","zh":"finish first 指比所有其他參賽者更早完成比賽。"},{"en":"In Sports Day, the student who crosses the line first finishes first.","zh":"在運動日中，最先衝過終點線的學生就是第一個完成。"},{"en":"Finishing first is exciting, but it is not the only meaningful part of sport.","zh":"第一個完成令人興奮，但不是運動唯一有意義的部分。"},{"en":"A marathon programme can also value effort, courage, and personal stories.","zh":"馬拉松節目也可以重視努力、勇氣和個人故事。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"in the first place","meaning":"一開始；本來","examples":[{"en":"The programme asks why people run in the first place.","zh":"這個節目會問人們一開始為甚麼跑步。"},{"en":"In the first place means originally, or at the beginning of the reason.","zh":"in the first place 指最初，或原因的開始。"},{"en":"Before criticising a late student, we should ask why they were late in the first place.","zh":"在批評遲到學生前，我們應先問他一開始為甚麼遲到。"},{"en":"This phrase helps uncover the starting reason behind an action.","zh":"這個短語有助找出行動背後的起始原因。"},{"en":"Asking why runners joined in the first place makes the programme more human.","zh":"問跑手一開始為何參加，令節目更有人情味。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"recover from illness","meaning":"從疾病中康復","examples":[{"en":"One runner may be trying to recover from illness.","zh":"一位跑手可能正在嘗試從疾病中康復。"},{"en":"To recover from illness means to become healthy again after being sick.","zh":"recover from illness 指生病後重新變得健康。"},{"en":"A student may return to gentle exercise while recovering from flu.","zh":"學生在流感康復期間可能恢復做溫和運動。"},{"en":"Running after illness can represent hope, patience, and rebuilding strength.","zh":"病後跑步可以代表希望、耐性和重建力量。"},{"en":"A recovery story can help viewers see sport as part of healing.","zh":"康復故事可以幫助觀眾把運動視為治癒的一部分。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"in memory of","meaning":"為紀念……","examples":[{"en":"Another runner may be running in memory of a loved one.","zh":"另一位跑手可能為紀念摯愛的人而跑。"},{"en":"In memory of someone means to honour and remember a person who has died or is absent.","zh":"in memory of someone 指為紀念和尊重已離世或不在場的人。"},{"en":"A family may plant a tree in memory of a grandparent.","zh":"一家人可能為紀念祖父母而種一棵樹。"},{"en":"Running in memory of someone gives the race emotional meaning beyond time and medals.","zh":"為紀念某人而跑，令比賽有超越時間和獎牌的情感意義。"},{"en":"This phrase shows that sport can carry love, grief, and remembrance.","zh":"這個短語顯示運動可以承載愛、悲傷和記念。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"a loved one","meaning":"摯愛的人","examples":[{"en":"A runner may run in memory of a loved one.","zh":"跑手可能為紀念摯愛的人而跑。"},{"en":"A loved one is a person who is deeply cared about, such as a family member or close friend.","zh":"loved one 指深受珍惜的人，例如家人或親密朋友。"},{"en":"People may dedicate a race, song, or speech to a loved one.","zh":"人們可能把比賽、歌曲或演講獻給摯愛的人。"},{"en":"Mentioning a loved one makes a story personal and emotional.","zh":"提到摯愛的人，令故事變得個人化和有情感。"},{"en":"A marathon can become meaningful when runners carry memories of loved ones with them.","zh":"當跑手帶着摯愛之人的記憶前進時，馬拉松可以變得有意義。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"prove that","meaning":"證明","examples":[{"en":"A student participant may want to prove that discipline can beat laziness.","zh":"一名學生參加者可能想證明紀律能戰勝懶惰。"},{"en":"To prove that means to show something is true through action, evidence, or results.","zh":"prove that 指透過行動、證據或結果顯示某事是真的。"},{"en":"A student may prove that practice works by improving after several weeks.","zh":"學生可能透過幾星期後有進步，證明練習有效。"},{"en":"People often try to prove something when others doubt them or when they doubt themselves.","zh":"當別人懷疑他們或他們懷疑自己時，人們常想證明某事。"},{"en":"Running a marathon can prove that steady effort is stronger than excuses.","zh":"跑馬拉松可以證明穩定努力比藉口更強。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"beat laziness","meaning":"戰勝懶惰","examples":[{"en":"A student participant may want to show that discipline can beat laziness.","zh":"一名學生參加者可能想顯示紀律能戰勝懶惰。"},{"en":"To beat laziness means to overcome the desire to avoid effort.","zh":"beat laziness 指克服逃避努力的慾望。"},{"en":"A student beats laziness by starting homework before opening social media.","zh":"學生在打開社交媒體前先開始做功課，就是戰勝懶惰。"},{"en":"Beating laziness is easier when the first step is small and clear.","zh":"當第一步細小而清楚時，戰勝懶惰會較容易。"},{"en":"The marathon can show that discipline grows through repeated action.","zh":"馬拉松可以顯示紀律透過重複行動成長。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"human stories","meaning":"人情故事","examples":[{"en":"Human stories would prevent the programme from becoming a plain sports report.","zh":"人情故事會防止節目變成平淡的體育報道。"},{"en":"Human stories are personal experiences that show feelings, struggles, choices, and relationships.","zh":"human stories 指展示感受、掙扎、選擇和關係的個人經歷。"},{"en":"A runner’s story about illness or family can make a marathon more meaningful.","zh":"跑手關於疾病或家庭的故事，可以令馬拉松更有意義。"},{"en":"Human stories help viewers care about people, not only results.","zh":"人情故事幫助觀眾關心人，而不只是結果。"},{"en":"A programme with human stories is more likely to keep students watching.","zh":"有人情故事的節目較可能令學生繼續觀看。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"prevent…from becoming","meaning":"防止……變成","examples":[{"en":"These stories would prevent the programme from becoming a plain sports report.","zh":"這些故事會防止節目變成平淡的體育報道。"},{"en":"To prevent something from becoming another thing means to stop it changing into an unwanted form.","zh":"prevent something from becoming another thing 指阻止某事變成不想要的形式。"},{"en":"Interviews can prevent a school video from becoming only a list of announcements.","zh":"訪問可以防止學校影片變成只有通告列表。"},{"en":"This phrase shows what danger the writer wants to avoid.","zh":"這個短語顯示作者想避免甚麼危險。"},{"en":"Human stories prevent the programme from becoming dry because they add emotion.","zh":"人情故事防止節目變得枯燥，因為它們加入情感。"}],"source":"2013 Q2.pdf","sourcePage":7},{"front":"plain sports report","meaning":"平淡的體育報道","examples":[{"en":"The programme should not become a plain sports report.","zh":"這個節目不應變成平淡的體育報道。"},{"en":"A plain sports report is a simple report that gives facts and results without much emotion or story.","zh":"plain sports report 指只提供事實和結果、缺少情感或故事的簡單報道。"},{"en":"A plain sports report may tell who won but not why the race mattered.","zh":"平淡的體育報道可能告訴誰勝出，但不說明比賽為何重要。"},{"en":"Such reports can be useful, but they may not attract students who are not sports fans.","zh":"這類報道有用，但未必吸引不是體育迷的學生。"},{"en":"Adding personal stories makes the programme more engaging than a plain report.","zh":"加入個人故事令節目比平淡報道更吸引。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"give someone to identify with","meaning":"給某人可以認同的人","examples":[{"en":"The stories would give our schoolmates someone to identify with.","zh":"這些故事會給同學可以認同的人。"},{"en":"To give someone a person to identify with means to offer a character or real person whose feelings they can understand.","zh":"give someone a person to identify with 指提供一個角色或真人，讓對方能理解其感受。"},{"en":"A documentary about a nervous student can give viewers someone to identify with before exams.","zh":"關於緊張學生的紀錄片，可以在考試前給觀眾可以認同的人。"},{"en":"Viewers stay interested when they recognise parts of themselves in others.","zh":"當觀眾在別人身上認出自己的一部分時，會保持興趣。"},{"en":"Marathon stories help students see that runners may share their fears and goals.","zh":"馬拉松故事幫助學生看見跑手可能與自己有相似恐懼和目標。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"identify with","meaning":"產生共鳴","examples":[{"en":"Students may identify with the runners’ personal stories.","zh":"學生可能與跑手的個人故事產生共鳴。"},{"en":"To identify with someone means to feel that you understand them because their experience is similar to yours.","zh":"identify with someone 指因對方經驗與自己相似，而感到理解對方。"},{"en":"A shy student may identify with a speaker who talks about fear of public speaking.","zh":"害羞學生可能與談論害怕公開演說的講者產生共鳴。"},{"en":"People identify with stories when emotions feel familiar.","zh":"當情感感覺熟悉時，人們會與故事產生共鳴。"},{"en":"If students identify with a runner, they may see sport as something for them too.","zh":"如果學生與跑手產生共鳴，他們可能也把運動視為屬於自己的東西。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"essential if","meaning":"如果……就是必不可少的","examples":[{"en":"Human stories are essential if we want students to keep watching.","zh":"如果我們想學生繼續觀看，人情故事就是必不可少的。"},{"en":"Essential if means necessary in order for a particular result to happen.","zh":"essential if 指為了達到某個結果，某事是必要的。"},{"en":"Clear subtitles are essential if viewers need to understand interviews in a noisy place.","zh":"如果觀眾需要在嘈雜地方理解訪問，清楚字幕就是必不可少的。"},{"en":"This phrase connects a necessary condition with a desired outcome.","zh":"這個短語把必要條件與想要的結果連接起來。"},{"en":"Human stories are essential if the programme aims to attract non-sports fans.","zh":"如果節目旨在吸引非體育迷，人情故事就是必不可少的。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"keep watching","meaning":"繼續觀看","examples":[{"en":"Relatable stories can encourage students to keep watching.","zh":"有共鳴的故事可以鼓勵學生繼續觀看。"},{"en":"To keep watching means to continue watching instead of stopping or losing interest.","zh":"keep watching 指繼續觀看，而不是停止或失去興趣。"},{"en":"Students keep watching a video when the first scene makes them curious.","zh":"當影片第一幕令人好奇時，學生會繼續觀看。"},{"en":"Programmes need variety and emotion if they want viewers to keep watching.","zh":"如果節目想觀眾繼續觀看，就需要多樣性和情感。"},{"en":"Familiar faces and human stories help Campus TV hold students’ attention.","zh":"熟悉面孔和人情故事幫助校園電視抓住學生注意力。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"final main section","meaning":"最後一個主要部分","examples":[{"en":"The final main section would bring the programme back to our school.","zh":"最後一個主要部分會把節目帶回我們學校。"},{"en":"The final main section is the last major part before the ending or conclusion.","zh":"final main section 指結尾或總結前最後一個重要部分。"},{"en":"A final main section may connect a public topic with students’ own school life.","zh":"最後一個主要部分可以把公共題材與學生自己的校園生活連接起來。"},{"en":"This section is important because it helps viewers see what the topic means to them.","zh":"這部分很重要，因為它幫助觀眾看見主題對自己有何意義。"},{"en":"Bringing the programme back to school makes the marathon feel relevant to students.","zh":"把節目帶回學校，令馬拉松感覺與學生相關。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"bring…back to","meaning":"把……帶回到","examples":[{"en":"The final section would bring the programme back to our school.","zh":"最後部分會把節目帶回到我們學校。"},{"en":"To bring something back to a place means to connect it again with that place or group.","zh":"bring something back to a place 指把某事再次與某地方或群體連接起來。"},{"en":"A news report about climate change can bring the issue back to students’ daily habits.","zh":"關於氣候變化的新聞報道，可以把議題帶回到學生的日常習慣。"},{"en":"This phrase helps move from a large public topic to a familiar local setting.","zh":"這個短語幫助由大型公共題材轉到熟悉本地場景。"},{"en":"Bringing the marathon back to school helps students see what they can try themselves.","zh":"把馬拉松帶回學校，幫助學生看見自己可以嘗試甚麼。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"invite someone to","meaning":"邀請某人去……","examples":[{"en":"We could invite two students and a PE teacher to complete a challenge.","zh":"我們可以邀請兩名學生和一位體育老師去完成一項挑戰。"},{"en":"To invite someone to do something means to ask them to take part in an activity.","zh":"invite someone to do something 指邀請某人參與某項活動。"},{"en":"A club may invite students to join a lunchtime reading game.","zh":"學會可能邀請學生參加午膳閱讀遊戲。"},{"en":"Inviting familiar people makes a programme more relatable to viewers.","zh":"邀請熟悉人物令節目更容易引起觀眾共鳴。"},{"en":"The phrase shows who will participate and what they will do.","zh":"這個短語顯示誰會參與，以及他們會做甚麼。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"mini-marathon challenge","meaning":"迷你馬拉松挑戰","examples":[{"en":"Students and a PE teacher could complete a mini-marathon challenge on campus.","zh":"學生和一位體育老師可以在校園內完成迷你馬拉松挑戰。"},{"en":"A mini-marathon challenge is a shorter running activity inspired by a real marathon.","zh":"mini-marathon challenge 指受真正馬拉松啟發的較短跑步活動。"},{"en":"A school may organise a mini-marathon challenge around the playground or campus path.","zh":"學校可以在操場或校園小路舉辦迷你馬拉松挑戰。"},{"en":"A mini version makes the idea safer and more suitable for students.","zh":"迷你版本令這個想法更安全，也更適合學生。"},{"en":"The challenge helps viewers understand marathon effort at a school level.","zh":"這項挑戰幫助觀眾在校園層面理解馬拉松努力。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"on campus","meaning":"在校園內","examples":[{"en":"The mini-marathon challenge would take place on campus.","zh":"迷你馬拉松挑戰會在校園內舉行。"},{"en":"On campus means within the school or college grounds.","zh":"on campus 指在學校或大學範圍內。"},{"en":"A charity run on campus can include the playground, corridors, and covered areas if safe.","zh":"如果安全，校園內慈善跑可以包括操場、走廊和有蓋地方。"},{"en":"Holding activities on campus makes participation easier for students.","zh":"在校園內舉行活動，令學生較容易參與。"},{"en":"The phrase shows that the challenge is close, practical, and school-based.","zh":"這個短語顯示挑戰貼近、實際並以學校為本。"}],"source":"2013 Q2.pdf","sourcePage":8},{"front":"basic running techniques","meaning":"基本跑步技巧","examples":[{"en":"The PE teacher could explain basic running techniques.","zh":"體育老師可以解釋基本跑步技巧。"},{"en":"Basic running techniques are simple methods that help people run more safely and efficiently.","zh":"basic running techniques 指幫助人更安全和有效率地跑步的簡單方法。"},{"en":"These techniques may include posture, arm movement, breathing, and foot placement.","zh":"這些技巧可以包括姿勢、手臂擺動、呼吸和落腳位置。"},{"en":"Learning basic techniques can prevent beginners from running in a painful or wasteful way.","zh":"學習基本技巧可以防止初學者以疼痛或浪費體力的方式跑步。"},{"en":"Explaining them makes the challenge educational, not only entertaining.","zh":"解釋這些技巧令挑戰有教育意義，而不只是娛樂。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"warm-up routines","meaning":"熱身程序","examples":[{"en":"The PE teacher could explain warm-up routines.","zh":"體育老師可以解釋熱身程序。"},{"en":"Warm-up routines are repeated movements done before exercise to prepare the body.","zh":"warm-up routines 指運動前為準備身體而做的一系列固定動作。"},{"en":"A warm-up routine may include light jogging, leg swings, and gentle stretching.","zh":"熱身程序可以包括慢跑、擺腿和溫和伸展。"},{"en":"Warm-ups reduce injury risk because muscles and joints become ready for movement.","zh":"熱身能減低受傷風險，因為肌肉和關節會準備好活動。"},{"en":"Showing warm-up routines teaches students that preparation is part of sport.","zh":"展示熱身程序教學生明白準備是運動的一部分。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"pacing","meaning":"配速","examples":[{"en":"The PE teacher could explain pacing during a run.","zh":"體育老師可以解釋跑步時的配速。"},{"en":"Pacing means controlling speed so a runner does not use all their energy too early.","zh":"pacing 指控制速度，讓跑手不會太早用盡體力。"},{"en":"A beginner may start too fast and then learn the importance of pacing.","zh":"初學者可能起步太快，然後學會配速的重要性。"},{"en":"Good pacing helps runners finish stronger because they save energy for later.","zh":"良好配速幫助跑手在尾段表現更好，因為他們保留了能量。"},{"en":"Pacing is useful in running, studying, and long projects.","zh":"配速在跑步、學習和長期專題中都有用。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"hydration","meaning":"補充水分","examples":[{"en":"Hydration is important during running.","zh":"跑步期間補充水分很重要。"},{"en":"Hydration means having enough water in the body.","zh":"hydration 指身體有足夠水分。"},{"en":"Runners need hydration because sweating causes the body to lose water.","zh":"跑手需要補充水分，因為流汗會令身體失去水分。"},{"en":"Poor hydration can make people feel tired, dizzy, or unable to perform well.","zh":"水分不足可能令人疲倦、頭暈或表現不佳。"},{"en":"Teaching hydration helps students understand that sport includes body care.","zh":"教授補充水分，幫助學生明白運動也包括照顧身體。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"injury prevention","meaning":"預防受傷","examples":[{"en":"The PE teacher could explain injury prevention.","zh":"體育老師可以解釋預防受傷。"},{"en":"Injury prevention means taking steps to reduce the chance of getting hurt.","zh":"injury prevention 指採取措施減低受傷機會。"},{"en":"Warming up, wearing suitable shoes, and resting properly are forms of injury prevention.","zh":"熱身、穿合適鞋子和適當休息都是預防受傷的方法。"},{"en":"Injury prevention matters because one careless session can lead to weeks of pain.","zh":"預防受傷很重要，因為一次粗心訓練可能帶來幾星期痛楚。"},{"en":"A school programme should make running feel achievable and safe.","zh":"校園節目應令跑步感覺可達成而安全。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, the student hosts could try the exercises.","zh":"與此同時，學生主持可以嘗試這些練習。"},{"en":"Meanwhile means at the same time or during the same period.","zh":"meanwhile 指同一時間或同一期間。"},{"en":"The PE teacher explains pacing; meanwhile, students practise running at different speeds.","zh":"體育老師解釋配速；與此同時，學生練習用不同速度跑步。"},{"en":"This word helps show two actions happening together in a programme.","zh":"這個詞幫助顯示節目中兩個行動同時發生。"},{"en":"It keeps the structure active because viewers see explanation and practice side by side.","zh":"它令結構保持活躍，因為觀眾同時看到解釋和實踐。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"react honestly","meaning":"真實地反應","examples":[{"en":"The student hosts could try the exercises and react honestly.","zh":"學生主持可以嘗試練習並真實地反應。"},{"en":"To react honestly means to show real feelings instead of pretending something is easy or perfect.","zh":"react honestly 指表現真實感受，而不是假裝某事容易或完美。"},{"en":"A student may react honestly by saying a training drill is harder than expected.","zh":"學生可以真實地反應，說訓練比預期困難。"},{"en":"Honest reactions help viewers trust the programme because they feel real.","zh":"真實反應幫助觀眾信任節目，因為它感覺真實。"},{"en":"If hosts react honestly, classmates may feel less embarrassed about finding exercise difficult.","zh":"如果主持真實地反應，同學覺得運動困難時會較不尷尬。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"find the training tiring","meaning":"覺得訓練辛苦","examples":[{"en":"If they find the training tiring, it would make the programme more authentic.","zh":"如果他們覺得訓練辛苦，這會令節目更真實。"},{"en":"To find the training tiring means to feel that the exercise is physically demanding.","zh":"find the training tiring 指感覺訓練在身體上很吃力。"},{"en":"A beginner may find hill running tiring after only a few minutes.","zh":"初學者可能只跑幾分鐘斜路就覺得訓練辛苦。"},{"en":"Tiredness can show viewers that the challenge is real, not staged.","zh":"疲倦可以向觀眾顯示挑戰是真實的，而不是預先安排得完美。"},{"en":"When students admit training is tiring, the programme becomes more relatable.","zh":"當學生承認訓練辛苦時，節目會更容易引起共鳴。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"that is not a problem","meaning":"那不是問題","examples":[{"en":"If students find the training tiring, that is not a problem.","zh":"如果學生覺得訓練辛苦，那不是問題。"},{"en":"That is not a problem means the situation is acceptable and should not be treated as a failure.","zh":"that is not a problem 指情況可以接受，不應被視為失敗。"},{"en":"If beginners run slowly, that is not a problem because they are still learning.","zh":"如果初學者跑得慢，那不是問題，因為他們仍在學習。"},{"en":"This phrase reassures people and reduces embarrassment.","zh":"這個短語安慰人並減少尷尬。"},{"en":"In the programme, tiredness is useful because it shows honest effort.","zh":"在節目中，疲倦是有用的，因為它展示真實努力。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, it would make the programme more authentic.","zh":"事實上，這會令節目更真實。"},{"en":"In fact is used to add a stronger or more accurate point.","zh":"in fact 用來加入更有力或更準確的觀點。"},{"en":"The challenge may look difficult; in fact, that difficulty can make it more meaningful.","zh":"挑戰可能看起來困難；事實上，這種困難可以令它更有意義。"},{"en":"Writers use this phrase to correct a possible misunderstanding.","zh":"作者使用這個短語來修正可能的誤解。"},{"en":"Here, the writer explains that tiredness is not a weakness but a strength of the programme.","zh":"在這裏，作者解釋疲倦不是節目的弱點，而是優點。"}],"source":"2013 Q2.pdf","sourcePage":9},{"front":"more authentic","meaning":"更真實","examples":[{"en":"Honest reactions would make the programme more authentic.","zh":"真實反應會令節目更真實。"},{"en":"More authentic means more real, believable, and true to actual experience.","zh":"more authentic 指更真實、可信，並貼近實際經驗。"},{"en":"A student video feels more authentic when mistakes and laughter are included.","zh":"當學生影片包括錯誤和笑聲時，會感覺更真實。"},{"en":"Viewers trust authentic programmes because they do not feel too polished or fake.","zh":"觀眾信任真實的節目，因為它們不會感覺過度修飾或虛假。"},{"en":"Real effort makes the running challenge more authentic than a perfect demonstration.","zh":"真實努力令跑步挑戰比完美示範更真實。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"few students, if any","meaning":"即使有，也很少學生","examples":[{"en":"Few students, if any, enjoy being lectured about health.","zh":"即使有，也很少學生喜歡被說教有關健康。"},{"en":"Few students, if any, means almost no students, and possibly none at all.","zh":"few students, if any 指幾乎沒有學生，甚至可能完全沒有。"},{"en":"Few students, if any, enjoy a programme that only gives rules and warnings.","zh":"即使有，也很少學生喜歡只給規則和警告的節目。"},{"en":"This phrase emphasises that something is uncommon or unlikely.","zh":"這個短語強調某事很少見或不太可能。"},{"en":"It supports the idea that the programme should show experience rather than preach.","zh":"它支持節目應展示經驗，而不是說教的想法。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"being lectured about","meaning":"被說教有關……","examples":[{"en":"Few students enjoy being lectured about health.","zh":"很少學生喜歡被說教有關健康。"},{"en":"Being lectured about something means being spoken to in a long, serious, and often moralising way.","zh":"being lectured about something 指被長篇、嚴肅，並常帶說教意味地講述某事。"},{"en":"Students may dislike being lectured about exercise if no practical example is shown.","zh":"如果沒有實際例子，學生可能不喜歡被說教有關運動。"},{"en":"Lecturing can feel boring when the audience is not invited to think or participate.","zh":"當觀眾沒有被邀請思考或參與時，說教會感覺沉悶。"},{"en":"Campus TV should avoid lecturing and use action, humour, and honest reactions instead.","zh":"校園電視應避免說教，而改用行動、幽默和真實反應。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"struggle, laugh, improve and complete","meaning":"掙扎、歡笑、進步並完成","examples":[{"en":"Students may enjoy watching classmates struggle, laugh, improve, and complete a challenge.","zh":"學生可能喜歡觀看同學掙扎、歡笑、進步並完成挑戰。"},{"en":"Struggle, laugh, improve and complete describes a process of facing difficulty, enjoying moments, getting better, and finishing.","zh":"struggle, laugh, improve and complete 描述面對困難、享受時刻、變得更好並完成的過程。"},{"en":"A group project may make students struggle, laugh, improve and finally complete their work.","zh":"小組專題可能令學生掙扎、歡笑、進步，最後完成工作。"},{"en":"This sequence feels human because progress includes mistakes and effort.","zh":"這個過程很有人情味，因為進步包括錯誤和努力。"},{"en":"Showing this process can make sport feel realistic rather than perfect.","zh":"展示這個過程可以令運動感覺真實，而不是完美。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"by showing effort step by step","meaning":"透過一步步展示努力","examples":[{"en":"By showing effort step by step, we can make sport feel achievable.","zh":"透過一步步展示努力，我們可以令運動感覺可達成。"},{"en":"By showing effort step by step means showing progress in small stages instead of only the final result.","zh":"by showing effort step by step 指展示小階段的進展，而不是只展示最終成果。"},{"en":"A cooking video shows effort step by step when it includes preparation, mistakes, and improvement.","zh":"烹飪影片如果包括準備、錯誤和改善，就是一步步展示努力。"},{"en":"Step-by-step effort helps beginners believe they can start too.","zh":"一步步展示努力幫助初學者相信自己也能開始。"},{"en":"This approach makes sport less frightening because viewers see how progress is built.","zh":"這種方法令運動較不嚇人，因為觀眾看見進步如何建立。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"achievable","meaning":"可達成的","examples":[{"en":"We can make sport feel achievable rather than intimidating.","zh":"我們可以令運動感覺可達成，而不是令人卻步。"},{"en":"Achievable means possible to do or reach with reasonable effort.","zh":"achievable 指透過合理努力可以做到或達到。"},{"en":"Running for five minutes may feel achievable to a beginner.","zh":"對初學者來說，跑五分鐘可能感覺可達成。"},{"en":"Goals feel achievable when they are clear, small, and realistic.","zh":"當目標清楚、細小和實際時，就會感覺可達成。"},{"en":"Sport becomes more welcoming when students see that improvement is possible.","zh":"當學生看見進步是可能的，運動就變得更友善。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"intimidating","meaning":"令人卻步的","examples":[{"en":"Sport should feel achievable rather than intimidating.","zh":"運動應感覺可達成，而不是令人卻步。"},{"en":"Intimidating means frightening, difficult, or discouraging to approach.","zh":"intimidating 指令人害怕、覺得困難或不敢接近的。"},{"en":"A long-distance run may feel intimidating to a student who rarely exercises.","zh":"對很少運動的學生來說，長跑可能令人卻步。"},{"en":"Good guidance makes a challenge less intimidating by breaking it into steps.","zh":"好指導透過把挑戰分成步驟，令它較不令人卻步。"},{"en":"The programme should reduce fear by showing ordinary students trying sport honestly.","zh":"節目應透過展示普通學生真實嘗試運動來減少恐懼。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"to make the programme interesting","meaning":"為了令節目有趣","examples":[{"en":"To make the programme interesting, I would use a fast but clear structure.","zh":"為了令節目有趣，我會使用節奏快但清晰的結構。"},{"en":"To make the programme interesting means in order to help the programme attract and hold attention.","zh":"to make the programme interesting 指為了幫助節目吸引並保持注意力。"},{"en":"To make a school video interesting, students may use interviews, music, and short scenes.","zh":"為了令學校影片有趣，學生可以使用訪問、音樂和短場景。"},{"en":"This phrase introduces the method used to achieve the goal.","zh":"這個短語引入達成目標的方法。"},{"en":"A programme becomes interesting when its structure, visuals, and stories work together.","zh":"當節目結構、畫面和故事配合時，節目就會有趣。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"fast but clear structure","meaning":"節奏快但清晰的結構","examples":[{"en":"I would use a fast but clear structure.","zh":"我會使用節奏快但清晰的結構。"},{"en":"A fast but clear structure moves quickly while still helping viewers understand the order of ideas.","zh":"fast but clear structure 指節奏快速，但仍幫助觀眾理解想法次序的結構。"},{"en":"A news video can be fast but clear if each section has a simple title.","zh":"如果每部分都有簡單標題，新聞影片可以節奏快但清晰。"},{"en":"Speed keeps attention, while clarity prevents confusion.","zh":"速度保持注意力，而清晰度防止混亂。"},{"en":"This structure suits Campus TV because students may stop watching if the pace is too slow.","zh":"這種結構適合校園電視，因為如果節奏太慢，學生可能停止觀看。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"exciting opening","meaning":"精彩開場","examples":[{"en":"The programme would have an exciting opening.","zh":"這個節目會有精彩開場。"},{"en":"An exciting opening is a beginning that catches attention and makes viewers want to continue.","zh":"exciting opening 指能吸引注意並令觀眾想繼續觀看的開首。"},{"en":"A sports programme may have an exciting opening with music, crowds, and quick shots.","zh":"體育節目可以用音樂、人群和快速鏡頭作精彩開場。"},{"en":"Openings matter because viewers decide quickly whether to keep watching.","zh":"開場很重要，因為觀眾很快決定是否繼續觀看。"},{"en":"A strong opening prepares the mood before the main sections begin.","zh":"有力開場在主要部分開始前先建立氣氛。"}],"source":"2013 Q2.pdf","sourcePage":10},{"front":"human-centred interviews","meaning":"以人為本的訪問","examples":[{"en":"The programme would include human-centred interviews.","zh":"節目會包括以人為本的訪問。"},{"en":"Human-centred interviews focus on people’s feelings, reasons, and experiences rather than only facts.","zh":"human-centred interviews 聚焦於人的感受、原因和經驗，而不只是事實。"},{"en":"A human-centred interview asks why a runner started and what the race means to them.","zh":"以人為本的訪問會問跑手為何開始，以及比賽對他有何意義。"},{"en":"Such interviews help viewers care about the people on screen.","zh":"這類訪問幫助觀眾關心螢幕上的人。"},{"en":"They prevent the programme from feeling cold or purely informational.","zh":"它們防止節目感覺冷冰冰或純粹資訊化。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"campus challenge","meaning":"校園挑戰","examples":[{"en":"The programme would include a campus challenge.","zh":"節目會包括校園挑戰。"},{"en":"A campus challenge is an activity completed by students or teachers within the school setting.","zh":"campus challenge 指由學生或老師在學校環境中完成的活動。"},{"en":"A campus challenge may ask students to run laps, answer questions, or complete a teamwork task.","zh":"校園挑戰可能要求學生跑圈、回答問題或完成團隊任務。"},{"en":"It makes the programme interactive because familiar people take part.","zh":"它令節目更有互動性，因為熟悉的人會參與。"},{"en":"A campus challenge brings a public sporting event back into school life.","zh":"校園挑戰把公共體育活動帶回校園生活中。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"closing reflection","meaning":"結尾反思","examples":[{"en":"The programme would end with a closing reflection.","zh":"節目會以結尾反思作結。"},{"en":"A closing reflection is a final thought that helps viewers understand the meaning of what they watched.","zh":"closing reflection 指幫助觀眾理解所看內容意義的最後思考。"},{"en":"After a sports video, a closing reflection may ask what effort means in daily life.","zh":"體育影片後，結尾反思可能問努力在日常生活中有何意思。"},{"en":"Reflections are useful because they turn action into learning.","zh":"反思很有用，因為它把行動轉化為學習。"},{"en":"A good closing reflection leaves viewers with a clear message.","zh":"好的結尾反思會留給觀眾清楚訊息。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"visually","meaning":"在視覺上","examples":[{"en":"Visually, I would include close-up shots and slow-motion cheering.","zh":"在視覺上，我會加入特寫鏡頭和慢鏡打氣畫面。"},{"en":"Visually means in terms of what viewers can see on screen.","zh":"visually 指從觀眾在螢幕上看見的東西來說。"},{"en":"Visually, a programme can be made stronger through colour, movement, and clear framing.","zh":"在視覺上，節目可以透過色彩、動作和清晰構圖變得更強。"},{"en":"This word helps introduce ideas about images rather than words or content.","zh":"這個詞幫助引入關於畫面，而不是文字或內容的想法。"},{"en":"Visual planning matters because Campus TV depends on what students see.","zh":"視覺規劃很重要，因為校園電視依賴學生看見的東西。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"close-up shots","meaning":"特寫鏡頭","examples":[{"en":"I would include close-up shots of shoes hitting the road.","zh":"我會加入鞋子踏上路面的特寫鏡頭。"},{"en":"Close-up shots are camera images taken near the subject to show details clearly.","zh":"close-up shots 指近距離拍攝主體、清楚展示細節的鏡頭。"},{"en":"A close-up shot can show sweat, shoelaces, facial expression, or a runner’s hands.","zh":"特寫鏡頭可以展示汗水、鞋帶、面部表情或跑手的手。"},{"en":"Close-ups help viewers notice details they may miss in wide scenes.","zh":"特寫幫助觀眾注意到廣角場面中可能錯過的細節。"},{"en":"They make physical effort feel more immediate and personal.","zh":"它們令身體努力感覺更即時和個人化。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"shoes hitting the road","meaning":"鞋子踏上路面","examples":[{"en":"Close-up shots would show shoes hitting the road.","zh":"特寫鏡頭會展示鞋子踏上路面。"},{"en":"Shoes hitting the road means runners’ feet landing repeatedly on the road surface.","zh":"shoes hitting the road 指跑手的腳反覆落在路面上。"},{"en":"The sound of shoes hitting the road can make a race feel rhythmic and powerful.","zh":"鞋子踏上路面的聲音可以令比賽感覺有節奏和力量。"},{"en":"This detail shows effort through movement instead of explanation.","zh":"這個細節透過動作而不是解釋展示努力。"},{"en":"It helps viewers feel the physical reality of running.","zh":"它幫助觀眾感受到跑步的身體真實感。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"slow-motion cheering","meaning":"慢鏡打氣畫面","examples":[{"en":"I would include slow-motion cheering in the programme.","zh":"我會在節目中加入慢鏡打氣畫面。"},{"en":"Slow-motion cheering means showing people cheering at a slower speed for emotional or visual effect.","zh":"slow-motion cheering 指以較慢速度展示人們打氣，以產生情感或視覺效果。"},{"en":"Slow motion can make clapping hands and smiling faces feel more dramatic.","zh":"慢鏡可以令拍手和笑臉感覺更富戲劇性。"},{"en":"This technique helps viewers notice the support around the runners.","zh":"這種技巧幫助觀眾注意跑手身邊的支持。"},{"en":"It can turn a brief cheer into a memorable moment.","zh":"它可以把短暫打氣變成難忘時刻。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"quick captions","meaning":"快速字幕","examples":[{"en":"Quick captions could explain key terms.","zh":"快速字幕可以解釋關鍵詞語。"},{"en":"Quick captions are short pieces of text shown briefly on screen to give information.","zh":"quick captions 指短暫出現在螢幕上提供資訊的簡短文字。"},{"en":"A sports video may use quick captions to explain pacing, hydration, or route names.","zh":"體育影片可以使用快速字幕解釋配速、補水或路線名稱。"},{"en":"Captions help viewers learn without interrupting the flow of the programme.","zh":"字幕幫助觀眾學習，而不打斷節目流程。"},{"en":"Quick captions are useful when the programme moves at a fast pace.","zh":"當節目節奏快時，快速字幕很有用。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"key terms","meaning":"關鍵詞語","examples":[{"en":"Captions could explain key terms about the marathon.","zh":"字幕可以解釋關於馬拉松的關鍵詞語。"},{"en":"Key terms are important words or phrases needed to understand a topic.","zh":"key terms 指理解某主題所需的重要字詞或短語。"},{"en":"In a running programme, key terms may include pacing, route, hydration, and endurance.","zh":"在跑步節目中，關鍵詞語可以包括配速、路線、補水和耐力。"},{"en":"Explaining key terms helps beginners follow the programme more easily.","zh":"解釋關鍵詞語幫助初學者更容易跟上節目。"},{"en":"Key terms turn entertainment into learning because viewers gain useful vocabulary.","zh":"關鍵詞語把娛樂轉化為學習，因為觀眾獲得有用詞彙。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"a simple map showing","meaning":"一幅簡單地圖顯示","examples":[{"en":"We could include a simple map showing where the race takes place.","zh":"我們可以加入一幅簡單地圖，顯示比賽在哪裏舉行。"},{"en":"A simple map showing something is an easy-to-read map that explains location or route visually.","zh":"simple map showing something 指一幅容易閱讀、以視覺方式解釋位置或路線的地圖。"},{"en":"A school trip video may include a simple map showing the places students visited.","zh":"學校旅行影片可以加入一幅簡單地圖，顯示學生到訪過的地方。"},{"en":"Maps help viewers understand movement through space.","zh":"地圖幫助觀眾理解空間中的移動。"},{"en":"A simple route map would make the marathon easier to follow.","zh":"簡單路線圖會令馬拉松更容易跟隨。"}],"source":"2013 Q2.pdf","sourcePage":11},{"front":"take place","meaning":"舉行","examples":[{"en":"The map would show where the race takes place.","zh":"地圖會顯示比賽在哪裏舉行。"},{"en":"To take place means to happen or be held at a particular time or location.","zh":"take place 指在某個時間或地點發生或舉行。"},{"en":"The charity run will take place on the school playground next Friday.","zh":"慈善跑會在下星期五於學校操場舉行。"},{"en":"Viewers understand an event better when they know where it takes place.","zh":"當觀眾知道活動在哪裏舉行時，會更理解該活動。"},{"en":"This phrase is useful for describing the setting of activities and events.","zh":"這個短語適合用來描述活動和事件的地點。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"better still","meaning":"更好的是","examples":[{"en":"Better still, we could add interactive elements.","zh":"更好的是，我們可以加入互動元素。"},{"en":"Better still means even better than the point just mentioned.","zh":"better still 指比剛才提到的一點更好的是。"},{"en":"The video could include interviews; better still, it could invite students to vote afterwards.","zh":"影片可以包括訪問；更好的是，它可以邀請學生之後投票。"},{"en":"Writers use this phrase to add a stronger or more exciting suggestion.","zh":"作者使用這個短語來加入更強或更令人期待的建議。"},{"en":"It helps the proposal build momentum by moving to an improved idea.","zh":"它透過提出更好的想法，幫助建議書建立推進力。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"interactive elements","meaning":"互動元素","examples":[{"en":"We could add interactive elements to the programme.","zh":"我們可以在節目中加入互動元素。"},{"en":"Interactive elements are features that allow viewers to participate, respond, or make choices.","zh":"interactive elements 指讓觀眾參與、回應或作選擇的功能。"},{"en":"A quiz, vote, comment wall, or challenge can be an interactive element.","zh":"小測驗、投票、留言牆或挑戰都可以是互動元素。"},{"en":"Interactive features make students feel involved rather than only watching passively.","zh":"互動功能令學生感到參與其中，而不只是被動觀看。"},{"en":"They can extend the programme’s impact beyond the viewing time.","zh":"它們可以把節目的影響延伸到觀看時間以外。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"social media page","meaning":"社交媒體專頁","examples":[{"en":"Campus TV’s social media page could host a short quiz.","zh":"校園電視的社交媒體專頁可以舉辦小測驗。"},{"en":"A social media page is an online page where an organisation shares posts, videos, questions, and updates.","zh":"social media page 指一個組織用來分享帖文、影片、問題和更新的網上頁面。"},{"en":"A school club may use its social media page to announce events and collect opinions.","zh":"學會可以使用社交媒體專頁宣布活動和收集意見。"},{"en":"Social media pages are useful because students can respond quickly on their phones.","zh":"社交媒體專頁很有用，因為學生可以用手機快速回應。"},{"en":"Using the page can connect the programme with discussion after it airs.","zh":"使用專頁可以把節目與播出後的討論連接起來。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"short quiz","meaning":"小測驗","examples":[{"en":"We could add a short quiz on Campus TV’s social media page.","zh":"我們可以在校園電視的社交媒體專頁加入小測驗。"},{"en":"A short quiz is a brief set of questions used to test knowledge or create interest.","zh":"short quiz 指用來測試知識或製造興趣的簡短問題組。"},{"en":"A short quiz after a video can help students remember key facts.","zh":"影片後的小測驗可以幫助學生記住重點資料。"},{"en":"Quizzes make viewers active because they must think and answer.","zh":"小測驗令觀眾變得主動，因為他們必須思考和回答。"},{"en":"A short quiz about the marathon can keep students engaged after watching.","zh":"關於馬拉松的小測驗可以令學生觀看後仍保持投入。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"full marathon","meaning":"全程馬拉松","examples":[{"en":"A quiz could ask how long a full marathon is.","zh":"小測驗可以問全程馬拉松有多長。"},{"en":"A full marathon is the complete standard marathon race, rather than a shorter running event.","zh":"full marathon 指完整標準馬拉松賽事，而不是較短跑步活動。"},{"en":"Beginners may first try shorter races before attempting a full marathon.","zh":"初學者可能先嘗試較短賽事，再挑戰全程馬拉松。"},{"en":"Mentioning a full marathon helps viewers understand the scale of the challenge.","zh":"提到全程馬拉松幫助觀眾理解挑戰的規模。"},{"en":"It can also make students appreciate the endurance needed by runners.","zh":"它也可以令學生欣賞跑手所需的耐力。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"nominate someone for","meaning":"提名某人參加……","examples":[{"en":"Students could nominate a teacher for the next running challenge.","zh":"學生可以提名一位老師參加下一次跑步挑戰。"},{"en":"To nominate someone for something means to suggest that person should take part or be chosen.","zh":"nominate someone for something 指建議某人參與或被選中。"},{"en":"Students may nominate a teacher for a charity cooking challenge.","zh":"學生可能提名一位老師參加慈善烹飪挑戰。"},{"en":"Nominations make activities more engaging because students help choose participants.","zh":"提名令活動更吸引，因為學生可以幫助選擇參加者。"},{"en":"This phrase shows how viewers can influence what happens next.","zh":"這個短語顯示觀眾如何影響下一步發生的事。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"running challenge","meaning":"跑步挑戰","examples":[{"en":"Students could nominate a teacher for the next running challenge.","zh":"學生可以提名一位老師參加下一次跑步挑戰。"},{"en":"A running challenge is a planned activity where people try to complete a running task.","zh":"running challenge 指人們嘗試完成跑步任務的有計劃活動。"},{"en":"A running challenge may ask students to jog for ten minutes or complete a fixed route.","zh":"跑步挑戰可能要求學生慢跑十分鐘或完成固定路線。"},{"en":"Challenges are useful because they turn advice about sport into action.","zh":"挑戰有用，因為它把關於運動的建議轉化為行動。"},{"en":"A teacher joining a running challenge may make students more willing to try.","zh":"老師參加跑步挑戰，可能令學生更願意嘗試。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"give students room to participate","meaning":"給學生參與空間","examples":[{"en":"Interactive elements would give students room to participate.","zh":"互動元素會給學生參與空間。"},{"en":"To give students room to participate means to create space or opportunities for students to take part.","zh":"give students room to participate 指創造空間或機會讓學生參與。"},{"en":"A live poll gives students room to participate during a school assembly.","zh":"即時投票在學校早會中給學生參與空間。"},{"en":"Students feel more connected when they can answer, vote, or suggest ideas.","zh":"當學生可以回答、投票或提出想法時，會感覺更有連繫。"},{"en":"Participation makes Campus TV feel like a shared school project.","zh":"參與令校園電視感覺像共同的校園項目。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"instead of merely watching","meaning":"而不是只觀看","examples":[{"en":"Students could participate instead of merely watching.","zh":"學生可以參與，而不是只觀看。"},{"en":"Instead of merely watching means rather than only looking at the programme without taking part.","zh":"instead of merely watching 指不只是觀看節目而不參與。"},{"en":"Students learn more when they answer questions instead of merely watching a video.","zh":"學生回答問題時，比只觀看影片學得更多。"},{"en":"This phrase contrasts passive viewing with active involvement.","zh":"這個短語對比被動觀看與主動參與。"},{"en":"Interactive elements encourage students to respond, not only receive information.","zh":"互動元素鼓勵學生回應，而不只是接收資訊。"}],"source":"2013 Q2.pdf","sourcePage":12},{"front":"familiar faces","meaning":"熟悉的面孔","examples":[{"en":"Students are more likely to respond when they see familiar faces.","zh":"當學生看見熟悉的面孔時，他們更可能作出回應。"},{"en":"Familiar faces are people viewers recognise, such as classmates, teachers, or schoolmates.","zh":"familiar faces 指觀眾認得的人，例如同學、老師或校友。"},{"en":"A Campus TV video feels more personal when familiar faces appear on screen.","zh":"當熟悉面孔出現在螢幕上時，校園電視影片會感覺更個人化。"},{"en":"Familiar faces attract attention because students wonder what people they know will do.","zh":"熟悉面孔會吸引注意，因為學生會好奇自己認識的人會做甚麼。"},{"en":"Showing familiar faces can make a school programme feel closer and more enjoyable.","zh":"展示熟悉面孔可以令校園節目感覺更貼近、更有趣。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"have a reason to respond","meaning":"有理由作出回應","examples":[{"en":"Students need a reason to respond to the programme.","zh":"學生需要有理由對節目作出回應。"},{"en":"To have a reason to respond means to be given a clear motivation or opportunity to react.","zh":"have a reason to respond 指獲得清楚動機或機會去作出反應。"},{"en":"A quiz gives students a reason to respond after watching a video.","zh":"小測驗給學生在觀看影片後作出回應的理由。"},{"en":"People respond more when they feel their answers or opinions matter.","zh":"當人們覺得自己的答案或意見重要時，會更願意回應。"},{"en":"The programme should invite students to act, not simply watch quietly.","zh":"節目應邀請學生行動，而不只是安靜觀看。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"the more…, the more likely…","meaning":"越……就越有可能……","examples":[{"en":"The more students see familiar faces, the more likely they are to talk about the programme.","zh":"學生越看見熟悉的面孔，就越有可能談論這個節目。"},{"en":"The more…, the more likely… shows that one increase raises the chance of another result.","zh":"the more…, the more likely… 顯示一件事增加時，另一個結果的可能性也提高。"},{"en":"The more students take part in filming, the more likely they are to watch the final video.","zh":"學生參與拍攝越多，就越有可能觀看最終影片。"},{"en":"This pattern is useful for explaining why interaction increases interest.","zh":"這個句式有助解釋互動為何增加興趣。"},{"en":"Familiar faces can turn a school programme into a topic of conversation.","zh":"熟悉面孔可以把校園節目變成談話話題。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"talk about the programme afterwards","meaning":"之後談論這個節目","examples":[{"en":"Students may talk about the programme afterwards.","zh":"學生可能之後談論這個節目。"},{"en":"To talk about the programme afterwards means to discuss it after watching it.","zh":"talk about the programme afterwards 指觀看後討論節目。"},{"en":"Students may talk about a funny campus challenge during recess.","zh":"學生可能在小息時談論有趣的校園挑戰。"},{"en":"A programme has stronger impact when viewers continue discussing it later.","zh":"當觀眾之後仍繼續討論，節目的影響會更強。"},{"en":"Good Campus TV content should create conversations beyond the screen.","zh":"好的校園電視內容應創造螢幕以外的對話。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, the Hong Kong Marathon would be the best choice.","zh":"總括而言，香港馬拉松會是最佳選擇。"},{"en":"All things considered means after thinking about all the important reasons and factors.","zh":"all things considered 指在考慮所有重要理由和因素之後。"},{"en":"All things considered, the school should choose a topic students can recognise and discuss.","zh":"總括而言，學校應選擇學生能認得和討論的題材。"},{"en":"Writers use this phrase near the conclusion to give a balanced final judgement.","zh":"作者常在結論附近使用這個短語，作出平衡的最後判斷。"},{"en":"It shows that the recommendation follows from the earlier arguments.","zh":"它顯示建議來自前面的論點。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"the best choice","meaning":"最佳選擇","examples":[{"en":"The Hong Kong Marathon would be the best choice for the programme.","zh":"香港馬拉松會是這個節目的最佳選擇。"},{"en":"The best choice means the most suitable option among the available possibilities.","zh":"best choice 指在可選項中最合適的選擇。"},{"en":"A local event may be the best choice when the audience is a school community.","zh":"當觀眾是學校社群時，本地活動可能是最佳選擇。"},{"en":"The best choice should match the programme’s aims, audience, and time limit.","zh":"最佳選擇應配合節目的目標、觀眾和時間限制。"},{"en":"The marathon is presented as the best choice because it combines sport, city life, and human stories.","zh":"馬拉松被呈現為最佳選擇，因為它結合運動、城市生活和人情故事。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"combine local identity with","meaning":"把本地身份與……結合","examples":[{"en":"The marathon combines local identity with dramatic visuals and personal stories.","zh":"馬拉松把本地身份與富戲劇性的畫面和個人故事結合起來。"},{"en":"To combine local identity with something means to bring together a sense of place and other attractive elements.","zh":"combine local identity with something 指把地方感與其他吸引元素結合起來。"},{"en":"A school video can combine local identity with student interviews and old photographs.","zh":"學校影片可以把本地身份與學生訪問和舊相片結合起來。"},{"en":"Combining these elements makes a programme both visually strong and meaningful.","zh":"結合這些元素會令節目既有視覺力量，又有意義。"},{"en":"The marathon works well because it connects Hong Kong places with human effort.","zh":"馬拉松有效，因為它把香港地方與人的努力連接起來。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"local identity","meaning":"本地身份認同","examples":[{"en":"The marathon shows Hong Kong’s local identity.","zh":"馬拉松展示香港的本地身份認同。"},{"en":"Local identity is the feeling, character, and culture that make a place recognisably itself.","zh":"local identity 指令一個地方清楚有自己特色的感覺、性格和文化。"},{"en":"Local identity can appear through streets, language, food, habits, and public events.","zh":"本地身份可以透過街道、語言、食物、習慣和公共活動出現。"},{"en":"A marathon route through familiar districts can show a city’s local identity.","zh":"穿過熟悉地區的馬拉松路線，可以展示城市的本地身份。"},{"en":"Showing local identity helps students feel the programme belongs to them.","zh":"展示本地身份能幫助學生感到節目屬於他們。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"dramatic visuals","meaning":"富戲劇性的畫面","examples":[{"en":"The marathon would provide dramatic visuals for Campus TV.","zh":"馬拉松會為校園電視提供富戲劇性的畫面。"},{"en":"Dramatic visuals are powerful or striking images that catch attention and create emotion.","zh":"dramatic visuals 指有力量或醒目、能吸引注意和製造情感的影像。"},{"en":"Crowds cheering beside city roads can create dramatic visuals in a sports programme.","zh":"人群在城市道路旁打氣，可以在體育節目中創造富戲劇性的畫面。"},{"en":"Dramatic visuals help viewers feel the scale and energy of an event.","zh":"富戲劇性的畫面幫助觀眾感受活動的規模和能量。"},{"en":"For Campus TV, strong images can make the programme more memorable.","zh":"對校園電視來說，強烈影像可以令節目更難忘。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"relatable personal stories","meaning":"令人有共鳴的個人故事","examples":[{"en":"The programme would include relatable personal stories.","zh":"這個節目會包括令人有共鳴的個人故事。"},{"en":"Relatable personal stories are individual experiences that viewers can understand or connect with.","zh":"relatable personal stories 指觀眾能理解或產生連繫的個人經驗。"},{"en":"A student runner’s story about overcoming laziness can be relatable to classmates.","zh":"學生跑手關於克服懶惰的故事，可能令同學有共鳴。"},{"en":"Relatable stories make viewers care because the feelings are familiar.","zh":"有共鳴的故事令觀眾關心，因為感受熟悉。"},{"en":"These stories help the marathon feel less distant and more human.","zh":"這些故事令馬拉松不那麼遙遠，而更有人情味。"}],"source":"2013 Q2.pdf","sourcePage":13},{"front":"with your approval","meaning":"如獲你批准","examples":[{"en":"With your approval, I will draft a shooting schedule.","zh":"如獲你批准，我會草擬拍攝時間表。"},{"en":"With your approval means if you agree or give permission.","zh":"with your approval 指如果你同意或給予許可。"},{"en":"With your approval, the media team can begin contacting interviewees.","zh":"如獲你批准，媒體團隊可以開始聯絡受訪者。"},{"en":"This phrase is polite because it recognises the reader’s authority.","zh":"這個短語很有禮貌，因為它承認讀者的權限。"},{"en":"It also shows that the writer is ready to act once permission is given.","zh":"它也顯示作者一旦獲准，已準備好行動。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"draft a shooting schedule","meaning":"草擬拍攝時間表","examples":[{"en":"I will draft a shooting schedule for the programme.","zh":"我會為節目草擬拍攝時間表。"},{"en":"To draft a shooting schedule means to prepare a plan for when and where filming will happen.","zh":"draft a shooting schedule 指準備拍攝何時何地進行的計劃。"},{"en":"A student producer may draft a shooting schedule before interviewing teachers.","zh":"學生製作人可能在訪問老師前草擬拍攝時間表。"},{"en":"A shooting schedule helps the team manage time, locations, equipment, and people.","zh":"拍攝時間表幫助團隊管理時間、地點、器材和人員。"},{"en":"Drafting it early makes production smoother and more organised.","zh":"及早草擬時間表令製作更順暢和有條理。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"contact the PE Department","meaning":"聯絡體育科","examples":[{"en":"I will contact the PE Department for advice.","zh":"我會聯絡體育科尋求建議。"},{"en":"To contact the PE Department means to communicate with the teachers responsible for physical education.","zh":"contact the PE Department 指與負責體育教育的老師溝通。"},{"en":"Students may contact the PE Department before organising a running challenge.","zh":"學生在舉辦跑步挑戰前可能會聯絡體育科。"},{"en":"The department can advise on safety, warm-ups, route design, and suitable exercises.","zh":"體育科可以就安全、熱身、路線設計和合適練習提供建議。"},{"en":"Contacting experts helps make the programme accurate and safe.","zh":"聯絡專業人士有助令節目準確和安全。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"form a small production team","meaning":"組成小型製作團隊","examples":[{"en":"I will form a small production team for filming, interviewing, and editing.","zh":"我會組成小型製作團隊，負責拍攝、訪問和剪接。"},{"en":"To form a small production team means to create a small group responsible for making the programme.","zh":"form a small production team 指建立一個負責製作節目的小組。"},{"en":"A Campus TV project may form a team of presenters, camera operators, and editors.","zh":"校園電視項目可以組成包括主持、攝影和剪接人員的團隊。"},{"en":"A small team can work efficiently if each member has a clear role.","zh":"如果每名成員角色清晰，小型團隊可以高效工作。"},{"en":"Forming the team early helps the programme move from idea to action.","zh":"及早組成團隊，有助節目由想法走向行動。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"production team","meaning":"製作團隊","examples":[{"en":"The production team would handle filming, interviewing, and editing.","zh":"製作團隊會處理拍攝、訪問和剪接。"},{"en":"A production team is the group of people who plan and create a video, show, or programme.","zh":"production team 指計劃和製作影片、節目或演出的團隊。"},{"en":"A school production team may include students who manage cameras, sound, captions, and editing.","zh":"學校製作團隊可能包括負責攝影、收音、字幕和剪接的學生。"},{"en":"Production teams need cooperation because each part affects the final programme.","zh":"製作團隊需要合作，因為每個部分都影響最終節目。"},{"en":"A strong production team makes the proposal more realistic.","zh":"強大的製作團隊令建議更實際。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"filming, interviewing and editing","meaning":"拍攝、訪問和剪接","examples":[{"en":"The team would be responsible for filming, interviewing, and editing.","zh":"團隊會負責拍攝、訪問和剪接。"},{"en":"Filming, interviewing and editing are the main steps of recording video, asking questions, and shaping the final programme.","zh":"filming, interviewing and editing 指錄影、提問和整理最終節目的主要步驟。"},{"en":"Students practise filming by capturing scenes, interviewing by asking clear questions, and editing by choosing useful clips.","zh":"學生透過拍攝場景練習拍攝、透過提清楚問題練習訪問、透過選擇有用片段練習剪接。"},{"en":"These skills turn raw material into a watchable programme.","zh":"這些技能把原始素材變成可觀看的節目。"},{"en":"Listing these tasks shows that the production plan is practical and complete.","zh":"列出這些任務顯示製作計劃實際而完整。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"I would appreciate it if","meaning":"如你能……我將不勝感激","examples":[{"en":"I would appreciate it if you could let me know whether this direction is suitable.","zh":"如你能讓我知道這個方向是否合適，我將不勝感激。"},{"en":"I would appreciate it if is a polite formal phrase used to make a request.","zh":"I would appreciate it if 是用來提出請求的禮貌正式短語。"},{"en":"I would appreciate it if you could give feedback on the programme outline.","zh":"如你能就節目大綱給予回饋，我將不勝感激。"},{"en":"This phrase sounds respectful because it asks rather than demands.","zh":"這個短語聽起來尊重，因為它是請求而不是命令。"},{"en":"It is useful when writing to a teacher or supervisor for approval.","zh":"寫信給老師或負責人請求批准時，這個短語很有用。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"let me know whether","meaning":"讓我知道是否","examples":[{"en":"Please let me know whether this direction is suitable.","zh":"請讓我知道這個方向是否合適。"},{"en":"Let me know whether means tell me if something is true, acceptable, or preferred.","zh":"let me know whether 指告訴我某事是否真實、可接受或較合適。"},{"en":"Please let me know whether the filming date works for the PE Department.","zh":"請讓我知道拍攝日期是否適合體育科。"},{"en":"This phrase is useful when asking for confirmation before taking action.","zh":"這個短語在採取行動前要求確認時很有用。"},{"en":"It keeps communication clear because the writer needs a decision.","zh":"它令溝通保持清晰，因為作者需要一個決定。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"this direction is suitable","meaning":"這個方向是否合適","examples":[{"en":"I hope you can tell me whether this direction is suitable.","zh":"我希望你可以告訴我這個方向是否合適。"},{"en":"This direction is suitable means this plan, approach, or topic fits the purpose and audience.","zh":"this direction is suitable 指這個計劃、做法或題材符合目的和觀眾需要。"},{"en":"A teacher may say the project direction is suitable if it matches the assignment aim.","zh":"如果項目方向符合功課目標，老師可能會說這個方向合適。"},{"en":"Asking whether the direction is suitable helps the writer avoid wasting time on the wrong plan.","zh":"詢問方向是否合適，幫助作者避免在錯誤計劃上浪費時間。"},{"en":"The phrase shows openness to feedback before production begins.","zh":"這個短語顯示作者在製作開始前願意接受回饋。"}],"source":"2013 Q2.pdf","sourcePage":14},{"front":"Yours sincerely","meaning":"謹啟","examples":[{"en":"Yours sincerely, Chris Wong.","zh":"Chris Wong 謹啟。"},{"en":"Yours sincerely is a polite formal closing used when ending a letter or email.","zh":"Yours sincerely 是結束信件或電郵時使用的禮貌正式結語。"},{"en":"A student may write Yours sincerely before signing a proposal to a teacher.","zh":"學生向老師提交建議書時，可能在簽名前寫 Yours sincerely。"},{"en":"This closing makes the message sound respectful and complete.","zh":"這個結語令訊息聽起來尊重而完整。"},{"en":"It is suitable for formal school emails, recommendations, and proposals.","zh":"它適合用於正式學校電郵、推薦信和建議書。"}],"source":"2013 Q2.pdf","sourcePage":14}],"dse/writing/part-b/2013/Q3":[{"front":"Dear Diary","meaning":"親愛的日記","examples":[{"en":"The diary entry begins with Dear Diary.","zh":"這篇日記以「親愛的日記」開始。"},{"en":"Dear Diary is a common opening used when someone writes privately to their diary.","zh":"Dear Diary 是人們私下寫日記時常用的開首語。"},{"en":"A student may write “Dear Diary” before describing a difficult school day.","zh":"學生可能在描述艱難上學日之前寫下「親愛的日記」。"},{"en":"This opening makes the writing feel personal, honest, and private.","zh":"這個開首令文字感覺個人化、誠實而私密。"},{"en":"In this entry, “Dear Diary” prepares readers for a confession rather than a formal report.","zh":"在這篇日記中，「親愛的日記」讓讀者準備讀到一段告白，而不是正式報告。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"cannot begin to describe","meaning":"無法形容","examples":[{"en":"I cannot begin to describe how heavy my schoolbag felt today.","zh":"我無法形容今天我的書包感覺有多沉重。"},{"en":"Cannot begin to describe means something is so strong that ordinary words feel insufficient.","zh":"cannot begin to describe 指某種感受太強烈，普通言語都顯得不足夠。"},{"en":"I cannot begin to describe how nervous I felt before the results were announced.","zh":"成績公布前，我無法形容自己有多緊張。"},{"en":"People use this phrase when an emotion is too deep, painful, or complicated to explain easily.","zh":"當情緒太深、太痛苦或太複雜而難以解釋時，人們會使用這個片語。"},{"en":"The writer uses it because the heavy schoolbag also represents guilt.","zh":"作者使用它，因為沉重的書包也象徵內疚。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"schoolbag felt heavy","meaning":"書包感覺很沉重","examples":[{"en":"My schoolbag felt unusually heavy today.","zh":"今天我的書包感覺異常沉重。"},{"en":"Schoolbag felt heavy means the bag seemed physically or emotionally difficult to carry.","zh":"schoolbag felt heavy 指書包在身體上或情緒上都讓人難以背負。"},{"en":"A student’s schoolbag may feel heavy after a long day with many books.","zh":"學生帶着很多書上了一整天課後，書包可能感覺很沉重。"},{"en":"A bag can feel heavier when the person carrying it is worried or guilty.","zh":"當背書包的人擔心或內疚時，書包也可能感覺更重。"},{"en":"In the diary, the heavy schoolbag reflects the writer’s troubled conscience.","zh":"在日記中，沉重的書包反映作者不安的良心。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"might as well have contained","meaning":"簡直像是裝著","examples":[{"en":"My schoolbag might as well have contained a knife.","zh":"我的書包簡直像是裝着一把刀。"},{"en":"Might as well have contained means it felt as if something harmful or painful was inside, even if it was not literal.","zh":"might as well have contained 指感覺好像裏面有傷人或痛苦的東西，即使不是字面意思。"},{"en":"After lying to his friend, his pocket might as well have contained a stone.","zh":"對朋友說謊後，他的口袋簡直像是裝着一塊石頭。"},{"en":"This phrase uses exaggeration to show emotional weight.","zh":"這個片語用誇張手法表達情感上的重量。"},{"en":"The writer feels the screenshots in the bag were almost like a weapon.","zh":"作者覺得書包裏的截圖幾乎像一件武器。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"drama class","meaning":"戲劇課","examples":[{"en":"Ms Lau asked a difficult question in drama class.","zh":"劉老師在戲劇課問了一個困難問題。"},{"en":"Drama class is a lesson where students study plays, characters, performance, and moral choices.","zh":"drama class 是學生學習劇本、角色、表演和道德選擇的課堂。"},{"en":"Students may act out scenes or discuss motives in drama class.","zh":"學生可能在戲劇課演出場景或討論人物動機。"},{"en":"A drama class can make students connect literature with their own lives.","zh":"戲劇課可以令學生把文學與自己生活連繫起來。"},{"en":"The question about Brutus later echoed painfully in the writer’s real situation.","zh":"關於布魯圖斯的問題後來痛苦地呼應了作者的真實處境。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"whether…or…","meaning":"是……還是……","examples":[{"en":"Ms Lau asked whether Brutus was a villain or a patriot.","zh":"劉老師問布魯圖斯是反派還是愛國者。"},{"en":"Whether…or… presents two possible choices or descriptions.","zh":"whether…or… 用來提出兩個可能的選擇或描述。"},{"en":"The class discussed whether the character was brave or foolish.","zh":"全班討論那個角色是勇敢還是愚蠢。"},{"en":"This structure is useful when a question has two competing answers.","zh":"當問題有兩個互相競爭的答案時，這個結構很有用。"},{"en":"The writer later wonders whether he saved Ryan or destroyed him.","zh":"作者後來也在想，自己是救了 Ryan 還是毀了他。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"a villain or a patriot","meaning":"反派還是愛國者","examples":[{"en":"The class discussed whether Brutus was a villain or a patriot.","zh":"全班討論布魯圖斯是反派還是愛國者。"},{"en":"A villain is a bad or harmful person, while a patriot acts for their country.","zh":"villain 指壞人或傷害他人的人，而 patriot 指為國家行事的人。"},{"en":"A person can look like a villain to friends but like a patriot to the public.","zh":"一個人對朋友來說可能像反派，但對公眾來說像愛國者。"},{"en":"This contrast asks whether betrayal can ever be morally justified.","zh":"這個對比追問背叛是否可能在道德上有理由。"},{"en":"The phrase prepares the diary’s central conflict between loyalty and honesty.","zh":"這個片語預示日記中忠誠與誠實之間的核心衝突。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"betrayed Caesar","meaning":"背叛凱撒","examples":[{"en":"Brutus betrayed Caesar “for Rome”.","zh":"布魯圖斯「為了羅馬」背叛凱撒。"},{"en":"Betrayed Caesar means Brutus turned against Caesar, although Caesar had trusted him.","zh":"betrayed Caesar 指布魯圖斯背棄了信任他的凱撒。"},{"en":"A friend betrays another person when they reveal a secret or act against them.","zh":"當朋友透露秘密或做出傷害對方的事，就是背叛對方。"},{"en":"Betrayal hurts more deeply when it comes from someone close.","zh":"背叛若來自親近的人，傷害會更深。"},{"en":"The writer compares himself with Brutus because he also acted against a friend for a reason he thought was right.","zh":"作者把自己與布魯圖斯比較，因為他也為了自己認為正確的理由背叛朋友。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"for Rome","meaning":"為了羅馬","examples":[{"en":"Brutus claimed that he acted for Rome.","zh":"布魯圖斯聲稱自己是為了羅馬而行動。"},{"en":"For Rome means for the good of Rome, not for personal pleasure.","zh":"for Rome 指為了羅馬的利益，而不是為個人快樂。"},{"en":"A leader may claim to act for the country when making a painful decision.","zh":"領袖作出痛苦決定時，可能聲稱自己是為了國家。"},{"en":"Saying “for Rome” can make betrayal sound noble, but it does not remove the harm.","zh":"說「為了羅馬」可以令背叛聽起來高尚，但不能消除傷害。"},{"en":"The writer later wonders whether “for fairness” is enough to excuse hurting Ryan.","zh":"作者後來也在想，「為了公平」是否足以解釋自己傷害 Ryan。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"answer too quickly","meaning":"回答得太快","examples":[{"en":"I answered too quickly in drama class.","zh":"我在戲劇課回答得太快。"},{"en":"Answer too quickly means respond before thinking deeply enough.","zh":"answer too quickly 指還未充分思考就作答。"},{"en":"A student may answer too quickly and later realise the question was more complicated.","zh":"學生可能回答得太快，後來才發現問題更複雜。"},{"en":"Quick answers can sound confident but miss moral difficulty.","zh":"快速答案可以聽起來很有信心，但可能忽略道德困難。"},{"en":"The writer’s quick answer becomes troubling when real life tests it.","zh":"當現實生活考驗那個答案時，作者才開始不安。"}],"source":"2013 Q3.pdf","sourcePage":1},{"front":"what he thought was right","meaning":"他認為正確的事","examples":[{"en":"Brutus did what he thought was right.","zh":"布魯圖斯做了他認為正確的事。"},{"en":"What he thought was right means the action he believed was morally correct.","zh":"what he thought was right 指他相信在道德上正確的行動。"},{"en":"A student may report cheating because she thinks it is right, even if it hurts a friend.","zh":"學生可能因認為舉報作弊是正確的，即使會傷害朋友仍然這樣做。"},{"en":"Believing something is right does not always make the result painless.","zh":"相信某事正確，不代表結果不會痛苦。"},{"en":"The diary asks whether doing what seems right can still feel like betrayal.","zh":"這篇日記追問做自己認為正確的事是否仍可能像背叛。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"no longer sounded clever","meaning":"聽起來不再聰明","examples":[{"en":"By four o’clock, my answer no longer sounded clever.","zh":"到四點鐘時，我的答案聽起來不再聰明。"},{"en":"No longer sounded clever means an idea that once seemed smart now feels foolish or troubling.","zh":"no longer sounded clever 指原本看似聰明的想法，現在變得愚蠢或令人不安。"},{"en":"A joke may no longer sound clever after it hurts someone.","zh":"一個笑話傷害別人後，可能聽起來不再聰明。"},{"en":"Words can change meaning when real consequences appear.","zh":"當真實後果出現，說過的話會改變意思。"},{"en":"The writer’s classroom answer feels less clever after he betrays Ryan.","zh":"作者背叛 Ryan 後，課堂上的答案變得不再聰明。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"sounded dangerous","meaning":"聽起來危險","examples":[{"en":"By four o’clock, my answer sounded dangerous.","zh":"到四點鐘時，我的答案聽起來危險。"},{"en":"Sounded dangerous means the idea seemed able to cause harm or justify hurtful action.","zh":"sounded dangerous 指那個想法似乎可能造成傷害或合理化傷人行為。"},{"en":"A simple rule can sound dangerous if people use it without compassion.","zh":"如果人們毫無同情心地使用簡單規則，它可能聽起來危險。"},{"en":"Saying “I did what was right” may sound dangerous when it hides another person’s pain.","zh":"當「我做了正確的事」掩蓋別人的痛苦時，這句話可能聽起來危險。"},{"en":"The writer fears his moral answer has become a weapon.","zh":"作者害怕自己的道德答案變成了武器。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"the person I betrayed","meaning":"我背叛的人","examples":[{"en":"The person I betrayed was Ryan.","zh":"我背叛的人是 Ryan。"},{"en":"The person I betrayed means the person I acted against after they trusted me.","zh":"the person I betrayed 指信任我、卻被我背棄的人。"},{"en":"Betraying a stranger is bad, but betraying a close friend feels even heavier.","zh":"背叛陌生人已經不好，但背叛親密朋友感覺更沉重。"},{"en":"Naming the person makes the guilt specific and personal.","zh":"說出那個人的名字，令內疚變得具體而個人化。"},{"en":"Ryan is not an abstract problem; he is the writer’s best friend.","zh":"Ryan 不是抽象問題；他是作者最好的朋友。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"best friend since","meaning":"自……以來的好朋友","examples":[{"en":"Ryan had been my best friend since Primary Four.","zh":"Ryan 自小四以來一直是我最好的朋友。"},{"en":"Best friend since means someone has been one’s closest friend from a particular time until now.","zh":"best friend since 指某人從某個時間開始一直是自己最親密的朋友。"},{"en":"My cousin has been my best friend since kindergarten.","zh":"我的表姐自幼稚園以來一直是我最好的朋友。"},{"en":"A long friendship makes betrayal feel more painful because it carries years of trust.","zh":"長久友誼令背叛更痛，因為它承載多年信任。"},{"en":"The phrase shows that Ryan was not just a teammate but part of the writer’s history.","zh":"這個片語顯示 Ryan 不只是隊友，也是作者人生歷史的一部分。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"Primary Four","meaning":"小四","examples":[{"en":"Ryan had been my best friend since Primary Four.","zh":"Ryan 自小四以來一直是我最好的朋友。"},{"en":"Primary Four is the fourth year of primary school.","zh":"Primary Four 指小學第四年。"},{"en":"Children in Primary Four are usually old enough to form close school friendships.","zh":"小四學生通常已能建立親密的校園友誼。"},{"en":"A friendship from Primary Four can feel like it has lasted for most of childhood.","zh":"從小四開始的友誼，可能感覺像陪伴了大半個童年。"},{"en":"Mentioning Primary Four shows how long the writer and Ryan have known each other.","zh":"提到小四顯示作者和 Ryan 認識了很久。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"survive almost everything together","meaning":"一起熬過幾乎所有事情","examples":[{"en":"Ryan and I had survived almost everything together.","zh":"Ryan 和我一起熬過幾乎所有事情。"},{"en":"Survive almost everything together means go through many difficult experiences side by side.","zh":"survive almost everything together 指並肩經歷許多困難。"},{"en":"Friends may survive exams, arguments, and embarrassing moments together.","zh":"朋友可能一起熬過考試、爭執和尷尬時刻。"},{"en":"Shared hardship usually strengthens trust between friends.","zh":"共同經歷困難通常會加強朋友之間的信任。"},{"en":"This makes the later betrayal feel even more painful.","zh":"因此，後來的背叛感覺更加痛苦。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"first detention","meaning":"第一次留堂","examples":[{"en":"We survived our first detention together.","zh":"我們一起熬過第一次留堂。"},{"en":"First detention means the first time students had to stay after school as punishment.","zh":"first detention 指學生第一次因受罰而放學後留下來。"},{"en":"Students may feel scared during their first detention because they do not know what to expect.","zh":"學生第一次留堂時可能會害怕，因為不知道會發生甚麼。"},{"en":"Going through punishment together can become an embarrassing but shared memory.","zh":"一起受罰可以變成尷尬但共同的回憶。"},{"en":"The diary uses this memory to show how close the two friends were.","zh":"日記用這段回憶顯示兩個朋友有多親近。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"the lonely first week","meaning":"孤單的第一個星期","examples":[{"en":"We survived the lonely first week of Secondary One together.","zh":"我們一起熬過中一孤單的第一個星期。"},{"en":"The lonely first week means the difficult beginning when someone feels alone in a new place.","zh":"the lonely first week 指在新地方開始時感到孤單的艱難初期。"},{"en":"The first week at a new school can feel lonely because students do not yet know anyone well.","zh":"在新學校的第一個星期可能很孤單，因為學生還未真正認識別人。"},{"en":"Having one trusted friend can make a lonely week easier to bear.","zh":"有一位可信任的朋友，可以令孤單的一星期較容易承受。"},{"en":"Ryan helped the writer feel less alone during a frightening transition.","zh":"Ryan 幫助作者在可怕轉變中不那麼孤單。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"Secondary One","meaning":"中一","examples":[{"en":"The lonely first week of Secondary One was difficult.","zh":"中一孤單的第一個星期很困難。"},{"en":"Secondary One is the first year of secondary school.","zh":"Secondary One 指中學第一年。"},{"en":"Students in Secondary One often face new classmates, new teachers, and new rules.","zh":"中一學生常要面對新同學、新老師和新規則。"},{"en":"Starting Secondary One can be lonely until friendships become stronger.","zh":"開始中一時可能很孤單，直到友誼逐漸穩固。"},{"en":"The phrase shows an important stage in the writer and Ryan’s friendship.","zh":"這個片語顯示作者和 Ryan 友誼中的重要階段。"}],"source":"2013 Q3.pdf","sourcePage":2},{"front":"debate competition","meaning":"辯論比賽","examples":[{"en":"Ryan supported me during last year’s debate competition.","zh":"Ryan 在去年的辯論比賽中支持我。"},{"en":"A debate competition is an event where students argue for or against a topic in teams.","zh":"debate competition 是學生以小隊形式就題目正反辯論的活動。"},{"en":"Students in a debate competition need clear speech, evidence, and confidence.","zh":"辯論比賽中的學生需要清楚說話、證據和信心。"},{"en":"Support from teammates can help a nervous speaker continue.","zh":"隊友的支持可以幫助緊張的講者繼續。"},{"en":"Ryan’s support during the competition became proof of his loyalty.","zh":"Ryan 在比賽中的支持成為他忠誠的證明。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"froze on stage","meaning":"在台上呆住","examples":[{"en":"I froze on stage during the debate competition.","zh":"我在辯論比賽中在台上呆住了。"},{"en":"Froze on stage means suddenly became unable to speak or move because of fear.","zh":"froze on stage 指因恐懼而突然無法說話或移動。"},{"en":"A performer may freeze on stage when the audience feels too large.","zh":"當觀眾太多時，表演者可能在台上呆住。"},{"en":"Freezing on stage can feel humiliating unless someone offers support.","zh":"在台上呆住可以很尷尬，除非有人提供支持。"},{"en":"Ryan helped the writer through a moment of public fear.","zh":"Ryan 幫助作者度過公開恐懼的一刻。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"whispered","meaning":"低聲說","examples":[{"en":"Ryan whispered, “Breathe. I’m here.”","zh":"Ryan 低聲說：「呼吸。我在這裏。」"},{"en":"Whispered means spoke very softly and quietly.","zh":"whispered 指非常輕聲和安靜地說話。"},{"en":"A friend may whisper encouragement before a performance begins.","zh":"朋友可能在表演開始前低聲鼓勵。"},{"en":"Whispering can feel private and comforting even in a public place.","zh":"即使在公開場合，低聲說話也可以感覺私密而安慰人。"},{"en":"Ryan’s quiet words helped the writer feel less alone on stage.","zh":"Ryan 安靜的話幫助作者在台上不那麼孤單。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"no words can do justice to","meaning":"言語無法充分表達","examples":[{"en":"No words can do justice to what Ryan’s support meant to me.","zh":"言語無法充分表達 Ryan 的支持對我有多重要。"},{"en":"No words can do justice to means language cannot fully express the value or feeling of something.","zh":"no words can do justice to 指語言無法完全表達某事的價值或感受。"},{"en":"No words can do justice to a parent’s sacrifice during difficult years.","zh":"言語無法充分表達父母在艱難歲月中的犧牲。"},{"en":"People use this phrase when gratitude or pain feels larger than explanation.","zh":"當感激或痛苦大於解釋時，人們會使用這個片語。"},{"en":"The writer cannot fully explain how much Ryan’s friendship once mattered.","zh":"作者無法完全說明 Ryan 的友誼曾經有多重要。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"the kind of friend who","meaning":"那種會……的朋友","examples":[{"en":"Ryan is the kind of friend who notices small changes in me.","zh":"Ryan 是那種會注意到我細微變化的朋友。"},{"en":"The kind of friend who means a friend with a particular caring quality or habit.","zh":"the kind of friend who 指具有某種關心特質或習慣的朋友。"},{"en":"She is the kind of friend who remembers when you are quiet, not only when you cry.","zh":"她是那種不只在你哭時才留意，也會在你沉默時記得你的朋友。"},{"en":"This phrase helps describe character through behaviour.","zh":"這個片語透過行為描述品格。"},{"en":"Ryan’s attention to small changes makes the betrayal feel even harder.","zh":"Ryan 對細微變化的留意，令背叛感覺更加艱難。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"half working","meaning":"只勉強撐起","examples":[{"en":"Ryan notices when my smile is only half working.","zh":"Ryan 會注意到我的笑容只勉強撐起。"},{"en":"Half working means only partly successful or not fully real.","zh":"half working 指只部分成功，或並非完全真實。"},{"en":"A smile is half working when someone tries to look fine but still seems sad.","zh":"當一個人努力看起來沒事但仍顯得傷心，笑容就是只勉強撐起。"},{"en":"Close friends can notice emotions that others miss.","zh":"親密朋友能注意到別人看不見的情緒。"},{"en":"Ryan knew the writer well enough to see behind a weak smile.","zh":"Ryan 足夠了解作者，能看穿勉強的笑容。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"made today unbearable","meaning":"令今天難以承受","examples":[{"en":"That is what made today unbearable.","zh":"這就是令今天難以承受的原因。"},{"en":"Made today unbearable means caused the day to feel too painful or difficult to endure.","zh":"made today unbearable 指令這一天痛苦或困難到難以忍受。"},{"en":"A fight with a close friend can make an ordinary school day unbearable.","zh":"與親密朋友爭執，可以令普通上學日變得難以承受。"},{"en":"Guilt becomes harder when the person hurt is someone deeply caring.","zh":"當被傷害的人曾經深深關心自己，內疚就更難受。"},{"en":"The writer suffers because he betrayed someone who had always understood him.","zh":"作者痛苦，因為他背叛了一個一直理解他的人。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"prepare for","meaning":"為……作準備","examples":[{"en":"Our school is preparing for the Inter-school English Drama Competition.","zh":"我們學校正在為聯校英文戲劇比賽作準備。"},{"en":"Prepare for means get ready for an event, task, or challenge.","zh":"prepare for 指為活動、任務或挑戰做好準備。"},{"en":"Students prepare for a competition by rehearsing, revising scripts, and learning lines.","zh":"學生透過排練、修改劇本和背台詞為比賽作準備。"},{"en":"Good preparation reduces mistakes and builds confidence.","zh":"良好準備能減少錯誤並建立信心。"},{"en":"The school’s preparation makes Ryan’s copied script especially serious.","zh":"學校的準備令 Ryan 抄襲劇本一事特別嚴重。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"Inter-school English Drama Competition","meaning":"聯校英文戲劇比賽","examples":[{"en":"Our school is preparing for the Inter-school English Drama Competition.","zh":"我們學校正在為聯校英文戲劇比賽作準備。"},{"en":"The Inter-school English Drama Competition is a contest where schools perform English plays against one another.","zh":"Inter-school English Drama Competition 是不同學校以英文戲劇表演互相比賽的活動。"},{"en":"Students in such a competition need teamwork, pronunciation, acting, and confidence.","zh":"參加這類比賽的學生需要團隊合作、發音、演技和信心。"},{"en":"A dishonest script can damage the whole school team’s entry.","zh":"不誠實的劇本會傷害整個學校隊伍的參賽資格。"},{"en":"The competition gives the betrayal a public and ethical weight.","zh":"這場比賽令背叛帶有公開和道德重量。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"wrote most of","meaning":"寫了……的大部分","examples":[{"en":"Ryan wrote most of our script.","zh":"Ryan 寫了我們劇本的大部分。"},{"en":"Wrote most of means produced the largest part of a piece of writing.","zh":"wrote most of 指創作了一份文字作品的大部分內容。"},{"en":"In a group project, one student may write most of the report.","zh":"在小組專題中，一名學生可能寫了報告的大部分。"},{"en":"Writing most of the script gave Ryan influence over the whole team.","zh":"寫了劇本大部分內容，令 Ryan 對整個團隊有很大影響。"},{"en":"Because Ryan wrote so much, the copied scenes affected everyone.","zh":"因為 Ryan 寫了很多，抄襲場景影響了所有人。"}],"source":"2013 Q3.pdf","sourcePage":3},{"front":"sharp, funny and painful","meaning":"犀利、有趣而恰到好處地令人心痛","examples":[{"en":"The script was sharp, funny and painful in all the right places.","zh":"劇本在恰當之處犀利、有趣而令人心痛。"},{"en":"Sharp, funny and painful means clever, humorous, and emotionally touching.","zh":"sharp, funny and painful 指聰明機智、有幽默感，並能在情感上打動人。"},{"en":"A good play can be funny in one scene and painful in the next.","zh":"好劇本可以上一幕有趣，下一幕令人心痛。"},{"en":"Strong writing often balances wit with real feeling.","zh":"有力的寫作常能平衡機智和真實情感。"},{"en":"Ryan’s talent makes his cheating more disappointing.","zh":"Ryan 的才華令他的作弊更令人失望。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"in all the right places","meaning":"在恰當之處","examples":[{"en":"The script was painful in all the right places.","zh":"劇本在恰當之處令人心痛。"},{"en":"In all the right places means at exactly the moments where that effect is suitable.","zh":"in all the right places 指正好在適合產生某種效果的時刻。"},{"en":"A speech can be humorous in all the right places without becoming silly.","zh":"演講可以在恰當之處幽默，而不變得愚蠢。"},{"en":"Good writing places emotion carefully so it feels earned.","zh":"好寫作會仔細安排情感，令它顯得自然有力。"},{"en":"This phrase shows why the script seemed impressive before the truth appeared.","zh":"這個片語顯示真相出現前，劇本為何看似出色。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"during lunch","meaning":"午膳期間","examples":[{"en":"During lunch, I found Ryan in the library.","zh":"午膳期間，我在圖書館找到 Ryan。"},{"en":"During lunch means in the lunch break or lunch period at school.","zh":"during lunch 指在學校午膳或午休時段。"},{"en":"Students may rehearse, study, or rest during lunch.","zh":"學生可能在午膳期間排練、溫習或休息。"},{"en":"A quiet library during lunch can become the place where secrets are found.","zh":"午膳期間安靜的圖書館可能成為秘密被發現的地方。"},{"en":"The writer discovers the copied file during an ordinary school break.","zh":"作者在一個普通校園休息時段發現了抄襲檔案。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"hunched over","meaning":"彎腰伏在……前","examples":[{"en":"I found Ryan hunched over a laptop.","zh":"我發現 Ryan 彎腰伏在手提電腦前。"},{"en":"Hunched over means bending the upper body forward over something.","zh":"hunched over 指上半身向前彎，伏在某物前。"},{"en":"A tired student may sit hunched over a desk while finishing homework.","zh":"疲倦學生可能彎腰伏在書桌前完成功課。"},{"en":"This posture can suggest pressure, secrecy, or deep concentration.","zh":"這種姿勢可以暗示壓力、秘密或高度集中。"},{"en":"Ryan hunched over the laptop as if he were hiding inside his work.","zh":"Ryan 伏在電腦前，彷彿把自己藏在作品裏。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"hidden behind","meaning":"隱藏在……後面","examples":[{"en":"Hidden behind his document was another file.","zh":"隱藏在他的文件後面的是另一個檔案。"},{"en":"Hidden behind means placed out of sight behind something else.","zh":"hidden behind 指被放在另一物後方而不容易看見。"},{"en":"A tab hidden behind another window may show what someone did not want others to see.","zh":"隱藏在另一個視窗後面的分頁，可能顯示某人不想讓別人看見的東西。"},{"en":"Something hidden behind ordinary work can reveal a secret.","zh":"隱藏在普通工作後面的東西，可能揭示秘密。"},{"en":"The other file behind Ryan’s document becomes the start of the crisis.","zh":"Ryan 文件後面的另一個檔案成為危機的開始。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"another file","meaning":"另一個檔案","examples":[{"en":"Another file was hidden behind Ryan’s document.","zh":"Ryan 的文件後面隱藏着另一個檔案。"},{"en":"Another file means a second digital document or item stored on the computer.","zh":"another file 指電腦中第二份數碼文件或項目。"},{"en":"A student may accidentally reveal another file while switching between windows.","zh":"學生切換視窗時可能意外露出另一個檔案。"},{"en":"In this diary, another file provides evidence that the script was not original.","zh":"在這篇日記中，另一個檔案提供了劇本並非原創的證據。"},{"en":"A small hidden file changes the writer’s friendship and team future.","zh":"一個小小隱藏檔案改變了作者的友誼和團隊前途。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"dated 2019","meaning":"日期為二零一九年","examples":[{"en":"The copied script was dated 2019.","zh":"那份被抄襲的劇本日期為二零一九年。"},{"en":"Dated 2019 means the file or document showed the year 2019 as its date.","zh":"dated 2019 指檔案或文件顯示年份是二零一九年。"},{"en":"A document dated 2019 must have existed before the current school script.","zh":"日期為二零一九年的文件，必然早於目前的學校劇本存在。"},{"en":"The date matters because it proves the older script came first.","zh":"日期重要，因為它證明較舊的劇本先出現。"},{"en":"This detail makes Ryan’s explanation harder to believe.","zh":"這個細節令 Ryan 的解釋更難令人相信。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"almost exactly the same as","meaning":"幾乎與……完全一樣","examples":[{"en":"Several scenes were almost exactly the same as ours.","zh":"幾個場景幾乎與我們的完全一樣。"},{"en":"Almost exactly the same as means nearly identical to something else.","zh":"almost exactly the same as 指幾乎與另一物完全相同。"},{"en":"Two essays with almost exactly the same sentences may suggest copying.","zh":"兩篇作文如果句子幾乎完全一樣，可能暗示抄襲。"},{"en":"Small changes do not remove suspicion if the structure and lines are nearly identical.","zh":"如果結構和台詞幾乎相同，小改動不能消除懷疑。"},{"en":"The similarity makes the writer fear that Ryan copied, not merely borrowed ideas.","zh":"這種相似令作者擔心 Ryan 是抄襲，而不只是借用想法。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"inspired","meaning":"受到啟發","examples":[{"en":"The scenes were not merely inspired by the other script.","zh":"那些場景不只是受到另一份劇本啟發。"},{"en":"Inspired means influenced by an idea while still creating something new.","zh":"inspired 指受某個想法影響，但仍創造出新的東西。"},{"en":"A poem may be inspired by a song but use different images and language.","zh":"一首詩可以受到歌曲啟發，但使用不同意象和語言。"},{"en":"Being inspired is acceptable when the new work is clearly original.","zh":"如果新作品明顯是原創的，受到啟發是可以接受的。"},{"en":"Ryan’s scenes seemed too similar to be only inspired.","zh":"Ryan 的場景太相似，不像只是受到啟發。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"influenced","meaning":"受影響","examples":[{"en":"The scenes were not simply influenced by the other script.","zh":"那些場景不只是受另一份劇本影響。"},{"en":"Influenced means affected by something in style, idea, or direction.","zh":"influenced 指在風格、想法或方向上受到某事影響。"},{"en":"A writer may be influenced by Shakespeare but still write original scenes.","zh":"作者可以受莎士比亞影響，但仍寫出原創場景。"},{"en":"Influence becomes a problem when it turns into copying.","zh":"當影響變成抄襲時，就會成為問題。"},{"en":"The writer realises Ryan’s work went beyond influence.","zh":"作者意識到 Ryan 的作品已超越單純影響。"}],"source":"2013 Q3.pdf","sourcePage":4},{"front":"copied","meaning":"抄襲的","examples":[{"en":"Several scenes were copied.","zh":"幾個場景是抄襲的。"},{"en":"Copied means taken from another source without enough original change or proper honesty.","zh":"copied 指從另一來源取用，而沒有足夠原創改動或誠實交代。"},{"en":"Copying another student’s paragraph is cheating, even if a few words are changed.","zh":"抄襲另一名學生的段落，即使改了幾個字，也是作弊。"},{"en":"Copied work damages trust because it pretends to be original.","zh":"抄襲作品會破壞信任，因為它假裝是原創。"},{"en":"The copied scenes force the writer to choose between friendship and fairness.","zh":"被抄襲的場景迫使作者在友誼和公平之間選擇。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"at first","meaning":"起初","examples":[{"en":"At first, I wanted to believe there was an explanation.","zh":"起初，我想相信事情有某種解釋。"},{"en":"At first means in the beginning, before thoughts or events changed.","zh":"at first 指一開始，在想法或事件改變之前。"},{"en":"At first, she thought the mistake was accidental, but later evidence proved otherwise.","zh":"起初，她以為錯誤是意外，但後來證據證明並非如此。"},{"en":"This phrase shows the writer’s first hopeful reaction.","zh":"這個片語顯示作者最初抱有希望的反應。"},{"en":"The writer initially tries to protect Ryan in his own mind.","zh":"作者一開始在心裏嘗試保護 Ryan。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"some explanation","meaning":"某種解釋","examples":[{"en":"I wanted to believe there was some explanation.","zh":"我想相信事情有某種解釋。"},{"en":"Some explanation means a possible reason that could make the situation less wrong or less shocking.","zh":"some explanation 指一個可能理由，能令情況不那麼錯或不那麼震驚。"},{"en":"A teacher may hope there is some explanation when a good student cheats.","zh":"當好學生作弊時，老師可能希望事情有某種解釋。"},{"en":"People search for explanations when the truth is too painful to accept immediately.","zh":"當真相太痛而不能立刻接受，人們會尋找解釋。"},{"en":"The writer wants an explanation because Ryan’s action does not match his friend’s image.","zh":"作者想要一個解釋，因為 Ryan 的行為與他心中的朋友形象不符。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"comparing structures","meaning":"比較結構","examples":[{"en":"Perhaps Ryan was only comparing structures.","zh":"也許 Ryan 只是比較結構。"},{"en":"Comparing structures means looking at how two pieces of writing are organised.","zh":"comparing structures 指觀察兩份作品如何組織。"},{"en":"Students may compare structures to learn how scenes are arranged.","zh":"學生可能比較結構，以學習場景如何安排。"},{"en":"Comparing structures can be a legitimate study method if the final work is original.","zh":"如果最後作品是原創的，比較結構可以是正當學習方法。"},{"en":"The writer hopes Ryan was studying form, not stealing content.","zh":"作者希望 Ryan 只是在研究形式，而不是偷取內容。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"the lines were temporary","meaning":"台詞只是暫時的","examples":[{"en":"I hoped the lines were only temporary.","zh":"我希望那些台詞只是暫時的。"},{"en":"The lines were temporary means the copied words were not meant to stay in the final version.","zh":"the lines were temporary 指那些被抄的文字並不是要留在最終版本。"},{"en":"A writer may put rough lines in a draft and replace them later.","zh":"作者可能在草稿中放入粗略句子，稍後再替換。"},{"en":"Temporary lines are less serious if they are clearly removed before submission.","zh":"如果暫時台詞在提交前明確刪除，問題會較不嚴重。"},{"en":"The writer hopes the copied dialogue was only part of an unfinished draft.","zh":"作者希望被抄的對白只是未完成草稿的一部分。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"went pale","meaning":"臉色發白","examples":[{"en":"Ryan went pale when I asked him about the script.","zh":"我問 Ryan 關於劇本的事時，他臉色發白。"},{"en":"Went pale means someone’s face lost colour because of shock, fear, or guilt.","zh":"went pale 指一個人因震驚、恐懼或內疚而臉上失去血色。"},{"en":"A student may go pale when the teacher mentions missing homework.","zh":"老師提到未交功課時，學生可能臉色發白。"},{"en":"Going pale can reveal fear before a person says anything.","zh":"臉色發白可以在一個人說話前透露恐懼。"},{"en":"Ryan’s pale face suggests he knows the writer has found something serious.","zh":"Ryan 發白的臉色暗示他知道作者發現了嚴重事情。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"just this once","meaning":"就這一次","examples":[{"en":"Ryan asked me to keep quiet just this once.","zh":"Ryan 叫我就這一次保持沉默。"},{"en":"Just this once means only on this single occasion.","zh":"just this once 指只在這一次。"},{"en":"A friend may ask for help just this once, even when the request is wrong.","zh":"朋友可能請你就這一次幫忙，即使要求是錯的。"},{"en":"The phrase can pressure someone to ignore a rule temporarily.","zh":"這個片語可能迫使人暫時忽略規則。"},{"en":"Ryan uses it to make silence sound small, although the moral cost is large.","zh":"Ryan 用它令沉默聽起來很小，但道德代價很大。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"scholarship application","meaning":"獎學金申請","examples":[{"en":"Ryan’s parents thought winning would help his scholarship application.","zh":"Ryan 的父母認為勝出比賽會有助他的獎學金申請。"},{"en":"A scholarship application is a formal request for financial support or an academic award.","zh":"scholarship application 是正式申請資助或學術獎項的文件。"},{"en":"Students often include achievements, grades, and activities in a scholarship application.","zh":"學生常在獎學金申請中加入成就、成績和活動。"},{"en":"Pressure to improve an application can tempt people to make dishonest choices.","zh":"改善申請的壓力可能誘惑人作出不誠實選擇。"},{"en":"Ryan’s desire for scholarship success does not excuse copying.","zh":"Ryan 想成功申請獎學金，並不能成為抄襲的藉口。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"changed enough of it","meaning":"已經改了足夠多","examples":[{"en":"Ryan claimed that he had changed enough of the script.","zh":"Ryan 聲稱他已經改了劇本足夠多的部分。"},{"en":"Changed enough of it means altered a large enough part to make it seem different.","zh":"changed enough of it 指改動了足夠多部分，令它看起來不同。"},{"en":"A student may think changing a few words is enough, but the idea may still be copied.","zh":"學生可能以為改幾個字已經足夠，但想法仍可能是抄襲的。"},{"en":"Changing parts of stolen work does not automatically make it original.","zh":"改動偷來作品的一部分，不會自動令它變成原創。"},{"en":"Ryan’s claim shows he cares more about being caught than about honesty.","zh":"Ryan 的說法顯示他更在意會否被發現，而不是誠實。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"nobody will know","meaning":"沒有人會知道","examples":[{"en":"Ryan said that nobody would know.","zh":"Ryan 說沒有人會知道。"},{"en":"Nobody will know means no one will discover the secret or wrongdoing.","zh":"nobody will know 指沒有人會發現秘密或錯事。"},{"en":"A person may use “nobody will know” to make cheating sound safe.","zh":"有人可能用「沒有人會知道」令作弊聽起來安全。"},{"en":"This sentence is dangerous because it focuses on discovery, not right and wrong.","zh":"這句話危險，因為它關心的是會否被發現，而不是對錯。"},{"en":"For the writer, the sentence breaks trust more than the copying itself.","zh":"對作者來說，這句話比抄襲本身更破壞信任。"}],"source":"2013 Q3.pdf","sourcePage":5},{"front":"broke something in me","meaning":"令我內心某部分崩塌","examples":[{"en":"That sentence broke something in me.","zh":"那句話令我內心某部分崩塌。"},{"en":"Broke something in me means damaged a feeling, belief, or trust inside someone.","zh":"broke something in me 指傷害了某人內心的感受、信念或信任。"},{"en":"A cruel lie can break something in a friendship.","zh":"殘酷謊言可以令友誼中的某部分崩塌。"},{"en":"Sometimes one sentence changes how we see a person forever.","zh":"有時一句話會永遠改變我們看待一個人的方式。"},{"en":"Ryan’s words broke the writer’s belief in his friend’s honesty.","zh":"Ryan 的話摧毀了作者對朋友誠實的信念。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"teammates","meaning":"隊友","examples":[{"en":"I thought of our teammates.","zh":"我想起我們的隊友。"},{"en":"Teammates are people who work or compete together in the same team.","zh":"teammates 指在同一隊伍中一起工作或比賽的人。"},{"en":"Teammates depend on one another during rehearsals and performances.","zh":"隊友在排練和表演中互相依靠。"},{"en":"If one teammate cheats, the whole team may suffer the consequences.","zh":"如果一名隊友作弊，整隊都可能承受後果。"},{"en":"Thinking of the teammates pushes the writer beyond personal loyalty to Ryan.","zh":"想起隊友令作者超越對 Ryan 的個人忠誠。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"stayed after school","meaning":"放學後留下來","examples":[{"en":"Our teammates had stayed after school for weeks to rehearse.","zh":"我們的隊友連續幾星期放學後留下來排練。"},{"en":"Stayed after school means remained at school after normal lessons ended.","zh":"stayed after school 指正常課堂結束後仍留在學校。"},{"en":"Students may stay after school to practise for competitions or finish projects.","zh":"學生可能放學後留下來練習比賽或完成專題。"},{"en":"Staying after school for weeks shows effort and commitment.","zh":"連續幾星期放學後留下來，顯示努力和投入。"},{"en":"The team’s sacrifice makes Ryan’s copying unfair to everyone.","zh":"團隊的付出令 Ryan 的抄襲對所有人都不公平。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"rehearse","meaning":"排練","examples":[{"en":"Our teammates had rehearsed for weeks.","zh":"我們的隊友已經排練了幾星期。"},{"en":"Rehearse means practise a performance before presenting it publicly.","zh":"rehearse 指在公開表演前練習演出。"},{"en":"Actors rehearse their lines so they can speak naturally on stage.","zh":"演員排練台詞，讓自己在台上說得自然。"},{"en":"Rehearsal takes time, patience, and repeated correction.","zh":"排練需要時間、耐性和反覆修正。"},{"en":"The team’s long rehearsals would be wasted if the entry were dishonest.","zh":"如果參賽作品不誠實，團隊長時間排練就會被浪費。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"pronounce","meaning":"發音","examples":[{"en":"Chloe cried because she could not pronounce “inevitably”.","zh":"Chloe 因為無法正確讀出 “inevitably” 而哭了。"},{"en":"Pronounce means say a word correctly with the right sounds.","zh":"pronounce 指用正確聲音說出一個字。"},{"en":"English learners may practise difficult words many times to pronounce them clearly.","zh":"英語學習者可能多次練習難字，以清楚發音。"},{"en":"Struggling to pronounce a word can feel embarrassing in front of teammates.","zh":"在隊友面前讀不準字音可能令人尷尬。"},{"en":"Chloe’s effort shows how much the team had invested in the play.","zh":"Chloe 的努力顯示團隊在這齣劇中投入了很多。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"inevitably","meaning":"不可避免地","examples":[{"en":"Chloe kept practising until she could pronounce “inevitably”.","zh":"Chloe 一直練習，直到能讀出 “inevitably”。"},{"en":"Inevitably means in a way that is certain to happen and cannot be avoided.","zh":"inevitably 指某事必然發生，無法避免。"},{"en":"If nobody studies, poor results will inevitably follow.","zh":"如果沒有人溫習，差成績就會不可避免地出現。"},{"en":"A difficult word becomes less frightening when students practise it patiently.","zh":"當學生耐心練習，難字就不再那麼可怕。"},{"en":"Chloe’s practice turns one hard word into proof of dedication.","zh":"Chloe 的練習把一個難字變成投入的證明。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"kept practising anyway","meaning":"仍然繼續練習","examples":[{"en":"Chloe kept practising anyway.","zh":"Chloe 仍然繼續練習。"},{"en":"Kept practising anyway means continued to practise despite difficulty, embarrassment, or failure.","zh":"kept practising anyway 指即使困難、尷尬或失敗，仍然繼續練習。"},{"en":"A student may keep practising anyway after mispronouncing a word many times.","zh":"學生多次讀錯字後，仍可能繼續練習。"},{"en":"Continuing despite tears shows courage and responsibility.","zh":"流淚後仍繼續，顯示勇氣和責任感。"},{"en":"Chloe’s persistence makes the copied script feel like a betrayal of real effort.","zh":"Chloe 的堅持令抄襲劇本像是對真實努力的背叛。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"faith in us","meaning":"對我們的信任","examples":[{"en":"Ms Lau’s faith in us was almost embarrassing.","zh":"劉老師對我們的信任幾乎令人不好意思。"},{"en":"Faith in us means trust or confidence that we can succeed or act well.","zh":"faith in us 指相信我們能成功或做得好。"},{"en":"A teacher’s faith in students can encourage them to work harder.","zh":"老師對學生的信任可以鼓勵他們更努力。"},{"en":"Faith becomes painful when students fail to live up to it.","zh":"當學生未能配得上那份信任時，信任會變得痛苦。"},{"en":"Ms Lau’s trust makes the dishonesty feel even heavier.","zh":"劉老師的信任令不誠實更加沉重。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"almost embarrassing","meaning":"幾乎令人不好意思","examples":[{"en":"Her faith in us was almost embarrassing.","zh":"她對我們的信任幾乎令人不好意思。"},{"en":"Almost embarrassing means so generous or strong that it makes someone feel shy, guilty, or undeserving.","zh":"almost embarrassing 指某事太慷慨或太強烈，以致令人害羞、內疚或覺得自己不配。"},{"en":"A teacher’s praise can feel almost embarrassing when a student knows the work is not honest.","zh":"當學生知道作品不誠實時，老師的讚賞可能幾乎令人不好意思。"},{"en":"This phrase shows discomfort rather than simple gratitude.","zh":"這個片語表達的是不自在，而不只是感激。"},{"en":"The writer feels ashamed because Ms Lau trusted the team so deeply.","zh":"作者感到羞愧，因為劉老師如此深深信任團隊。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"more than that","meaning":"更重要的是","examples":[{"en":"More than that, I thought of Ryan himself.","zh":"更重要的是，我想起 Ryan 本人。"},{"en":"More than that means beyond the previous point, there is something even more important.","zh":"more than that 指除了前一點之外，還有更重要的事情。"},{"en":"More than that, she worried about how the mistake would affect her friend.","zh":"更重要的是，她擔心這個錯誤會如何影響朋友。"},{"en":"This phrase adds emotional weight to an argument.","zh":"這個片語為論點增加情感重量。"},{"en":"The writer moves from the team’s fairness to Ryan’s own moral future.","zh":"作者由團隊公平轉向 Ryan 自己的道德未來。"}],"source":"2013 Q3.pdf","sourcePage":6},{"front":"protect him","meaning":"保護他","examples":[{"en":"If I protected Ryan, I would not be saving him.","zh":"如果我保護 Ryan，我並不是真的在救他。"},{"en":"Protect him means try to keep him safe from punishment, shame, or harm.","zh":"protect him 指嘗試讓他免受懲罰、羞恥或傷害。"},{"en":"A friend may want to protect someone by hiding their mistake.","zh":"朋友可能想透過隱瞞錯誤來保護某人。"},{"en":"Protection can become harmful if it allows wrongdoing to continue.","zh":"如果保護令錯事繼續，它反而可能有害。"},{"en":"The writer realises that true friendship may require honesty, not cover-up.","zh":"作者意識到真正友誼可能需要誠實，而不是掩飾。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"not be saving him","meaning":"並不是真的在救他","examples":[{"en":"Protecting Ryan would not really be saving him.","zh":"保護 Ryan 並不是真的在救他。"},{"en":"Not be saving him means not truly helping him, even if the action seems protective.","zh":"not be saving him 指即使行動看似保護，也不是真正幫助他。"},{"en":"Hiding a student’s cheating may not be saving him because he learns the wrong lesson.","zh":"隱瞞學生作弊可能並不是真的在救他，因為他會學到錯誤教訓。"},{"en":"Real help sometimes feels painful at first.","zh":"真正幫助有時一開始會令人痛苦。"},{"en":"The writer believes silence would teach Ryan that talent excuses dishonesty.","zh":"作者相信沉默會教 Ryan 以為才華能原諒不誠實。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"give someone permission to","meaning":"給某人……的許可","examples":[{"en":"I would be teaching him that talent gave him permission to cheat.","zh":"我會教會他，才華給了他作弊的許可。"},{"en":"Give someone permission to means allow someone to do something or make them feel allowed to do it.","zh":"give someone permission to 指允許某人做某事，或令某人覺得自己可以那樣做。"},{"en":"Praise should not give students permission to ignore rules.","zh":"讚賞不應給學生忽視規則的許可。"},{"en":"If adults excuse bad behaviour, children may think success gives permission to be unfair.","zh":"如果大人原諒壞行為，孩子可能以為成功給了他們不公平的許可。"},{"en":"The writer fears his silence would give Ryan permission to cheat again.","zh":"作者害怕自己的沉默會給 Ryan 再次作弊的許可。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"cheat","meaning":"作弊","examples":[{"en":"Ryan had used his talent as permission to cheat.","zh":"Ryan 把自己的才華當成作弊的許可。"},{"en":"Cheat means act dishonestly to gain an unfair advantage.","zh":"cheat 指用不誠實方式取得不公平優勢。"},{"en":"Copying another script and entering it as original work is cheating.","zh":"抄襲另一份劇本並以原創作品參賽，就是作弊。"},{"en":"Cheating hurts honest teammates because it steals fairness from them.","zh":"作弊傷害誠實隊友，因為它奪走公平。"},{"en":"Ryan’s cheating is painful because he was talented enough not to need it.","zh":"Ryan 的作弊令人痛心，因為他本來有才華到不需要這樣做。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"the fact that","meaning":"……這個事實","examples":[{"en":"The fact that I loved him did not change what he had done.","zh":"我愛他這個事實並沒有改變他所做的事。"},{"en":"The fact that introduces a true situation that must be considered.","zh":"the fact that 用來引出必須考慮的真實情況。"},{"en":"The fact that someone is kind does not mean every choice they make is right.","zh":"某人善良這個事實，不代表他作出的每個選擇都是對的。"},{"en":"This phrase helps separate emotion from reality.","zh":"這個片語幫助把情感和現實分開。"},{"en":"The writer admits his love for Ryan while still facing the truth.","zh":"作者承認自己愛 Ryan，同時仍面對真相。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"alter the fact that","meaning":"改變……這個事實","examples":[{"en":"My love for Ryan did not alter the fact that he was wrong.","zh":"我對 Ryan 的愛沒有改變他錯了這個事實。"},{"en":"Alter the fact that means change the truth of a situation.","zh":"alter the fact that 指改變某個情況的真相。"},{"en":"Feeling sorry for a friend does not alter the fact that cheating is unfair.","zh":"為朋友感到難過，不能改變作弊不公平這個事實。"},{"en":"Emotions may affect our choices, but they do not rewrite what happened.","zh":"情感可能影響選擇，但不能改寫已發生的事。"},{"en":"The writer’s affection cannot turn Ryan’s wrong action into a right one.","zh":"作者的感情不能把 Ryan 的錯誤行為變成正確。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"what he had done was wrong","meaning":"他所做的事是錯的","examples":[{"en":"The fact remained that what Ryan had done was wrong.","zh":"事實仍然是，Ryan 所做的事是錯的。"},{"en":"What he had done was wrong means his action was morally unacceptable.","zh":"what he had done was wrong 指他的行為在道德上不可接受。"},{"en":"A person may have good reasons, but copying another person’s work is still wrong.","zh":"一個人可能有原因，但抄襲別人的作品仍然是錯的。"},{"en":"Saying this clearly helps the writer face the truth.","zh":"清楚說出這一點，幫助作者面對真相。"},{"en":"The moral problem remains even though Ryan is his best friend.","zh":"即使 Ryan 是他最好的朋友，道德問題仍然存在。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"had promised him","meaning":"曾經答應他","examples":[{"en":"I had promised Ryan that I would not tell.","zh":"我曾經答應 Ryan 我不會說出去。"},{"en":"Had promised him means had given him one’s word before a later event happened.","zh":"had promised him 指在後來事件發生前已向他作出承諾。"},{"en":"A student may regret a promise made too quickly under pressure.","zh":"學生可能後悔自己在壓力下太快作出的承諾。"},{"en":"Promises can become painful when they protect something wrong.","zh":"當承諾保護錯事時，它會變得痛苦。"},{"en":"The writer’s promise traps him between loyalty and honesty.","zh":"作者的承諾把他困在忠誠與誠實之間。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"what that promise would cost","meaning":"那個承諾會付出甚麼代價","examples":[{"en":"I did not know what that promise would cost.","zh":"我不知道那個承諾會付出甚麼代價。"},{"en":"What that promise would cost means the pain, damage, or consequence caused by keeping the promise.","zh":"what that promise would cost 指守住承諾所造成的痛苦、損害或後果。"},{"en":"A promise may cost a person sleep, friendship, or peace of mind.","zh":"一個承諾可能令人失去睡眠、友誼或內心平安。"},{"en":"People may promise quickly before understanding the moral price.","zh":"人們可能在未理解道德代價前太快承諾。"},{"en":"The writer later learns that silence would cost fairness and self-respect.","zh":"作者後來明白，沉默會付出公平和自尊的代價。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"might never have made it","meaning":"可能從來不會作出它","examples":[{"en":"Had I known the cost, I might never have made the promise.","zh":"如果我早知道代價，我可能從來不會作出那個承諾。"},{"en":"Might never have made it means perhaps would not have agreed if the result had been known.","zh":"might never have made it 指如果早知道結果，也許不會答應。"},{"en":"If she had known the lie would hurt others, she might never have made it.","zh":"如果她知道謊言會傷害別人，她可能從來不會說出它。"},{"en":"This phrase expresses regret about a past decision.","zh":"這個片語表達對過去決定的後悔。"},{"en":"The writer wishes he had not promised silence before thinking clearly.","zh":"作者希望自己在清楚思考前沒有答應保持沉默。"}],"source":"2013 Q3.pdf","sourcePage":7},{"front":"walked to the staff room","meaning":"走到教員室","examples":[{"en":"After school, I walked to the staff room three times.","zh":"放學後，我三次走到教員室。"},{"en":"Walked to the staff room means went towards the teachers’ room, often to speak to a teacher.","zh":"walked to the staff room 指走向教師辦公室，通常是為了找老師說話。"},{"en":"A nervous student may walk to the staff room and turn back several times.","zh":"緊張的學生可能走到教員室，又幾次轉身離開。"},{"en":"Repeating the walk shows hesitation and fear.","zh":"重複走過去顯示猶豫和恐懼。"},{"en":"The writer’s three attempts show how difficult telling the truth felt.","zh":"作者三次嘗試顯示說出真相有多困難。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"walked away","meaning":"走開","examples":[{"en":"I walked away from the staff room twice.","zh":"我兩次從教員室走開。"},{"en":"Walked away means left a place instead of continuing with the action.","zh":"walked away 指離開某個地方，而不是繼續行動。"},{"en":"A student may walk away when fear becomes stronger than courage.","zh":"當恐懼比勇氣更強時，學生可能會走開。"},{"en":"Walking away twice shows the writer was not eager to betray Ryan.","zh":"兩次走開顯示作者並不是急於背叛 Ryan。"},{"en":"The phrase captures the battle between conscience and friendship.","zh":"這個片語捕捉良心與友誼之間的掙扎。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"shook so badly","meaning":"抖得很厲害","examples":[{"en":"My hands shook so badly that I nearly dropped my phone.","zh":"我的手抖得很厲害，差點把電話掉下。"},{"en":"Shook so badly means trembled very strongly because of fear, stress, or shock.","zh":"shook so badly 指因恐懼、壓力或震驚而強烈顫抖。"},{"en":"Her hands shook so badly before the interview that she spilled water.","zh":"她面試前手抖得很厲害，弄灑了水。"},{"en":"Physical shaking can show emotional pressure more clearly than words.","zh":"身體顫抖比言語更清楚顯示情緒壓力。"},{"en":"The writer’s shaking hands reveal how painful the decision was.","zh":"作者顫抖的手顯示這個決定多麼痛苦。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"nearly dropped","meaning":"差點掉下","examples":[{"en":"I nearly dropped my phone.","zh":"我差點把電話掉下。"},{"en":"Nearly dropped means almost let something fall by accident.","zh":"nearly dropped 指幾乎意外讓某物掉落。"},{"en":"He nearly dropped the glass when he heard the bad news.","zh":"他聽到壞消息時，差點把玻璃杯掉下。"},{"en":"Strong emotion can make the body less steady.","zh":"強烈情緒會令身體不穩。"},{"en":"The writer nearly drops his phone because sending the evidence terrifies him.","zh":"作者差點掉下電話，因為傳送證據令他害怕。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"finally","meaning":"最後","examples":[{"en":"Finally, I sent Ms Lau the screenshots.","zh":"最後，我把截圖傳給劉老師。"},{"en":"Finally means after delay, hesitation, or several earlier attempts.","zh":"finally 指經過拖延、猶豫或幾次嘗試後終於發生。"},{"en":"Finally, the student told the teacher what had happened.","zh":"最後，學生告訴老師發生了甚麼。"},{"en":"This word shows that the action was difficult but eventually completed.","zh":"這個詞顯示行動很困難，但最終完成了。"},{"en":"The writer finally chooses honesty, though it does not feel peaceful.","zh":"作者最後選擇誠實，雖然內心並不平靜。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"screenshots","meaning":"截圖","examples":[{"en":"I sent Ms Lau the screenshots.","zh":"我把截圖傳給劉老師。"},{"en":"Screenshots are pictures taken of what appears on a phone or computer screen.","zh":"screenshots 是手機或電腦螢幕畫面的圖片記錄。"},{"en":"Students may use screenshots as evidence of messages or files.","zh":"學生可能用截圖作為訊息或檔案的證據。"},{"en":"Screenshots can prove what someone saw, but they can also damage relationships.","zh":"截圖可以證明某人看見了甚麼，但也可能傷害關係。"},{"en":"The screenshots become the evidence that exposes Ryan’s copied script.","zh":"截圖成為揭露 Ryan 抄襲劇本的證據。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"reveal my name","meaning":"透露我的名字","examples":[{"en":"I asked Ms Lau not to reveal my name.","zh":"我請劉老師不要透露我的名字。"},{"en":"Reveal my name means tell others who I am or who provided the information.","zh":"reveal my name 指告訴別人我是誰，或是誰提供資料。"},{"en":"A student may ask a teacher not to reveal their name when reporting bullying.","zh":"學生舉報欺凌時，可能請老師不要透露自己的名字。"},{"en":"Hiding a name can protect someone from anger, but it may also feel cowardly.","zh":"隱藏名字可以保護人免受憤怒攻擊，但也可能令人覺得懦弱。"},{"en":"The writer wants truth to be known without becoming publicly exposed.","zh":"作者希望真相被知道，但自己不被公開暴露。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"cowardly","meaning":"懦弱的","examples":[{"en":"Reporting Ryan anonymously may have been cowardly.","zh":"匿名舉報 Ryan 可能是懦弱的。"},{"en":"Cowardly means lacking courage, especially when facing a difficult truth or consequence.","zh":"cowardly 指缺乏勇氣，尤其是在面對困難真相或後果時。"},{"en":"It may feel cowardly to hide one’s name after making an accusation.","zh":"提出指控後隱藏名字，可能令人覺得懦弱。"},{"en":"However, fear does not always mean the action itself is wrong.","zh":"然而，害怕不一定代表行動本身是錯的。"},{"en":"The writer judges himself harshly because he told the truth from behind a screen.","zh":"作者嚴厲審視自己，因為他是隔着螢幕說出真相。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"necessary","meaning":"必要的","examples":[{"en":"I wondered whether reporting Ryan was necessary.","zh":"我懷疑舉報 Ryan 是否必要。"},{"en":"Necessary means needed because there is no responsible alternative.","zh":"necessary 指因沒有負責任的替代選擇而需要做。"},{"en":"A painful conversation may be necessary if silence protects wrongdoing.","zh":"如果沉默保護錯事，痛苦對話可能是必要的。"},{"en":"Something necessary can still hurt deeply.","zh":"必要的事情仍然可以令人非常痛苦。"},{"en":"The writer cannot decide whether the report was the only honest choice.","zh":"作者無法確定舉報是否唯一誠實的選擇。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"do not know anymore","meaning":"已經不知道","examples":[{"en":"I do not know anymore whether I did the right thing.","zh":"我已經不知道自己是否做了正確的事。"},{"en":"Do not know anymore means no longer feel sure about something once believed or hoped.","zh":"do not know anymore 指對原本相信或希望的事不再確定。"},{"en":"After an argument, a person may not know anymore who was right.","zh":"爭執後，一個人可能已經不知道誰是對的。"},{"en":"Moral choices can leave people uncertain even after they act.","zh":"道德選擇即使已經作出，仍可能令人不確定。"},{"en":"The writer’s uncertainty shows how complicated honesty can feel.","zh":"作者的不確定顯示誠實有時多麼複雜。"}],"source":"2013 Q3.pdf","sourcePage":8},{"front":"all I know is that","meaning":"我只知道","examples":[{"en":"All I know is that I could not let the team perform a lie.","zh":"我只知道，我不能讓團隊演出一個謊言。"},{"en":"All I know is that means this is the one thing I feel certain about.","zh":"all I know is that 指這是我唯一確定的事。"},{"en":"All I know is that ignoring cheating would be unfair to the class.","zh":"我只知道，忽視作弊對全班不公平。"},{"en":"This phrase is useful when many details are confusing but one truth remains clear.","zh":"當許多細節令人困惑但仍有一個真相清楚時，這個片語很有用。"},{"en":"The writer is unsure about everything except the team’s right not to perform dishonestly.","zh":"作者對一切都不肯定，唯一肯定的是團隊不應不誠實地演出。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"walk onto that stage","meaning":"走上那個舞台","examples":[{"en":"I could not let our team walk onto that stage carrying a lie.","zh":"我不能讓我們的團隊帶着謊言走上那個舞台。"},{"en":"Walk onto that stage means go onstage to perform before an audience.","zh":"walk onto that stage 指走上舞台，在觀眾面前表演。"},{"en":"Students walk onto the stage after weeks of rehearsal.","zh":"學生經過幾星期排練後走上舞台。"},{"en":"Going onstage with dishonest work would turn performance into deception.","zh":"帶着不誠實作品上台，會把表演變成欺騙。"},{"en":"The stage becomes a place where the team’s honesty is tested.","zh":"舞台成為考驗團隊誠實的地方。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"carrying a lie","meaning":"帶著謊言","examples":[{"en":"The team would have walked onto the stage carrying a lie.","zh":"團隊本來會帶着謊言走上舞台。"},{"en":"Carrying a lie means continuing forward while hiding a dishonest truth.","zh":"carrying a lie 指在隱藏不誠實真相的情況下繼續向前。"},{"en":"A student carries a lie when they submit copied work as their own.","zh":"學生把抄襲作品當成自己的提交，就是帶着謊言。"},{"en":"Lies can feel heavy because they affect everyone involved.","zh":"謊言會感覺沉重，因為它影響所有相關的人。"},{"en":"The writer refuses to let the team’s performance be built on dishonesty.","zh":"作者拒絕讓團隊表演建基於不誠實。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"saw the storm coming","meaning":"預見風暴來臨","examples":[{"en":"No one saw the storm coming.","zh":"沒有人預見風暴來臨。"},{"en":"Saw the storm coming means expected serious trouble before it happened.","zh":"saw the storm coming 指在嚴重麻煩發生前已預料到。"},{"en":"A class may not see the storm coming until a secret is revealed.","zh":"班上可能直到秘密被揭露前，都沒有預見風暴來臨。"},{"en":"This phrase compares conflict to bad weather arriving suddenly.","zh":"這個片語把衝突比作突然到來的惡劣天氣。"},{"en":"The team did not realise that the copied script would soon cause chaos.","zh":"團隊沒有意識到抄襲劇本很快會造成混亂。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"by the last lesson","meaning":"到最後一堂課時","examples":[{"en":"By the last lesson, Ryan had been called out.","zh":"到最後一堂課時，Ryan 已經被叫出去。"},{"en":"By the last lesson means when the final class period arrived.","zh":"by the last lesson 指到最後一節課的時候。"},{"en":"By the last lesson, everyone knew something serious had happened.","zh":"到最後一堂課時，每個人都知道發生了嚴重事情。"},{"en":"This phrase shows how quickly the situation changed during the school day.","zh":"這個片語顯示情況在上學日中變化得多快。"},{"en":"The day ends with Ryan being removed from class and the team left uncertain.","zh":"這一天以 Ryan 被叫出課室、團隊陷入不安作結。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"called out","meaning":"被叫出去","examples":[{"en":"Ryan had been called out of class.","zh":"Ryan 已經被叫出課室。"},{"en":"Called out means asked to leave a place, often by a teacher or authority figure.","zh":"called out 指被老師或權威人物要求離開某個地方。"},{"en":"A student may be called out of class to speak with the principal.","zh":"學生可能被叫出課室去見校長。"},{"en":"Being called out can make classmates curious or worried.","zh":"被叫出去會令同學好奇或擔心。"},{"en":"Ryan’s removal signals that Ms Lau has acted on the evidence.","zh":"Ryan 被叫出去，顯示劉老師已根據證據採取行動。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"competition entry","meaning":"比賽參賽資格","examples":[{"en":"The competition entry was suspended.","zh":"比賽參賽資格被暫停。"},{"en":"A competition entry is the work or performance submitted for a contest.","zh":"competition entry 指提交到比賽中的作品或表演。"},{"en":"A school’s drama competition entry may include the script, cast, and performance plan.","zh":"學校的戲劇比賽參賽作品可能包括劇本、演員和表演計劃。"},{"en":"If an entry breaks rules, organisers or teachers may stop it temporarily.","zh":"如果參賽作品違反規則，主辦方或老師可能暫時停止它。"},{"en":"The team’s entry is suspended because its honesty is now in question.","zh":"團隊參賽資格被暫停，因為其誠信受到質疑。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"suspended","meaning":"暫停；擱置","examples":[{"en":"The competition entry was suspended.","zh":"比賽參賽資格被暫停。"},{"en":"Suspended means temporarily stopped while a problem is investigated or decided.","zh":"suspended 指在問題被調查或決定期間暫時停止。"},{"en":"A match may be suspended because of bad weather.","zh":"比賽可能因惡劣天氣而暫停。"},{"en":"A school activity may be suspended if rules have been broken.","zh":"如果規則被違反，學校活動可能被暫停。"},{"en":"Suspension leaves the team waiting, unsure whether they can still perform.","zh":"暫停令團隊只能等待，不知道是否仍能表演。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"left whispering","meaning":"只剩下竊竊私語","examples":[{"en":"Our classmates were left whispering.","zh":"我們的同學只剩下竊竊私語。"},{"en":"Left whispering means remained quietly talking in confusion after something happened.","zh":"left whispering 指事情發生後，人們留在原地低聲困惑地交談。"},{"en":"After the teacher suddenly left, the class was left whispering.","zh":"老師突然離開後，全班只剩下竊竊私語。"},{"en":"Whispering often appears when people sense trouble but do not know the full truth.","zh":"當人們感到出事卻不知道完整真相時，常會低聲私語。"},{"en":"The classmates whisper because they know something is wrong but not why.","zh":"同學竊竊私語，因為他們知道出事了，但不知道原因。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"confused and furious","meaning":"困惑而憤怒","examples":[{"en":"Our classmates were confused and furious.","zh":"我們的同學困惑而憤怒。"},{"en":"Confused and furious means unable to understand what happened and extremely angry about it.","zh":"confused and furious 指不明白發生甚麼，同時非常生氣。"},{"en":"Students may feel confused and furious when a competition is cancelled without explanation.","zh":"當比賽無解釋地取消，學生可能困惑而憤怒。"},{"en":"Confusion often makes anger stronger because people do not know whom to blame.","zh":"困惑常令憤怒更強，因為人們不知道該怪誰。"},{"en":"The team feels betrayed by the sudden suspension and lack of answers.","zh":"團隊因突然暫停和沒有答案而感到被背叛。"}],"source":"2013 Q3.pdf","sourcePage":9},{"front":"go home and wait","meaning":"回家等候","examples":[{"en":"Ms Lau told us to go home and wait.","zh":"劉老師叫我們回家等候。"},{"en":"Go home and wait means leave without receiving an immediate answer and wait for further news.","zh":"go home and wait 指離開而沒有立即得到答案，等待進一步消息。"},{"en":"After a serious school incident, students may be told to go home and wait.","zh":"嚴重校園事件後，學生可能被告知回家等候。"},{"en":"Waiting can feel painful because people have no control over what happens next.","zh":"等待可能很痛苦，因為人們無法控制接下來會發生甚麼。"},{"en":"The instruction leaves the team trapped in uncertainty.","zh":"這個指示令團隊困在不確定之中。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"near the staircase","meaning":"在樓梯附近","examples":[{"en":"Ryan found me near the staircase.","zh":"Ryan 在樓梯附近找到我。"},{"en":"Near the staircase means close to the stairs in a building.","zh":"near the staircase 指在建築物樓梯附近。"},{"en":"Students often gather near the staircase between lessons.","zh":"學生常在課堂之間聚集在樓梯附近。"},{"en":"A staircase can become a tense meeting place when someone is trying to leave.","zh":"當某人想離開時，樓梯可以成為緊張的相遇地點。"},{"en":"Ryan finds the writer in a place where escape feels possible but not easy.","zh":"Ryan 在一個看似可以逃走但並不容易的地方找到作者。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"did not shout","meaning":"沒有大叫","examples":[{"en":"Ryan did not shout when he confronted me.","zh":"Ryan 質問我時沒有大叫。"},{"en":"Did not shout means he stayed quiet instead of raising his voice angrily.","zh":"did not shout 指他保持安靜，而不是憤怒地提高聲音。"},{"en":"Sometimes quiet disappointment hurts more than shouting.","zh":"有時安靜的失望比大叫更傷人。"},{"en":"Not shouting can make a confrontation feel colder and more serious.","zh":"沒有大叫可以令對質感覺更冷、更嚴重。"},{"en":"Ryan’s calmness makes the writer feel even more guilty.","zh":"Ryan 的平靜令作者更加內疚。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"simply looked at me","meaning":"只是看著我","examples":[{"en":"He simply looked at me with a strange calm.","zh":"他只是帶着奇怪的平靜看着我。"},{"en":"Simply looked at me means did nothing except look directly, without speaking or acting dramatically.","zh":"simply looked at me 指除了直接看着我之外，沒有說話或誇張行動。"},{"en":"A parent may simply look at a child when disappointment is too deep for words.","zh":"當失望深到無話可說，父母可能只是看着孩子。"},{"en":"Silence can make a look feel heavier than an argument.","zh":"沉默可以令一個眼神比爭吵更沉重。"},{"en":"Ryan’s look gives the writer no place to hide.","zh":"Ryan 的眼神令作者無處可躲。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"strange, empty calm","meaning":"奇怪而空洞的平靜","examples":[{"en":"Ryan looked at me with a strange, empty calm.","zh":"Ryan 帶着奇怪而空洞的平靜看着我。"},{"en":"Strange, empty calm means a quietness that feels unnatural because emotion has gone cold or numb.","zh":"strange, empty calm 指一種不自然的安靜，因情感變冷或麻木而空洞。"},{"en":"Someone may show an empty calm after receiving shocking news.","zh":"一個人收到震驚消息後，可能呈現空洞的平靜。"},{"en":"This calm can be frightening because anger has turned into distance.","zh":"這種平靜可能令人害怕，因為憤怒已變成距離。"},{"en":"Ryan’s calm suggests the friendship has been deeply damaged.","zh":"Ryan 的平靜暗示友誼已受到深刻傷害。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"enough","meaning":"足夠了","examples":[{"en":"Two words were enough.","zh":"兩個字已經足夠了。"},{"en":"Enough means sufficient; no more is needed.","zh":"enough 指足夠，不需要更多。"},{"en":"Sometimes one look is enough to show disappointment.","zh":"有時一個眼神已足夠顯示失望。"},{"en":"Few words can be enough when the feeling behind them is strong.","zh":"當背後感情強烈，寥寥數語已經足夠。"},{"en":"Ryan does not need a long speech to make the writer understand his hurt.","zh":"Ryan 不需要長篇說話，也能令作者明白他的受傷。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"wanted to explain","meaning":"想解釋","examples":[{"en":"I wanted to explain why I had told Ms Lau.","zh":"我想解釋為何我告訴劉老師。"},{"en":"Wanted to explain means wished to give reasons so another person could understand.","zh":"wanted to explain 指希望說出理由，讓對方明白。"},{"en":"A student may want to explain after hurting a friend unintentionally.","zh":"學生無意傷害朋友後，可能想解釋。"},{"en":"Explanation can help, but it may not remove pain immediately.","zh":"解釋可以有幫助，但未必能立刻消除痛苦。"},{"en":"The writer wants Ryan to see the reason, not only the betrayal.","zh":"作者想 Ryan 看見理由，而不只是背叛。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"for the team","meaning":"為了團隊","examples":[{"en":"I wanted to explain that I did it for the team.","zh":"我想解釋我是為了團隊才這樣做。"},{"en":"For the team means for the benefit, protection, or fairness of the group.","zh":"for the team 指為了整個小組的利益、保護或公平。"},{"en":"A captain may make a difficult choice for the team, not for personal comfort.","zh":"隊長可能為了團隊作出艱難選擇，而不是為了個人舒服。"},{"en":"Acting for the team can still hurt an individual member.","zh":"為了團隊行事仍可能傷害個別成員。"},{"en":"The writer uses this reason to defend reporting Ryan, but it feels painfully small.","zh":"作者用這個理由為舉報 Ryan 辯護，但它感覺痛苦地渺小。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"for fairness","meaning":"為了公平","examples":[{"en":"I wanted to say that I did it for fairness.","zh":"我想說我是為了公平才這樣做。"},{"en":"For fairness means in order to protect justice and equal treatment.","zh":"for fairness 指為了保護公義和平等對待。"},{"en":"A teacher may cancel copied work for fairness to honest students.","zh":"老師可能為了公平對待誠實學生而取消抄襲作品。"},{"en":"Fairness matters when everyone has worked hard under the same rules.","zh":"當每個人都在同一規則下努力，公平就很重要。"},{"en":"The writer believes fairness required truth, but the cost still hurts.","zh":"作者相信公平需要真相，但代價仍然令人痛苦。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"even for him","meaning":"甚至是為了他","examples":[{"en":"I wanted to believe that I had done it even for him.","zh":"我想相信自己這樣做甚至是為了他。"},{"en":"Even for him means also for his good, although he may not see it that way.","zh":"even for him 指也是為了他的好，即使他未必這樣看。"},{"en":"A parent may punish a child even for the child’s own safety.","zh":"父母可能為了孩子自己的安全而懲罰孩子。"},{"en":"Helping someone can feel like betrayal if they do not understand the reason.","zh":"如果對方不明白原因，幫助也可能像背叛。"},{"en":"The writer hopes telling the truth may protect Ryan’s future character.","zh":"作者希望說出真相可能保護 Ryan 未來的品格。"}],"source":"2013 Q3.pdf","sourcePage":10},{"front":"instead","meaning":"反而","examples":[{"en":"Instead, I stood there like Brutus at Caesar’s feet.","zh":"反而，我站在那裏，像站在凱撒腳邊的布魯圖斯。"},{"en":"Instead means rather than doing what was expected or intended.","zh":"instead 指沒有做原本預期或打算做的事，而是做了另一件事。"},{"en":"She wanted to apologise; instead, she stayed silent.","zh":"她想道歉；反而，她保持沉默。"},{"en":"This word marks the difference between intention and action.","zh":"這個詞標示意圖和行動之間的差距。"},{"en":"The writer wanted to explain but instead became frozen by guilt.","zh":"作者想解釋，反而被內疚凍住。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"like Brutus at Caesar’s feet","meaning":"像站在凱撒腳邊的布魯圖斯","examples":[{"en":"I stood there like Brutus at Caesar’s feet.","zh":"我站在那裏，像站在凱撒腳邊的布魯圖斯。"},{"en":"Like Brutus at Caesar’s feet means feeling like a betrayer standing before the person he has harmed.","zh":"like Brutus at Caesar’s feet 指感覺像背叛者站在被自己傷害的人面前。"},{"en":"A student who reports a friend may feel like Brutus facing Caesar.","zh":"舉報朋友的學生可能感覺像面對凱撒的布魯圖斯。"},{"en":"The comparison turns a school conflict into a tragic moral scene.","zh":"這個比較把校園衝突變成悲劇式的道德場景。"},{"en":"The writer sees Ryan as the person wounded by his choice.","zh":"作者把 Ryan 看成被自己選擇刺傷的人。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"holding reasons","meaning":"握著理由","examples":[{"en":"I stood there holding reasons that felt too small.","zh":"我站在那裏，握着那些顯得太渺小的理由。"},{"en":"Holding reasons means having explanations or justifications ready in one’s mind.","zh":"holding reasons 指心裏準備着解釋或辯解。"},{"en":"A person may hold many reasons but still feel unable to speak.","zh":"一個人可能握着許多理由，卻仍說不出口。"},{"en":"Reasons can feel small when another person’s pain is directly in front of us.","zh":"當別人的痛苦直接在眼前，理由可能變得渺小。"},{"en":"The writer’s reasons cannot fully cover the hurt on Ryan’s face.","zh":"作者的理由無法完全遮蓋 Ryan 臉上的受傷。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"suddenly felt too small","meaning":"突然顯得太渺小","examples":[{"en":"My reasons suddenly felt too small.","zh":"我的理由突然顯得太渺小。"},{"en":"Suddenly felt too small means quickly seemed weak, insufficient, or unable to explain the damage.","zh":"suddenly felt too small 指突然顯得薄弱、不足或無法解釋傷害。"},{"en":"An excuse may suddenly feel too small when someone starts crying.","zh":"當有人開始哭，藉口可能突然顯得太渺小。"},{"en":"Moral reasons can feel smaller when emotional consequences become visible.","zh":"當情感後果變得可見，道德理由可能變小。"},{"en":"The writer still believes in fairness, but his reasons feel powerless before Ryan’s silence.","zh":"作者仍相信公平，但在 Ryan 的沉默面前，理由顯得無力。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"for the first time in forever","meaning":"久違地第一次","examples":[{"en":"For the first time in forever, I did not know what I had done.","zh":"久違地第一次，我不知道自己做了甚麼。"},{"en":"For the first time in forever means for the first time in a very long time.","zh":"for the first time in forever 指很久以來第一次。"},{"en":"For the first time in forever, the confident student felt completely unsure.","zh":"久違地第一次，那名自信學生感到完全不確定。"},{"en":"This phrase emphasises how unusual the writer’s uncertainty feels.","zh":"這個片語強調作者的不確定感多麼罕見。"},{"en":"The decision has shaken a certainty he had trusted for a long time.","zh":"這個決定動搖了他長久相信的確定感。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"had no idea whether","meaning":"完全不知道是否","examples":[{"en":"I had no idea whether I had saved my friend or destroyed him.","zh":"我完全不知道自己是救了朋友，還是毀了他。"},{"en":"Had no idea whether means was completely unsure which possibility was true.","zh":"had no idea whether 指完全不確定哪個可能性是真的。"},{"en":"After a difficult choice, someone may have no idea whether they helped or hurt.","zh":"作出艱難選擇後，一個人可能完全不知道自己是幫了人還是傷了人。"},{"en":"This phrase shows deep moral confusion.","zh":"這個片語顯示深刻的道德混亂。"},{"en":"The writer cannot tell whether honesty has protected Ryan or harmed him.","zh":"作者分不清誠實是保護了 Ryan，還是傷害了他。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"saved my friend","meaning":"救了我的朋友","examples":[{"en":"I wondered whether I had saved my friend.","zh":"我不知道自己是否救了我的朋友。"},{"en":"Saved my friend means helped a friend avoid deeper harm or a worse future.","zh":"saved my friend 指幫助朋友避開更深傷害或更壞未來。"},{"en":"Reporting a friend’s mistake may save them from repeating it later.","zh":"舉報朋友的錯誤，可能會讓他日後不再重犯。"},{"en":"Saving someone does not always feel kind at the moment.","zh":"救一個人當下未必感覺溫柔。"},{"en":"The writer hopes the painful truth may stop Ryan from becoming dishonest.","zh":"作者希望痛苦真相能阻止 Ryan 變得不誠實。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"destroyed him","meaning":"毀了他","examples":[{"en":"I wondered whether I had destroyed him.","zh":"我不知道自己是否毀了他。"},{"en":"Destroyed him means damaged his confidence, reputation, or future very seriously.","zh":"destroyed him 指嚴重傷害他的信心、名聲或未來。"},{"en":"A public scandal can destroy a student’s confidence if handled cruelly.","zh":"如果處理得殘酷，公開醜聞可能毀掉學生的信心。"},{"en":"The writer fears the report may have broken Ryan instead of helping him.","zh":"作者害怕舉報不是幫助 Ryan，而是毀了他。"},{"en":"This fear makes the diary feel tragic rather than self-righteous.","zh":"這種恐懼令日記感覺悲劇化，而不是自以為正義。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"except for this page","meaning":"除了這一頁之外","examples":[{"en":"My room is dark except for this page.","zh":"我的房間一片黑暗，除了這一頁之外。"},{"en":"Except for this page means everything else is dark, with only the diary page visible.","zh":"except for this page 指其他一切都是黑暗的，只有日記頁可見。"},{"en":"A room may be silent except for the sound of writing.","zh":"房間可能一片寂靜，除了寫字聲之外。"},{"en":"This phrase focuses attention on the diary as the only place where truth can appear.","zh":"這個片語把注意力集中在日記上，彷彿它是真相唯一能出現的地方。"},{"en":"The page becomes a small light in the writer’s confusion.","zh":"這一頁成為作者混亂中的一點光。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"keep telling myself","meaning":"不斷告訴自己","examples":[{"en":"I keep telling myself that honesty is the best policy.","zh":"我不斷告訴自己誠實是上策。"},{"en":"Keep telling myself means repeat something in my mind to try to believe or accept it.","zh":"keep telling myself 指在心裏反覆說某事，試圖相信或接受它。"},{"en":"Before an exam, a student may keep telling herself to stay calm.","zh":"考試前，學生可能不斷告訴自己要保持冷靜。"},{"en":"Repeating a belief can show that the person is not fully convinced yet.","zh":"反覆重申一個信念，可能顯示那個人還未完全相信。"},{"en":"The writer repeats moral sayings because his heart still feels heavy.","zh":"作者重複道德格言，因為他的心仍然沉重。"}],"source":"2013 Q3.pdf","sourcePage":11},{"front":"honesty is the best policy","meaning":"誠實是上策","examples":[{"en":"I keep telling myself that honesty is the best policy.","zh":"我不斷告訴自己誠實是上策。"},{"en":"Honesty is the best policy means telling the truth is usually the wisest and most moral choice.","zh":"honesty is the best policy 指說真話通常是最明智、最合道德的選擇。"},{"en":"A student who admits a mistake may suffer first but rebuild trust later.","zh":"承認錯誤的學生起初可能受苦，但日後可以重建信任。"},{"en":"This proverb supports truthfulness, but it does not promise truth will feel easy.","zh":"這句諺語支持誠實，但沒有保證真相會令人輕鬆。"},{"en":"The writer believes the saying, yet still feels hurt by its cost.","zh":"作者相信這句話，卻仍因它的代價而痛苦。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"actions have consequences","meaning":"行為會帶來後果","examples":[{"en":"I remind myself that actions have consequences.","zh":"我提醒自己，行為會帶來後果。"},{"en":"Actions have consequences means choices lead to results, whether good or bad.","zh":"actions have consequences 指選擇會帶來結果，無論好壞。"},{"en":"Cheating has consequences for the person who cheats and for the people around them.","zh":"作弊會對作弊者和身邊的人帶來後果。"},{"en":"Remembering consequences helps people take responsibility.","zh":"記住後果能幫助人承擔責任。"},{"en":"The writer knows Ryan’s action had consequences, but so did his own report.","zh":"作者知道 Ryan 的行為有後果，但自己的舉報也有後果。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"as you sow, so you reap","meaning":"種瓜得瓜，種豆得豆","examples":[{"en":"I keep repeating the proverb, “As you sow, so you reap.”","zh":"我不斷重複那句諺語：「種瓜得瓜，種豆得豆。」"},{"en":"As you sow, so you reap means people eventually face the results of their own actions.","zh":"as you sow, so you reap 指人最終會面對自己行為帶來的結果。"},{"en":"If a student cheats, the loss of trust may be what they reap.","zh":"如果學生作弊，失去信任可能就是他收穫的後果。"},{"en":"The proverb sounds clear, but real life can still feel emotionally messy.","zh":"這句諺語聽起來清楚，但現實生活在情感上仍可以很混亂。"},{"en":"The writer repeats it to justify the truth, but it does not comfort him.","zh":"作者重複它來證明真相有理，但它沒有安慰他。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"may be true","meaning":"也許是真的","examples":[{"en":"All of that may be true.","zh":"這一切也許是真的。"},{"en":"May be true means something is possibly or probably correct, but it may not settle the whole matter.","zh":"may be true 指某事可能或大概正確，但未必能解決整件事。"},{"en":"The rule may be true, but applying it to a friend can still hurt.","zh":"規則也許是真的，但把它用在朋友身上仍可能傷人。"},{"en":"This phrase allows agreement while leaving space for doubt or pain.","zh":"這個片語既表示同意，也留下懷疑或痛苦的空間。"},{"en":"The writer accepts the moral sayings but still feels emotionally unsettled.","zh":"作者接受那些道德格言，卻仍在情感上不安。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"even so","meaning":"即使如此","examples":[{"en":"Even so, truth has not made my heart lighter.","zh":"即使如此，真相沒有令我的心變得輕鬆。"},{"en":"Even so means despite what has just been accepted or said.","zh":"even so 指儘管剛才接受或說過某事，仍然如此。"},{"en":"The apology was sincere; even so, the friendship still felt broken.","zh":"道歉很真誠；即使如此，友誼仍感覺破裂。"},{"en":"This phrase introduces a contrast between moral truth and emotional pain.","zh":"這個片語引出道德真相和情感痛苦之間的對比。"},{"en":"The writer admits honesty may be right, but it has not brought peace.","zh":"作者承認誠實可能正確，但它沒有帶來平靜。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"made my heart lighter","meaning":"令我的心變得輕鬆","examples":[{"en":"Truth has not made my heart lighter.","zh":"真相沒有令我的心變得輕鬆。"},{"en":"Made my heart lighter means made me feel less guilty, sad, or burdened.","zh":"made my heart lighter 指令我感到較少內疚、悲傷或負擔。"},{"en":"Saying sorry can make someone’s heart lighter if the other person listens.","zh":"如果對方願意聆聽，道歉可以令人的心變得輕鬆。"},{"en":"Sometimes doing the right thing does not immediately remove emotional weight.","zh":"有時做正確的事不會立刻消除情感重量。"},{"en":"The writer still feels heavy because honesty has hurt someone he loves.","zh":"作者仍感到沉重，因為誠實傷害了他所愛的人。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"speak to Ryan in person","meaning":"親身跟 Ryan 說話","examples":[{"en":"Tomorrow, I will speak to Ryan in person.","zh":"明天，我會親身跟 Ryan 說話。"},{"en":"Speak to Ryan in person means talk to Ryan face to face, not through messages or other people.","zh":"speak to Ryan in person 指面對面跟 Ryan 說話，而不是透過訊息或他人。"},{"en":"Difficult apologies are often better made in person.","zh":"困難道歉通常親身說會更好。"},{"en":"Speaking in person allows both people to hear tone and see emotion.","zh":"親身說話讓雙方聽到語氣，也看見情緒。"},{"en":"The writer decides that hiding behind screenshots is not enough.","zh":"作者決定躲在截圖背後並不足夠。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"apologise for","meaning":"為……道歉","examples":[{"en":"I will apologise for making a promise I should never have made.","zh":"我會為作出一個本不應作出的承諾而道歉。"},{"en":"Apologise for means say sorry for a specific action or mistake.","zh":"apologise for 指為某個具體行動或錯誤說對不起。"},{"en":"A student may apologise for breaking a friend’s trust.","zh":"學生可能為破壞朋友信任而道歉。"},{"en":"A clear apology names the wrong action instead of speaking vaguely.","zh":"清楚的道歉會說明錯誤行動，而不是含糊其詞。"},{"en":"The writer plans to apologise for the promise, not for the truth itself.","zh":"作者計劃為那個承諾道歉，而不是為真相本身道歉。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"not for telling the truth","meaning":"不是為說出真相","examples":[{"en":"I will apologise not for telling the truth, but for hurting him.","zh":"我會道歉，不是為說出真相，而是為傷害了他。"},{"en":"Not for telling the truth means the writer does not regret honesty itself.","zh":"not for telling the truth 指作者並不後悔誠實本身。"},{"en":"A person may apologise for the way they spoke, not for being honest.","zh":"一個人可能為自己說話的方式道歉，而不是為誠實道歉。"},{"en":"This distinction separates moral duty from emotional harm.","zh":"這個區分把道德責任和情感傷害分開。"},{"en":"The writer still believes truth was necessary, but he regrets the pain he caused.","zh":"作者仍相信真相是必要的，但後悔自己造成痛苦。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"make a promise","meaning":"作出承諾","examples":[{"en":"I made a promise I should never have made.","zh":"我作出了一個本不應作出的承諾。"},{"en":"Make a promise means say that one will definitely do or not do something.","zh":"make a promise 指說明自己一定會做或不做某事。"},{"en":"Friends should think carefully before making promises about serious secrets.","zh":"朋友在為嚴重秘密作出承諾前應仔細思考。"},{"en":"A promise can trap someone if it protects wrongdoing.","zh":"如果承諾保護錯事，它可能困住一個人。"},{"en":"The writer regrets promising silence before understanding the truth.","zh":"作者後悔在理解真相前答應保持沉默。"}],"source":"2013 Q3.pdf","sourcePage":12},{"front":"should never have made","meaning":"本不應作出","examples":[{"en":"I should never have made that promise.","zh":"我本不應作出那個承諾。"},{"en":"Should never have made means now recognising that a past action was a mistake.","zh":"should never have made 指現在意識到過去的行動是錯誤。"},{"en":"A student may say, “I should never have made that excuse,” after hurting a friend.","zh":"學生傷害朋友後可能會說：「我本不應作出那個藉口。」"},{"en":"This phrase expresses regret and moral learning.","zh":"這個片語表達後悔和道德上的學習。"},{"en":"The writer understands that some promises should not be made at all.","zh":"作者明白有些承諾根本不應作出。"}],"source":"2013 Q3.pdf","sourcePage":13},{"front":"behind his back","meaning":"在他背後","examples":[{"en":"I hurt Ryan behind his back.","zh":"我在 Ryan 背後傷害了他。"},{"en":"Behind his back means without him knowing or without speaking to him directly first.","zh":"behind his back 指在他不知道的情況下，或沒有先直接跟他說。"},{"en":"Talking about a friend’s mistake behind their back can damage trust.","zh":"在朋友背後談論他的錯誤，可能破壞信任。"},{"en":"Sometimes reporting quietly is necessary, but it can still feel like betrayal.","zh":"有時安靜舉報是必要的，但仍可能感覺像背叛。"},{"en":"The writer feels guilty because Ryan learned the truth through consequences, not a conversation.","zh":"作者感到內疚，因為 Ryan 是透過後果而不是對話知道真相。"}],"source":"2013 Q3.pdf","sourcePage":13},{"front":"if he never forgives me","meaning":"如果他永遠不原諒我","examples":[{"en":"If Ryan never forgives me, so be it.","zh":"如果 Ryan 永遠不原諒我，那也只好如此。"},{"en":"If he never forgives me means if he never stops feeling hurt or angry towards me.","zh":"if he never forgives me 指如果他永遠不停止對我感到受傷或憤怒。"},{"en":"A person may accept that a friend may never forgive them after a serious betrayal.","zh":"嚴重背叛後，一個人可能要接受朋友永遠不原諒自己的可能。"},{"en":"Forgiveness cannot be demanded; it must be freely given.","zh":"原諒不能被要求；它必須由對方自由給予。"},{"en":"The writer prepares to face the possibility that the friendship may not recover.","zh":"作者準備面對友誼可能無法恢復的可能。"}],"source":"2013 Q3.pdf","sourcePage":13},{"front":"so be it","meaning":"那也只好如此","examples":[{"en":"If he never forgives me, so be it.","zh":"如果他永遠不原諒我，那也只好如此。"},{"en":"So be it means I accept the result, even if it is painful.","zh":"so be it 指我接受這個結果，即使它很痛苦。"},{"en":"If the truth costs me popularity, so be it.","zh":"如果真相令我失去受歡迎程度，那也只好如此。"},{"en":"This phrase shows resignation rather than happiness.","zh":"這個片語顯示的是接受命運，而不是快樂。"},{"en":"The writer accepts that consequences may include losing Ryan’s forgiveness.","zh":"作者接受後果可能包括失去 Ryan 的原諒。"}],"source":"2013 Q3.pdf","sourcePage":13},{"front":"with every choice comes a consequence","meaning":"每個選擇都伴隨後果","examples":[{"en":"With every choice comes a consequence.","zh":"每個選擇都伴隨後果。"},{"en":"With every choice comes a consequence means every decision brings some result or cost.","zh":"with every choice comes a consequence 指每個決定都會帶來結果或代價。"},{"en":"Choosing to tell the truth may bring justice but also pain.","zh":"選擇說出真相可能帶來公義，也帶來痛苦。"},{"en":"This phrase reminds readers that no moral choice is completely free.","zh":"這個片語提醒讀者，沒有道德選擇是完全沒有代價的。"},{"en":"The writer understands that Ryan’s choice and his own choice both have consequences.","zh":"作者明白 Ryan 的選擇和自己的選擇都有後果。"}],"source":"2013 Q3.pdf","sourcePage":13},{"front":"tonight, mine is silence","meaning":"今晚，我的後果是沉默","examples":[{"en":"Tonight, the consequence of my choice is silence.","zh":"今晚，我選擇的後果是沉默。"},{"en":"Tonight, mine is silence means the result he must live with tonight is loneliness, quietness, and emotional distance.","zh":"tonight, mine is silence 指今晚他必須承受的結果是孤單、安靜和情感距離。"},{"en":"After a broken friendship, silence can feel heavier than shouting.","zh":"友誼破裂後，沉默可能比大叫更沉重。"},{"en":"The phrase shows that doing the right thing has not brought comfort yet.","zh":"這個片語顯示做正確的事尚未帶來安慰。"},{"en":"The diary ends in silence because the writer has truth but no peace.","zh":"日記在沉默中結束，因為作者有了真相，卻沒有平安。"}],"source":"2013 Q3.pdf","sourcePage":13}],"dse/writing/part-b/2013/Q4":[{"front":"children are not parcels","meaning":"孩子不是包裹","examples":[{"en":"Children are not parcels, so school bus services must protect them carefully.","zh":"孩子不是包裹，所以校巴服務必須小心保護他們。"},{"en":"“Children are not parcels” means children should not be treated like objects that can simply be moved from one place to another.","zh":"“Children are not parcels” 指孩子不應被當成只需由一地送到另一地的物件。"},{"en":"A school bus operator must remember that children are not parcels because they need care, patience, and supervision.","zh":"校巴營辦商必須記住孩子不是包裹，因為他們需要照顧、耐性和監督。"},{"en":"If staff treat children like parcels, they may ignore fear, confusion, or danger during the journey.","zh":"如果職員把孩子當成包裹，可能會忽略他們在車程中的恐懼、混亂或危險。"},{"en":"This phrase reminds adults that transporting children is a human responsibility, not just a delivery task.","zh":"這個說法提醒成人，接送孩子是一項人的責任，而不只是運送任務。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"private school bus services","meaning":"私營校巴服務","examples":[{"en":"Private school bus services in Hong Kong must be safe and reliable.","zh":"香港的私營校巴服務必須安全可靠。"},{"en":"Private school bus services are transport services run by private operators to take students to and from school.","zh":"私營校巴服務是由私人營辦商經營，接送學生往返學校的交通服務。"},{"en":"Many families use private school bus services when parents cannot take children to school themselves.","zh":"當家長不能親自送孩子上學時，許多家庭會使用私營校巴服務。"},{"en":"Private school bus services need clear safety rules because they carry young passengers every day.","zh":"私營校巴服務每天接載年幼乘客，因此需要清晰安全規則。"},{"en":"Reliable private school bus services can give parents confidence and reduce daily worry.","zh":"可靠的私營校巴服務可以給家長信心，減少每日憂慮。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"Dear Sir or Madam","meaning":"敬啟者","examples":[{"en":"A formal letter to an unknown recipient may begin with “Dear Sir or Madam”.","zh":"寫給未知收件人的正式信件可以用 “Dear Sir or Madam” 開首。"},{"en":"“Dear Sir or Madam” is a formal greeting used when the writer does not know the recipient’s name or gender.","zh":"“Dear Sir or Madam” 是在不知道收件人姓名或性別時使用的正式稱呼。"},{"en":"Dear Sir or Madam, I am writing to express my concern about school bus safety.","zh":"敬啟者：本人寫信表達對校巴安全的關注。"},{"en":"This greeting is suitable for official letters to organisations rather than close personal messages.","zh":"這個稱呼適合寫給機構的正式信件，而不是親密私人訊息。"},{"en":"It keeps the tone polite when the writer is addressing an unknown person.","zh":"當作者寫給未知人士時，它能保持有禮語氣。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"write on behalf of","meaning":"代表……寫信","examples":[{"en":"I am writing on behalf of many worried parents and students.","zh":"本人代表許多憂心的家長和學生寫信。"},{"en":"To write on behalf of someone means to write as their representative or to express their shared views.","zh":"“Write on behalf of” 指作為某人的代表寫信，或表達他們共同的看法。"},{"en":"The class monitor wrote on behalf of the students to request a safer school bus stop.","zh":"班長代表學生寫信，要求設立更安全的校巴站。"},{"en":"A person who writes on behalf of others should represent their concerns accurately and respectfully.","zh":"代表他人寫信的人，應準確而尊重地表達他們的憂慮。"},{"en":"This phrase gives the letter a collective voice, not only a personal opinion.","zh":"這個說法令信件有集體聲音，而不只是個人意見。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"worried parents and students","meaning":"憂心的家長和學生","examples":[{"en":"Many worried parents and students are concerned about school bus safety.","zh":"許多憂心的家長和學生關注校巴安全。"},{"en":"Worried parents and students are families and learners who feel anxious because they fear something may be unsafe.","zh":"憂心的家長和學生，是因害怕某事不安全而感到焦慮的家庭和學習者。"},{"en":"Worried parents and students asked the school for clearer information about bus routes.","zh":"憂心的家長和學生要求學校提供更清楚的校巴路線資料。"},{"en":"When school transport is unreliable, worried parents and students may lose trust in the service.","zh":"當學校交通服務不可靠，憂心的家長和學生可能會失去對服務的信任。"},{"en":"This phrase shows that the issue affects both children and their families.","zh":"這個說法顯示問題同時影響孩子和家庭。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"express my deep concern about","meaning":"表達我對……的深切關注","examples":[{"en":"I am writing to express my deep concern about school bus safety.","zh":"本人寫信表達我對校巴安全的深切關注。"},{"en":"To express my deep concern about something means to state clearly that I am very worried about it.","zh":"“Express my deep concern about” 指清楚表明自己對某事非常擔心。"},{"en":"Parents wrote to express their deep concern about children crossing a busy road alone.","zh":"家長寫信表達他們對孩子獨自橫過繁忙馬路的深切關注。"},{"en":"This phrase is useful in formal letters because it states the seriousness of the issue politely.","zh":"這個說法適合用於正式信件，因為它有禮地表明議題的嚴重性。"},{"en":"It shows that the writer is not complaining casually but raising an important matter.","zh":"它顯示作者不是隨便投訴，而是在提出重要問題。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"the safety of","meaning":"……的安全","examples":[{"en":"Parents are concerned about the safety of private school bus services.","zh":"家長關注私營校巴服務的安全。"},{"en":"The safety of something refers to how well it protects people from danger, injury, or harm.","zh":"“The safety of” 指某事物保護人們免受危險、受傷或傷害的程度。"},{"en":"The safety of the playground improved after broken equipment was repaired.","zh":"破損設施修好後，遊樂場的安全有所改善。"},{"en":"Parents worry about the safety of school buses because young children cannot always protect themselves.","zh":"家長擔心校巴的安全，因為年幼孩子未必能保護自己。"},{"en":"This phrase focuses attention on protection rather than convenience alone.","zh":"這個說法把注意力集中於保護，而不只是方便。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"depend on school buses","meaning":"依賴校巴","examples":[{"en":"Thousands of young children depend on school buses every day.","zh":"成千上萬年幼孩子每天依賴校巴。"},{"en":"To depend on school buses means to need school buses regularly in order to get to and from school.","zh":"“Depend on school buses” 指經常需要校巴接送才能往返學校。"},{"en":"Some children depend on school buses because their homes are far from campus.","zh":"有些孩子因家離校園很遠而依賴校巴。"},{"en":"When children depend on school buses, operators must provide safe and reliable service.","zh":"當孩子依賴校巴時，營辦商必須提供安全可靠的服務。"},{"en":"This phrase shows why school bus safety affects many families every day.","zh":"這個說法顯示校巴安全為何每天影響許多家庭。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"school transport","meaning":"學校交通服務","examples":[{"en":"School transport should give parents confidence.","zh":"學校交通服務應給家長信心。"},{"en":"School transport means the buses, routes, and services that take students to and from school.","zh":"學校交通服務指接送學生往返學校的巴士、路線和相關服務。"},{"en":"Safe school transport helps children arrive at school on time and return home safely.","zh":"安全的學校交通服務幫助孩子準時到校並安全回家。"},{"en":"Poor school transport can make parents anxious even after their children have left home.","zh":"差劣的學校交通服務會令家長即使孩子已離家仍感到焦慮。"},{"en":"This phrase covers more than vehicles; it includes the whole system of student travel.","zh":"這個說法不只包括車輛，也包括整個學生出行系統。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"a quiet assurance","meaning":"默默帶來安心的保障","examples":[{"en":"School transport should be a quiet assurance, not a daily anxiety.","zh":"學校交通服務應是默默帶來安心的保障，而不是每日的焦慮。"},{"en":"A quiet assurance is a calm sense of confidence that something is safe and dependable.","zh":"“A quiet assurance” 是一種平靜的信心，相信某事安全可靠。"},{"en":"A well-trained escort gives parents a quiet assurance that their children are watched carefully.","zh":"受過訓練的隨車照顧員，能讓家長默默感到孩子被細心看顧。"},{"en":"School transport becomes a quiet assurance when parents do not need to worry every morning.","zh":"當家長每天早上不用擔心時，學校交通服務便成為默默帶來安心的保障。"},{"en":"This phrase shows that good service brings peace of mind without needing attention.","zh":"這個說法顯示良好服務能安定人心，而不需要特別吸引注意。"}],"source":"2013 Q4.pdf","sourcePage":1},{"front":"not a daily anxiety","meaning":"而不是每日的焦慮","examples":[{"en":"School buses should not become a daily anxiety for parents.","zh":"校巴不應成為家長每日的焦慮。"},{"en":"Not a daily anxiety means not something that causes worry every single day.","zh":"“Not a daily anxiety” 指不應成為每天都造成憂慮的事情。"},{"en":"Sending a child to school should be a normal routine, not a daily anxiety.","zh":"送孩子上學應是正常日常安排，而不是每日的焦慮。"},{"en":"If parents must wonder whether the bus is safe each morning, transport becomes a daily anxiety.","zh":"如果家長每天早上都要懷疑校巴是否安全，交通服務便成為每日的焦慮。"},{"en":"This phrase contrasts reliable service with repeated fear.","zh":"這個說法把可靠服務與反覆恐懼作對比。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"raise concerns that","meaning":"提出憂慮指","examples":[{"en":"Many parents have raised concerns that some operators ignore safety procedures.","zh":"許多家長提出憂慮，指有些營辦商忽視安全程序。"},{"en":"To raise concerns that means to formally or clearly express worries about something that may be happening.","zh":"“Raise concerns that” 指正式或清楚表達對某事可能正在發生的擔憂。"},{"en":"Teachers raised concerns that students were crossing the road without supervision.","zh":"老師提出憂慮，指學生在沒有監督下橫過馬路。"},{"en":"Parents raise concerns when they believe a problem may harm children if ignored.","zh":"當家長相信問題若被忽視可能傷害孩子時，便會提出憂慮。"},{"en":"This phrase is useful for introducing public worries in a formal letter.","zh":"這個說法適合在正式信件中引出公眾憂慮。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"operators","meaning":"營辦商","examples":[{"en":"Some operators may treat safety too casually.","zh":"有些營辦商可能太隨便看待安全。"},{"en":"Operators are companies or people who run a service or business.","zh":"營辦商是經營某項服務或業務的公司或人士。"},{"en":"School bus operators arrange vehicles, drivers, escorts, and routes.","zh":"校巴營辦商安排車輛、司機、隨車照顧員和路線。"},{"en":"Operators must follow safety rules because their decisions affect children directly.","zh":"營辦商必須遵守安全規則，因為他們的決定直接影響孩子。"},{"en":"This word identifies the people responsible for providing the service.","zh":"這個詞指出負責提供服務的人。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"treat safety as","meaning":"把安全視為","examples":[{"en":"No operator should treat safety as a matter of habit only.","zh":"沒有營辦商應只把安全視為習慣問題。"},{"en":"To treat safety as something means to understand or handle safety in that particular way.","zh":"“Treat safety as” 指以某種特定方式理解或處理安全。"},{"en":"A school should not treat safety as paperwork only.","zh":"學校不應只把安全視為文書工作。"},{"en":"If operators treat safety as routine habit rather than active responsibility, important checks may be missed.","zh":"如果營辦商把安全視為例行習慣，而不是主動責任，重要檢查可能會被遺漏。"},{"en":"This phrase helps explain the attitude behind unsafe behaviour.","zh":"這個說法有助解釋不安全行為背後的態度。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"a matter of habit","meaning":"習慣問題","examples":[{"en":"Safety should not be treated merely as a matter of habit.","zh":"安全不應只被視為習慣問題。"},{"en":"A matter of habit means something done automatically because people are used to doing it.","zh":"“A matter of habit” 指因人們習慣了而自動做的事情。"},{"en":"Checking seat belts should not be only a matter of habit; it should be a required step.","zh":"檢查安全帶不應只是一個習慣問題，而應是一個必須步驟。"},{"en":"Habits can be helpful, but relying only on habit may lead to missed checks.","zh":"習慣可以有幫助，但只依賴習慣可能導致漏查。"},{"en":"This phrase warns that safety needs conscious procedures, not memory alone.","zh":"這個說法提醒我們，安全需要有意識的程序，而不只是記憶。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"rather than","meaning":"而不是","examples":[{"en":"Safety should be based on procedures rather than memory.","zh":"安全應基於程序，而不是記憶。"},{"en":"Rather than means instead of, and it clearly contrasts two choices.","zh":"“Rather than” 指「而不是」，用來清楚對比兩個選擇。"},{"en":"Drivers should follow a checklist rather than guess whether every child has left the bus.","zh":"司機應跟隨清單，而不是憑猜測判斷每個孩子是否已下車。"},{"en":"A safety system should rely on written procedures rather than personal memory.","zh":"安全系統應依賴書面程序，而不是個人記憶。"},{"en":"This phrase helps show the better choice between two possibilities.","zh":"這個說法有助顯示兩個可能選擇中較好的做法。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"non-negotiable procedures","meaning":"不容妥協的程序","examples":[{"en":"Child safety requires a set of non-negotiable procedures.","zh":"兒童安全需要一套不容妥協的程序。"},{"en":"Non-negotiable procedures are rules or steps that must always be followed and cannot be skipped.","zh":"不容妥協的程序是必須永遠遵守、不能跳過的規則或步驟。"},{"en":"Checking every seat after the route should be a non-negotiable procedure.","zh":"路線完成後檢查每個座位，應是不容妥協的程序。"},{"en":"Non-negotiable procedures protect children because staff cannot ignore them when they are busy.","zh":"不容妥協的程序能保護孩子，因為職員忙碌時也不能忽視它們。"},{"en":"This phrase shows that some safety rules must be absolute.","zh":"這個說法顯示有些安全規則必須絕對執行。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"drivers rushing to complete routes","meaning":"司機趕着完成路線","examples":[{"en":"Drivers rushing to complete routes may miss important safety steps.","zh":"司機趕着完成路線，可能會錯過重要安全步驟。"},{"en":"Drivers rushing to complete routes are drivers trying to finish their bus journeys too quickly.","zh":"“Drivers rushing to complete routes” 指司機太急於完成校巴車程。"},{"en":"A driver rushing to complete routes may forget to check whether a child is asleep at the back.","zh":"趕着完成路線的司機可能忘記檢查後排是否有孩子睡着。"},{"en":"Rushing can create danger because speed may replace careful attention.","zh":"匆忙可能造成危險，因為速度可能取代細心注意。"},{"en":"This phrase explains how time pressure can weaken safety.","zh":"這個說法解釋時間壓力如何削弱安全。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"complete routes","meaning":"完成行車路線","examples":[{"en":"Drivers should not rush to complete routes at the cost of safety.","zh":"司機不應以安全為代價趕着完成行車路線。"},{"en":"To complete routes means to finish the planned bus journeys or stops.","zh":"“Complete routes” 指完成原定巴士車程或站點。"},{"en":"A school bus driver must complete routes on time but still check every child carefully.","zh":"校巴司機需要準時完成路線，但仍要細心檢查每個孩子。"},{"en":"Completing routes quickly is not helpful if safety procedures are skipped.","zh":"如果跳過安全程序，快速完成路線並沒有幫助。"},{"en":"This phrase refers to finishing transport duties, not simply driving fast.","zh":"這個說法指完成交通職責，而不只是快速駕駛。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"bus escorts","meaning":"校巴保姆；隨車照顧員","examples":[{"en":"Bus escorts should receive proper child-safety training.","zh":"校巴隨車照顧員應接受適當兒童安全培訓。"},{"en":"Bus escorts are adults who travel on a school bus to supervise and assist children.","zh":"校巴隨車照顧員是在校巴上監督和協助孩子的成人。"},{"en":"Bus escorts help children fasten seat belts, get off safely, and find the right adult.","zh":"校巴保姆協助孩子扣好安全帶、安全下車和找到正確成人。"},{"en":"Trained bus escorts reduce risk because drivers cannot watch every child while driving.","zh":"受訓的隨車照顧員能減低風險，因為司機駕駛時不能看顧每個孩子。"},{"en":"This phrase identifies an important safety role on school buses.","zh":"這個說法指出校巴上一個重要安全角色。"}],"source":"2013 Q4.pdf","sourcePage":2},{"front":"handle several toddlers at once","meaning":"同時照顧幾名幼兒","examples":[{"en":"Escorts may have to handle several toddlers at once.","zh":"隨車照顧員可能需要同時照顧幾名幼兒。"},{"en":"To handle several toddlers at once means to look after a few very young children at the same time.","zh":"“Handle several toddlers at once” 指同一時間照顧幾名很年幼的孩子。"},{"en":"A bus escort may need to handle several toddlers at once when they all want help with seat belts.","zh":"當幾名幼兒都需要協助扣安全帶時，校巴保姆可能要同時照顧他們。"},{"en":"Handling several toddlers at once is difficult because young children may cry, move, or become confused suddenly.","zh":"同時照顧幾名幼兒並不容易，因為小孩可能突然哭、走動或感到混亂。"},{"en":"This phrase shows why proper training and enough staff are necessary.","zh":"這個說法顯示為何適當培訓和足夠人手是必要的。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"toddlers","meaning":"幼兒","examples":[{"en":"Toddlers need close supervision on school buses.","zh":"幼兒在校巴上需要密切監督。"},{"en":"Toddlers are very young children who have recently learned to walk and still need careful care.","zh":"幼兒是剛學會走路不久、仍需要細心照顧的年幼孩子。"},{"en":"Toddlers may not understand danger when a bus door opens.","zh":"當車門打開時，幼兒可能不明白危險。"},{"en":"Because toddlers can move suddenly, adults must watch them closely during transport.","zh":"由於幼兒可能突然移動，成人在接送途中必須密切看顧他們。"},{"en":"This word highlights that some passengers are too young to manage safety alone.","zh":"這個詞突顯有些乘客太年幼，不能自行處理安全。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"one missed step","meaning":"一個疏漏","examples":[{"en":"One missed step can quickly become a serious danger.","zh":"一個疏漏可以很快變成嚴重危險。"},{"en":"One missed step means one safety action that staff forget, skip, or fail to complete.","zh":"“One missed step” 指職員忘記、跳過或沒有完成的一個安全步驟。"},{"en":"Forgetting to count children after they get off is one missed step that can cause fear and confusion.","zh":"孩子下車後忘記點算人數，就是一個可能造成恐懼和混亂的疏漏。"},{"en":"In child transport, one missed step may matter because young children cannot fix the problem themselves.","zh":"在兒童交通服務中，一個疏漏可能很重要，因為年幼孩子不能自行補救。"},{"en":"This phrase warns that small errors can have large consequences.","zh":"這個說法提醒我們，小錯誤可以帶來大後果。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"serious danger","meaning":"嚴重危險","examples":[{"en":"A small mistake can quickly become a serious danger.","zh":"一個小錯誤可以很快變成嚴重危險。"},{"en":"Serious danger is a situation that may cause real harm, injury, or loss.","zh":"嚴重危險是可能造成真正傷害、受傷或損失的情況。"},{"en":"A child left alone on a bus could face serious danger, especially in hot weather.","zh":"孩子被單獨遺留在校巴上，尤其在炎熱天氣下，可能面對嚴重危險。"},{"en":"Serious danger can develop from small mistakes when no one checks carefully.","zh":"如果沒有人仔細檢查，小錯誤也可能發展成嚴重危險。"},{"en":"This phrase makes clear that school bus safety is urgent, not minor.","zh":"這個說法清楚表明校巴安全是緊急問題，而不是小事。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"the body representing","meaning":"代表……的機構","examples":[{"en":"The Association is the body representing private school bus operators.","zh":"該協會是代表私營校巴營辦商的機構。"},{"en":"The body representing a group is the organisation that speaks or acts for that group.","zh":"“The body representing” 某群體，是為該群體發聲或行動的組織。"},{"en":"A teachers’ union is a body representing teachers in discussions with the government.","zh":"教師工會是與政府討論時代表教師的機構。"},{"en":"The body representing operators should set standards because it understands the industry.","zh":"代表營辦商的機構應制定標準，因為它了解行業。"},{"en":"This phrase identifies who has authority to coordinate action.","zh":"這個說法指出誰有權協調行動。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"private school bus service operators","meaning":"私營校巴服務營辦商","examples":[{"en":"The Association represents private school bus service operators.","zh":"該協會代表私營校巴服務營辦商。"},{"en":"Private school bus service operators are companies or individuals who run school bus services outside direct public operation.","zh":"私營校巴服務營辦商是經營非直接公營校巴服務的公司或個人。"},{"en":"Private school bus service operators arrange drivers, escorts, vehicles, and routes for students.","zh":"私營校巴服務營辦商為學生安排司機、隨車照顧員、車輛和路線。"},{"en":"These operators must follow strong safety standards because they carry children.","zh":"這些營辦商接載孩子，因此必須遵守嚴格安全標準。"},{"en":"This phrase names the industry group being addressed in the letter.","zh":"這個說法指出信件所針對的行業群體。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"take the lead in","meaning":"帶頭","examples":[{"en":"The Association should take the lead in tightening industry standards.","zh":"該協會應帶頭收緊行業標準。"},{"en":"To take the lead in something means to be the first or main group to guide action.","zh":"“Take the lead in” 指成為首先或主要引導行動的一方。"},{"en":"The school should take the lead in improving road safety near the gate.","zh":"學校應帶頭改善校門附近的道路安全。"},{"en":"An industry association can take the lead by setting rules before accidents happen.","zh":"行業協會可以在意外發生前制定規則，主動帶頭。"},{"en":"This phrase suggests responsibility and initiative.","zh":"這個說法暗示責任和主動性。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"tightening industry standards","meaning":"收緊行業標準","examples":[{"en":"The Association should take the lead in tightening industry standards.","zh":"該協會應帶頭收緊行業標準。"},{"en":"Tightening industry standards means making the rules for an industry stricter and clearer.","zh":"收緊行業標準指令某行業的規則更嚴格和清晰。"},{"en":"Tightening safety standards can require drivers to complete more regular training.","zh":"收緊安全標準可以要求司機完成更定期的培訓。"},{"en":"Industry standards should be tightened when existing practices leave too much room for error.","zh":"當現有做法留下太多出錯空間時，行業標準便應收緊。"},{"en":"This phrase shows a practical way to improve safety across all operators.","zh":"這個說法顯示改善所有營辦商安全的一種實際方法。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"in order to","meaning":"為了","examples":[{"en":"The Association should act in order to rebuild public confidence.","zh":"該協會應採取行動，為了重建公眾信心。"},{"en":"In order to means for the purpose of achieving a particular result.","zh":"“In order to” 指為了達成某個特定結果。"},{"en":"Drivers receive training in order to handle emergencies safely.","zh":"司機接受培訓，是為了安全處理緊急情況。"},{"en":"The Association should set clear rules in order to protect children better.","zh":"該協會應制定清晰規則，為了更好保護兒童。"},{"en":"This phrase clearly connects an action with its purpose.","zh":"這個說法清楚連接行動和目的。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"rebuild public confidence","meaning":"重建公眾信心","examples":[{"en":"Clearer standards can help rebuild public confidence.","zh":"更清晰的標準可以幫助重建公眾信心。"},{"en":"To rebuild public confidence means to restore people’s trust after worry or disappointment.","zh":"“Rebuild public confidence” 指在憂慮或失望後恢復市民信任。"},{"en":"After repeated delays, the company needed to rebuild public confidence through honest updates.","zh":"多次延誤後，公司需要透過誠實更新來重建公眾信心。"},{"en":"School bus operators can rebuild public confidence by proving that safety rules are enforced.","zh":"校巴營辦商可以透過證明安全規則得到執行來重建公眾信心。"},{"en":"This phrase shows that trust must be earned again through action.","zh":"這個說法顯示信任必須透過行動重新贏得。"}],"source":"2013 Q4.pdf","sourcePage":3},{"front":"protect children","meaning":"保護兒童","examples":[{"en":"The main aim is to protect children on school buses.","zh":"主要目標是在校巴上保護兒童。"},{"en":"To protect children means to keep them safe from harm, danger, neglect, or avoidable risk.","zh":"「保護兒童」指讓孩子遠離傷害、危險、疏忽或可避免風險。"},{"en":"Adults protect children by checking seat belts and supervising them when they get off.","zh":"成人透過檢查安全帶和監督孩子下車來保護兒童。"},{"en":"Strong school bus procedures protect children because young passengers may not notice danger.","zh":"嚴格校巴程序能保護兒童，因為年幼乘客未必察覺危險。"},{"en":"This phrase places children’s safety at the centre of the argument.","zh":"這個說法把兒童安全放在論點中心。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"unable to protect themselves","meaning":"無法保護自己","examples":[{"en":"Young children are often unable to protect themselves.","zh":"年幼孩子往往無法保護自己。"},{"en":"Unable to protect themselves means not having enough age, strength, knowledge, or judgement to stay safe alone.","zh":"“Unable to protect themselves” 指因年齡、力量、知識或判斷力不足，不能獨自保持安全。"},{"en":"Toddlers are unable to protect themselves when traffic is close and adults are not watching.","zh":"當車流靠近而成人沒有看顧時，幼兒無法保護自己。"},{"en":"Because children may be unable to protect themselves, adults must build safer systems for them.","zh":"因為孩子可能無法保護自己，成人必須為他們建立更安全的系統。"},{"en":"This phrase explains why school bus safety cannot depend on children’s own judgement.","zh":"這個說法解釋為何校巴安全不能依賴孩子自己的判斷。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"strongly recommend that","meaning":"強烈建議","examples":[{"en":"I strongly recommend that the Association introduce new safety measures.","zh":"本人強烈建議該協會推出新的安全措施。"},{"en":"Strongly recommend that means firmly suggest that someone should do something.","zh":"“Strongly recommend that” 指堅定地建議某人應做某事。"},{"en":"Parents strongly recommend that drivers receive yearly safety training.","zh":"家長強烈建議司機每年接受安全培訓。"},{"en":"This phrase is formal and persuasive because it clearly states what action is needed.","zh":"這個說法正式而有說服力，因為它清楚指出需要甚麼行動。"},{"en":"It shows that the writer believes the recommendation is important, not optional.","zh":"它顯示作者認為該建議重要，而不是可有可無。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"introduce compulsory safety training","meaning":"推行強制安全培訓","examples":[{"en":"The Association should introduce compulsory safety training.","zh":"該協會應推行強制安全培訓。"},{"en":"To introduce compulsory safety training means to start required training that all relevant staff must complete.","zh":"「推行強制安全培訓」指開始要求所有相關職員必須完成安全訓練。"},{"en":"A bus company may introduce compulsory safety training for new drivers and escorts.","zh":"巴士公司可以為新司機和隨車照顧員推行強制安全培訓。"},{"en":"Compulsory training ensures that safety knowledge does not depend only on personal experience.","zh":"強制培訓能確保安全知識不只依賴個人經驗。"},{"en":"This phrase suggests a direct way to improve professional standards.","zh":"這個說法提出直接改善專業標準的方法。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"standardised child-check system","meaning":"標準化兒童點算系統","examples":[{"en":"Each bus should use a standardised child-check system.","zh":"每輛校巴應使用標準化兒童點算系統。"},{"en":"A standardised child-check system is a common set of steps used to count and confirm every child’s safety.","zh":"標準化兒童點算系統是一套共同步驟，用來點算並確認每名孩子的安全。"},{"en":"A standardised child-check system may include attendance lists, seat checks, and handover records.","zh":"標準化兒童點算系統可以包括點名表、座位檢查和交接記錄。"},{"en":"Such a system prevents confusion because every operator follows the same basic procedure.","zh":"這種系統能防止混亂，因為每個營辦商都跟隨同一基本程序。"},{"en":"This phrase shows that child safety should be systematic, not casual.","zh":"這個說法顯示兒童安全應有系統，而不是隨便處理。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"transparent monitoring mechanism","meaning":"透明監察機制","examples":[{"en":"The Association should create a transparent monitoring mechanism.","zh":"該協會應建立透明監察機制。"},{"en":"A transparent monitoring mechanism is a clear system for checking performance and letting people understand how checks are done.","zh":"透明監察機制是一套清楚檢查表現，並讓人理解檢查如何進行的系統。"},{"en":"A transparent monitoring mechanism may include inspections, records, complaint handling, and public updates.","zh":"透明監察機制可以包括巡查、記錄、投訴處理和公開更新。"},{"en":"Transparency matters because parents need to know that safety rules are actually followed.","zh":"透明度很重要，因為家長需要知道安全規則確實被遵守。"},{"en":"This phrase shows that rules need visible enforcement.","zh":"這個說法顯示規則需要看得見的執行。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"be required to complete","meaning":"被要求完成","examples":[{"en":"All drivers and escorts should be required to complete safety training.","zh":"所有司機和隨車照顧員都應被要求完成安全培訓。"},{"en":"Be required to complete means be officially told that finishing a task is necessary.","zh":"“Be required to complete” 指被正式要求必須完成某項任務。"},{"en":"New staff should be required to complete first-aid training before working with children.","zh":"新職員在與兒童工作前，應被要求完成急救培訓。"},{"en":"If training is required, operators cannot treat it as a personal choice.","zh":"如果培訓是必須完成的，營辦商便不能把它視為個人選擇。"},{"en":"This phrase introduces a formal duty rather than a suggestion.","zh":"這個說法引出正式責任，而不只是建議。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"recognised child-safety training","meaning":"認可兒童安全培訓","examples":[{"en":"Drivers should complete recognised child-safety training.","zh":"司機應完成認可兒童安全培訓。"},{"en":"Recognised child-safety training is approved training that teaches adults how to protect children properly.","zh":"認可兒童安全培訓是經批准、教導成人如何正確保護兒童的培訓。"},{"en":"Recognised child-safety training may include supervision, emergency response, and safe handover procedures.","zh":"認可兒童安全培訓可以包括監督、緊急應對和安全交接程序。"},{"en":"Training is more trustworthy when it is recognised by a responsible authority.","zh":"當培訓得到負責任機構認可時，會更值得信任。"},{"en":"This phrase shows that safety education should meet accepted standards.","zh":"這個說法顯示安全教育應符合公認標準。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"be allowed to serve school routes","meaning":"獲准服務校巴路線","examples":[{"en":"Staff should complete training before they are allowed to serve school routes.","zh":"職員應完成培訓後才獲准服務校巴路線。"},{"en":"Be allowed to serve school routes means be permitted to work on journeys that transport students.","zh":"“Be allowed to serve school routes” 指獲准在接送學生的車程中工作。"},{"en":"Drivers should not be allowed to serve school routes until they understand child-safety rules.","zh":"司機在了解兒童安全規則前，不應獲准服務校巴路線。"},{"en":"Requiring training before staff serve routes helps prevent avoidable mistakes.","zh":"要求職員在服務路線前接受培訓，有助防止可避免錯誤。"},{"en":"This phrase links permission to proper preparation.","zh":"這個說法把許可與適當準備連接起來。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"It is one thing to…, it is another to…","meaning":"……是一回事，……是另一回事","examples":[{"en":"It is one thing to drive carefully; it is another to look after young children.","zh":"小心駕駛是一回事，照顧年幼孩子又是另一回事。"},{"en":"“It is one thing to…, it is another to…” contrasts an easier or different task with a more difficult one.","zh":"“It is one thing to…, it is another to…” 用來對比一項較容易或不同的任務與另一項較困難的任務。"},{"en":"It is one thing to know traffic rules; it is another to calm a crying child on a bus.","zh":"懂交通規則是一回事，在巴士上安撫哭泣的孩子又是另一回事。"},{"en":"This structure shows that safe driving alone is not enough for school bus work.","zh":"這個結構顯示單靠安全駕駛不足以應付校巴工作。"},{"en":"It helps explain why special child-care training is needed.","zh":"它有助解釋為何需要特別兒童照顧培訓。"}],"source":"2013 Q4.pdf","sourcePage":4},{"front":"drive carefully","meaning":"小心駕駛","examples":[{"en":"School bus drivers must drive carefully at all times.","zh":"校巴司機必須時刻小心駕駛。"},{"en":"To drive carefully means to control a vehicle safely, calmly, and with attention to road conditions.","zh":"「小心駕駛」指安全、冷靜並留意路面情況地控制車輛。"},{"en":"Drivers must drive carefully near schools because children may move suddenly.","zh":"司機在學校附近必須小心駕駛，因為孩子可能突然移動。"},{"en":"Careful driving reduces the risk of sudden stops, accidents, and passenger injuries.","zh":"小心駕駛能減少急煞、意外和乘客受傷的風險。"},{"en":"This phrase describes a basic duty of every school bus driver.","zh":"這個說法描述每位校巴司機的基本責任。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"look after three-year-olds","meaning":"照顧三歲幼兒","examples":[{"en":"Escorts must know how to look after three-year-olds.","zh":"隨車照顧員必須知道如何照顧三歲幼兒。"},{"en":"To look after three-year-olds means to care for very young children who need close help and supervision.","zh":"“Look after three-year-olds” 指照顧非常年幼、需要密切協助和監督的孩子。"},{"en":"Looking after three-year-olds on a bus may include fastening belts and helping them step down safely.","zh":"在巴士上照顧三歲幼兒，可能包括扣安全帶和協助他們安全下車。"},{"en":"Three-year-olds may not understand instructions quickly, so adults must be patient.","zh":"三歲幼兒未必能快速明白指示，所以成人必須有耐性。"},{"en":"This phrase shows why school bus escorts need child-care skills.","zh":"這個說法顯示為何校巴保姆需要兒童照顧技巧。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"unbuckle their belts","meaning":"解開安全帶","examples":[{"en":"Young children may unbuckle their belts during the journey.","zh":"年幼孩子可能在車程中解開安全帶。"},{"en":"To unbuckle their belts means to open or release their seat belts.","zh":"“Unbuckle their belts” 指打開或鬆開安全帶。"},{"en":"A child may unbuckle his belt because he feels uncomfortable or curious.","zh":"孩子可能因感到不舒服或好奇而解開安全帶。"},{"en":"If children unbuckle their belts while the bus is moving, they may be injured during sudden braking.","zh":"如果孩子在校巴行駛時解開安全帶，急煞時可能會受傷。"},{"en":"This phrase shows one behaviour that escorts must watch for.","zh":"這個說法顯示隨車照顧員必須留意的一種行為。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"cry suddenly","meaning":"突然哭起來","examples":[{"en":"A frightened child may cry suddenly on the bus.","zh":"受驚的孩子可能在校巴上突然哭起來。"},{"en":"To cry suddenly means to begin crying quickly and unexpectedly.","zh":"“Cry suddenly” 指快速而意外地開始哭。"},{"en":"A toddler may cry suddenly when the bus becomes noisy or crowded.","zh":"當校巴變得嘈吵或擠迫時，幼兒可能突然哭起來。"},{"en":"If a child cries suddenly, an escort should respond calmly and safely.","zh":"如果孩子突然哭起來，隨車照顧員應冷靜而安全地回應。"},{"en":"This phrase shows that bus staff must be ready for children’s emotional reactions.","zh":"這個說法顯示校巴職員必須準備好面對孩子的情緒反應。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"fall asleep","meaning":"睡着","examples":[{"en":"A young child may fall asleep in the back seat.","zh":"年幼孩子可能在後排座位睡着。"},{"en":"To fall asleep means to begin sleeping.","zh":"“Fall asleep” 指開始睡覺。"},{"en":"A tired kindergarten pupil may fall asleep before the bus reaches home.","zh":"疲累的幼稚園學生可能在校巴到家前睡着。"},{"en":"If staff do not check carefully, a child who falls asleep may be left behind.","zh":"如果職員沒有仔細檢查，睡着的孩子可能會被遺留。"},{"en":"This phrase explains why every row must be checked after each route.","zh":"這個說法解釋為何每條路線後都必須檢查每一排座位。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"run towards the road","meaning":"跑向馬路","examples":[{"en":"A child may run towards the road when the door opens.","zh":"當車門打開時，孩子可能跑向馬路。"},{"en":"To run towards the road means to move quickly in the direction of traffic.","zh":"“Run towards the road” 指快速朝車流方向跑去。"},{"en":"A child may run towards the road after seeing a parent on the opposite side.","zh":"孩子看到父母在對面時，可能會跑向馬路。"},{"en":"Running towards the road is dangerous because drivers may not expect a child to move suddenly.","zh":"跑向馬路很危險，因為司機未必預料孩子會突然移動。"},{"en":"This phrase shows why adults must guide children when they get off.","zh":"這個說法顯示孩子下車時為何必須有成人指導。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"when the door opens","meaning":"當車門打開時","examples":[{"en":"A child may move suddenly when the bus door opens.","zh":"當車門打開時，孩子可能突然移動。"},{"en":"When the door opens means at the moment the door becomes open and people can leave or enter.","zh":"“When the door opens” 指車門打開、人們可以出入的那一刻。"},{"en":"Children should wait for the escort’s instruction when the door opens.","zh":"當車門打開時，孩子應等待隨車照顧員指示。"},{"en":"The moment the door opens can be risky because children may rush out.","zh":"車門打開的一刻可能有風險，因為孩子可能衝出去。"},{"en":"This phrase identifies a key moment when supervision is needed.","zh":"這個說法指出需要監督的關鍵時刻。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"a trained escort","meaning":"受過訓練的隨車照顧員","examples":[{"en":"A trained escort would know how to calm a frightened child.","zh":"受過訓練的隨車照顧員會知道如何安撫受驚的孩子。"},{"en":"A trained escort is a bus assistant who has received proper instruction in child safety and care.","zh":"受過訓練的隨車照顧員，是接受過兒童安全和照顧指導的校巴助理。"},{"en":"A trained escort can help children fasten belts and leave the bus safely.","zh":"受訓隨車照顧員可以協助孩子扣安全帶和安全下車。"},{"en":"Training helps an escort respond calmly instead of guessing what to do.","zh":"培訓幫助隨車照顧員冷靜回應，而不是猜測該怎樣做。"},{"en":"This phrase shows that safety depends on preparation, not only kindness.","zh":"這個說法顯示安全取決於準備，而不只是善意。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"seat younger pupils first","meaning":"先安排年幼學生入座","examples":[{"en":"A trained escort should seat younger pupils first.","zh":"受過訓練的隨車照顧員應先安排年幼學生入座。"},{"en":"To seat younger pupils first means to help the youngest children sit down before others.","zh":"“Seat younger pupils first” 指先協助最年幼的學生坐下。"},{"en":"An escort may seat younger pupils first so they do not stand in the aisle while the bus prepares to move.","zh":"隨車照顧員可以先安排年幼學生入座，讓他們在校巴準備開動時不會站在通道。"},{"en":"Seating younger pupils first reduces confusion because the children who need most help are settled early.","zh":"先安排年幼學生入座能減少混亂，因為最需要幫助的孩子會先安頓好。"},{"en":"This phrase describes a practical routine for safer boarding.","zh":"這個說法描述一個令上車更安全的實際常規。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"calm a frightened child","meaning":"安撫受驚的孩子","examples":[{"en":"An escort should know how to calm a frightened child.","zh":"隨車照顧員應知道如何安撫受驚的孩子。"},{"en":"To calm a frightened child means to help a scared child feel safer and less upset.","zh":"「安撫受驚的孩子」指幫助害怕的孩子感到較安全和較不難過。"},{"en":"A gentle voice can calm a frightened child who is crying on the bus.","zh":"溫柔的聲音可以安撫在校巴上哭泣的受驚孩子。"},{"en":"Calming a frightened child is important because panic can lead to sudden movement or unsafe behaviour.","zh":"安撫受驚的孩子很重要，因為驚慌可能導致突然移動或不安全行為。"},{"en":"This phrase shows that emotional care is part of transport safety.","zh":"這個說法顯示情緒照顧也是交通安全的一部分。"}],"source":"2013 Q4.pdf","sourcePage":5},{"front":"stop children from standing","meaning":"阻止兒童站立","examples":[{"en":"Escorts should stop children from standing while the bus is moving.","zh":"當校巴行駛時，隨車照顧員應阻止兒童站立。"},{"en":"To stop children from standing means to prevent children from remaining on their feet when they should be seated.","zh":"「阻止兒童站立」指防止孩子在應坐好時仍然站着。"},{"en":"An escort should stop children from standing by reminding them to sit and fasten their belts.","zh":"隨車照顧員應提醒孩子坐好並扣上安全帶，以阻止兒童站立。"},{"en":"Standing on a moving bus can be dangerous because sudden braking may make children fall.","zh":"在行駛中的巴士上站立很危險，因為急煞可能令孩子跌倒。"},{"en":"This phrase names a clear safety duty during the journey.","zh":"這個說法指出車程中的一項清晰安全職責。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"while the bus is moving","meaning":"當校巴行駛時","examples":[{"en":"Children should not stand while the bus is moving.","zh":"當校巴行駛時，孩子不應站立。"},{"en":"While the bus is moving means during the time when the bus is travelling, not stopped.","zh":"“While the bus is moving” 指巴士正在行駛而不是停下的時候。"},{"en":"Passengers should stay seated while the bus is moving through busy traffic.","zh":"當巴士在繁忙車流中行駛時，乘客應保持坐好。"},{"en":"Children may lose balance more easily while the bus is moving.","zh":"當校巴行駛時，孩子可能更容易失去平衡。"},{"en":"This phrase identifies a time when safety rules must be especially strict.","zh":"這個說法指出安全規則必須特別嚴格的時間。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"send staff to an annual course","meaning":"派職員參加年度課程","examples":[{"en":"Operators could send staff to an annual safety course.","zh":"營辦商可以派職員參加年度安全課程。"},{"en":"To send staff to an annual course means to arrange for employees to attend training once every year.","zh":"“Send staff to an annual course” 指安排員工每年一次參加培訓。"},{"en":"A bus company can send staff to an annual course on emergency evacuation.","zh":"巴士公司可以派職員參加有關緊急疏散的年度課程。"},{"en":"Annual courses help staff refresh knowledge instead of relying on old habits.","zh":"年度課程幫助職員更新知識，而不是依賴舊習慣。"},{"en":"This phrase suggests regular training rather than one-time instruction.","zh":"這個說法建議定期培訓，而不是一次性指導。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"first aid","meaning":"急救","examples":[{"en":"The course should cover first aid and emergency evacuation.","zh":"課程應涵蓋急救和緊急疏散。"},{"en":"First aid is basic help given to an injured or ill person before professional medical care arrives.","zh":"急救是在專業醫療人員到達前，給受傷或不適者的基本幫助。"},{"en":"A bus escort with first-aid knowledge can respond quickly if a child falls.","zh":"具急救知識的隨車照顧員，在孩子跌倒時可以快速回應。"},{"en":"First aid training is important because small injuries may happen during boarding or alighting.","zh":"急救培訓很重要，因為孩子上車或下車時可能發生小傷。"},{"en":"This phrase refers to practical skills that protect children in urgent situations.","zh":"這個說法指在緊急情況中保護孩子的實用技能。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"emergency evacuation","meaning":"緊急疏散","examples":[{"en":"Bus staff should learn emergency evacuation procedures.","zh":"校巴職員應學習緊急疏散程序。"},{"en":"Emergency evacuation means moving people quickly and safely away from danger.","zh":"緊急疏散指快速而安全地把人帶離危險。"},{"en":"If a bus breaks down in a dangerous place, staff may need emergency evacuation procedures.","zh":"如果校巴在危險位置故障，職員可能需要使用緊急疏散程序。"},{"en":"Children need clear guidance during emergency evacuation because they may panic.","zh":"緊急疏散時，孩子需要清楚指導，因為他們可能驚慌。"},{"en":"This phrase shows that staff must prepare for rare but serious situations.","zh":"這個說法顯示職員必須為罕見但嚴重的情況作準備。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"child psychology","meaning":"兒童心理學","examples":[{"en":"Child psychology can help escorts understand young passengers.","zh":"兒童心理學可以幫助隨車照顧員理解年幼乘客。"},{"en":"Child psychology is the study of how children think, feel, learn, and behave.","zh":"兒童心理學是研究兒童如何思考、感受、學習和行為的學問。"},{"en":"Basic child psychology helps adults understand why a toddler may cry when separated from a parent.","zh":"基本兒童心理學幫助成人理解幼兒為何與父母分開時會哭。"},{"en":"Bus escorts with child-psychology knowledge can respond more patiently to fear or confusion.","zh":"具兒童心理學知識的校巴保姆，能更有耐性地回應恐懼或混亂。"},{"en":"This phrase shows that safety also requires understanding children’s emotions.","zh":"這個說法顯示安全也需要理解孩子的情緒。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"traffic-side hazards","meaning":"近車路一邊的危險","examples":[{"en":"The course should cover traffic-side hazards.","zh":"課程應涵蓋近車路一邊的危險。"},{"en":"Traffic-side hazards are dangers on the side of the bus closest to moving vehicles.","zh":"近車路一邊的危險，是指校巴靠近行駛車輛那一邊的風險。"},{"en":"A child getting off on the traffic side may be too close to cars or motorcycles.","zh":"孩子若在近車路一邊下車，可能太接近汽車或電單車。"},{"en":"Training about traffic-side hazards teaches staff where children should stand and exit.","zh":"有關近車路一邊危險的培訓，會教職員孩子應站在哪裏和從哪裏下車。"},{"en":"This phrase highlights a specific danger during boarding and alighting.","zh":"這個說法突顯上車和下車時的一項具體危險。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"communication with schools","meaning":"與學校溝通","examples":[{"en":"Drivers and escorts need clear communication with schools.","zh":"司機和隨車照顧員需要與學校清楚溝通。"},{"en":"Communication with schools means sharing information with schools about routes, delays, students, and safety issues.","zh":"與學校溝通指與學校分享路線、延誤、學生和安全問題等資訊。"},{"en":"Good communication with schools helps parents receive updates when a bus is late.","zh":"良好的與學校溝通，可以在校巴遲到時幫助家長收到最新消息。"},{"en":"Without communication with schools, small problems may become confusing for families.","zh":"如果沒有與學校溝通，小問題可能令家庭感到混亂。"},{"en":"This phrase shows that bus safety depends on cooperation, not only driving.","zh":"這個說法顯示校巴安全取決於合作，而不只是駕駛。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"receive a certificate","meaning":"獲發證書","examples":[{"en":"Staff should receive a certificate after completing the course.","zh":"職員完成課程後應獲發證書。"},{"en":"To receive a certificate means to get an official document proving that training or study has been completed.","zh":"“Receive a certificate” 指得到一份官方文件，證明已完成培訓或學習。"},{"en":"Drivers who complete the safety course should receive a certificate from the Association.","zh":"完成安全課程的司機應由協會獲發證書。"},{"en":"Certificates help schools and parents know that staff have received proper training.","zh":"證書幫助學校和家長知道職員已接受適當培訓。"},{"en":"This phrase connects training with visible proof.","zh":"這個說法把培訓與可見證明連接起來。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"display their identification clearly","meaning":"清楚展示身分證明","examples":[{"en":"Staff should display their identification clearly.","zh":"職員應清楚展示身分證明。"},{"en":"To display their identification clearly means to show their name card, badge, or official proof in an easy-to-see way.","zh":"“Display their identification clearly” 指以容易看見的方式展示名牌、職員證或官方證明。"},{"en":"A bus escort should display her identification clearly so parents know who is responsible.","zh":"校巴保姆應清楚展示身分證明，讓家長知道誰負責。"},{"en":"Clear identification helps children, parents, and schools recognise authorised staff.","zh":"清楚身分證明幫助孩子、家長和學校認出獲授權職員。"},{"en":"This phrase supports transparency and accountability.","zh":"這個說法支持透明度和問責性。"}],"source":"2013 Q4.pdf","sourcePage":6},{"front":"involve time and cost","meaning":"涉及時間和成本","examples":[{"en":"Training may involve time and cost.","zh":"培訓可能涉及時間和成本。"},{"en":"To involve time and cost means to require both effort over a period and money to carry out.","zh":"“Involve time and cost” 指需要花時間和金錢才能執行。"},{"en":"Installing safety equipment may involve time and cost, but it can prevent accidents.","zh":"安裝安全設備可能涉及時間和成本，但它可以防止意外。"},{"en":"Operators may resist training because it involves time and cost.","zh":"營辦商可能因培訓涉及時間和成本而抗拒。"},{"en":"This phrase admits a practical burden before arguing that safety is still worth it.","zh":"這個說法先承認實際負擔，再主張安全仍然值得。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, children’s safety must come first.","zh":"然而，兒童安全必須放在第一位。"},{"en":"Nevertheless means despite the previous point, the following point is still true or more important.","zh":"“Nevertheless” 指儘管前面一點存在，後面的觀點仍然成立或更重要。"},{"en":"The new system may cost money; nevertheless, it is necessary for safety.","zh":"新系統可能要花錢；然而，為了安全它是必要的。"},{"en":"This word is useful when admitting a difficulty before stating a stronger reason.","zh":"這個詞適合在承認困難後提出更強理由。"},{"en":"It helps the writer sound balanced but firm.","zh":"它幫助作者聽起來平衡但堅定。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"when it comes to","meaning":"當談到……時","examples":[{"en":"When it comes to children’s safety, professionalism matters most.","zh":"當談到兒童安全時，專業精神最重要。"},{"en":"When it comes to means when discussing or dealing with a particular subject.","zh":"“When it comes to” 指當討論或處理某個特定主題時。"},{"en":"When it comes to road safety, small details can save lives.","zh":"當談到道路安全時，小細節可以救命。"},{"en":"This phrase introduces the area where a rule or opinion is especially important.","zh":"這個說法引出某項規則或看法尤其重要的範疇。"},{"en":"It helps focus the reader on the key issue.","zh":"它幫助讀者集中於核心議題。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"professionalism","meaning":"專業精神","examples":[{"en":"Professionalism must matter more than convenience.","zh":"專業精神必須比方便更重要。"},{"en":"Professionalism means doing work responsibly, carefully, ethically, and to a high standard.","zh":"專業精神指以負責、仔細、合乎道德和高標準的方式工作。"},{"en":"A professional escort follows safety steps even when the bus is running late.","zh":"專業的隨車照顧員即使校巴遲到，也會跟足安全步驟。"},{"en":"Professionalism is important in child transport because children depend on adults’ judgement.","zh":"專業精神在兒童交通服務中很重要，因為孩子依賴成人判斷。"},{"en":"This word shows that school bus work should be treated as skilled service.","zh":"這個詞顯示校巴工作應被視為專業服務。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"matter more than convenience","meaning":"比方便更重要","examples":[{"en":"Children’s safety must matter more than convenience.","zh":"兒童安全必須比方便更重要。"},{"en":"Matter more than convenience means be more important than saving time, effort, or trouble.","zh":"“Matter more than convenience” 指比節省時間、力氣或麻煩更重要。"},{"en":"Checking every seat matters more than convenience, even if the driver is tired.","zh":"即使司機疲累，檢查每個座位也比方便更重要。"},{"en":"Safety must matter more than convenience because a small shortcut can cause harm.","zh":"安全必須比方便更重要，因為一個小捷徑可能造成傷害。"},{"en":"This phrase sets a clear order of priorities.","zh":"這個說法清楚列出優先次序。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"translate into","meaning":"轉化為","examples":[{"en":"Better training translates into safer journeys.","zh":"更好的培訓會轉化為更安全的車程。"},{"en":"To translate into something means to become or produce a particular practical result.","zh":"“Translate into” 指變成或產生某個實際結果。"},{"en":"Clear instructions translate into fewer mistakes during busy mornings.","zh":"清晰指示會轉化為繁忙早上較少錯誤。"},{"en":"Training translates into safer journeys when staff know exactly what to do.","zh":"當職員清楚知道該怎樣做時，培訓便會轉化為更安全的車程。"},{"en":"This phrase links preparation with real-world improvement.","zh":"這個說法把準備與現實改善連接起來。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"careless decisions","meaning":"粗心的決定","examples":[{"en":"Better training can reduce careless decisions.","zh":"更好的培訓可以減少粗心的決定。"},{"en":"Careless decisions are choices made without enough attention, thought, or responsibility.","zh":"粗心的決定是沒有足夠注意、思考或責任感而作出的選擇。"},{"en":"Letting a child get off on the traffic side is a careless decision.","zh":"讓孩子在近車路一邊下車，是一個粗心的決定。"},{"en":"Clear procedures reduce careless decisions because staff have steps to follow.","zh":"清晰程序能減少粗心決定，因為職員有步驟可跟隨。"},{"en":"This phrase shows how poor judgement can create safety risks.","zh":"這個說法顯示差劣判斷如何造成安全風險。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"safer journeys","meaning":"更安全的車程","examples":[{"en":"Better procedures can create safer journeys for children.","zh":"更好的程序可以為孩子創造更安全的車程。"},{"en":"Safer journeys are trips with fewer risks, better supervision, and stronger protection.","zh":"更安全的車程是風險較少、監督較好和保護較強的旅程。"},{"en":"Seat-belt checks and careful handovers help create safer journeys.","zh":"安全帶檢查和細心交接有助創造更安全的車程。"},{"en":"Safer journeys give parents confidence because children are protected from boarding to arrival.","zh":"更安全的車程讓家長有信心，因為孩子由上車到抵達都受到保護。"},{"en":"This phrase focuses on the whole trip, not only the driving.","zh":"這個說法關注整段旅程，而不只是駕駛。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"adopt a strict step-by-step procedure","meaning":"採用嚴格的逐步程序","examples":[{"en":"Operators should adopt a strict step-by-step procedure.","zh":"營辦商應採用嚴格的逐步程序。"},{"en":"To adopt a strict step-by-step procedure means to start using a clear sequence of required actions.","zh":"「採用嚴格的逐步程序」指開始使用一套清晰、有先後次序且必須執行的行動。"},{"en":"A bus operator should adopt a strict step-by-step procedure for boarding and alighting.","zh":"校巴營辦商應為上車和下車採用嚴格的逐步程序。"},{"en":"Step-by-step procedures reduce mistakes because staff do not have to rely on memory alone.","zh":"逐步程序能減少錯誤，因為職員不用只依賴記憶。"},{"en":"This phrase suggests organised and repeatable safety practice.","zh":"這個說法建議有組織且可重複的安全做法。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"boarding, travelling and alighting","meaning":"上車、乘車和下車","examples":[{"en":"There should be clear rules for boarding, travelling and alighting.","zh":"上車、乘車和下車都應有清晰規則。"},{"en":"Boarding, travelling and alighting are the stages of getting on, riding in, and getting off a vehicle.","zh":"“Boarding, travelling and alighting” 是上車、乘坐車輛和下車的各個階段。"},{"en":"School bus safety must cover boarding, travelling and alighting because danger can occur at each stage.","zh":"校巴安全必須涵蓋上車、乘車和下車，因為每個階段都可能有危險。"},{"en":"A child may need help during boarding, supervision while travelling, and guidance when alighting.","zh":"孩子上車時可能需要幫助，乘車時需要監督，下車時需要指引。"},{"en":"This phrase shows the whole process of a school bus journey.","zh":"這個說法顯示校巴車程的整個過程。"}],"source":"2013 Q4.pdf","sourcePage":7},{"front":"at present","meaning":"目前","examples":[{"en":"At present, parents are unsure whether every child is properly checked.","zh":"目前，家長不確定每個孩子是否得到妥善檢查。"},{"en":"At present means now, or in the current situation.","zh":"“At present” 指現在，或在目前情況下。"},{"en":"At present, some parents do not receive clear updates when buses are late.","zh":"目前，有些家長在校巴遲到時收不到清楚更新。"},{"en":"This phrase is useful when describing a problem that exists now.","zh":"當描述現時存在的問題時，這個說法很有用。"},{"en":"It prepares the reader for suggested improvements.","zh":"它為之後提出改善建議作準備。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"be unsure whether","meaning":"不確定是否","examples":[{"en":"Parents are often unsure whether every child has been counted.","zh":"家長常不確定是否每個孩子都已被點算。"},{"en":"Be unsure whether means not know clearly if something is true or has happened.","zh":"“Be unsure whether” 指不清楚某事是否屬實或已發生。"},{"en":"Parents may be unsure whether the escort checked the back seats.","zh":"家長可能不確定隨車照顧員是否檢查了後排座位。"},{"en":"When people are unsure whether safety steps were completed, trust becomes weaker.","zh":"當人們不確定安全步驟是否已完成時，信任便會減弱。"},{"en":"This phrase shows how lack of information creates anxiety.","zh":"這個說法顯示資訊不足如何造成焦慮。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"be counted","meaning":"被點算","examples":[{"en":"Every child should be counted when getting on and off the bus.","zh":"每個孩子上車和下車時都應被點算。"},{"en":"Be counted means be included in a careful check of the number of people present.","zh":"“Be counted” 指在仔細核對人數時被包括在內。"},{"en":"Pupils should be counted before the bus leaves school.","zh":"校巴離開學校前，學生應被點算。"},{"en":"Counting children helps staff notice immediately if someone is missing.","zh":"點算孩子可以幫助職員立即發現是否有人不見。"},{"en":"This phrase describes a basic safety step in school transport.","zh":"這個說法描述學校交通服務中的基本安全步驟。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"seated properly","meaning":"正確就座","examples":[{"en":"Children should be seated properly before the bus moves.","zh":"校巴開動前，孩子應正確就座。"},{"en":"Seated properly means sitting in the correct seat, in a safe position, with any required belt fastened.","zh":"“Seated properly” 指坐在正確座位、安全姿勢，並扣好所需安全帶。"},{"en":"A child is seated properly when both feet are inside the seat area and the belt is fastened.","zh":"當孩子雙腳留在座位範圍內並扣好安全帶，就是正確就座。"},{"en":"If children are not seated properly, they may fall when the bus brakes.","zh":"如果孩子沒有正確就座，巴士煞車時可能會跌倒。"},{"en":"This phrase shows that safety begins before the bus starts moving.","zh":"這個說法顯示安全在校巴開動前已經開始。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"handed over to the right adult","meaning":"交給正確的成人","examples":[{"en":"Young children should be handed over to the right adult.","zh":"年幼孩子應交給正確的成人。"},{"en":"Handed over to the right adult means given safely into the care of the correct parent, guardian, or authorised person.","zh":"“Handed over to the right adult” 指安全交到正確家長、監護人或獲授權人士照顧。"},{"en":"A kindergarten pupil should not be handed over to someone the school has not approved.","zh":"幼稚園學生不應被交給學校未批准的人。"},{"en":"Careful handover prevents children from leaving with the wrong person or waiting alone.","zh":"細心交接可以防止孩子跟錯人離開或獨自等候。"},{"en":"This phrase shows that safety continues after the bus stops.","zh":"這個說法顯示安全在校巴停下後仍然繼續。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"uncertainty","meaning":"不確定性","examples":[{"en":"This uncertainty leaves too much room for error.","zh":"這種不確定性留下太多出錯空間。"},{"en":"Uncertainty is a situation in which people do not know clearly what is happening or what is true.","zh":"不確定性是人們不清楚發生甚麼或甚麼是真實的情況。"},{"en":"Uncertainty about bus arrival times makes parents anxious.","zh":"對校巴抵達時間的不確定性會令家長焦慮。"},{"en":"Safety systems should reduce uncertainty by recording each child’s boarding and alighting.","zh":"安全系統應透過記錄每名孩子上車和下車來減少不確定性。"},{"en":"This word shows why clear information matters.","zh":"這個詞顯示清楚資訊為何重要。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"leave too much room for error","meaning":"留下太多出錯空間","examples":[{"en":"An unclear system leaves too much room for error.","zh":"不清晰的系統留下太多出錯空間。"},{"en":"To leave too much room for error means to allow too many chances for mistakes to happen.","zh":"“Leave too much room for error” 指容許太多機會讓錯誤發生。"},{"en":"A bus route without a checklist leaves too much room for error.","zh":"沒有清單的校巴路線會留下太多出錯空間。"},{"en":"Clear procedures reduce room for error because staff know each step.","zh":"清晰程序能減少出錯空間，因為職員知道每一步。"},{"en":"This phrase warns that weak systems make mistakes more likely.","zh":"這個說法提醒我們，薄弱系統會令錯誤更容易發生。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"printed or digital attendance list","meaning":"紙本或電子點名表","examples":[{"en":"Each bus should have a printed or digital attendance list.","zh":"每輛校巴都應有紙本或電子點名表。"},{"en":"A printed or digital attendance list is a paper or electronic record of the pupils expected on the bus.","zh":"紙本或電子點名表是記錄預計乘坐校巴學生的紙本或電子資料。"},{"en":"The escort can use a printed or digital attendance list to check who has boarded.","zh":"隨車照顧員可以用紙本或電子點名表核對誰已上車。"},{"en":"Such a list helps staff avoid relying only on memory.","zh":"這種點名表幫助職員避免只依賴記憶。"},{"en":"This phrase describes a practical tool for counting children accurately.","zh":"這個說法描述準確點算孩子的實用工具。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"tick off pupils","meaning":"為學生剔名","examples":[{"en":"The escort should tick off pupils when they get on and off.","zh":"隨車照顧員應在學生上車和下車時為他們剔名。"},{"en":"To tick off pupils means to mark their names on a list to show they have been checked.","zh":"“Tick off pupils” 指在名單上標記學生姓名，表示他們已被核對。"},{"en":"The teacher ticked off pupils one by one before the school trip bus left.","zh":"學校旅行巴士開出前，老師逐一為學生剔名。"},{"en":"Ticking off pupils helps staff know immediately if someone is missing.","zh":"為學生剔名能幫助職員立即知道是否有人缺少。"},{"en":"This phrase shows a simple but important safety record.","zh":"這個說法顯示一項簡單但重要的安全記錄。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"get on","meaning":"上車","examples":[{"en":"Pupils should be checked when they get on the bus.","zh":"學生上車時應被核對。"},{"en":"To get on means to enter a bus, train, or other vehicle.","zh":"“Get on” 指進入巴士、火車或其他交通工具。"},{"en":"Children should line up before they get on the school bus.","zh":"孩子上校巴前應排隊。"},{"en":"Checking pupils as they get on helps confirm that the right children are on the right bus.","zh":"學生上車時進行核對，有助確認正確孩子乘坐正確校巴。"},{"en":"This phrase describes the first stage of a safe journey.","zh":"這個說法描述安全車程的第一階段。"}],"source":"2013 Q4.pdf","sourcePage":8},{"front":"get off","meaning":"下車","examples":[{"en":"Pupils should be checked again when they get off the bus.","zh":"學生下車時應再次被核對。"},{"en":"To get off means to leave a bus, train, or other vehicle.","zh":"“Get off” 指離開巴士、火車或其他交通工具。"},{"en":"The escort helped the younger pupils get off safely at their stop.","zh":"隨車照顧員協助年幼學生在站點安全下車。"},{"en":"Checking pupils when they get off prevents children from being dropped at the wrong place.","zh":"學生下車時核對，可以防止孩子在錯誤地點下車。"},{"en":"This phrase describes a key moment when adult guidance is needed.","zh":"這個說法描述需要成人指導的關鍵時刻。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"before leaving the bus","meaning":"離開校巴前","examples":[{"en":"Staff should check every row before leaving the bus.","zh":"職員離開校巴前應檢查每一排座位。"},{"en":"Before leaving the bus means before the driver or escort gets off and finishes the journey duty.","zh":"“Before leaving the bus” 指司機或隨車照顧員下車並完成車程職責之前。"},{"en":"The escort looked under the seats before leaving the bus.","zh":"隨車照顧員離開校巴前查看座位下面。"},{"en":"Checking before leaving the bus can prevent a sleeping child from being left behind.","zh":"離開校巴前檢查，可以防止睡着的孩子被遺留。"},{"en":"This phrase marks the final safety check after a route.","zh":"這個說法標示路線結束後的最後安全檢查。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"check every row","meaning":"檢查每一排座位","examples":[{"en":"The driver and escort should check every row.","zh":"司機和隨車照顧員應檢查每一排座位。"},{"en":"To check every row means to look carefully along each line of seats.","zh":"“Check every row” 指仔細查看每一排座位。"},{"en":"Staff should check every row, including the back seats and corners.","zh":"職員應檢查每一排座位，包括後排和角落。"},{"en":"Checking every row matters because small children may be hidden behind high seats.","zh":"檢查每一排很重要，因為小孩可能被高座椅遮住。"},{"en":"This phrase describes a concrete action that prevents children from being missed.","zh":"這個說法描述一個防止漏看孩子的具體行動。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"back seats","meaning":"後排座位","examples":[{"en":"The back seats must also be checked carefully.","zh":"後排座位也必須仔細檢查。"},{"en":"Back seats are the seats near the rear of a bus, car, or classroom.","zh":"後排座位是巴士、汽車或課室靠近後方的座位。"},{"en":"A sleepy child may be difficult to notice in the back seats.","zh":"睡着的孩子在後排座位可能不容易被看見。"},{"en":"Staff should not assume the bus is empty until the back seats are checked.","zh":"在檢查後排座位前，職員不應假定校巴已經沒有人。"},{"en":"This phrase highlights an area where children may be overlooked.","zh":"這個說法突顯孩子可能被忽略的地方。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"make sure no child is asleep or left behind","meaning":"確保沒有孩子睡着或被遺留","examples":[{"en":"Staff must make sure no child is asleep or left behind.","zh":"職員必須確保沒有孩子睡着或被遺留。"},{"en":"To make sure no child is asleep or left behind means to check carefully that every child has safely left the bus.","zh":"“Make sure no child is asleep or left behind” 指仔細檢查每個孩子都已安全離開校巴。"},{"en":"After the final stop, the escort should make sure no child is asleep or left behind.","zh":"到達最後一站後，隨車照顧員應確保沒有孩子睡着或被遺留。"},{"en":"This check is important because young children may sleep quietly and fail to answer.","zh":"這項檢查很重要，因為年幼孩子可能安靜地睡着，沒有回應。"},{"en":"This phrase expresses the central purpose of the final bus inspection.","zh":"這個說法表達最後校巴檢查的核心目的。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"be left behind","meaning":"被遺留","examples":[{"en":"No child should be left behind on a school bus.","zh":"不應有孩子被遺留在校巴上。"},{"en":"To be left behind means to remain in a place after others have gone, often by mistake.","zh":"“Be left behind” 指在其他人離開後仍留在某處，通常是因錯誤造成。"},{"en":"A sleeping pupil could be left behind if no one checks the bus.","zh":"如果沒有人檢查校巴，睡着的學生可能會被遺留。"},{"en":"Being left behind on a school bus can be frightening and dangerous for a young child.","zh":"年幼孩子被遺留在校巴上，可能會感到恐懼並面對危險。"},{"en":"This phrase shows why counting and final checks are essential.","zh":"這個說法顯示點算和最後檢查為何必要。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"seat belts should be fastened","meaning":"安全帶應扣好","examples":[{"en":"Seat belts should be fastened before the bus moves.","zh":"校巴開動前，安全帶應扣好。"},{"en":"Seat belts should be fastened means safety belts should be properly buckled and secured.","zh":"“Seat belts should be fastened” 指安全帶應正確扣上並固定好。"},{"en":"The escort checked that seat belts were fastened before the journey began.","zh":"車程開始前，隨車照顧員檢查安全帶是否扣好。"},{"en":"Fastened seat belts can protect children during sudden braking or accidents.","zh":"扣好的安全帶可以在急煞或意外時保護孩子。"},{"en":"This phrase states a basic rule for passenger safety.","zh":"這個說法指出乘客安全的基本規則。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"before the bus moves","meaning":"在校巴開動前","examples":[{"en":"Children should be seated before the bus moves.","zh":"孩子應在校巴開動前坐好。"},{"en":"Before the bus moves means before the vehicle starts travelling from a stopped position.","zh":"“Before the bus moves” 指車輛由停止狀態開始行駛之前。"},{"en":"The driver waited until every child was seated before the bus moved.","zh":"司機等到每個孩子坐好後，校巴才開動。"},{"en":"Safety checks before the bus moves can prevent falls inside the vehicle.","zh":"在校巴開動前進行安全檢查，可以防止車內跌倒。"},{"en":"This phrase identifies the moment when preparation must be complete.","zh":"這個說法指出準備工作必須完成的時刻。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"only be allowed to","meaning":"只獲准","examples":[{"en":"Children should only be allowed to get off on the pavement side.","zh":"孩子應只獲准在行人路一邊下車。"},{"en":"Only be allowed to means be permitted to do one specific thing and not other unsafe alternatives.","zh":"“Only be allowed to” 指只被允許做某一特定事情，而不是其他不安全選擇。"},{"en":"Pupils should only be allowed to leave the bus when the escort says it is safe.","zh":"學生應只在隨車照顧員說安全時才獲准離開校巴。"},{"en":"Limiting what children are allowed to do can reduce danger near traffic.","zh":"限制孩子可做的事情，可以減少靠近車流時的危險。"},{"en":"This phrase introduces a strict safety permission.","zh":"這個說法引出嚴格的安全許可。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"pavement side","meaning":"行人路一邊","examples":[{"en":"Children should get off on the pavement side.","zh":"孩子應在行人路一邊下車。"},{"en":"The pavement side is the side of the vehicle next to the pedestrian walkway, away from moving traffic.","zh":"行人路一邊是車輛靠近行人路、遠離行駛車輛的一邊。"},{"en":"The escort asked the children to leave only from the pavement side.","zh":"隨車照顧員要求孩子只從行人路一邊下車。"},{"en":"Getting off on the pavement side is safer because children are not stepping into traffic.","zh":"在行人路一邊下車較安全，因為孩子不是踏進車流中。"},{"en":"This phrase identifies the safer side for alighting.","zh":"這個說法指出較安全的下車位置。"}],"source":"2013 Q4.pdf","sourcePage":9},{"front":"kindergarten pupil","meaning":"幼稚園學生","examples":[{"en":"A kindergarten pupil may need help getting off the bus.","zh":"幼稚園學生下車時可能需要幫助。"},{"en":"A kindergarten pupil is a young child who attends kindergarten before primary school.","zh":"幼稚園學生是在升讀小學前就讀幼稚園的年幼孩子。"},{"en":"A kindergarten pupil may carry a large schoolbag and need help with steps.","zh":"幼稚園學生可能背着大書包，需要協助踏下車級。"},{"en":"Kindergarten pupils need close supervision because they may not understand road danger.","zh":"幼稚園學生需要密切監督，因為他們未必明白道路危險。"},{"en":"This phrase reminds readers that some school bus passengers are very young.","zh":"這個說法提醒讀者，有些校巴乘客非常年幼。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"carrying a large schoolbag","meaning":"背着大書包","examples":[{"en":"A young pupil carrying a large schoolbag may lose balance easily.","zh":"背着大書包的年幼學生可能很容易失去平衡。"},{"en":"Carrying a large schoolbag means wearing or holding a heavy or bulky school bag.","zh":"“Carrying a large schoolbag” 指背着或拿着沉重或笨重的書包。"},{"en":"A small child carrying a large schoolbag may struggle when stepping down from a bus.","zh":"背着大書包的小孩從巴士下車時可能會吃力。"},{"en":"Large schoolbags can make movement harder because the child’s weight is uneven.","zh":"大書包會令行動更困難，因為孩子身上的重量不平均。"},{"en":"This phrase explains why young pupils may need adult guidance.","zh":"這個說法解釋為何年幼學生可能需要成人指導。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"without adult guidance","meaning":"沒有成人指導","examples":[{"en":"Without adult guidance, stepping down from a bus can become risky.","zh":"沒有成人指導，從巴士下車也可能變得有風險。"},{"en":"Without adult guidance means without help, direction, or supervision from a responsible grown-up.","zh":"“Without adult guidance” 指沒有負責任成人的協助、指示或監督。"},{"en":"Without adult guidance, a child may step towards traffic instead of the pavement.","zh":"沒有成人指導，孩子可能踏向車流而不是行人路。"},{"en":"Young children need adult guidance because they may not judge distance or danger well.","zh":"年幼孩子需要成人指導，因為他們未必能準確判斷距離或危險。"},{"en":"This phrase shows how the absence of supervision can create risk.","zh":"這個說法顯示缺乏監督如何造成風險。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"step down from a bus","meaning":"從巴士下車","examples":[{"en":"Even stepping down from a bus can be risky for a young child.","zh":"即使從巴士下車，對年幼孩子來說也可能有風險。"},{"en":"To step down from a bus means to move from the bus floor down onto the ground or pavement.","zh":"“Step down from a bus” 指由巴士車廂踏到地面或行人路。"},{"en":"A small child may need to hold an adult’s hand when stepping down from a bus.","zh":"小孩從巴士下車時，可能需要握着成人的手。"},{"en":"Stepping down from a bus can be difficult if the child is carrying a heavy bag.","zh":"如果孩子背着沉重書包，從巴士下車可能會困難。"},{"en":"This phrase describes an ordinary action that still needs care.","zh":"這個說法描述一個普通但仍需要小心的動作。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"become risky","meaning":"變得有風險","examples":[{"en":"A simple action can become risky without guidance.","zh":"沒有指導時，一個簡單動作可以變得有風險。"},{"en":"Become risky means change into something that may cause danger or harm.","zh":"“Become risky” 指變成可能造成危險或傷害的事情。"},{"en":"Crossing a quiet road can become risky if a child runs without looking.","zh":"如果孩子不看路就跑，橫過安靜馬路也可能變得有風險。"},{"en":"Getting off a bus becomes risky when there is traffic nearby and no adult supervision.","zh":"當附近有車流而沒有成人監督時，下車便會變得有風險。"},{"en":"This phrase shows how ordinary actions can become dangerous in the wrong conditions.","zh":"這個說法顯示普通行動在錯誤情況下也會變危險。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"a clear routine","meaning":"清晰常規","examples":[{"en":"A clear routine would make safety automatic.","zh":"清晰常規會令安全步驟成為自然習慣。"},{"en":"A clear routine is a simple repeated set of steps that everyone understands and follows.","zh":"清晰常規是一套簡單、重複、人人明白並跟隨的步驟。"},{"en":"A clear routine for counting pupils can prevent confusion during busy mornings.","zh":"點算學生的清晰常規可以防止繁忙早上的混亂。"},{"en":"Staff follow safety rules better when a clear routine is practised every day.","zh":"當清晰常規每天被實踐，職員會更好地遵守安全規則。"},{"en":"This phrase shows how repeated procedures can reduce mistakes.","zh":"這個說法顯示重複程序如何減少錯誤。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"make safety automatic","meaning":"令安全步驟成為自然習慣","examples":[{"en":"A clear routine can make safety automatic.","zh":"清晰常規可以令安全步驟成為自然習慣。"},{"en":"To make safety automatic means to make safe actions happen naturally because they are built into the routine.","zh":"“Make safety automatic” 指把安全行動納入常規，使它們自然發生。"},{"en":"A checklist can make safety automatic by reminding staff what to do every time.","zh":"清單可以透過每次提醒職員該做甚麼，令安全步驟成為自然習慣。"},{"en":"Safety becomes more reliable when it is automatic rather than dependent on mood or memory.","zh":"當安全成為自然習慣，而不是依賴心情或記憶，它便更可靠。"},{"en":"This phrase shows the goal of standard procedures.","zh":"這個說法顯示標準程序的目標。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"dependent on individual memory","meaning":"依賴個人記憶","examples":[{"en":"Safety should not be dependent on individual memory.","zh":"安全不應依賴個人記憶。"},{"en":"Dependent on individual memory means relying on one person to remember every step without a system.","zh":"“Dependent on individual memory” 指依靠某個人沒有系統地記住每一步。"},{"en":"Child checks should not be dependent on individual memory because people can forget when busy.","zh":"兒童點算不應依賴個人記憶，因為人忙碌時可能會忘記。"},{"en":"Written lists reduce dependence on memory and make checks easier to confirm.","zh":"書面名單能減少對記憶的依賴，並令檢查更容易確認。"},{"en":"This phrase warns against safety systems that are too personal and unreliable.","zh":"這個說法提醒我們，不要建立過於個人化和不可靠的安全系統。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"set up","meaning":"設立","examples":[{"en":"The Association should set up a monitoring and complaint system.","zh":"該協會應設立監察和投訴系統。"},{"en":"To set up something means to create, organise, or start it.","zh":"“Set up” 指建立、組織或開始某事物。"},{"en":"The school set up a hotline for parents to report transport problems.","zh":"學校設立熱線，讓家長匯報交通問題。"},{"en":"Setting up a complaint system gives people a clear way to raise concerns.","zh":"設立投訴系統能給人清楚方法提出憂慮。"},{"en":"This phrase describes the beginning of a practical solution.","zh":"這個說法描述實際解決方法的開始。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"transparent monitoring and complaint system","meaning":"透明監察及投訴系統","examples":[{"en":"Parents need a transparent monitoring and complaint system.","zh":"家長需要透明監察及投訴系統。"},{"en":"A transparent monitoring and complaint system is a clear process for checking services and handling reports from the public.","zh":"透明監察及投訴系統是一套清楚檢查服務和處理公眾報告的流程。"},{"en":"Such a system should tell parents how complaints are received, investigated, and answered.","zh":"這套系統應告訴家長投訴如何接收、調查和回覆。"},{"en":"Transparency helps families trust that problems will not be hidden or ignored.","zh":"透明度幫助家庭相信問題不會被隱瞞或忽視。"},{"en":"This phrase combines oversight with a way for users to speak up.","zh":"這個說法結合監督和讓使用者發聲的方法。"}],"source":"2013 Q4.pdf","sourcePage":10},{"front":"exist only on paper","meaning":"只存在於紙上","examples":[{"en":"Rules that exist only on paper are not enough.","zh":"只存在於紙上的規則並不足夠。"},{"en":"Exist only on paper means be written down but not actually followed or enforced.","zh":"“Exist only on paper” 指某事只被寫下，卻沒有真正被遵守或執行。"},{"en":"A safety policy exists only on paper if no one checks whether staff obey it.","zh":"如果沒有人檢查職員是否遵守，安全政策就只存在於紙上。"},{"en":"Rules that exist only on paper cannot protect children in real situations.","zh":"只存在於紙上的規則不能在真實情況中保護孩子。"},{"en":"This phrase criticises empty rules without action.","zh":"這個說法批評沒有行動的空洞規則。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"no better than promises","meaning":"與空口承諾無異","examples":[{"en":"Rules without enforcement are no better than promises.","zh":"沒有執行的規則與空口承諾無異。"},{"en":"No better than promises means not more useful than words that may never be acted on.","zh":"“No better than promises” 指不比可能永不實行的說話更有用。"},{"en":"A safety rule without inspection is no better than a promise.","zh":"沒有巡查的安全規則與空口承諾無異。"},{"en":"Parents need action because promises alone cannot prevent accidents.","zh":"家長需要行動，因為單靠承諾不能防止意外。"},{"en":"This phrase shows that rules need enforcement to have real value.","zh":"這個說法顯示規則需要執行才有真正價值。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"know who is responsible","meaning":"知道誰負責","examples":[{"en":"Parents need to know who is responsible when problems happen.","zh":"問題發生時，家長需要知道誰負責。"},{"en":"To know who is responsible means to understand which person, company, or organisation must answer for a problem.","zh":"“Know who is responsible” 指明白哪個人、公司或機構必須為問題作出交代。"},{"en":"When a child is dropped off late, parents should know who is responsible for explaining the delay.","zh":"當孩子下車遲了，家長應知道誰負責解釋延誤。"},{"en":"Clear responsibility prevents operators from blaming one another.","zh":"清楚責任可以防止營辦商互相推卸。"},{"en":"This phrase highlights accountability in school bus services.","zh":"這個說法突顯校巴服務中的問責性。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"arrive late","meaning":"遲到","examples":[{"en":"Parents need answers when a bus arrives late.","zh":"校巴遲到時，家長需要答案。"},{"en":"To arrive late means to reach a place after the expected or scheduled time.","zh":"“Arrive late” 指在預期或原定時間之後到達。"},{"en":"If a school bus arrives late, parents may worry that something has happened.","zh":"如果校巴遲到，家長可能擔心發生了事情。"},{"en":"A bus that arrives late should be reported clearly to schools and parents.","zh":"校巴遲到時，應清楚通知學校和家長。"},{"en":"This phrase identifies a common transport problem that needs communication.","zh":"這個說法指出需要溝通的常見交通問題。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"be dropped off at the wrong place","meaning":"被送到錯誤地點下車","examples":[{"en":"A child must never be dropped off at the wrong place.","zh":"孩子絕不應被送到錯誤地點下車。"},{"en":"To be dropped off at the wrong place means to be let out of a vehicle at an incorrect or unsafe location.","zh":"“Be dropped off at the wrong place” 指被安排在錯誤或不安全地點下車。"},{"en":"A kindergarten pupil dropped off at the wrong place may not know how to find help.","zh":"幼稚園學生如果被送到錯誤地點下車，可能不知道如何求助。"},{"en":"Careful attendance records can prevent children from being dropped off at the wrong stop.","zh":"仔細點名記錄可以防止孩子在錯誤站點下車。"},{"en":"This phrase describes a serious failure in school transport safety.","zh":"這個說法描述學校交通安全中的嚴重失誤。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"repeatedly ignore","meaning":"一再忽視","examples":[{"en":"An escort should not repeatedly ignore seat-belt rules.","zh":"隨車照顧員不應一再忽視安全帶規則。"},{"en":"To repeatedly ignore something means to fail to follow or notice it again and again.","zh":"“Repeatedly ignore” 指一次又一次不遵守或不理會某事。"},{"en":"Operators that repeatedly ignore complaints should face investigation.","zh":"一再忽視投訴的營辦商應接受調查。"},{"en":"Repeatedly ignoring seat-belt rules suggests a serious safety culture problem.","zh":"一再忽視安全帶規則，顯示安全文化可能有嚴重問題。"},{"en":"This phrase shows that the issue is not one accident but a continuing pattern.","zh":"這個說法顯示問題不是一次意外，而是持續模式。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"seat-belt rules","meaning":"安全帶規則","examples":[{"en":"Seat-belt rules must be followed on every journey.","zh":"每次車程都必須遵守安全帶規則。"},{"en":"Seat-belt rules are instructions about when and how passengers should wear safety belts.","zh":"安全帶規則是關於乘客何時及如何佩戴安全帶的指示。"},{"en":"Seat-belt rules may require children to fasten belts before the bus moves.","zh":"安全帶規則可能要求孩子在校巴開動前扣好安全帶。"},{"en":"Following seat-belt rules reduces injury during sudden stops or accidents.","zh":"遵守安全帶規則可以減少急停或意外時的受傷。"},{"en":"This phrase names a basic part of passenger safety.","zh":"這個說法指出乘客安全的一個基本部分。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"issue a code of practice","meaning":"發出實務守則","examples":[{"en":"The Association should issue a code of practice.","zh":"該協會應發出實務守則。"},{"en":"To issue a code of practice means to publish formal guidelines explaining how work should be done.","zh":"“Issue a code of practice” 指發布正式指引，說明工作應如何進行。"},{"en":"The Association could issue a code of practice for boarding checks and emergency procedures.","zh":"該協會可以就上車檢查和緊急程序發出實務守則。"},{"en":"A code of practice helps operators follow the same safety standards.","zh":"實務守則幫助營辦商遵守同一套安全標準。"},{"en":"This phrase suggests official guidance rather than informal advice.","zh":"這個說法建議官方指引，而不是非正式建議。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"conduct random inspections","meaning":"進行突擊檢查","examples":[{"en":"The Association should conduct random inspections.","zh":"該協會應進行突擊檢查。"},{"en":"To conduct random inspections means to check services without always giving operators advance notice.","zh":"“Conduct random inspections” 指在不一定預先通知營辦商的情況下檢查服務。"},{"en":"Random inspections can reveal whether escorts really follow child-check procedures.","zh":"突擊檢查可以揭示隨車照顧員是否真的跟隨兒童點算程序。"},{"en":"Operators are more likely to follow rules every day if random inspections may happen.","zh":"如果可能有突擊檢查，營辦商更可能每天遵守規則。"},{"en":"This phrase describes a way to enforce standards.","zh":"這個說法描述執行標準的一種方法。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"keep journey records","meaning":"保存行車紀錄","examples":[{"en":"Operators should keep journey records.","zh":"營辦商應保存行車紀錄。"},{"en":"To keep journey records means to store written or digital information about each trip.","zh":"“Keep journey records” 指保存每次車程的書面或電子資料。"},{"en":"Journey records may include departure times, arrival times, pupil lists, and incidents.","zh":"行車紀錄可以包括出發時間、抵達時間、學生名單和事故。"},{"en":"Keeping journey records helps investigate complaints because facts are available later.","zh":"保存行車紀錄有助調查投訴，因為日後有事實可查。"},{"en":"This phrase supports accountability and safer management.","zh":"這個說法支持問責和更安全管理。"}],"source":"2013 Q4.pdf","sourcePage":11},{"front":"better still","meaning":"更好的是","examples":[{"en":"Better still, parents should have a simple way to report problems.","zh":"更好的是，家長應有簡單方法匯報問題。"},{"en":"Better still means an even better idea or stronger improvement is being added.","zh":"“Better still” 指加入一個更好的想法或更有力的改善。"},{"en":"The school could send bus updates by email; better still, it could use instant messages.","zh":"學校可以用電郵發送校巴更新；更好的是，可以使用即時訊息。"},{"en":"This phrase introduces an improvement beyond the previous suggestion.","zh":"這個說法引出比前一個建議更進一步的改善。"},{"en":"It helps the writer build a stronger proposal step by step.","zh":"它幫助作者一步步建立更有力的建議。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"communication channel","meaning":"溝通渠道","examples":[{"en":"A communication channel can help parents report problems promptly.","zh":"溝通渠道可以幫助家長及時匯報問題。"},{"en":"A communication channel is a method people use to send and receive information.","zh":"溝通渠道是人們用來傳送和接收資訊的方法。"},{"en":"A school may use a phone line, email, or app as a communication channel.","zh":"學校可以使用電話線、電郵或應用程式作為溝通渠道。"},{"en":"A clear communication channel reduces confusion when a bus is late or an incident occurs.","zh":"當校巴遲到或發生事故時，清晰溝通渠道能減少混亂。"},{"en":"This phrase shows how information can move between parents, schools, and operators.","zh":"這個說法顯示資訊如何在家長、學校和營辦商之間流動。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"hotline","meaning":"熱線","examples":[{"en":"A hotline could allow parents to report urgent problems.","zh":"熱線可以讓家長匯報緊急問題。"},{"en":"A hotline is a phone service people can call for help, information, or reporting problems.","zh":"熱線是讓人致電求助、查詢資料或匯報問題的電話服務。"},{"en":"Parents could call the hotline if a bus has not arrived after a long delay.","zh":"如果校巴長時間未到，家長可以致電熱線。"},{"en":"A hotline is useful for urgent matters because people can speak to someone directly.","zh":"熱線對緊急事情有用，因為人們可以直接與職員通話。"},{"en":"This phrase suggests a quick reporting method.","zh":"這個說法建議一種快速匯報方法。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"messaging system","meaning":"訊息系統","examples":[{"en":"A messaging system could connect parents, schools and operators.","zh":"訊息系統可以連接家長、學校和營辦商。"},{"en":"A messaging system is a digital tool for sending notices, updates, and reports between people or groups.","zh":"訊息系統是在人或群體之間傳送通知、更新和報告的數碼工具。"},{"en":"A school bus messaging system can tell parents when a bus is delayed.","zh":"校巴訊息系統可以在校巴延誤時通知家長。"},{"en":"Messaging systems help because written updates can be sent to many people quickly.","zh":"訊息系統有幫助，因為書面更新可以快速發送給很多人。"},{"en":"This phrase shows a practical way to improve communication.","zh":"這個說法顯示改善溝通的實際方法。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"report problems promptly","meaning":"及時匯報問題","examples":[{"en":"Parents and schools should be able to report problems promptly.","zh":"家長和學校應能及時匯報問題。"},{"en":"To report problems promptly means to tell the responsible people about issues quickly.","zh":"“Report problems promptly” 指快速把問題告訴負責人士。"},{"en":"Parents should report problems promptly if a child is dropped off at the wrong place.","zh":"如果孩子被送到錯誤地點下車，家長應及時匯報問題。"},{"en":"Prompt reporting helps operators correct mistakes before they happen again.","zh":"及時匯報有助營辦商在錯誤再次發生前作出糾正。"},{"en":"This phrase shows that communication must be quick, not delayed.","zh":"這個說法顯示溝通必須快速，而不是延遲。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"operators with repeated complaints","meaning":"屢遭投訴的營辦商","examples":[{"en":"Operators with repeated complaints should undergo retraining.","zh":"屢遭投訴的營辦商應接受再培訓。"},{"en":"Operators with repeated complaints are service providers that have received the same or similar complaints many times.","zh":"屢遭投訴的營辦商，是多次收到相同或相似投訴的服務提供者。"},{"en":"An operator with repeated complaints about late buses should be investigated.","zh":"一間屢遭投訴校巴遲到的營辦商應接受調查。"},{"en":"Repeated complaints may show that the problem is systematic, not accidental.","zh":"重複投訴可能顯示問題是系統性的，而不是偶然。"},{"en":"This phrase identifies operators that need closer attention.","zh":"這個說法指出需要更密切關注的營辦商。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"undergo retraining","meaning":"接受再培訓","examples":[{"en":"Operators with repeated complaints should undergo retraining.","zh":"屢遭投訴的營辦商應接受再培訓。"},{"en":"To undergo retraining means to receive training again in order to correct weaknesses or update skills.","zh":"“Undergo retraining” 指再次接受培訓，以糾正弱點或更新技能。"},{"en":"Drivers who fail safety checks should undergo retraining before serving children again.","zh":"未能通過安全檢查的司機，在再次服務兒童前應接受再培訓。"},{"en":"Retraining helps staff replace unsafe habits with clearer procedures.","zh":"再培訓幫助職員用更清晰程序取代不安全習慣。"},{"en":"This phrase suggests improvement before harsher punishment.","zh":"這個說法建議在更嚴厲懲罰前先作改善。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"serious or repeated breaches","meaning":"嚴重或重複違規","examples":[{"en":"Serious or repeated breaches should lead to suspension.","zh":"嚴重或重複違規應導致暫停服務。"},{"en":"Serious or repeated breaches are major rule-breaking incidents or the same kind of rule-breaking happening again and again.","zh":"嚴重或重複違規是重大違反規則事件，或同類違規一再發生。"},{"en":"Ignoring child-check rules several times would be a repeated breach.","zh":"多次忽視兒童點算規則，就是重複違規。"},{"en":"Serious breaches must have consequences because they may put children in danger.","zh":"嚴重違規必須有後果，因為它可能令孩子處於危險。"},{"en":"This phrase shows that enforcement should respond to both severity and pattern.","zh":"這個說法顯示執法應同時回應嚴重程度和重複模式。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"lead to suspension","meaning":"導致停牌；導致暫停服務","examples":[{"en":"Repeated breaches should lead to suspension from school routes.","zh":"重複違規應導致暫停營運校巴路線。"},{"en":"Lead to suspension means result in temporary removal from service or permission.","zh":"“Lead to suspension” 指導致暫時被停止服務或許可。"},{"en":"Dangerous driving should lead to suspension if children’s safety is at risk.","zh":"如果危險駕駛危及兒童安全，應導致停牌。"},{"en":"Clear penalties can lead to better behaviour because operators know the consequences.","zh":"清楚罰則可以帶來更好行為，因為營辦商知道後果。"},{"en":"This phrase connects serious wrongdoing with a formal result.","zh":"這個說法把嚴重錯誤與正式結果連接起來。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"suspension from school routes","meaning":"暫停營運校巴路線","examples":[{"en":"Unsafe operators should face suspension from school routes.","zh":"不安全的營辦商應面對暫停營運校巴路線。"},{"en":"Suspension from school routes means being temporarily stopped from operating routes that serve students.","zh":"暫停營運校巴路線指暫時被停止經營接送學生的路線。"},{"en":"An operator may face suspension from school routes after serious safety breaches.","zh":"營辦商在嚴重安全違規後，可能面對暫停營運校巴路線。"},{"en":"Suspension protects children by removing unsafe services from daily transport.","zh":"暫停服務能把不安全服務移出日常交通，從而保護孩子。"},{"en":"This phrase names a strong consequence for serious problems.","zh":"這個說法指出嚴重問題的一項強烈後果。"}],"source":"2013 Q4.pdf","sourcePage":12},{"front":"not meant to punish","meaning":"並非旨在懲罰","examples":[{"en":"The system is not meant to punish responsible operators.","zh":"這套系統並非旨在懲罰負責任的營辦商。"},{"en":"Not meant to punish means not designed mainly to blame or harm someone.","zh":"“Not meant to punish” 指主要目的不是責備或傷害某人。"},{"en":"Safety checks are not meant to punish careful drivers but to protect passengers.","zh":"安全檢查並非旨在懲罰謹慎司機，而是保護乘客。"},{"en":"A fair monitoring system should correct problems without attacking responsible operators.","zh":"公平的監察系統應糾正問題，而不是攻擊負責任的營辦商。"},{"en":"This phrase explains the purpose of rules in a balanced way.","zh":"這個說法以平衡方式解釋規則的目的。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"responsible operators","meaning":"負責任的營辦商","examples":[{"en":"Responsible operators would benefit from clearer standards.","zh":"負責任的營辦商會從更清晰的標準中受益。"},{"en":"Responsible operators are service providers that follow rules, protect passengers, and act honestly.","zh":"負責任的營辦商是遵守規則、保護乘客並誠實行事的服務提供者。"},{"en":"Responsible operators keep records, train staff, and respond to complaints quickly.","zh":"負責任的營辦商會保存記錄、培訓職員並迅速回應投訴。"},{"en":"Clear standards help responsible operators show that their service is careful and trustworthy.","zh":"清晰標準幫助負責任的營辦商顯示其服務謹慎和值得信任。"},{"en":"This phrase separates good service providers from careless ones.","zh":"這個說法把良好服務提供者與馬虎者區分開。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"protect their reputation","meaning":"保護他們的聲譽","examples":[{"en":"A fair system would protect responsible operators’ reputation.","zh":"公平系統會保護負責任營辦商的聲譽。"},{"en":"To protect their reputation means to help preserve the good public opinion people have of them.","zh":"“Protect their reputation” 指幫助保存公眾對他們的良好看法。"},{"en":"Clear inspection results can protect careful operators’ reputation from unfair suspicion.","zh":"清楚的檢查結果可以保護謹慎營辦商的聲譽，避免不公平懷疑。"},{"en":"A company’s reputation is protected when people can see it follows high standards.","zh":"當人們看見公司遵守高標準時，公司的聲譽便受到保護。"},{"en":"This phrase shows that monitoring can help good operators, not only punish bad ones.","zh":"這個說法顯示監察可以幫助良好營辦商，而不只是懲罰差劣者。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"separate careful services from careless ones","meaning":"區分謹慎服務和馬虎服務","examples":[{"en":"Monitoring can separate careful services from careless ones.","zh":"監察可以區分謹慎服務和馬虎服務。"},{"en":"To separate careful services from careless ones means to show clearly which operators act responsibly and which do not.","zh":"“Separate careful services from careless ones” 指清楚顯示哪些營辦商負責任，哪些不是。"},{"en":"Inspection records can separate careful services from careless ones by using evidence.","zh":"巡查紀錄可以透過證據區分謹慎服務和馬虎服務。"},{"en":"Parents benefit when they can distinguish safe operators from unsafe operators.","zh":"當家長能分辨安全和不安全的營辦商時，他們會受益。"},{"en":"This phrase shows why transparent monitoring is fair to both families and good providers.","zh":"這個說法顯示透明監察為何對家庭和良好服務提供者都公平。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"in conclusion","meaning":"總括而言","examples":[{"en":"In conclusion, private school bus services must be improved.","zh":"總括而言，私營校巴服務必須改善。"},{"en":"In conclusion means finally, after considering the main points.","zh":"“In conclusion” 指在考慮主要重點後作出最後總結。"},{"en":"In conclusion, the safety system should protect every child before convenience is considered.","zh":"總括而言，安全系統應先保護每個孩子，才考慮方便。"},{"en":"This phrase is often used to begin the final paragraph of a formal letter or essay.","zh":"這個說法常用於正式信件或文章的最後一段開首。"},{"en":"It signals that the writer is summarising the main argument.","zh":"它表示作者正在總結主要論點。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"not merely transport businesses","meaning":"不只是交通生意","examples":[{"en":"Private school bus services are not merely transport businesses.","zh":"私營校巴服務不只是交通生意。"},{"en":"Not merely transport businesses means they are more than companies that move people from one place to another.","zh":"“Not merely transport businesses” 指它們不只是把人由一地送到另一地的公司。"},{"en":"School bus services are not merely transport businesses because they care for children during the journey.","zh":"校巴服務不只是交通生意，因為它們在車程中照顧孩子。"},{"en":"A service that carries young children also carries trust and public responsibility.","zh":"接載年幼孩子的服務，也承載信任和公共責任。"},{"en":"This phrase deepens the meaning of school bus work.","zh":"這個說法深化校巴工作的意義。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"carry children, trust and public responsibility","meaning":"承載孩子、信任和公共責任","examples":[{"en":"School buses carry children, trust and public responsibility.","zh":"校巴承載孩子、信任和公共責任。"},{"en":"Carry children, trust and public responsibility means school buses transport young passengers while also carrying parents’ confidence and social duty.","zh":"“Carry children, trust and public responsibility” 指校巴接載年幼乘客，同時承載家長信心和社會責任。"},{"en":"A school bus does not only carry children; it also carries parents’ trust in the adults operating it.","zh":"校巴不只承載孩子，也承載家長對營辦成人的信任。"},{"en":"Because school buses carry public responsibility, safety rules should be strict and transparent.","zh":"因為校巴承載公共責任，安全規則應嚴格而透明。"},{"en":"This phrase shows that school transport has moral weight beyond movement.","zh":"這個說法顯示學校交通除了移動之外，還有道德重量。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"present concerns","meaning":"目前的憂慮","examples":[{"en":"The present concerns should be taken seriously.","zh":"目前的憂慮應被認真對待。"},{"en":"Present concerns are the worries or problems that exist now.","zh":"目前的憂慮是現在存在的擔心或問題。"},{"en":"Present concerns about late buses and missed checks should not be ignored.","zh":"對校巴遲到和漏查的目前憂慮不應被忽視。"},{"en":"Taking present concerns seriously can prevent larger problems later.","zh":"認真處理目前的憂慮，可以防止日後出現更大問題。"},{"en":"This phrase focuses on current worries that require action.","zh":"這個說法集中於需要行動的現時憂慮。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"be dismissed as","meaning":"被視為……而不予理會","examples":[{"en":"The concerns should not be dismissed as parental overreaction.","zh":"這些憂慮不應被視為家長反應過度而不予理會。"},{"en":"To be dismissed as something means to be rejected or ignored because people label it in a certain way.","zh":"“Be dismissed as” 指因被貼上某種標籤而遭拒絕或忽視。"},{"en":"Safety worries should not be dismissed as unnecessary fear before they are investigated.","zh":"安全憂慮在調查前不應被視為不必要恐懼而被忽視。"},{"en":"If parents’ concerns are dismissed as overreaction, real problems may remain hidden.","zh":"如果家長憂慮被視為反應過度，真正問題可能仍被隱藏。"},{"en":"This phrase warns against ignoring complaints too quickly.","zh":"這個說法提醒我們不要太快忽視投訴。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"parental overreaction","meaning":"家長反應過度","examples":[{"en":"Safety concerns should not be dismissed as parental overreaction.","zh":"安全憂慮不應被視為家長反應過度而不予理會。"},{"en":"Parental overreaction means parents are seen as worrying too much or reacting too strongly.","zh":"家長反應過度指父母被認為過分擔心或反應太強烈。"},{"en":"A school may call complaints parental overreaction if it does not take safety fears seriously.","zh":"如果學校沒有認真看待安全憂慮，可能會把投訴稱為家長反應過度。"},{"en":"What seems like parental overreaction may actually be a warning about weak procedures.","zh":"看似家長反應過度的事情，其實可能是對薄弱程序的警號。"},{"en":"This phrase shows how serious concerns can be unfairly minimised.","zh":"這個說法顯示嚴肅憂慮如何被不公平地淡化。"}],"source":"2013 Q4.pdf","sourcePage":13},{"front":"prevention is always better than cure","meaning":"預防勝於治療","examples":[{"en":"Prevention is always better than cure.","zh":"預防勝於治療。"},{"en":"Prevention is always better than cure means it is wiser to stop problems before they happen than to fix harm afterwards.","zh":"“Prevention is always better than cure” 指在問題發生前阻止它，比事後補救更明智。"},{"en":"Checking every seat is better than apologising after a child is left behind.","zh":"檢查每個座位，比孩子被遺留後道歉更好。"},{"en":"In school bus safety, prevention is better because accidents may cause lasting harm.","zh":"在校巴安全中，預防更好，因為意外可能造成長久傷害。"},{"en":"This phrase supports early action and careful planning.","zh":"這個說法支持及早行動和仔細規劃。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"sincerely urge","meaning":"誠懇敦促","examples":[{"en":"I sincerely urge the Association to act quickly.","zh":"本人誠懇敦促該協會迅速行動。"},{"en":"To sincerely urge someone to do something means to strongly and honestly ask them to take action.","zh":"“Sincerely urge” 指真誠而強烈地要求某人採取行動。"},{"en":"Parents sincerely urge operators to improve safety before another incident occurs.","zh":"家長誠懇敦促營辦商在另一次事故發生前改善安全。"},{"en":"This phrase is polite but firm because it expresses serious concern.","zh":"這個說法有禮但堅定，因為它表達嚴肅關注。"},{"en":"It is useful near the end of a formal letter when calling for action.","zh":"它適合在正式信件結尾附近用來呼籲行動。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"act before","meaning":"在……之前採取行動","examples":[{"en":"The Association should act before an avoidable tragedy occurs.","zh":"該協會應在可避免的悲劇發生之前採取行動。"},{"en":"To act before something happens means to take action early enough to prevent or reduce harm.","zh":"“Act before” 指及早行動，以防止或減少傷害。"},{"en":"Schools should act before a dangerous crossing causes an accident.","zh":"學校應在危險過路處造成意外前採取行動。"},{"en":"Acting before tragedy occurs is wiser than waiting for public anger afterwards.","zh":"在悲劇發生前行動，比事後等待公眾憤怒更明智。"},{"en":"This phrase stresses urgency and prevention.","zh":"這個說法強調迫切性和預防。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"avoidable tragedy","meaning":"可避免的悲劇","examples":[{"en":"An avoidable tragedy should not be needed before change happens.","zh":"不應等到可避免的悲劇發生，改變才出現。"},{"en":"An avoidable tragedy is a serious sad event that could have been prevented with proper action.","zh":"可避免的悲劇是本可透過適當行動防止的嚴重悲傷事件。"},{"en":"A child left on a bus in dangerous weather could become an avoidable tragedy.","zh":"孩子在危險天氣中被遺留在巴士上，可能變成可避免的悲劇。"},{"en":"Calling a tragedy avoidable shows that failure to prepare may be partly responsible.","zh":"稱悲劇為可避免，顯示未有準備可能需要負上部分責任。"},{"en":"This phrase urges people to act before harm occurs.","zh":"這個說法敦促人們在傷害發生前行動。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"force change upon the industry","meaning":"迫使行業作出改變","examples":[{"en":"A tragedy may force change upon the industry.","zh":"悲劇可能迫使行業作出改變。"},{"en":"To force change upon the industry means to make the whole industry change because a serious event leaves no choice.","zh":"“Force change upon the industry” 指因嚴重事件令整個行業別無選擇，只能改變。"},{"en":"A major accident can force change upon transport operators if weak rules are exposed.","zh":"如果薄弱規則被揭露，重大意外可能迫使交通營辦商改變。"},{"en":"It is better for the industry to improve voluntarily than to wait for tragedy to force change.","zh":"行業主動改善，比等到悲劇迫使改變更好。"},{"en":"This phrase warns that delayed action may lead to harsher consequences.","zh":"這個說法提醒我們，延遲行動可能帶來更嚴重後果。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"train staff properly","meaning":"正確培訓職員","examples":[{"en":"Operators should train staff properly.","zh":"營辦商應正確培訓職員。"},{"en":"To train staff properly means to teach employees the right skills, procedures, and attitudes for their work.","zh":"“Train staff properly” 指教導員工工作所需的正確技能、程序和態度。"},{"en":"School bus operators must train staff properly before they handle young children.","zh":"校巴營辦商在職員照顧年幼孩子前，必須正確培訓他們。"},{"en":"Proper training reduces confusion because staff know what to do in ordinary and emergency situations.","zh":"適當培訓能減少混亂，因為職員知道在普通和緊急情況中應怎樣做。"},{"en":"This phrase shows that safety begins with people’s preparation.","zh":"這個說法顯示安全始於人的準備。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"standardise daily procedures","meaning":"標準化日常程序","examples":[{"en":"The Association should standardise daily procedures.","zh":"該協會應標準化日常程序。"},{"en":"To standardise daily procedures means to make everyday working steps the same across different staff or operators.","zh":"“Standardise daily procedures” 指令不同職員或營辦商的日常工作步驟一致。"},{"en":"School bus services should standardise daily procedures for attendance checks and seat-belt inspections.","zh":"校巴服務應標準化點名檢查和安全帶檢查等日常程序。"},{"en":"Standardising procedures reduces variation because every bus follows the same basic routine.","zh":"標準化程序能減少差異，因為每輛校巴都跟隨同一基本常規。"},{"en":"This phrase supports fairness, consistency, and safety.","zh":"這個說法支持公平、一致和安全。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"monitor operators openly","meaning":"公開透明地監察營辦商","examples":[{"en":"The Association should monitor operators openly.","zh":"該協會應公開透明地監察營辦商。"},{"en":"To monitor operators openly means to check operators in a transparent way that schools and parents can understand.","zh":"“Monitor operators openly” 指以學校和家長能理解的透明方式檢查營辦商。"},{"en":"The Association can monitor operators openly by publishing inspection rules and complaint procedures.","zh":"該協會可以透過公布巡查規則和投訴程序，公開透明地監察營辦商。"},{"en":"Open monitoring builds trust because people know problems are not hidden.","zh":"公開監察能建立信任，因為人們知道問題不會被隱藏。"},{"en":"This phrase connects supervision with public confidence.","zh":"這個說法把監督與公眾信心連接起來。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"more worthy of parents’ trust","meaning":"更值得家長信任","examples":[{"en":"Private school buses should become more worthy of parents’ trust.","zh":"私營校巴應變得更值得家長信任。"},{"en":"More worthy of parents’ trust means more deserving of parents’ confidence because the service is safer and more responsible.","zh":"“More worthy of parents’ trust” 指因服務更安全、更負責任而更配得上家長信心。"},{"en":"A bus service becomes more worthy of parents’ trust when it checks every child carefully.","zh":"當校巴服務仔細檢查每名孩子，它便更值得家長信任。"},{"en":"Operators earn parents’ trust through consistent safety actions, not just promises.","zh":"營辦商透過持續安全行動贏得家長信任，而不是只靠承諾。"},{"en":"This phrase shows the goal of improving school bus services.","zh":"這個說法顯示改善校巴服務的目標。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"I would be grateful if you could consider","meaning":"如你能考慮……，我將不勝感激","examples":[{"en":"I would be grateful if you could consider these recommendations.","zh":"如你能考慮這些建議，本人將不勝感激。"},{"en":"I would be grateful if you could consider is a polite way to ask someone to think seriously about suggestions.","zh":"“I would be grateful if you could consider” 是有禮地請求對方認真考慮建議的說法。"},{"en":"I would be grateful if you could consider holding a meeting with parents.","zh":"如你能考慮與家長舉行會議，本人將不勝感激。"},{"en":"This phrase sounds respectful because it does not demand immediate agreement.","zh":"這個說法語氣尊重，因為它沒有要求對方立即同意。"},{"en":"It is useful in formal letters when making recommendations to an organisation.","zh":"在正式信件中向機構提出建議時，這個說法很有用。"}],"source":"2013 Q4.pdf","sourcePage":14},{"front":"share with schools and parents","meaning":"與學校和家長分享","examples":[{"en":"The Association should share its actions with schools and parents.","zh":"該協會應與學校和家長分享其行動。"},{"en":"To share with schools and parents means to give information to both schools and families.","zh":"“Share with schools and parents” 指向學校和家庭提供資訊。"},{"en":"Operators should share route changes with schools and parents before the next school day.","zh":"營辦商應在下一個上學日前與學校和家長分享路線改動。"},{"en":"Sharing safety actions helps schools and parents understand what improvements have been made.","zh":"分享安全行動能幫助學校和家長了解已作出哪些改善。"},{"en":"This phrase supports transparency and cooperation.","zh":"這個說法支持透明度和合作。"}],"source":"2013 Q4.pdf","sourcePage":15},{"front":"what action will be taken","meaning":"將會採取甚麼行動","examples":[{"en":"Parents should know what action will be taken.","zh":"家長應知道將會採取甚麼行動。"},{"en":"What action will be taken means which steps or measures will happen in response to a problem.","zh":"“What action will be taken” 指會採取哪些步驟或措施來回應問題。"},{"en":"After a complaint, parents should know what action will be taken by the operator.","zh":"投訴後，家長應知道營辦商將會採取甚麼行動。"},{"en":"Knowing what action will be taken reduces uncertainty and builds trust.","zh":"知道將會採取甚麼行動可以減少不確定性並建立信任。"},{"en":"This phrase asks for concrete steps, not vague promises.","zh":"這個說法要求具體步驟，而不是模糊承諾。"}],"source":"2013 Q4.pdf","sourcePage":15},{"front":"in due course","meaning":"適時；在適當時候","examples":[{"en":"The Association should announce its actions in due course.","zh":"該協會應在適當時候公布其行動。"},{"en":"In due course means at the proper or suitable time, usually after necessary preparation.","zh":"“In due course” 指在合適或適當時間，通常是在完成必要準備後。"},{"en":"The school will inform parents of the new bus rules in due course.","zh":"學校會在適當時候通知家長新的校巴規則。"},{"en":"This phrase is formal and useful when exact timing is not yet given.","zh":"這個說法較正式，適合在尚未給出確實時間時使用。"},{"en":"It suggests that action or information should come at an appropriate time, not be forgotten.","zh":"它暗示行動或資訊應在合適時候出現，而不是被忘記。"}],"source":"2013 Q4.pdf","sourcePage":15},{"front":"Yours faithfully","meaning":"此致敬禮","examples":[{"en":"A formal letter can end with “Yours faithfully”.","zh":"正式信件可以用 “Yours faithfully” 作結。"},{"en":"Yours faithfully is a formal closing used when the writer does not know the recipient’s name.","zh":"“Yours faithfully” 是在作者不知道收件人姓名時使用的正式結尾語。"},{"en":"A letter beginning with “Dear Sir or Madam” often ends with “Yours faithfully”.","zh":"以 “Dear Sir or Madam” 開首的信件，常以 “Yours faithfully” 作結。"},{"en":"This closing keeps the letter polite and professional.","zh":"這個結尾語令信件保持有禮和專業。"},{"en":"In formal writing, the closing should match the greeting and situation.","zh":"在正式寫作中，結尾語應配合稱呼和情況。"}],"source":"2013 Q4.pdf","sourcePage":15}],"dse/writing/part-b/2013/Q5":[{"front":"minor detour","meaning":"小小繞路","examples":[{"en":"A minor detour should not be treated as a major injustice.","zh":"小小繞路不應被視為重大不公。"},{"en":"A minor detour is a small change in route that takes a little extra time.","zh":"小小繞路，是路線上的小改變，只會多花一點時間。"},{"en":"A student may take a minor detour when the school gate is being repaired.","zh":"當學校大門維修時，學生可能需要小小繞路。"},{"en":"Minor detours can be annoying, but they are usually manageable.","zh":"小小繞路可能令人煩躁，但通常可以應付。"},{"en":"In this letter, the writer argues that a minor detour is acceptable if it helps people who need access.","zh":"在這封信中，作者認為如果小小繞路能幫助有出行需要的人，它是可以接受的。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"major injustice","meaning":"重大不公","examples":[{"en":"A minor detour is not a major injustice.","zh":"小小繞路並不是重大不公。"},{"en":"A major injustice is a serious unfairness that causes real harm or exclusion.","zh":"重大不公，是造成真正傷害或排斥的嚴重不公平。"},{"en":"Refusing a wheelchair user access to a public building would be a major injustice.","zh":"拒絕輪椅使用者進入公共建築物會是重大不公。"},{"en":"Calling every small inconvenience a major injustice weakens the meaning of real unfairness.","zh":"把每個小不便都稱為重大不公，會削弱真正不公平的意義。"},{"en":"The writer says the temporary detour is inconvenient, but not a major injustice.","zh":"作者指出臨時繞路是不便，但不是重大不公。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"Dear Editor","meaning":"編輯先生／女士","examples":[{"en":"The letter begins with “Dear Editor.”","zh":"這封信以「編輯先生／女士」開始。"},{"en":"Dear Editor is a formal greeting used when writing a letter to a newspaper or magazine editor.","zh":"「編輯先生／女士」是寫信給報章或雜誌編輯時使用的正式問候語。"},{"en":"A reader may write “Dear Editor” before giving an opinion on a public issue.","zh":"讀者在就公共議題表達意見前，可能會寫「編輯先生／女士」。"},{"en":"This greeting shows that the letter is meant for publication or public discussion.","zh":"這個問候語顯示信件是為了刊登或公共討論。"},{"en":"“Dear Editor” is suitable because the writer is responding to complaints in the community.","zh":"「編輯先生／女士」適合這封信，因為作者正在回應社區中的投訴。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"write in response to","meaning":"寫信回應","examples":[{"en":"I am writing in response to a series of complaints.","zh":"我寫信回應一連串投訴。"},{"en":"To write in response to something means to write because of it and reply to it.","zh":"寫信回應某事，意思是因某事而寫信並作出回覆。"},{"en":"A student may write in response to a school notice about uniform rules.","zh":"學生可能寫信回應學校關於校服規則的通知。"},{"en":"People write in response to complaints when they want to correct or balance an argument.","zh":"當人們想糾正或平衡某個論點時，會寫信回應投訴。"},{"en":"The writer writes in response to complaints about the footbridge works.","zh":"作者寫信回應關於行人天橋工程的投訴。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"a series of complaints","meaning":"一連串投訴","examples":[{"en":"I heard a series of complaints outside the footbridge.","zh":"我在行人天橋外聽到一連串投訴。"},{"en":"A series of complaints means several complaints made one after another or about the same issue.","zh":"一連串投訴，意思是接連出現或關於同一問題的多個投訴。"},{"en":"The school received a series of complaints about the noisy renovation.","zh":"學校收到一連串關於嘈雜翻新的投訴。"},{"en":"A series of complaints can show that people are upset, but not always that they are right.","zh":"一連串投訴可以顯示人們不滿，但不一定代表他們是對的。"},{"en":"The writer listened to a series of complaints before explaining another side.","zh":"作者聽到一連串投訴後，解釋另一個角度。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"newly renovated footbridge","meaning":"新近翻新的行人天橋","examples":[{"en":"The complaints were made outside the newly renovated footbridge.","zh":"這些投訴是在新近翻新的行人天橋外提出的。"},{"en":"A newly renovated footbridge is a pedestrian bridge that has recently been repaired or improved.","zh":"新近翻新的行人天橋，是最近經過維修或改善的行人橋。"},{"en":"A newly renovated footbridge may include better lighting, safer surfaces, and clearer signs.","zh":"新近翻新的行人天橋可能包括更好照明、更安全地面和更清晰指示。"},{"en":"Renovated public facilities may still cause inconvenience while final works are being completed.","zh":"翻新的公共設施在最後工程完成前仍可能造成不便。"},{"en":"The newly renovated footbridge is meant to become more accessible to different users.","zh":"這座新近翻新的行人天橋旨在讓不同使用者更容易通行。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"district MTR station","meaning":"區內港鐵站","examples":[{"en":"The footbridge is near our district MTR station.","zh":"這座行人天橋位於我們區內港鐵站附近。"},{"en":"A district MTR station is the railway station serving a local area or neighbourhood.","zh":"區內港鐵站，是服務本區或社區的鐵路車站。"},{"en":"Many residents walk to the district MTR station every morning to go to work or school.","zh":"許多居民每天早上步行到區內港鐵站上班或上學。"},{"en":"Facilities near a district MTR station affect many people because the station is heavily used.","zh":"區內港鐵站附近的設施會影響很多人，因為車站使用量很高。"},{"en":"Improving access near the district MTR station can help elderly residents and wheelchair users.","zh":"改善區內港鐵站附近的通道，可以幫助年長居民和輪椅使用者。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"temporarily narrowed","meaning":"暫時收窄","examples":[{"en":"The government has temporarily narrowed part of the pavement.","zh":"政府已暫時收窄部分行人路。"},{"en":"Temporarily narrowed means made smaller for a limited period, not permanently.","zh":"暫時收窄，意思是在有限時間內變窄，而不是永久如此。"},{"en":"A school corridor may be temporarily narrowed while workers repair the ceiling.","zh":"工人維修天花時，學校走廊可能被暫時收窄。"},{"en":"Temporary narrowing can slow people down, but it may allow important improvements to happen.","zh":"暫時收窄可能令人行慢一點，但可以讓重要改善工程進行。"},{"en":"The pavement was temporarily narrowed so access facilities could be installed.","zh":"行人路被暫時收窄，是為了安裝無障礙設施。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"pavement","meaning":"行人路","examples":[{"en":"Part of the pavement has been narrowed for improvement works.","zh":"部分行人路因改善工程而被收窄。"},{"en":"A pavement is the part of a road or street where pedestrians walk.","zh":"行人路，是道路或街道中供行人行走的部分。"},{"en":"Students should stay on the pavement when walking near busy traffic.","zh":"學生在繁忙交通附近步行時應留在行人路上。"},{"en":"A safe pavement needs enough space for people, prams, wheelchairs, and trolleys.","zh":"安全的行人路需要有足夠空間給行人、嬰兒車、輪椅和手推車。"},{"en":"The pavement near the footbridge was narrowed only while works were being carried out.","zh":"天橋附近的行人路只是在工程進行期間被收窄。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"in order to install","meaning":"為了安裝","examples":[{"en":"The pavement was narrowed in order to install a lift and a covered ramp.","zh":"行人路被收窄，是為了安裝升降機和有上蓋斜道。"},{"en":"In order to install means for the purpose of putting a new facility in place.","zh":"為了安裝，意思是以放置新設施為目的。"},{"en":"The classroom was closed in order to install new lights.","zh":"課室關閉，是為了安裝新燈。"},{"en":"Public spaces may be disturbed in order to install facilities that help more people.","zh":"公共空間可能暫時受影響，是為了安裝幫助更多人的設施。"},{"en":"The pavement was narrowed not for decoration, but in order to install access improvements.","zh":"行人路被收窄不是為了裝飾，而是為了安裝無障礙改善設施。"}],"source":"2013 Q5.pdf","sourcePage":1},{"front":"lift","meaning":"升降機","examples":[{"en":"The new lift will help wheelchair users and elderly residents.","zh":"新升降機將幫助輪椅使用者和年長居民。"},{"en":"A lift is a machine that carries people up and down between levels.","zh":"升降機，是運載人們在不同樓層之間上下的機器。"},{"en":"A lift helps a person with heavy bags reach an upper floor without using stairs.","zh":"升降機幫助拿着重袋的人不用走樓梯也能到達較高樓層。"},{"en":"Without a lift, some people may be unable to reach a footbridge safely.","zh":"沒有升降機，有些人可能無法安全到達行人天橋。"},{"en":"The lift is important because it turns the footbridge into a route more people can use.","zh":"升降機重要，因為它令行人天橋成為更多人可使用的路線。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"tactile paving","meaning":"觸覺引路帶","examples":[{"en":"Tactile paving helps visually impaired pedestrians move more safely.","zh":"觸覺引路帶幫助視障行人更安全地行動。"},{"en":"Tactile paving is textured ground surface that guides people who cannot see well.","zh":"觸覺引路帶，是有凹凸紋理的地面，用來引導視力不佳的人。"},{"en":"You may see tactile paving near crossings, lifts, and railway platforms.","zh":"你可能在過路處、升降機和鐵路月台附近看見觸覺引路帶。"},{"en":"Tactile paving helps users feel direction or warning through their feet or cane.","zh":"觸覺引路帶幫助使用者透過腳或手杖感受方向或警告。"},{"en":"Installing tactile paving makes public space safer for visually impaired pedestrians.","zh":"安裝觸覺引路帶令公共空間對視障行人更安全。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"covered ramp","meaning":"有上蓋斜道","examples":[{"en":"A covered ramp will make the footbridge more accessible.","zh":"有上蓋斜道將令行人天橋更容易通行。"},{"en":"A covered ramp is a sloping path with a roof that helps people move between levels.","zh":"有上蓋斜道，是有屋頂的斜路，幫助人們在不同高度之間移動。"},{"en":"A parent with a pram can use a covered ramp more easily than stairs.","zh":"推嬰兒車的家長使用有上蓋斜道會比走樓梯容易。"},{"en":"A covered ramp protects users from rain while they move up or down.","zh":"有上蓋斜道讓使用者上下時免受雨水影響。"},{"en":"The covered ramp helps turn the footbridge into a barrier-free route.","zh":"有上蓋斜道幫助行人天橋變成無障礙路線。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"elderly residents","meaning":"年長居民","examples":[{"en":"The works will benefit elderly residents.","zh":"這些工程將令年長居民受惠。"},{"en":"Elderly residents are older people who live in the area.","zh":"年長居民，是住在區內的較年長人士。"},{"en":"Elderly residents may find stairs difficult when carrying shopping bags.","zh":"年長居民拿着購物袋時，可能覺得樓梯很難行。"},{"en":"Public improvements should consider elderly residents because they use neighbourhood facilities every day.","zh":"公共改善工程應考慮年長居民，因為他們每天使用社區設施。"},{"en":"The lift and ramp will help elderly residents move with less pain and risk.","zh":"升降機和斜道會幫助年長居民較少痛楚和風險地出行。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"wheelchair users","meaning":"輪椅使用者","examples":[{"en":"Wheelchair users need barrier-free access.","zh":"輪椅使用者需要無障礙通道。"},{"en":"Wheelchair users are people who use wheelchairs to move around.","zh":"輪椅使用者，是使用輪椅出行的人。"},{"en":"Wheelchair users may be blocked by stairs, narrow gates, or uneven pavements.","zh":"樓梯、狹窄閘口或不平坦行人路可能阻礙輪椅使用者。"},{"en":"Public facilities should allow wheelchair users to travel without depending on strangers.","zh":"公共設施應讓輪椅使用者不必依賴陌生人也能出行。"},{"en":"The new lift is important because wheelchair users cannot simply be told to use the stairs.","zh":"新升降機重要，因為不能簡單叫輪椅使用者走樓梯。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"parents with prams","meaning":"推嬰兒車的父母","examples":[{"en":"Parents with prams will also benefit from the ramp.","zh":"推嬰兒車的父母也會從斜道受惠。"},{"en":"Parents with prams are mothers, fathers, or carers pushing babies or young children in prams.","zh":"推嬰兒車的父母，是推着嬰兒或幼兒車的母親、父親或照顧者。"},{"en":"Parents with prams may struggle when a footbridge has only stairs.","zh":"當行人天橋只有樓梯，推嬰兒車的父母可能會吃力。"},{"en":"Ramps help parents with prams move safely without lifting the child and pram together.","zh":"斜道幫助推嬰兒車的父母安全前進，不用把孩子和嬰兒車一起抬起。"},{"en":"Accessibility helps parents with prams as well as wheelchair users and elderly residents.","zh":"無障礙設施幫助推嬰兒車的父母，也幫助輪椅使用者和年長居民。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"passers-by","meaning":"路人","examples":[{"en":"Several passers-by criticised the works.","zh":"幾名路人批評這些工程。"},{"en":"Passers-by are people walking past a place, not necessarily involved in it.","zh":"路人，是走過某個地方的人，未必直接參與其中。"},{"en":"Passers-by may stop to watch when roadworks block part of a street.","zh":"當道路工程阻塞部分街道，路人可能停下觀看。"},{"en":"Passers-by often judge a project by how it affects them immediately.","zh":"路人常按工程對自己即時的影響來判斷項目。"},{"en":"Some passers-by criticised the works because they focused on the temporary inconvenience.","zh":"有些路人批評工程，因為他們集中於暫時不便。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"condemn the works as","meaning":"將工程譴責為","examples":[{"en":"Some passers-by condemned the works as a waste of money.","zh":"有些路人將工程譴責為浪費金錢。"},{"en":"To condemn the works as something means to strongly criticise the project and describe it in that way.","zh":"將工程譴責為某事，意思是強烈批評工程，並以那種方式形容它。"},{"en":"Residents may condemn a plan as careless if it ignores safety.","zh":"如果計劃忽視安全，居民可能將它譴責為粗心。"},{"en":"Condemning a project too quickly can overlook the people it is meant to help.","zh":"太快譴責一項工程，可能忽略它本來要幫助的人。"},{"en":"The writer disagrees with condemning accessibility works as a waste.","zh":"作者不同意將無障礙工程譴責為浪費。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"a waste of money","meaning":"浪費金錢","examples":[{"en":"Some people wrongly called the project a waste of money.","zh":"有些人錯誤地稱這個項目為浪費金錢。"},{"en":"A waste of money means money spent on something useless or not worth the cost.","zh":"浪費金錢，意思是把錢花在無用或不值得的事情上。"},{"en":"Buying equipment that no one uses would be a waste of money.","zh":"購買沒有人使用的設備會是浪費金錢。"},{"en":"A project is not a waste of money if it gives essential access to vulnerable people.","zh":"如果一項工程為弱勢人士提供必要通道，它就不是浪費金錢。"},{"en":"The writer argues that spending on lifts and ramps is not a waste of money.","zh":"作者認為把錢用於升降機和斜道並不是浪費金錢。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"a nuisance to","meaning":"對……造成滋擾","examples":[{"en":"They described the works as a nuisance to ordinary people.","zh":"他們形容工程對普通人造成滋擾。"},{"en":"A nuisance to someone is something that annoys, disturbs, or inconveniences them.","zh":"對某人造成滋擾，是指某事令人煩擾、打擾或不便。"},{"en":"Loud drilling can be a nuisance to people studying nearby.","zh":"嘈雜鑽鑿聲可能對附近溫習的人造成滋擾。"},{"en":"Something may be a nuisance for a short time but still bring long-term benefits.","zh":"某事可能短時間造成滋擾，但仍帶來長遠好處。"},{"en":"The works may be a nuisance to some pedestrians, but they help people who need access.","zh":"工程可能對部分行人造成滋擾，但它幫助有無障礙需要的人。"}],"source":"2013 Q5.pdf","sourcePage":2},{"front":"with all due respect","meaning":"恕我直言","examples":[{"en":"With all due respect, I take issue with that view.","zh":"恕我直言，我不同意那個看法。"},{"en":"With all due respect is a polite phrase used before disagreeing strongly.","zh":"恕我直言，是在強烈不同意之前使用的禮貌說法。"},{"en":"With all due respect, the school should listen to quiet students as well as loud ones.","zh":"恕我直言，學校應聆聽安靜學生，也應聆聽大聲學生。"},{"en":"This phrase softens disagreement while keeping the writer’s position clear.","zh":"這個短語令異議較溫和，同時保持作者立場清楚。"},{"en":"The writer uses it before challenging the complaints about accessibility works.","zh":"作者用它來挑戰關於無障礙工程的投訴。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"take issue with","meaning":"不同意；對……提出異議","examples":[{"en":"I take issue with the view that the works are unnecessary.","zh":"我不同意這些工程不必要的看法。"},{"en":"To take issue with something means to disagree with it and explain why.","zh":"對某事提出異議，意思是不同意它並解釋原因。"},{"en":"A student may take issue with a rule if it treats some classmates unfairly.","zh":"如果校規不公平對待某些同學，學生可能對它提出異議。"},{"en":"Taking issue with a view is stronger than simply saying you dislike it.","zh":"對某個看法提出異議，比單純說不喜歡更有力。"},{"en":"The writer takes issue with complaints that ignore accessibility needs.","zh":"作者對忽視無障礙需要的投訴提出異議。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"irritation","meaning":"不滿；煩躁","examples":[{"en":"Their irritation may be understandable.","zh":"他們的不滿可能可以理解。"},{"en":"Irritation is a feeling of annoyance or impatience.","zh":"不滿或煩躁，是感到惱怒或不耐煩。"},{"en":"A student may feel irritation when a noisy repair interrupts revision.","zh":"當嘈雜維修打擾溫習，學生可能感到煩躁。"},{"en":"Irritation is natural when daily routines are disturbed.","zh":"當日常習慣被打擾，不滿是自然的。"},{"en":"The writer accepts the irritation but says it should not become unfair criticism.","zh":"作者接受這種不滿，但認為它不應變成不公平批評。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"understandable","meaning":"可以理解的","examples":[{"en":"Their irritation may be understandable, but the complaint is unreasonable.","zh":"他們的不滿可以理解，但投訴是不合理的。"},{"en":"Understandable means easy to accept or sympathise with because there is a reason.","zh":"可以理解的，意思是因有理由而容易接受或同情。"},{"en":"It is understandable that residents dislike noise during breakfast.","zh":"居民不喜歡早餐時的噪音是可以理解的。"},{"en":"A feeling can be understandable even when the conclusion is wrong.","zh":"一種感受可以理解，即使結論是錯的。"},{"en":"The writer says annoyance is understandable, but cancelling accessibility works is not.","zh":"作者說煩躁可以理解，但取消無障礙工程則不合理。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"unreasonable","meaning":"不合理的","examples":[{"en":"The complaint is unreasonable because it ignores accessibility needs.","zh":"這個投訴不合理，因為它忽視無障礙需要。"},{"en":"Unreasonable means not fair, sensible, or based on enough thought.","zh":"不合理的，意思是不公平、不明智，或沒有足夠思考。"},{"en":"It is unreasonable to demand silence from a school during a necessary fire drill.","zh":"在必要火警演習期間要求學校完全安靜是不合理的。"},{"en":"A complaint becomes unreasonable when it ignores other people’s basic needs.","zh":"當投訴忽視其他人的基本需要，它就變得不合理。"},{"en":"The writer finds the complaint unreasonable because it values speed over inclusion.","zh":"作者認為這投訴不合理，因為它把速度看得比共融更重要。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"mistake… for…","meaning":"將……誤當作……","examples":[{"en":"The complaint mistakes a small inconvenience for a serious injustice.","zh":"這個投訴將小小不便誤當作嚴重不公。"},{"en":"To mistake A for B means to wrongly think A is B.","zh":"將 A 誤當作 B，意思是錯誤地以為 A 是 B。"},{"en":"A student may mistake strict feedback for personal attack.","zh":"學生可能將嚴格回饋誤當作人身攻擊。"},{"en":"People sometimes mistake inconvenience for unfairness when their routine is disturbed.","zh":"當日常習慣被打擾，人們有時會將不便誤當作不公平。"},{"en":"The writer says the complainants mistook a short detour for a serious injustice.","zh":"作者說投訴者把短暫繞路誤當作嚴重不公。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"temporary inconvenience","meaning":"暫時不便","examples":[{"en":"The works create only a temporary inconvenience.","zh":"這些工程只造成暫時不便。"},{"en":"A temporary inconvenience is a problem that causes trouble for a short time only.","zh":"暫時不便，是只在短時間內造成麻煩的問題。"},{"en":"A closed school gate can be a temporary inconvenience during repairs.","zh":"維修期間學校大門關閉可以是暫時不便。"},{"en":"Temporary inconvenience is easier to accept when the final benefit is important.","zh":"當最終好處重要，暫時不便較容易接受。"},{"en":"The footbridge works cause temporary inconvenience but will improve long-term access.","zh":"行人天橋工程造成暫時不便，但會改善長遠通行。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"serious injustice","meaning":"嚴重不公","examples":[{"en":"A short detour should not be seen as a serious injustice.","zh":"短暫繞路不應被視為嚴重不公。"},{"en":"A serious injustice is a deep unfairness that harms people’s rights or dignity.","zh":"嚴重不公，是傷害人們權利或尊嚴的深層不公平。"},{"en":"Blocking disabled people from public transport would be a serious injustice.","zh":"阻止殘疾人士使用公共交通會是嚴重不公。"},{"en":"Not every delay or inconvenience is a serious injustice.","zh":"不是每次延誤或不便都是嚴重不公。"},{"en":"The writer says the real serious injustice would be ignoring people who need accessibility.","zh":"作者認為真正的嚴重不公，是忽視需要無障礙設施的人。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"forget those for whom","meaning":"忘記對某些人來說","examples":[{"en":"The complaint forgets those for whom accessibility is a daily necessity.","zh":"這個投訴忘記對某些人來說，無障礙設施是日常必需。"},{"en":"Forget those for whom means ignore the people who experience something in a particular way.","zh":"忘記對某些人來說，意思是忽視那些以特定方式經歷某事的人。"},{"en":"A school rule may forget those for whom quiet study space is essential.","zh":"學校規則可能忘記對某些學生來說，安靜自修空間是必需的。"},{"en":"Public complaints become unfair when they forget those with less visible needs.","zh":"當公共投訴忘記有較不明顯需要的人，就會變得不公平。"},{"en":"The writer says the complaints forget those for whom stairs are a barrier.","zh":"作者說這些投訴忘記對某些人來說，樓梯是一道障礙。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"accessibility","meaning":"無障礙設施；可達性","examples":[{"en":"Accessibility is not a luxury for many citizens.","zh":"對許多市民來說，無障礙設施不是奢侈品。"},{"en":"Accessibility means making places, services, and information usable by people with different needs.","zh":"無障礙設施或可達性，是令有不同需要的人都能使用地方、服務和資訊。"},{"en":"A ramp improves accessibility for wheelchair users and parents with prams.","zh":"斜道改善輪椅使用者和推嬰兒車父母的可達性。"},{"en":"Poor accessibility can stop people from using public places that others take for granted.","zh":"無障礙設施欠佳，會阻止一些人使用其他人視為理所當然的公共地方。"},{"en":"The letter argues that accessibility is part of fairness in public space.","zh":"這封信主張，無障礙設施是公共空間公平的一部分。"}],"source":"2013 Q5.pdf","sourcePage":3},{"front":"not a luxury, but a daily necessity","meaning":"不是奢侈品，而是日常必需","examples":[{"en":"For wheelchair users, accessibility is not a luxury, but a daily necessity.","zh":"對輪椅使用者來說，無障礙設施不是奢侈品，而是日常必需。"},{"en":"Not a luxury, but a daily necessity means something is not extra comfort but something needed for normal life.","zh":"不是奢侈品，而是日常必需，意思是某事不是額外享受，而是正常生活所需。"},{"en":"For a patient, medicine is not a luxury, but a daily necessity.","zh":"對病人來說，藥物不是奢侈品，而是日常必需。"},{"en":"Public lifts are daily necessities for people who cannot safely use stairs.","zh":"對不能安全使用樓梯的人來說，公共升降機是日常必需。"},{"en":"The phrase reminds readers that accessibility is basic, not special treatment.","zh":"這個短語提醒讀者，無障礙設施是基本需要，不是特別待遇。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"complainants’ argument","meaning":"投訴者的論點","examples":[{"en":"The complainants’ argument was built on three points.","zh":"投訴者的論點建基於三點。"},{"en":"The complainants’ argument means the reasons given by the people making the complaints.","zh":"投訴者的論點，是提出投訴的人所給出的理由。"},{"en":"A teacher may ask students to summarise the complainants’ argument before replying to it.","zh":"老師可能要求學生先概括投訴者的論點，再作回應。"},{"en":"Understanding an argument fairly helps a writer answer it more clearly.","zh":"公平理解一個論點，可以幫助作者更清楚地回應它。"},{"en":"The writer explains the complainants’ argument before showing why it is too narrow.","zh":"作者先解釋投訴者的論點，再指出它為何太狹隘。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"as far as I could tell","meaning":"據我所知；依我判斷","examples":[{"en":"As far as I could tell, their argument had three parts.","zh":"據我所知，他們的論點有三部分。"},{"en":"As far as I could tell means based on what I was able to understand or observe.","zh":"據我所知或依我判斷，意思是根據我能理解或觀察到的資料。"},{"en":"As far as I could tell, the meeting ended because no one had more questions.","zh":"據我所知，會議結束是因為沒有人再有問題。"},{"en":"This phrase shows that the writer is making a careful judgement from available information.","zh":"這個短語顯示作者是根據現有資料作出謹慎判斷。"},{"en":"The writer uses it to summarise the complaints without claiming perfect knowledge.","zh":"作者使用它來概括投訴，而不是聲稱自己掌握所有資料。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"be built on three points","meaning":"建基於三點","examples":[{"en":"The complainants’ argument was built on three points.","zh":"投訴者的論點建基於三點。"},{"en":"Be built on three points means an argument depends on three main reasons.","zh":"建基於三點，意思是一個論點依靠三個主要理由。"},{"en":"A school proposal may be built on three points: safety, cost, and fairness.","zh":"學校建議可能建基於三點：安全、成本和公平。"},{"en":"Clear arguments are easier to answer when their main points are identified.","zh":"當主要觀點被指出，清晰論點較容易回應。"},{"en":"The writer lists the three points so readers can see the complaint clearly.","zh":"作者列出三點，好讓讀者清楚看見投訴內容。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"barriers","meaning":"圍欄；障礙物","examples":[{"en":"The barriers forced pedestrians to walk further.","zh":"圍欄迫使行人走得更遠。"},{"en":"Barriers are objects such as fences or boards that block or direct movement.","zh":"圍欄或障礙物，是用來阻擋或引導行動的物件，例如欄杆或板。"},{"en":"Barriers may be placed around roadworks to keep people safe.","zh":"道路工程周圍可能設置圍欄，以保障行人安全。"},{"en":"Barriers can cause inconvenience, but they often prevent accidents near construction areas.","zh":"圍欄可能造成不便，但通常能防止人在工程區附近發生意外。"},{"en":"The barriers near the footbridge created a detour for pedestrians.","zh":"天橋附近的圍欄為行人造成繞路。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"force pedestrians to","meaning":"迫使行人去","examples":[{"en":"The barriers forced pedestrians to take a short detour.","zh":"圍欄迫使行人短暫繞路。"},{"en":"To force pedestrians to do something means to make walkers do it because there is no easier route.","zh":"迫使行人去做某事，意思是因沒有更方便路線而令步行者必須這樣做。"},{"en":"A closed gate may force pedestrians to use another entrance.","zh":"關閉的大門可能迫使行人使用另一個入口。"},{"en":"Temporary works can force pedestrians to slow down or walk further.","zh":"臨時工程可能迫使行人放慢腳步或走得更遠。"},{"en":"The writer accepts that the barriers forced pedestrians to detour, but says the reason matters.","zh":"作者承認圍欄迫使行人繞路，但認為原因很重要。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"pedestrians","meaning":"行人","examples":[{"en":"Pedestrians had to walk an extra few minutes.","zh":"行人不得不多走幾分鐘。"},{"en":"Pedestrians are people who are walking, especially along streets or roads.","zh":"行人，是正在步行的人，特別是在街道或道路旁。"},{"en":"Pedestrians should use crossings when traffic is heavy.","zh":"交通繁忙時，行人應使用過路處。"},{"en":"Good pavements protect pedestrians from vehicles and construction areas.","zh":"良好行人路保護行人免受車輛和工程區影響。"},{"en":"The works affected pedestrians, but they were designed to help pedestrians with greater needs.","zh":"工程影響了行人，但也是為了幫助有更大需要的行人。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"an extra few minutes","meaning":"額外幾分鐘","examples":[{"en":"The barriers added an extra few minutes to the walk.","zh":"圍欄令步程增加額外幾分鐘。"},{"en":"An extra few minutes means a small additional amount of time.","zh":"額外幾分鐘，意思是多出的一小段時間。"},{"en":"A student may need an extra few minutes to reach class when the lift is busy.","zh":"當升降機繁忙時，學生可能需要額外幾分鐘才到課室。"},{"en":"An extra few minutes can be annoying, but it is different from being unable to access a place.","zh":"額外幾分鐘可能令人煩躁，但與完全不能到達某地不同。"},{"en":"The writer compares an extra few minutes with the much bigger problem of exclusion.","zh":"作者把額外幾分鐘與被排斥這個更大問題作比較。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"morning rush hour","meaning":"早上繁忙時間","examples":[{"en":"The detour felt annoying during the morning rush hour.","zh":"早上繁忙時間繞路令人覺得煩躁。"},{"en":"Morning rush hour is the busy time when many people travel to work or school.","zh":"早上繁忙時間，是很多人上班或上學的繁忙時段。"},{"en":"Buses and trains are often crowded during the morning rush hour.","zh":"巴士和港鐵在早上繁忙時間通常很擠迫。"},{"en":"Delays feel worse during rush hour because people worry about being late.","zh":"繁忙時間的延誤感覺更糟，因為人們擔心遲到。"},{"en":"The detour was irritating during morning rush hour, but still temporary.","zh":"早上繁忙時間繞路令人不快，但仍只是暫時的。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"construction noise","meaning":"建築噪音","examples":[{"en":"Construction noise disturbed nearby shops and residents.","zh":"建築噪音打擾附近商店和居民。"},{"en":"Construction noise is loud sound made by building, repairing, or drilling work.","zh":"建築噪音，是建造、維修或鑽鑿工程產生的巨大聲音。"},{"en":"Construction noise near a classroom can make it hard for students to concentrate.","zh":"課室附近的建築噪音會令學生難以專心。"},{"en":"Noise complaints are reasonable when works are poorly timed or badly managed.","zh":"當工程時間安排差或管理欠佳，噪音投訴是合理的。"},{"en":"The writer agrees construction noise should be managed, but not used to reject accessibility.","zh":"作者同意建築噪音應被管理，但不應用它來否定無障礙設施。"}],"source":"2013 Q5.pdf","sourcePage":4},{"front":"nearby shops and residents","meaning":"附近商店和居民","examples":[{"en":"Construction noise affected nearby shops and residents.","zh":"建築噪音影響附近商店和居民。"},{"en":"Nearby shops and residents means businesses and people living close to the works.","zh":"附近商店和居民，是指靠近工程的店舖和住在附近的人。"},{"en":"Nearby shops may lose customers when entrances are blocked.","zh":"當入口被阻塞，附近商店可能失去顧客。"},{"en":"Residents near construction sites may suffer from noise, dust, and inconvenience.","zh":"工程地點附近的居民可能受噪音、塵埃和不便影響。"},{"en":"The authorities should inform nearby shops and residents clearly during public works.","zh":"當局在公共工程期間應清楚通知附近商店和居民。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"insist that","meaning":"堅稱","examples":[{"en":"Some people insisted that most people could use the stairs.","zh":"有些人堅稱大多數人可以使用樓梯。"},{"en":"To insist that means to state something firmly, often even when others disagree.","zh":"堅稱，意思是堅定地說某事，通常即使其他人不同意。"},{"en":"A student may insist that the group project needs more time.","zh":"學生可能堅稱小組專題需要更多時間。"},{"en":"People may insist on a view because it matches their own experience.","zh":"人們可能堅持某個看法，因為它符合自己的經驗。"},{"en":"The complainants insisted that stairs were enough, but forgot people who cannot use them.","zh":"投訴者堅稱樓梯已足夠，卻忘記不能使用樓梯的人。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"public money","meaning":"公帑","examples":[{"en":"Public money should be used to make public spaces accessible.","zh":"公帑應用於令公共空間無障礙。"},{"en":"Public money is money collected or controlled by the government for community use.","zh":"公帑，是政府為社會用途收取或管理的金錢。"},{"en":"Taxes are one source of public money.","zh":"稅款是公帑的一個來源。"},{"en":"Public money should support facilities that serve the whole community fairly.","zh":"公帑應支持公平服務整個社群的設施。"},{"en":"Spending public money on lifts and ramps can make public places truly open to all.","zh":"將公帑用於升降機和斜道，可以令公共地方真正向所有人開放。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"be spent on","meaning":"被花在","examples":[{"en":"Public money should be spent on facilities that help citizens.","zh":"公帑應被花在幫助市民的設施上。"},{"en":"Be spent on means money is used for a particular purpose.","zh":"被花在某事上，意思是金錢被用於某個特定目的。"},{"en":"School funds may be spent on library books and safety equipment.","zh":"學校資金可能被花在圖書館書籍和安全設備上。"},{"en":"Money should be spent on needs that create real benefit.","zh":"金錢應花在能創造真正好處的需要上。"},{"en":"The writer believes public money is well spent on accessibility.","zh":"作者相信把公帑花在無障礙設施上是值得的。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"facilities for a minority","meaning":"為少數人而設的設施","examples":[{"en":"Some people objected to spending money on facilities for a minority.","zh":"有些人反對把錢花在為少數人而設的設施上。"},{"en":"Facilities for a minority are services or structures used mainly by a smaller group of people.","zh":"為少數人而設的設施，是主要由較小群體使用的服務或結構。"},{"en":"Braille signs may seem like facilities for a minority, but they make a place fairer.","zh":"點字標誌可能看似為少數人而設的設施，但它令地方更公平。"},{"en":"A minority still deserves access when the need is serious and basic.","zh":"即使是少數人，當需要嚴重而基本時，也值得獲得通道。"},{"en":"The writer argues that helping a minority can improve the whole community.","zh":"作者認為幫助少數人也可以改善整個社區。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"on the face of it","meaning":"表面看來","examples":[{"en":"On the face of it, these concerns may sound practical.","zh":"表面看來，這些憂慮可能聽起來實際。"},{"en":"On the face of it means at first sight or before deeper thinking.","zh":"表面看來，意思是乍看之下或在深入思考之前。"},{"en":"On the face of it, cancelling the trip saves money, but students lose learning opportunities.","zh":"表面看來，取消旅行可以省錢，但學生會失去學習機會。"},{"en":"This phrase warns that first impressions may be incomplete.","zh":"這個短語提醒我們，第一印象可能不完整。"},{"en":"On the face of it, the complaints seem practical, but they hide a narrow view of public space.","zh":"表面看來，投訴似乎實際，但它們隱藏了對公共空間的狹隘看法。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"sound practical","meaning":"聽起來實際","examples":[{"en":"The concerns may sound practical at first.","zh":"這些憂慮起初可能聽起來實際。"},{"en":"Sound practical means seem sensible, useful, or based on real problems.","zh":"聽起來實際，意思是看似合理、有用或基於真實問題。"},{"en":"A suggestion to shorten meetings may sound practical if everyone is busy.","zh":"如果每個人都很忙，縮短會議的建議可能聽起來實際。"},{"en":"Some ideas sound practical until we ask who may be harmed by them.","zh":"有些想法聽起來實際，直到我們問誰可能受傷害。"},{"en":"The complaints sound practical, but they ignore people who cannot use stairs.","zh":"這些投訴聽起來實際，但它們忽視不能使用樓梯的人。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"squeeze past","meaning":"擠過","examples":[{"en":"Nobody enjoys squeezing past metal fences.","zh":"沒有人喜歡擠過金屬圍欄。"},{"en":"To squeeze past something means to move through a very narrow space beside it.","zh":"擠過某物，意思是在它旁邊很窄的空間中穿過。"},{"en":"Students may squeeze past desks in a crowded classroom.","zh":"學生可能在擠迫課室中擠過書桌。"},{"en":"Squeezing past barriers can be unpleasant, especially during rush hour.","zh":"擠過圍欄可能令人不快，特別是在繁忙時間。"},{"en":"The writer admits that squeezing past fences is annoying, but says the project still matters.","zh":"作者承認擠過圍欄很煩，但指出工程仍然重要。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"metal fences","meaning":"金屬圍欄","examples":[{"en":"Pedestrians had to squeeze past metal fences.","zh":"行人不得不擠過金屬圍欄。"},{"en":"Metal fences are strong barriers made of metal, often used around construction areas.","zh":"金屬圍欄，是由金屬製成的堅固障礙物，常用於工程區周圍。"},{"en":"Metal fences keep people away from dangerous tools or unfinished ground.","zh":"金屬圍欄令行人遠離危險工具或未完成地面。"},{"en":"Poorly placed metal fences can block walking space and create frustration.","zh":"放置不當的金屬圍欄會阻塞步行空間並造成不滿。"},{"en":"The metal fences near the footbridge caused inconvenience but also protected pedestrians.","zh":"天橋附近的金屬圍欄造成不便，但也保護行人。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"drilling before breakfast","meaning":"早餐前的鑽鑿聲","examples":[{"en":"Nobody enjoys listening to drilling before breakfast.","zh":"沒有人喜歡聽早餐前的鑽鑿聲。"},{"en":"Drilling before breakfast means loud construction drilling early in the morning.","zh":"早餐前的鑽鑿聲，是清早出現的嘈雜工程鑽鑿聲。"},{"en":"Residents may feel irritated by drilling before breakfast because it breaks quiet morning time.","zh":"居民可能因早餐前的鑽鑿聲而不滿，因為它打破安靜早晨。"},{"en":"Early drilling should be managed carefully so it does not disturb people unnecessarily.","zh":"清早鑽鑿應小心管理，避免不必要地打擾人。"},{"en":"The writer agrees that drilling before breakfast is unpleasant, but not a reason to cancel the project.","zh":"作者同意早餐前的鑽鑿聲令人不快，但不是取消工程的理由。"}],"source":"2013 Q5.pdf","sourcePage":5},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, the complaint concerns efficiency.","zh":"乍看之下，這個投訴關乎效率。"},{"en":"At first glance means when first looking at something, before careful thought.","zh":"乍看之下，意思是在第一次看某事、還未仔細思考時。"},{"en":"At first glance, the new rule looked strict, but it was meant to protect safety.","zh":"乍看之下，新規則看起來嚴格，但它是為了保障安全。"},{"en":"First impressions can miss deeper issues behind a complaint.","zh":"第一印象可能錯過投訴背後更深層的問題。"},{"en":"At first glance, the complaint seems about speed, but it is also about who counts in public space.","zh":"乍看之下，投訴似乎關乎速度，但它也關乎公共空間中誰被重視。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"on closer inspection","meaning":"仔細看來","examples":[{"en":"On closer inspection, the complaint reveals a narrower attitude.","zh":"仔細看來，這個投訴顯示較狹隘的態度。"},{"en":"On closer inspection means after looking more carefully at the details.","zh":"仔細看來，意思是在更仔細觀察細節之後。"},{"en":"On closer inspection, the short essay had strong ideas hidden under simple language.","zh":"仔細看來，那篇短文在簡單語言下藏着有力想法。"},{"en":"Careful inspection can reveal assumptions that first impressions miss.","zh":"仔細檢視可以揭示第一印象錯過的假設。"},{"en":"On closer inspection, the complaints show a limited view of who public space is for.","zh":"仔細看來，這些投訴顯示對公共空間服務對象的看法有限。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"reveal a narrower attitude","meaning":"顯示較狹隘的態度","examples":[{"en":"The complaint reveals a narrower attitude towards public space.","zh":"這個投訴顯示對公共空間較狹隘的態度。"},{"en":"To reveal a narrower attitude means to show a limited or less generous way of thinking.","zh":"顯示較狹隘的態度，意思是呈現有限或不夠寬厚的思考方式。"},{"en":"A rule that ignores disabled students may reveal a narrower attitude towards inclusion.","zh":"忽視殘疾學生的規則，可能顯示對共融較狹隘的態度。"},{"en":"Complaints can reveal narrow attitudes when they focus only on personal convenience.","zh":"當投訴只集中於個人方便，它們可能顯示狹隘態度。"},{"en":"The writer says the complaint reveals a narrower attitude because it ignores vulnerable users.","zh":"作者說這投訴顯示較狹隘的態度，因為它忽視弱勢使用者。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"public space","meaning":"公共空間","examples":[{"en":"Public space should serve more than the fastest users.","zh":"公共空間應服務的不只是行得最快的使用者。"},{"en":"Public space is an area shared by members of the community, such as pavements, parks, and stations.","zh":"公共空間，是社區成員共享的地方，例如行人路、公園和車站。"},{"en":"A good public space allows children, elderly people, and disabled people to use it safely.","zh":"好的公共空間讓兒童、長者和殘疾人士安全使用。"},{"en":"Public space becomes unfair when it is designed only for strong and quick users.","zh":"當公共空間只為強壯和行動快速的人設計，它就變得不公平。"},{"en":"The footbridge is public space, so it should be accessible to different citizens.","zh":"行人天橋是公共空間，所以應讓不同市民都能使用。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"be judged through the eyes of","meaning":"透過……的眼光判斷","examples":[{"en":"Public space should not be judged only through the eyes of healthy users.","zh":"公共空間不應只透過健康使用者的眼光判斷。"},{"en":"Be judged through the eyes of someone means be evaluated from that person’s point of view.","zh":"透過某人的眼光判斷，意思是從那人的角度評價某事。"},{"en":"School rules should not be judged only through the eyes of top students.","zh":"校規不應只透過尖子學生的眼光判斷。"},{"en":"If a city is judged only through the eyes of fast walkers, slower citizens disappear from the discussion.","zh":"如果城市只透過快步行人的眼光判斷，行動較慢的市民就會在討論中消失。"},{"en":"The writer asks readers to judge public space through the eyes of people with access needs.","zh":"作者要求讀者透過有無障礙需要人士的眼光判斷公共空間。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"the fastest and healthiest users","meaning":"行得最快、最健康的使用者","examples":[{"en":"The city should not be designed only for the fastest and healthiest users.","zh":"城市不應只為行得最快、最健康的使用者而設計。"},{"en":"The fastest and healthiest users are people who can move quickly and easily without physical difficulty.","zh":"行得最快、最健康的使用者，是能快速輕鬆移動而沒有身體困難的人。"},{"en":"A young athlete may be one of the fastest and healthiest users of a footbridge.","zh":"年輕運動員可能是行人天橋上行得最快、最健康的使用者之一。"},{"en":"Designing only for such users excludes people with injuries, disabilities, or age-related needs.","zh":"只為這些使用者設計，會排除有傷患、殘疾或年老需要的人。"},{"en":"A fair city considers more than the fastest and healthiest users.","zh":"公平城市考慮的不只是行得最快、最健康的使用者。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"fail to see","meaning":"未能看見；忽略","examples":[{"en":"The complainants failed to see that stairs can exclude people.","zh":"投訴者未能看見樓梯可以排斥某些人。"},{"en":"To fail to see something means to not notice or understand an important fact.","zh":"未能看見某事，意思是沒有注意或理解一個重要事實。"},{"en":"A teacher may fail to see that a quiet student needs help.","zh":"老師可能忽略安靜學生需要幫助。"},{"en":"People fail to see others’ difficulties when they only think about their own routine.","zh":"當人們只想着自己的日常習慣，就會忽略別人的困難。"},{"en":"The complainants failed to see that stairs are not usable for everyone.","zh":"投訴者未能看見樓梯不是人人都能使用。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"staircase","meaning":"樓梯","examples":[{"en":"A staircase can be a closed door for some people.","zh":"對某些人來說，樓梯可以是一扇關上的門。"},{"en":"A staircase is a set of steps used to move between different levels.","zh":"樓梯，是用來在不同高度之間移動的一組階梯。"},{"en":"A staircase is easy for some people but impossible for others.","zh":"樓梯對某些人容易，但對另一些人可能不可能使用。"},{"en":"If a building has only a staircase, wheelchair users may be excluded.","zh":"如果建築物只有樓梯，輪椅使用者可能被排斥。"},{"en":"The writer uses the staircase as an example of hidden barriers in public space.","zh":"作者用樓梯作例子，說明公共空間中的隱藏障礙。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"not merely inconvenient","meaning":"不只是造成不便","examples":[{"en":"A staircase is not merely inconvenient to some people.","zh":"對某些人來說，樓梯不只是造成不便。"},{"en":"Not merely inconvenient means not just annoying, but much more serious.","zh":"不只是造成不便，意思是不只是令人煩惱，而是嚴重得多。"},{"en":"For a person with a broken leg, stairs are not merely inconvenient but painful and unsafe.","zh":"對腿骨折的人來說，樓梯不只是造成不便，而是痛苦且不安全。"},{"en":"Calling a barrier “inconvenient” may hide how serious it is for some people.","zh":"把障礙稱為「不便」，可能掩蓋它對某些人的嚴重性。"},{"en":"The writer argues that stairs are not merely inconvenient for wheelchair users; they can block access completely.","zh":"作者認為對輪椅使用者來說，樓梯不只是造成不便；它可以完全阻擋通行。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"a closed door","meaning":"一扇關上的門","examples":[{"en":"For some people, a staircase is a closed door.","zh":"對某些人來說，樓梯是一扇關上的門。"},{"en":"A closed door here means a barrier that stops someone from entering or using a place.","zh":"這裏的一扇關上的門，意思是阻止某人進入或使用某地方的障礙。"},{"en":"A website without screen-reader support can be a closed door to visually impaired users.","zh":"不支援讀屏軟件的網站，對視障使用者來說可以是一扇關上的門。"},{"en":"A closed door is not just inconvenient; it tells people they are not included.","zh":"一扇關上的門不只是造成不便；它告訴人們他們不被包括。"},{"en":"Without a lift, the footbridge may feel like a closed door to wheelchair users.","zh":"沒有升降機，行人天橋對輪椅使用者來說可能像一扇關上的門。"}],"source":"2013 Q5.pdf","sourcePage":6},{"front":"take… for example","meaning":"以……為例","examples":[{"en":"Take an elderly woman carrying groceries, for example.","zh":"以一名拿着雜貨的年長女士為例。"},{"en":"Take… for example is used to introduce a specific case that supports a point.","zh":"以……為例，用來引入支持某個觀點的具體例子。"},{"en":"Take a student with a broken arm, for example; writing quickly is not easy for them.","zh":"以一名手臂骨折的學生為例；快速寫字對他來說並不容易。"},{"en":"Writers use examples to make general arguments easier to understand.","zh":"作者使用例子，令一般論點更容易理解。"},{"en":"The writer says “take…for example” before showing who may need a lift.","zh":"作者說「以……為例」，然後展示誰可能需要升降機。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"carry groceries","meaning":"拿着雜貨","examples":[{"en":"An elderly woman carrying groceries may struggle with stairs.","zh":"一名拿着雜貨的年長女士可能難以應付樓梯。"},{"en":"To carry groceries means to hold or transport food and household items bought from shops.","zh":"拿着雜貨，意思是手持或搬運從商店買回來的食物和家居用品。"},{"en":"A person carrying groceries may find a long staircase tiring.","zh":"拿着雜貨的人可能覺得長樓梯很累。"},{"en":"Heavy bags make walking harder, especially for elderly residents.","zh":"沉重袋子會令步行更困難，特別是對年長居民而言。"},{"en":"A lift helps someone carrying groceries use the footbridge safely.","zh":"升降機幫助拿着雜貨的人安全使用行人天橋。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"push a sleeping child","meaning":"推着熟睡的孩子","examples":[{"en":"A father may be pushing a sleeping child in a pram.","zh":"一名父親可能正推着嬰兒車中熟睡的孩子。"},{"en":"To push a sleeping child means to move a pram while the child inside is asleep.","zh":"推着熟睡的孩子，意思是孩子在嬰兒車中睡着時推動嬰兒車。"},{"en":"A parent pushing a sleeping child cannot easily carry the pram up stairs.","zh":"推着熟睡孩子的家長，難以輕鬆把嬰兒車搬上樓梯。"},{"en":"A ramp helps parents avoid waking or endangering a child.","zh":"斜道幫助家長避免弄醒孩子或令孩子有危險。"},{"en":"The example shows that accessibility helps families, not only wheelchair users.","zh":"這個例子顯示無障礙設施幫助家庭，不只是幫助輪椅使用者。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"delivery worker","meaning":"送貨員","examples":[{"en":"A delivery worker with a heavy trolley needs accessible routes.","zh":"帶着沉重手推車的送貨員需要無障礙路線。"},{"en":"A delivery worker is someone who transports goods, parcels, or food from one place to another.","zh":"送貨員，是把貨物、包裹或食物從一地運到另一地的人。"},{"en":"A delivery worker may need ramps when carrying heavy items through a district.","zh":"送貨員搬運重物穿過社區時，可能需要斜道。"},{"en":"Stairs can slow delivery workers down and make their work unsafe.","zh":"樓梯會令送貨員放慢速度，並使工作不安全。"},{"en":"Accessible routes help delivery workers as well as residents with mobility needs.","zh":"無障礙路線幫助送貨員，也幫助有行動需要的居民。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"heavy trolley","meaning":"沉重手推車","examples":[{"en":"A heavy trolley can make stairs impossible to use.","zh":"沉重手推車可以令樓梯無法使用。"},{"en":"A heavy trolley is a wheeled cart carrying items that are difficult to lift.","zh":"沉重手推車，是載着難以抬起物件的有輪推車。"},{"en":"A cleaner may use a heavy trolley to move supplies through a building.","zh":"清潔工可能使用沉重手推車在大樓中運送用品。"},{"en":"Stairs become a serious barrier when someone must move a heavy trolley.","zh":"當某人必須移動沉重手推車，樓梯就成為嚴重障礙。"},{"en":"A ramp allows a heavy trolley to move safely without lifting.","zh":"斜道讓沉重手推車不用抬起也能安全移動。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"recover from","meaning":"從……康復中","examples":[{"en":"A student may be recovering from a leg injury.","zh":"學生可能正從腿傷康復中。"},{"en":"To recover from something means to get better after illness, injury, or difficulty.","zh":"從某事康復中，意思是在疾病、受傷或困難後逐漸好轉。"},{"en":"A runner may recover from a knee injury by resting and doing physiotherapy.","zh":"跑手可能透過休息和物理治療從膝傷康復。"},{"en":"People recovering from injuries may need temporary support in public spaces.","zh":"正在康復的人可能在公共空間中需要臨時支援。"},{"en":"A lift helps students recovering from leg injuries move safely.","zh":"升降機幫助正從腿傷康復中的學生安全移動。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"leg injury","meaning":"腿傷","examples":[{"en":"A student with a leg injury may need a lift.","zh":"腿傷學生可能需要升降機。"},{"en":"A leg injury is harm to the leg that makes walking, climbing, or standing difficult.","zh":"腿傷，是令步行、上樓梯或站立變得困難的腿部傷害。"},{"en":"A sprained ankle is a common leg injury among students who play sport.","zh":"扭傷腳踝是做運動學生常見的腿傷。"},{"en":"Even a temporary leg injury can make stairs painful or unsafe.","zh":"即使是暫時腿傷，也會令樓梯變得痛苦或不安全。"},{"en":"Accessibility matters because anyone may have a leg injury at some point.","zh":"無障礙設施重要，因為任何人都有可能在某一刻遇上腿傷。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"not advice, but exclusion","meaning":"不是建議，而是排斥","examples":[{"en":"“Just use the stairs” is not advice, but exclusion.","zh":"「用樓梯就可以」不是建議，而是排斥。"},{"en":"Not advice, but exclusion means a suggestion may sound helpful but actually shuts people out.","zh":"不是建議，而是排斥，意思是某個說法聽似有幫助，但其實把人拒之門外。"},{"en":"Telling a wheelchair user to enter through the stairs is not advice, but exclusion.","zh":"叫輪椅使用者經樓梯進入，不是建議，而是排斥。"},{"en":"Words can exclude people when they ignore what those people physically cannot do.","zh":"當說話忽視人們身體上做不到的事，它就會排斥人。"},{"en":"The writer says “use the stairs” is unfair because stairs are impossible for some people.","zh":"作者說「用樓梯」是不公平的，因為對某些人來說樓梯是不可能的。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"disguised as common sense","meaning":"偽裝成常識","examples":[{"en":"Exclusion can be disguised as common sense.","zh":"排斥可以偽裝成常識。"},{"en":"Disguised as common sense means something unfair is presented as if it were obvious and reasonable.","zh":"偽裝成常識，意思是不公平的事被包裝成顯而易見和合理。"},{"en":"Saying “everyone can climb stairs” may be exclusion disguised as common sense.","zh":"說「人人都可以爬樓梯」可能是偽裝成常識的排斥。"},{"en":"Harmful ideas are harder to challenge when they sound like common sense.","zh":"當有害想法聽起來像常識，就更難被挑戰。"},{"en":"The writer warns that convenience arguments may hide exclusion.","zh":"作者提醒我們，方便的論點可能隱藏排斥。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"common sense","meaning":"常識","examples":[{"en":"Some people wrongly present exclusion as common sense.","zh":"有些人錯誤地把排斥包裝成常識。"},{"en":"Common sense means practical judgement that seems obvious to many people.","zh":"常識，意思是對很多人來說顯而易見的實際判斷。"},{"en":"Looking both ways before crossing the road is common sense.","zh":"過馬路前左右看是常識。"},{"en":"What sounds like common sense to one group may ignore another group’s needs.","zh":"對一個群體來說像常識的東西，可能忽視另一群體的需要。"},{"en":"The writer challenges the so-called common sense that everyone can simply use stairs.","zh":"作者挑戰所謂人人都可以簡單使用樓梯的常識。"}],"source":"2013 Q5.pdf","sourcePage":7},{"front":"five-minute detour","meaning":"五分鐘繞路","examples":[{"en":"A five-minute detour may be annoying but manageable.","zh":"五分鐘繞路可能令人煩躁，但可以應付。"},{"en":"A five-minute detour is a route that takes about five extra minutes.","zh":"五分鐘繞路，是多花大約五分鐘的路線。"},{"en":"A student may take a five-minute detour when the playground path is closed.","zh":"當操場小路關閉，學生可能需要五分鐘繞路。"},{"en":"A short detour is different from a barrier that stops someone completely.","zh":"短暫繞路不同於完全阻止某人通行的障礙。"},{"en":"The writer says a five-minute detour is minor compared with lack of accessibility.","zh":"作者說與缺乏無障礙設施相比，五分鐘繞路是小事。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"able-bodied pedestrian","meaning":"身體健全的行人","examples":[{"en":"A five-minute detour is minor for an able-bodied pedestrian.","zh":"對身體健全的行人來說，五分鐘繞路是小事。"},{"en":"An able-bodied pedestrian is a walker without a physical condition that limits movement.","zh":"身體健全的行人，是沒有行動限制身體狀況的步行者。"},{"en":"An able-bodied pedestrian may climb stairs without thinking twice.","zh":"身體健全的行人可能不加思索就能爬樓梯。"},{"en":"Cities should not be planned only around able-bodied pedestrians.","zh":"城市不應只圍繞身體健全的行人來規劃。"},{"en":"What is minor for an able-bodied pedestrian may be serious for a wheelchair user.","zh":"對身體健全的行人來說是小事的東西，對輪椅使用者可能很嚴重。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"absence of a lift","meaning":"缺少升降機","examples":[{"en":"The absence of a lift can seriously affect wheelchair users.","zh":"缺少升降機可以嚴重影響輪椅使用者。"},{"en":"The absence of a lift means there is no lift available where one is needed.","zh":"缺少升降機，意思是在需要升降機的地方沒有可用升降機。"},{"en":"The absence of a lift in an old building may trap elderly residents on upper floors.","zh":"舊大廈缺少升降機，可能令年長居民困在高層。"},{"en":"When a lift is absent, stairs may become the only route.","zh":"當缺少升降機，樓梯可能成為唯一路線。"},{"en":"The absence of a lift can turn a public footbridge into an inaccessible place.","zh":"缺少升降機可以令公共行人天橋變成不能通行的地方。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"cancelling a medical appointment","meaning":"取消覆診／醫療預約","examples":[{"en":"The absence of a lift can mean cancelling a medical appointment.","zh":"缺少升降機可能意味着取消覆診。"},{"en":"Cancelling a medical appointment means not attending a planned visit to a doctor or clinic.","zh":"取消覆診或醫療預約，意思是不出席已安排的醫生或診所約見。"},{"en":"An elderly patient may cancel a medical appointment if the route is too difficult.","zh":"如果路線太困難，年長病人可能取消覆診。"},{"en":"Poor access can affect health when people miss medical care.","zh":"當人們錯過醫療照顧，差劣通道會影響健康。"},{"en":"The writer shows that lack of a lift can cause more than simple inconvenience.","zh":"作者顯示缺少升降機造成的不只是簡單不便。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"medical appointment","meaning":"醫療預約","examples":[{"en":"A wheelchair user may miss a medical appointment without a lift.","zh":"沒有升降機，輪椅使用者可能錯過醫療預約。"},{"en":"A medical appointment is an arranged time to see a doctor, nurse, or clinic worker.","zh":"醫療預約，是安排好見醫生、護士或診所人員的時間。"},{"en":"Patients should arrive on time for a medical appointment so treatment is not delayed.","zh":"病人應準時出席醫療預約，以免延誤治療。"},{"en":"Missing medical appointments can affect health, especially for elderly or disabled people.","zh":"錯過醫療預約可能影響健康，特別是對年長或殘疾人士而言。"},{"en":"Accessible transport routes help people keep their medical appointments.","zh":"無障礙交通路線幫助人們出席醫療預約。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"avoid a library","meaning":"避開圖書館","examples":[{"en":"Without accessible facilities, some people may avoid a library.","zh":"沒有無障礙設施，有些人可能避開圖書館。"},{"en":"To avoid a library means to stop going there because it is difficult or unpleasant to use.","zh":"避開圖書館，意思是因難以使用或令人不快而不再前往。"},{"en":"A student with a leg injury may avoid a library if it has only stairs.","zh":"如果圖書館只有樓梯，腿傷學生可能避開它。"},{"en":"People avoid public places when the route makes them feel unsafe or dependent.","zh":"當路線令人感到不安全或需要依賴別人，人們會避開公共地方。"},{"en":"A lift can stop people from avoiding useful community facilities.","zh":"升降機可以阻止人們避開有用的社區設施。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"depend on a stranger for help","meaning":"依賴陌生人幫忙","examples":[{"en":"A wheelchair user should not have to depend on a stranger for help.","zh":"輪椅使用者不應需要依賴陌生人幫忙。"},{"en":"To depend on a stranger for help means to need assistance from someone unknown in order to move or enter a place.","zh":"依賴陌生人幫忙，意思是需要不認識的人協助才能移動或進入某地。"},{"en":"A person should not need to depend on a stranger to climb stairs at a station.","zh":"一個人不應需要依賴陌生人在車站爬樓梯。"},{"en":"Dependence can feel humiliating when the place should already be accessible.","zh":"當地方本應無障礙時，依賴別人可能令人感到難堪。"},{"en":"Public design should allow people to move independently, not depend on strangers.","zh":"公共設計應讓人獨立出行，而不是依賴陌生人。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"the more…, the more…","meaning":"越……就越……","examples":[{"en":"The more we design the city for fast users, the more invisible others become.","zh":"我們越為快速使用者設計城市，其他人就越被忽視。"},{"en":"The more…, the more… shows that one change increases as another change increases.","zh":"越……就越……，顯示一件事增加時，另一件事也隨之增加。"},{"en":"The more students practise, the more confident they become.","zh":"學生越練習，就越有信心。"},{"en":"This structure helps show cause and effect growing together.","zh":"這個結構幫助顯示因果一起增長。"},{"en":"The writer uses it to show that speed-focused design makes vulnerable users easier to ignore.","zh":"作者用它來顯示以速度為中心的設計會令弱勢使用者更容易被忽視。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"design the city","meaning":"設計城市","examples":[{"en":"We should not design the city only for people who move quickly.","zh":"我們不應只為行動迅速的人設計城市。"},{"en":"To design the city means to plan public spaces, transport, buildings, and routes.","zh":"設計城市，意思是規劃公共空間、交通、建築物和路線。"},{"en":"City planners design the city when they decide where pavements, lifts, and crossings go.","zh":"城市規劃者決定行人路、升降機和過路處的位置時，就是在設計城市。"},{"en":"Designing the city only for strong users creates hidden unfairness.","zh":"只為強壯使用者設計城市，會造成隱藏的不公平。"},{"en":"A fair city is designed for people with different bodies, ages, and needs.","zh":"公平城市是為不同身體、年齡和需要的人而設計的。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"move quickly","meaning":"行動迅速","examples":[{"en":"Some citizens cannot move quickly through public spaces.","zh":"有些市民不能在公共空間中行動迅速。"},{"en":"To move quickly means to walk, travel, or pass through a place at high speed.","zh":"行動迅速，意思是快速步行、出行或穿過某地。"},{"en":"Young commuters may move quickly through a station during rush hour.","zh":"年輕通勤者在繁忙時間可能快速穿過車站。"},{"en":"Elderly people, injured students, and wheelchair users may not be able to move quickly.","zh":"長者、受傷學生和輪椅使用者未必能行動迅速。"},{"en":"Public space should not punish people simply because they cannot move quickly.","zh":"公共空間不應只因人不能行動迅速就令他們受罰。"}],"source":"2013 Q5.pdf","sourcePage":8},{"front":"make someone invisible","meaning":"令某人被忽視","examples":[{"en":"Poor design can make disabled citizens invisible.","zh":"差劣設計可以令殘疾市民被忽視。"},{"en":"To make someone invisible means to ignore their needs so completely that society seems not to notice them.","zh":"令某人被忽視，意思是完全忽略他們的需要，令社會似乎看不見他們。"},{"en":"A school timetable can make carers invisible if it assumes every parent is free at noon.","zh":"如果學校時間表假設每位家長中午都有空，就可能令照顧者被忽視。"},{"en":"Bad design makes people invisible when it prevents them from appearing in public life.","zh":"當差劣設計阻止人們出現在公共生活中，它就令他們被忽視。"},{"en":"Lack of lifts can make wheelchair users invisible by keeping them away from shared places.","zh":"缺少升降機會令輪椅使用者遠離共享地方，從而令他們被忽視。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"it therefore follows that","meaning":"因此可以推論","examples":[{"en":"It therefore follows that accessibility is not special treatment.","zh":"因此可以推論，無障礙設施不是特別待遇。"},{"en":"It therefore follows that means this conclusion logically comes from the previous points.","zh":"因此可以推論，意思是這個結論合乎邏輯地來自前面的觀點。"},{"en":"If every student needs safety, it therefore follows that broken stairs must be repaired.","zh":"如果每位學生都需要安全，因此可以推論壞樓梯必須維修。"},{"en":"This phrase helps writers connect evidence to a clear conclusion.","zh":"這個短語幫助作者把證據連接到清晰結論。"},{"en":"After showing that stairs exclude people, the writer says accessibility is basic fairness.","zh":"在顯示樓梯會排斥某些人後，作者指出無障礙設施是基本公平。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"spending public money on accessibility","meaning":"將公帑用於無障礙設施","examples":[{"en":"Spending public money on accessibility benefits the whole community.","zh":"將公帑用於無障礙設施令整個社區受惠。"},{"en":"Spending public money on accessibility means using government funds to make places easier for everyone to use.","zh":"將公帑用於無障礙設施，意思是使用政府資金令地方更容易讓所有人使用。"},{"en":"Installing ramps and tactile paving is spending public money on accessibility.","zh":"安裝斜道和觸覺引路帶，就是將公帑用於無障礙設施。"},{"en":"Such spending may help disabled users first, but others also benefit over time.","zh":"這類開支可能首先幫助殘疾使用者，但其他人長遠也會受惠。"},{"en":"The writer defends spending public money on accessibility because public places should serve all citizens.","zh":"作者支持將公帑用於無障礙設施，因為公共地方應服務所有市民。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"special treatment","meaning":"特別待遇","examples":[{"en":"Accessibility is not special treatment.","zh":"無障礙設施不是特別待遇。"},{"en":"Special treatment means giving someone extra advantage beyond what is fair or necessary.","zh":"特別待遇，意思是給某人超出公平或必要範圍的額外優勢。"},{"en":"Allowing a wheelchair user to enter a building is not special treatment; it is basic access.","zh":"讓輪椅使用者進入建築物不是特別待遇；這是基本通行。"},{"en":"People may wrongly call fairness special treatment when they do not share the same need.","zh":"當人們沒有相同需要時，可能錯誤地把公平稱為特別待遇。"},{"en":"The writer argues that lifts and ramps create equal access, not special treatment.","zh":"作者認為升降機和斜道創造平等通道，而不是特別待遇。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"truly public","meaning":"真正屬於公眾","examples":[{"en":"Accessibility makes an already public place truly public.","zh":"無障礙設施令一個本已屬於公眾的地方真正屬於公眾。"},{"en":"Truly public means genuinely open and usable by all members of the community.","zh":"真正屬於公眾，意思是真正向社區所有成員開放並可使用。"},{"en":"A park is not truly public if wheelchair users cannot enter it.","zh":"如果輪椅使用者不能進入公園，公園就不是真正屬於公眾。"},{"en":"Public spaces become truly public only when different people can use them safely.","zh":"只有當不同人士都能安全使用，公共空間才真正屬於公眾。"},{"en":"The footbridge becomes truly public when elderly residents and wheelchair users can cross it too.","zh":"當年長居民和輪椅使用者也能過橋，行人天橋才真正屬於公眾。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, the works could have been better managed.","zh":"誠然，這些工程本可以管理得更好。"},{"en":"Granted is used to admit that an opposing point has some truth before answering it.","zh":"誠然，用來承認相反觀點有一定道理，然後再回應它。"},{"en":"Granted, the roadworks are noisy, but they will make the junction safer.","zh":"誠然，道路工程很嘈，但它會令路口更安全。"},{"en":"This word helps a writer sound fair instead of ignoring real problems.","zh":"這個詞幫助作者顯得公平，而不是忽視真正問題。"},{"en":"The writer grants that management could improve, but still supports the project.","zh":"作者承認管理可以改善，但仍支持這項工程。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"better managed","meaning":"管理得更好","examples":[{"en":"The construction works could have been better managed.","zh":"這些建築工程本可以管理得更好。"},{"en":"Better managed means organised, timed, and communicated in a more effective way.","zh":"管理得更好，意思是在組織、時間安排和溝通上更有效。"},{"en":"A school event is better managed when signs are clear and queues are short.","zh":"當標誌清楚、排隊時間短，學校活動就是管理得更好。"},{"en":"Works are better managed when residents know what will happen and when.","zh":"當居民知道會發生甚麼和何時發生，工程就是管理得更好。"},{"en":"The writer believes the project is right, even if it should be better managed.","zh":"作者認為工程本身正確，即使它應該管理得更好。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"authorities","meaning":"當局","examples":[{"en":"The authorities should display clearer notices.","zh":"當局應展示更清晰的告示。"},{"en":"Authorities are official organisations or people with power to manage public matters.","zh":"當局，是有權管理公共事務的官方組織或人員。"},{"en":"Transport authorities may announce changes to station exits.","zh":"交通當局可能宣布車站出口改動。"},{"en":"Authorities should explain public works clearly so residents understand the reason.","zh":"當局應清楚解釋公共工程，讓居民明白原因。"},{"en":"In this case, the authorities should improve communication about the footbridge works.","zh":"在這件事上，當局應改善關於行人天橋工程的溝通。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"display clearer notices","meaning":"展示更清晰的告示","examples":[{"en":"The authorities should display clearer notices near the works.","zh":"當局應在工程附近展示更清晰的告示。"},{"en":"To display clearer notices means to put up easier-to-read signs or messages.","zh":"展示更清晰的告示，意思是張貼更容易閱讀的標誌或訊息。"},{"en":"A school should display clearer notices when classrooms are moved.","zh":"當課室改動時，學校應展示更清晰的告示。"},{"en":"Clear notices reduce frustration because people know where to go.","zh":"清晰告示可以減少不滿，因為人們知道該往哪裏走。"},{"en":"The footbridge works would be less confusing if the authorities displayed clearer notices.","zh":"如果當局展示更清晰的告示，行人天橋工程會較少令人困惑。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"noisy procedures","meaning":"噪音較大的工序","examples":[{"en":"Noisy procedures should be finished efficiently.","zh":"噪音較大的工序應有效率地完成。"},{"en":"Noisy procedures are parts of work that create loud sounds, such as drilling or breaking concrete.","zh":"噪音較大的工序，是產生巨大聲音的工作部分，例如鑽鑿或破碎混凝土。"},{"en":"Schools may schedule noisy procedures after exam hours to avoid disturbing students.","zh":"學校可能把噪音較大的工序安排在考試時間後，以免打擾學生。"},{"en":"Noisy procedures should be planned carefully because they affect shops and residents.","zh":"噪音較大的工序應小心計劃，因為它們影響商店和居民。"},{"en":"The writer supports the works but wants noisy procedures handled more considerately.","zh":"作者支持工程，但希望噪音較大的工序更體貼地處理。"}],"source":"2013 Q5.pdf","sourcePage":9},{"front":"as efficiently as possible","meaning":"盡可能有效率地","examples":[{"en":"The authorities should finish noisy procedures as efficiently as possible.","zh":"當局應盡可能有效率地完成噪音較大的工序。"},{"en":"As efficiently as possible means with as little wasted time, effort, or disturbance as can reasonably be achieved.","zh":"盡可能有效率地，意思是在合理情況下盡量少浪費時間、努力或造成滋擾。"},{"en":"A school should repair a broken gate as efficiently as possible to reduce disruption.","zh":"學校應盡可能有效率地維修壞門，以減少干擾。"},{"en":"Efficient work does not mean rushing carelessly; it means planning well.","zh":"有效率工作不是魯莽趕工，而是良好規劃。"},{"en":"Finishing noisy work efficiently would reduce the burden on nearby residents.","zh":"有效率地完成噪音工程，可以減少附近居民的負擔。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"leave enough room for","meaning":"留出足夠空間予","examples":[{"en":"The works should leave enough room for safe pedestrian flow.","zh":"工程應留出足夠空間予安全行人流動。"},{"en":"To leave enough room for something means to keep sufficient space for it to happen safely.","zh":"留出足夠空間予某事，意思是保留足夠空間讓它安全發生。"},{"en":"A classroom should leave enough room for students to walk between desks.","zh":"課室應留出足夠空間讓學生在書桌之間行走。"},{"en":"Construction barriers should leave enough room for prams and wheelchairs to pass.","zh":"工程圍欄應留出足夠空間讓嬰兒車和輪椅通過。"},{"en":"The writer says the temporary route should leave enough room for pedestrians.","zh":"作者說臨時路線應留出足夠空間給行人。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"safe pedestrian flow","meaning":"安全行人流動","examples":[{"en":"The temporary route should allow safe pedestrian flow.","zh":"臨時路線應容許安全行人流動。"},{"en":"Safe pedestrian flow means people can walk through an area smoothly without danger or crowding.","zh":"安全行人流動，意思是人們可以順暢地走過某區域，而沒有危險或擠迫。"},{"en":"Clear signs and wide paths help safe pedestrian flow near a school gate.","zh":"清晰標誌和寬闊通道有助學校門口的安全行人流動。"},{"en":"Poor pedestrian flow can cause pushing, confusion, and accidents.","zh":"行人流動欠佳可能造成推撞、混亂和意外。"},{"en":"The footbridge works should be arranged to keep safe pedestrian flow during construction.","zh":"行人天橋工程應安排得在施工期間仍保持安全行人流動。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"shop owners","meaning":"店主","examples":[{"en":"Shop owners deserve to be informed about affected entrances.","zh":"店主應該被通知入口受影響的情況。"},{"en":"Shop owners are people who own or run shops.","zh":"店主，是擁有或經營商店的人。"},{"en":"Shop owners may lose business if customers cannot find the entrance.","zh":"如果顧客找不到入口，店主可能失去生意。"},{"en":"Public works should consider shop owners because construction can affect daily income.","zh":"公共工程應考慮店主，因為工程可能影響每日收入。"},{"en":"The writer believes shop owners should receive clear information before entrances are affected.","zh":"作者認為在入口受影響前，店主應收到清晰資訊。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"deserve to be informed","meaning":"應該被通知","examples":[{"en":"Shop owners deserve to be informed if entrances may be affected.","zh":"如果入口可能受影響，店主應該被通知。"},{"en":"Deserve to be informed means have a fair right to receive important information.","zh":"應該被通知，意思是有公平權利收到重要資訊。"},{"en":"Parents deserve to be informed if a school trip is delayed.","zh":"如果學校旅行延誤，家長應該被通知。"},{"en":"People deserve to be informed when a public change affects their daily work.","zh":"當公共變動影響日常工作，人們應該被通知。"},{"en":"Shop owners deserve to be informed so they can prepare for possible disruption.","zh":"店主應該被通知，好讓他們為可能的干擾作準備。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"entrances may be affected","meaning":"入口可能受影響","examples":[{"en":"Shop owners should be told if their entrances may be affected.","zh":"如果店舖入口可能受影響，店主應該獲告知。"},{"en":"Entrances may be affected means doorways or access points might be blocked, moved, or made harder to use.","zh":"入口可能受影響，意思是門口或進入點可能被阻塞、改動或變得較難使用。"},{"en":"A shop entrance may be affected when barriers are placed in front of it.","zh":"當圍欄放在店舖門前，入口可能受影響。"},{"en":"If entrances are affected, customers may not know how to enter safely.","zh":"如果入口受影響，顧客可能不知道如何安全進入。"},{"en":"Clear notice helps shop owners prepare when entrances may be affected.","zh":"當入口可能受影響，清晰通知能幫助店主準備。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"this is not to say that","meaning":"這並不是說","examples":[{"en":"This is not to say that residents have no right to complain.","zh":"這並不是說居民沒有權投訴。"},{"en":"This is not to say that means the writer is limiting their argument and avoiding misunderstanding.","zh":"這並不是說，意思是作者限制自己的論點，避免被誤解。"},{"en":"This is not to say that homework is useless; it means homework should be reasonable.","zh":"這並不是說功課無用；而是說功課應合理。"},{"en":"Writers use this phrase to show balance and fairness.","zh":"作者使用這個短語來顯示平衡和公平。"},{"en":"The writer supports accessibility but does not deny residents’ right to complain about poor management.","zh":"作者支持無障礙設施，但並沒有否定居民投訴管理欠佳的權利。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"have no right to complain","meaning":"沒有權投訴","examples":[{"en":"Residents do not have no right to complain about poor arrangements.","zh":"居民並不是沒有權投訴欠佳安排。"},{"en":"Have no right to complain means not be allowed or justified to express dissatisfaction.","zh":"沒有權投訴，意思是不被容許或沒有理由表達不滿。"},{"en":"Students do not have no right to complain if a school bus is always late.","zh":"如果校巴經常遲到，學生並不是沒有權投訴。"},{"en":"People have a right to complain when arrangements are unsafe or unclear.","zh":"當安排不安全或不清晰，人們有權投訴。"},{"en":"The writer says residents may complain, but they should complain about practical problems.","zh":"作者說居民可以投訴，但應投訴實際問題。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"poor arrangements","meaning":"欠佳安排","examples":[{"en":"Residents may complain about poor arrangements.","zh":"居民可以投訴欠佳安排。"},{"en":"Poor arrangements are badly planned details that cause unnecessary trouble.","zh":"欠佳安排，是計劃不好的細節，造成不必要麻煩。"},{"en":"A school event has poor arrangements if signs are unclear and queues are confusing.","zh":"如果標誌不清晰、排隊混亂，學校活動就是安排欠佳。"},{"en":"Poor arrangements should be corrected because they waste time and create frustration.","zh":"欠佳安排應被糾正，因為它浪費時間並造成不滿。"},{"en":"The writer separates poor arrangements from the principle of accessibility.","zh":"作者把欠佳安排與無障礙原則分開看待。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"the point is not whether…, but whether…","meaning":"重點不在於是否……，而在於是否……","examples":[{"en":"The point is not whether people may complain, but whether every inconvenience deserves outrage.","zh":"重點不在於人們是否可以投訴，而在於是否每種不便都值得憤怒。"},{"en":"The point is not whether…, but whether… shifts attention from the wrong question to the real question.","zh":"重點不在於是否……，而在於是否……，把注意力由錯誤問題轉向真正問題。"},{"en":"The point is not whether students dislike homework, but whether the homework helps them learn.","zh":"重點不在於學生是否不喜歡功課，而在於功課是否幫助他們學習。"},{"en":"This structure helps writers make a sharper argument.","zh":"這個結構幫助作者提出更清晰的論點。"},{"en":"Here, the real issue is not complaint itself, but whether a short detour justifies anger.","zh":"在這裏，真正問題不是投訴本身，而是短暫繞路是否值得憤怒。"}],"source":"2013 Q5.pdf","sourcePage":10},{"front":"object to inconvenience","meaning":"反對不便","examples":[{"en":"People may object to inconvenience.","zh":"人們可以反對不便。"},{"en":"To object to inconvenience means to express disagreement or dissatisfaction about being troubled.","zh":"反對不便，意思是對受到麻煩表達不同意或不滿。"},{"en":"Residents may object to inconvenience when roadworks block their usual route.","zh":"當道路工程阻塞平常路線，居民可能反對不便。"},{"en":"Objecting to inconvenience is reasonable if the problem is badly managed.","zh":"如果問題管理欠佳，反對不便是合理的。"},{"en":"The writer says people may object to inconvenience, but should not attack accessibility itself.","zh":"作者說人們可以反對不便，但不應攻擊無障礙設施本身。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"moral outrage","meaning":"道德憤怒","examples":[{"en":"Not every inconvenience deserves moral outrage.","zh":"不是每種不便都值得道德憤怒。"},{"en":"Moral outrage is strong anger based on the belief that something is deeply wrong or unfair.","zh":"道德憤怒，是基於相信某事深深錯誤或不公平而產生的強烈憤怒。"},{"en":"Cheating vulnerable customers may deserve moral outrage.","zh":"欺騙弱勢顧客可能值得道德憤怒。"},{"en":"A short queue usually does not deserve moral outrage.","zh":"短暫排隊通常不值得道德憤怒。"},{"en":"The writer argues that a temporary detour should not be treated with moral outrage.","zh":"作者認為暫時繞路不應被當成需要道德憤怒的事情。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"a resounding no","meaning":"響亮的否定答案","examples":[{"en":"The answer should be a resounding no.","zh":"答案應是響亮的否定答案。"},{"en":"A resounding no is a very clear and strong refusal or rejection.","zh":"響亮的否定答案，是非常清楚和強烈的拒絕或否定。"},{"en":"Should safety be ignored for speed? The answer is a resounding no.","zh":"安全應為速度被忽視嗎？答案是響亮的否定答案。"},{"en":"This phrase makes the writer’s judgement firm and unmistakable.","zh":"這個短語令作者的判斷堅定而明確。"},{"en":"The writer gives a resounding no to the idea that every inconvenience deserves outrage.","zh":"對於每種不便都值得憤怒的想法，作者給出響亮的否定答案。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"temporary route","meaning":"臨時路線","examples":[{"en":"Residents may reasonably ask for a better temporary route.","zh":"居民可以合理地要求更好的臨時路線。"},{"en":"A temporary route is a short-term path used while the usual route is closed or changed.","zh":"臨時路線，是平常路線關閉或改動時使用的短期路徑。"},{"en":"A school may create a temporary route when the main staircase is being repaired.","zh":"當主樓梯維修時，學校可能設立臨時路線。"},{"en":"Temporary routes should be safe, clearly marked, and wide enough.","zh":"臨時路線應安全、標示清楚，並有足夠寬度。"},{"en":"The writer supports asking for a better temporary route, not cancelling the whole project.","zh":"作者支持要求更好的臨時路線，而不是取消整項工程。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"demand that","meaning":"要求","examples":[{"en":"Some people demanded that the project be cancelled.","zh":"有些人要求取消工程。"},{"en":"To demand that means to strongly ask or insist that something happen.","zh":"要求某事，意思是強烈請求或堅持某事發生。"},{"en":"Residents may demand that noisy works stop after midnight.","zh":"居民可能要求午夜後停止噪音工程。"},{"en":"Demanding a change can be fair when people face real danger.","zh":"當人們面對真正危險，要求改變可以是公平的。"},{"en":"The writer thinks demanding cancellation is too extreme for a temporary detour.","zh":"作者認為因暫時繞路而要求取消工程太極端。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"the project be cancelled","meaning":"取消工程","examples":[{"en":"Demanding that the project be cancelled is unreasonable.","zh":"要求取消工程是不合理的。"},{"en":"The project be cancelled means the planned work should be stopped and not completed.","zh":"取消工程，意思是停止計劃中的工作並不再完成。"},{"en":"A school trip may be cancelled if a storm makes travel unsafe.","zh":"如果暴風雨令出行不安全，學校旅行可能被取消。"},{"en":"Cancelling a project should require serious reasons, not just mild inconvenience.","zh":"取消工程應需要嚴重理由，而不是只有輕微不便。"},{"en":"The writer says the accessibility project should not be cancelled because some people dislike a detour.","zh":"作者說，不應只因為有些人不喜歡繞路就取消無障礙工程。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"simply because","meaning":"只是因為","examples":[{"en":"The project should not be cancelled simply because it disrupts a shortcut.","zh":"工程不應只是因為打亂熟悉的捷徑就被取消。"},{"en":"Simply because means only for that reason and no stronger reason.","zh":"只是因為，意思是只由於那個原因，而沒有更強理由。"},{"en":"A student should not quit a club simply because the first meeting was awkward.","zh":"學生不應只是因為第一次會議尷尬就退出學會。"},{"en":"This phrase often suggests the reason is too weak by itself.","zh":"這個短語常暗示單靠該理由太薄弱。"},{"en":"The writer says a public project should not end simply because it causes a short inconvenience.","zh":"作者說公共工程不應只是因為造成短暫不便就結束。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"disrupt a familiar shortcut","meaning":"打亂熟悉的捷徑","examples":[{"en":"The works disrupted a familiar shortcut.","zh":"工程打亂了熟悉的捷徑。"},{"en":"To disrupt a familiar shortcut means to interrupt a route people usually use to save time.","zh":"打亂熟悉的捷徑，意思是中斷人們平常用來節省時間的路線。"},{"en":"A closed school gate may disrupt a familiar shortcut to the bus stop.","zh":"關閉的學校大門可能打亂通往巴士站的熟悉捷徑。"},{"en":"Disrupting a shortcut can annoy people because it changes daily habits.","zh":"打亂捷徑會令人煩躁，因為它改變日常習慣。"},{"en":"The writer says disrupting a shortcut is not enough reason to cancel accessibility works.","zh":"作者說打亂捷徑不足以成為取消無障礙工程的理由。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"another matter altogether","meaning":"完全是另一回事","examples":[{"en":"Demanding cancellation is another matter altogether.","zh":"要求取消工程完全是另一回事。"},{"en":"Another matter altogether means a completely different and more serious issue.","zh":"完全是另一回事，意思是完全不同而且更嚴重的問題。"},{"en":"Asking for clearer signs is reasonable; demanding the whole plan stop is another matter altogether.","zh":"要求更清晰標誌是合理的；要求整個計劃停止完全是另一回事。"},{"en":"This phrase separates a fair complaint from an extreme demand.","zh":"這個短語把合理投訴與極端要求分開。"},{"en":"The writer accepts criticism of management but treats cancellation as another matter altogether.","zh":"作者接受對管理的批評，但把取消工程視為完全是另一回事。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, such complaints encourage an ungenerous civic culture.","zh":"更重要的是，這類投訴助長缺乏包容的公民文化。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"更重要的是，用來引出比前一點更重要的內容。"},{"en":"The detour is temporary; more importantly, the lift will help people for years.","zh":"繞路是暫時的；更重要的是，升降機會多年幫助人們。"},{"en":"Writers use this phrase to move from a smaller issue to a deeper concern.","zh":"作者使用這個短語，由較小問題轉向更深層憂慮。"},{"en":"The writer says the deeper problem is the attitude such complaints create.","zh":"作者說更深層問題是這類投訴所造成的態度。"}],"source":"2013 Q5.pdf","sourcePage":11},{"front":"encourage an ungenerous civic culture","meaning":"助長缺乏包容的公民文化","examples":[{"en":"Such complaints encourage an ungenerous civic culture.","zh":"這類投訴助長缺乏包容的公民文化。"},{"en":"To encourage an ungenerous civic culture means to make society less willing to consider others’ needs.","zh":"助長缺乏包容的公民文化，意思是令社會更不願考慮他人需要。"},{"en":"Complaints that reject ramps can encourage an ungenerous civic culture.","zh":"反對斜道的投訴可以助長缺乏包容的公民文化。"},{"en":"A generous civic culture asks who benefits, not only who is inconvenienced.","zh":"有包容的公民文化會問誰受惠，而不只是誰感到不便。"},{"en":"The writer fears that selfish complaints will teach citizens to ignore vulnerable people.","zh":"作者擔心自私投訴會教市民忽視弱勢人士。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"ungenerous","meaning":"不夠寬厚的；缺乏包容的","examples":[{"en":"The complaint shows an ungenerous attitude towards vulnerable people.","zh":"這個投訴顯示對弱勢人士不夠寬厚的態度。"},{"en":"Ungenerous means not kind, not understanding, or unwilling to share comfort with others.","zh":"不夠寬厚或缺乏包容，意思是不友善、不理解，或不願與他人分享便利。"},{"en":"It is ungenerous to complain about a ramp simply because you personally do not need it.","zh":"只是因為自己不需要斜道就投訴，是缺乏包容的。"},{"en":"Ungenerous attitudes make public life colder and less fair.","zh":"缺乏包容的態度令公共生活更冷漠和不公平。"},{"en":"The writer calls the complaint ungenerous because it puts personal convenience first.","zh":"作者稱這個投訴不夠寬厚，因為它把個人方便放在首位。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"civic culture","meaning":"公民文化","examples":[{"en":"A decent city needs a generous civic culture.","zh":"像樣的城市需要寬厚的公民文化。"},{"en":"Civic culture means the shared habits, values, and attitudes citizens show in public life.","zh":"公民文化，是市民在公共生活中展現的共同習慣、價值觀和態度。"},{"en":"A city has healthy civic culture when people queue, help strangers, and respect shared spaces.","zh":"當人們排隊、幫助陌生人並尊重共享空間，城市就有健康公民文化。"},{"en":"Civic culture shapes how residents react to public works and other people’s needs.","zh":"公民文化影響居民如何回應公共工程和他人的需要。"},{"en":"The writer wants a civic culture that values accessibility and patience.","zh":"作者希望有重視無障礙和耐性的公民文化。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"space is limited","meaning":"空間有限","examples":[{"en":"In Hong Kong, space is limited and everyone is in a hurry.","zh":"在香港，空間有限，而且每個人都很匆忙。"},{"en":"Space is limited means there is not much room available.","zh":"空間有限，意思是可用地方不多。"},{"en":"Space is limited in a small classroom when desks are packed closely together.","zh":"當書桌排得很密，小課室裏空間就有限。"},{"en":"When space is limited, people need more patience and better sharing rules.","zh":"當空間有限，人們需要更多耐性和更好的共享規則。"},{"en":"Hong Kong’s limited space makes accessibility planning more difficult but also more important.","zh":"香港空間有限，令無障礙規劃更困難，但也更重要。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"in a hurry","meaning":"匆忙","examples":[{"en":"Everyone in Hong Kong often seems to be in a hurry.","zh":"香港每個人常常似乎都很匆忙。"},{"en":"To be in a hurry means to be rushing because there is little time.","zh":"匆忙，意思是因時間不足而趕急。"},{"en":"Students are in a hurry when they run to class before the bell rings.","zh":"鐘聲響前學生跑去上課，就是很匆忙。"},{"en":"People in a hurry may become less patient with small delays.","zh":"匆忙的人可能對小延誤較少耐性。"},{"en":"The writer suggests that being in a hurry should not make us forget vulnerable people.","zh":"作者暗示，匆忙不應令我們忘記弱勢人士。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"be tempted to","meaning":"忍不住想","examples":[{"en":"We are often tempted to put our own convenience first.","zh":"我們常常忍不住想把自己的方便放在首位。"},{"en":"Be tempted to do something means feel a strong wish to do it, even if it may not be right.","zh":"忍不住想做某事，意思是強烈想做它，即使那未必正確。"},{"en":"A student may be tempted to skip practice when homework is heavy.","zh":"當功課很多，學生可能忍不住想逃避練習。"},{"en":"People are tempted to complain when public works disturb their routine.","zh":"當公共工程打擾日常習慣，人們會忍不住想投訴。"},{"en":"The writer warns that we are tempted to value our convenience over others’ access.","zh":"作者提醒我們，我們會忍不住想把自己的方便看得比別人的通行更重要。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"measure fairness by","meaning":"以……衡量公平","examples":[{"en":"We should not measure fairness only by our own convenience.","zh":"我們不應只以自己的方便衡量公平。"},{"en":"To measure fairness by something means to judge fairness using that standard.","zh":"以某事衡量公平，意思是用那個標準判斷是否公平。"},{"en":"A teacher should not measure fairness only by what the strongest students need.","zh":"老師不應只以最強學生的需要衡量公平。"},{"en":"Measuring fairness by convenience can ignore people facing real barriers.","zh":"以方便衡量公平，可能忽視面對真正障礙的人。"},{"en":"The writer says fairness should be measured by inclusion, not only speed.","zh":"作者說公平應以共融衡量，而不只是以速度衡量。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"our own routine","meaning":"自己的日常習慣","examples":[{"en":"People dislike it when their own routine is disturbed.","zh":"當自己的日常習慣被打擾，人們會不喜歡。"},{"en":"Our own routine means the usual pattern of daily actions we are used to.","zh":"自己的日常習慣，是我們慣常的一日行動模式。"},{"en":"A student’s routine may include taking the same bus every morning.","zh":"學生的日常習慣可能包括每天早上乘同一班巴士。"},{"en":"When our routine is disturbed, we may feel annoyed before thinking about the reason.","zh":"當日常習慣被打擾，我們可能先感到煩躁，而未思考原因。"},{"en":"The writer asks readers not to value their own routine above accessibility.","zh":"作者要求讀者不要把自己的日常習慣看得比無障礙設施更重要。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"be disturbed","meaning":"被打擾","examples":[{"en":"Public works may disturb our daily routine for a short time.","zh":"公共工程可能短時間打擾我們的日常習慣。"},{"en":"Be disturbed means be interrupted, troubled, or made less peaceful.","zh":"被打擾，意思是被中斷、煩擾或變得不再平靜。"},{"en":"Students may be disturbed by loud noise during a lesson.","zh":"學生可能在上課時被巨大噪音打擾。"},{"en":"Being disturbed is unpleasant, but some disturbance is part of improvement works.","zh":"被打擾令人不快，但某些滋擾是改善工程的一部分。"},{"en":"The writer says a disturbed routine should not become a reason to reject accessibility.","zh":"作者說日常習慣被打擾不應成為反對無障礙設施的理由。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"decent city","meaning":"像樣的城市","examples":[{"en":"A decent city cannot be built on “my convenience first.”","zh":"像樣的城市不能建基於「我的方便優先」。"},{"en":"A decent city is a fair, caring, and well-managed city where people can live with dignity.","zh":"像樣的城市，是公平、關懷並管理良好，讓人有尊嚴生活的城市。"},{"en":"A decent city protects children, elderly people, disabled people, and ordinary workers.","zh":"像樣的城市會保護兒童、長者、殘疾人士和普通工人。"},{"en":"A city is not decent if only the loudest and fastest people matter.","zh":"如果只有最大聲和行得最快的人重要，城市就不算像樣。"},{"en":"The writer believes a decent city must make room for people with different needs.","zh":"作者相信像樣的城市必須為不同需要的人留出空間。"}],"source":"2013 Q5.pdf","sourcePage":12},{"front":"be built on","meaning":"建基於","examples":[{"en":"A decent city cannot be built on selfish convenience.","zh":"像樣的城市不能建基於自私的方便。"},{"en":"Be built on means be based on or supported by a particular idea or value.","zh":"建基於，意思是以某種想法或價值作基礎或支撐。"},{"en":"A strong friendship is built on trust and respect.","zh":"穩固友誼建基於信任和尊重。"},{"en":"A fair society cannot be built on ignoring weaker people.","zh":"公平社會不能建基於忽視較弱勢的人。"},{"en":"The writer says a decent city should be built on inclusion, not selfish convenience.","zh":"作者說像樣的城市應建基於共融，而不是自私方便。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"my convenience first","meaning":"我的方便優先","examples":[{"en":"A decent city cannot be built on “my convenience first.”","zh":"像樣的城市不能建基於「我的方便優先」。"},{"en":"My convenience first means the selfish belief that one’s own ease matters more than others’ needs.","zh":"我的方便優先，意思是自私地認為自己的便利比他人的需要更重要。"},{"en":"A student shows “my convenience first” thinking if they block a doorway to save themselves time.","zh":"如果學生為了省時間而阻塞門口，就是「我的方便優先」的想法。"},{"en":"Public life becomes unfair when everyone follows “my convenience first.”","zh":"如果人人都奉行「我的方便優先」，公共生活就會變得不公平。"},{"en":"The writer rejects “my convenience first” because public space belongs to everyone.","zh":"作者拒絕「我的方便優先」，因為公共空間屬於所有人。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"with every public improvement comes","meaning":"每項公共改善都會帶來","examples":[{"en":"With every public improvement comes some disturbance.","zh":"每項公共改善都會帶來一些滋擾。"},{"en":"With every public improvement comes something means that improvement usually brings that result with it.","zh":"每項公共改善都會帶來某事，意思是改善通常伴隨某種結果。"},{"en":"With every school renovation comes some noise and dust.","zh":"每項學校翻新都會帶來一些噪音和塵埃。"},{"en":"This structure shows that benefits and inconvenience can arrive together.","zh":"這個結構顯示好處和不便可以同時出現。"},{"en":"The writer says public improvement often requires temporary disturbance.","zh":"作者說公共改善往往需要暫時滋擾。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"public improvement","meaning":"公共改善工程","examples":[{"en":"Public improvements often require patience.","zh":"公共改善工程往往需要耐性。"},{"en":"Public improvement means changes made to shared facilities or spaces to make them better.","zh":"公共改善工程，是為令共享設施或空間變得更好而作出的改動。"},{"en":"Installing safer crossings is a public improvement.","zh":"安裝更安全的過路處是一項公共改善工程。"},{"en":"Public improvements may disturb people at first but help many users later.","zh":"公共改善工程起初可能打擾人，但之後會幫助很多使用者。"},{"en":"The footbridge project is a public improvement because it makes access fairer.","zh":"行人天橋工程是公共改善工程，因為它令通行更公平。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"disturbance","meaning":"滋擾；干擾","examples":[{"en":"Road repairs and safety works bring some disturbance.","zh":"道路維修和安全工程會帶來一些滋擾。"},{"en":"Disturbance means noise, interruption, inconvenience, or disruption to normal life.","zh":"滋擾或干擾，意思是噪音、中斷、不便或對正常生活的打亂。"},{"en":"A fire drill creates temporary disturbance but teaches students safety.","zh":"火警演習造成暫時滋擾，但教導學生安全。"},{"en":"Some disturbance is acceptable when the final result protects people.","zh":"當最終結果能保護人，某些滋擾是可以接受的。"},{"en":"The writer says disturbance should be managed, not used to reject useful works.","zh":"作者說滋擾應被管理，而不是用來否定有用工程。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"road repairs","meaning":"道路維修","examples":[{"en":"Road repairs may disturb residents before they bring benefits.","zh":"道路維修在帶來好處前可能打擾居民。"},{"en":"Road repairs are works done to fix or improve roads.","zh":"道路維修，是修理或改善道路的工程。"},{"en":"Road repairs may include filling holes, repainting lines, or replacing damaged surfaces.","zh":"道路維修可能包括填補路洞、重畫道路標線或更換損壞路面。"},{"en":"Residents may dislike road repairs while they are noisy, but safer roads help everyone later.","zh":"居民可能不喜歡嘈雜的道路維修，但更安全的道路之後會幫助所有人。"},{"en":"The writer compares footbridge works to road repairs that require patience.","zh":"作者把行人天橋工程比作需要耐性的道路維修。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"drainage works","meaning":"渠務工程","examples":[{"en":"Drainage works can cause temporary inconvenience.","zh":"渠務工程可以造成暫時不便。"},{"en":"Drainage works are construction or repair works that help water flow away properly.","zh":"渠務工程，是幫助雨水或污水正常排走的建造或維修工程。"},{"en":"Drainage works can prevent flooding during heavy rain.","zh":"渠務工程可以防止大雨期間水浸。"},{"en":"People may complain about drainage works, but blocked drains can create bigger problems.","zh":"人們可能投訴渠務工程，但渠道堵塞會造成更大問題。"},{"en":"Like drainage works, accessibility works may disturb people before bringing benefits.","zh":"像渠務工程一樣，無障礙工程可能在帶來好處前打擾人們。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"barrier-free facilities","meaning":"無障礙設施","examples":[{"en":"Barrier-free facilities help people move with dignity.","zh":"無障礙設施幫助人們有尊嚴地出行。"},{"en":"Barrier-free facilities are designs such as lifts, ramps, and tactile paving that remove obstacles.","zh":"無障礙設施，是移除障礙的設計，例如升降機、斜道和觸覺引路帶。"},{"en":"A barrier-free entrance allows wheelchair users to enter without asking for help.","zh":"無障礙入口讓輪椅使用者不用求助也能進入。"},{"en":"Barrier-free facilities support independence because people can move safely by themselves.","zh":"無障礙設施支持獨立，因為人們可以自行安全移動。"},{"en":"The footbridge project adds barrier-free facilities for citizens who need them.","zh":"行人天橋工程為有需要的市民增加無障礙設施。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"school-zone safety measures","meaning":"學校區域安全措施","examples":[{"en":"School-zone safety measures protect children near schools.","zh":"學校區域安全措施保護學校附近的兒童。"},{"en":"School-zone safety measures are rules, signs, crossings, or road designs that make areas around schools safer.","zh":"學校區域安全措施，是令學校周圍更安全的規則、標誌、過路處或道路設計。"},{"en":"Speed bumps near a school are school-zone safety measures.","zh":"學校附近的減速壆是學校區域安全措施。"},{"en":"Such measures may slow drivers down, but they protect children.","zh":"這些措施可能令司機放慢速度，但它們保護兒童。"},{"en":"The writer uses school-zone safety measures as an example of public improvements that require patience.","zh":"作者用學校區域安全措施作例子，說明公共改善工程需要耐性。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"require patience","meaning":"需要耐性","examples":[{"en":"Public improvements require patience before they bring benefits.","zh":"公共改善工程在帶來好處前需要耐性。"},{"en":"Require patience means need people to wait calmly and accept some difficulty for a while.","zh":"需要耐性，意思是需要人們冷靜等待，並暫時接受一些困難。"},{"en":"Learning a musical instrument requires patience because progress is slow.","zh":"學習樂器需要耐性，因為進步是緩慢的。"},{"en":"Repair works require patience when the final result will improve safety.","zh":"當最終結果會改善安全，維修工程就需要耐性。"},{"en":"The writer asks residents to show patience while the accessibility works are completed.","zh":"作者請居民在無障礙工程完成期間表現耐性。"}],"source":"2013 Q5.pdf","sourcePage":13},{"front":"bring benefits","meaning":"帶來好處","examples":[{"en":"These works will bring benefits after the inconvenience ends.","zh":"這些工程在不便結束後會帶來好處。"},{"en":"To bring benefits means to create useful or positive results.","zh":"帶來好處，意思是創造有用或正面的結果。"},{"en":"A new library can bring benefits to students who need quiet study space.","zh":"新圖書館可以為需要安靜自修空間的學生帶來好處。"},{"en":"Some projects bring benefits only after people endure temporary disruption.","zh":"有些項目只有在人們忍受暫時干擾後才會帶來好處。"},{"en":"The footbridge works will bring benefits by giving more citizens safe access.","zh":"行人天橋工程會透過給更多市民安全通道而帶來好處。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"object whenever","meaning":"每當……便反對","examples":[{"en":"If we object whenever the gain is not ours, we ignore others’ needs.","zh":"如果每當好處不是自己的，我們便反對，我們就是忽視別人的需要。"},{"en":"Object whenever means oppose something every time a certain condition appears.","zh":"每當……便反對，意思是每次某種情況出現就反對。"},{"en":"If students object whenever a rule helps another class, cooperation becomes impossible.","zh":"如果學生每當規則幫助另一班便反對，合作就變得不可能。"},{"en":"Objecting whenever we do not benefit immediately makes public life selfish.","zh":"每當自己沒有即時受惠便反對，會令公共生活變得自私。"},{"en":"The writer warns against objecting whenever the improvement mainly helps someone else.","zh":"作者提醒我們，不要每當改善主要幫助別人便反對。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"immediate gain","meaning":"即時好處","examples":[{"en":"Some people object when the immediate gain is not theirs.","zh":"當即時好處不是自己的，有些人便反對。"},{"en":"Immediate gain means the direct benefit someone receives right away.","zh":"即時好處，意思是某人立刻得到的直接利益。"},{"en":"A student may not see an immediate gain from cleaning the classroom, but everyone benefits later.","zh":"學生未必從清潔課室中看見即時好處，但之後人人都受惠。"},{"en":"Public projects should not be judged only by immediate gain.","zh":"公共項目不應只以即時好處判斷。"},{"en":"The lift may not give every pedestrian immediate gain, but it creates fair access.","zh":"升降機未必給每個行人即時好處，但它創造公平通道。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"where does that leave…?","meaning":"那會令……處於甚麼境地？","examples":[{"en":"If we object to every inconvenience, where does that leave the disabled?","zh":"如果我們反對每一種不便，那會令殘疾人士處於甚麼境地？"},{"en":"Where does that leave…? asks what situation or problem a decision creates for someone.","zh":"那會令……處於甚麼境地？是問某個決定會為某人造成甚麼情況或問題。"},{"en":"If schools remove all quiet study rooms, where does that leave students who need silence?","zh":"如果學校取消所有安靜自修室，那會令需要安靜的學生處於甚麼境地？"},{"en":"This question pushes readers to think about people affected by a selfish choice.","zh":"這個問題迫使讀者思考自私選擇會影響哪些人。"},{"en":"The writer asks where constant objection leaves the elderly, the disabled, and the less vocal.","zh":"作者問持續反對會令長者、殘疾人士和較少發聲的人處於甚麼境地。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"the elderly","meaning":"長者","examples":[{"en":"Public space must also serve the elderly.","zh":"公共空間也必須服務長者。"},{"en":"The elderly are older people, especially those who may need more support in daily life.","zh":"長者，是年紀較大的人，特別是日常生活中可能需要更多支援的人。"},{"en":"The elderly may need benches, lifts, handrails, and safer crossings.","zh":"長者可能需要長椅、升降機、扶手和更安全的過路處。"},{"en":"A city that ignores the elderly becomes difficult for many families too.","zh":"忽視長者的城市，對很多家庭也會變得困難。"},{"en":"The writer says accessibility helps the elderly move with dignity.","zh":"作者說無障礙設施幫助長者有尊嚴地出行。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"the disabled","meaning":"殘疾人士","examples":[{"en":"Barrier-free facilities are essential for the disabled.","zh":"無障礙設施對殘疾人士是必要的。"},{"en":"The disabled refers to people with physical, sensory, or other impairments that may affect daily activities.","zh":"殘疾人士，是有身體、感官或其他障礙，可能影響日常活動的人。"},{"en":"The disabled may need ramps, lifts, tactile paving, or clear audio information.","zh":"殘疾人士可能需要斜道、升降機、觸覺引路帶或清晰聲音資訊。"},{"en":"Public spaces exclude the disabled when they are designed only for able-bodied users.","zh":"當公共空間只為身體健全使用者設計，它就排斥殘疾人士。"},{"en":"The writer argues that the disabled must not be pushed aside for other people’s convenience.","zh":"作者認為殘疾人士不應為了他人的方便而被擠走。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"the less vocal","meaning":"較少發聲的人","examples":[{"en":"The less vocal may suffer when only loud complaints are heard.","zh":"當只有大聲投訴被聽見，較少發聲的人可能受苦。"},{"en":"The less vocal are people who speak less loudly or complain less publicly.","zh":"較少發聲的人，是較少大聲說話或較少公開投訴的人。"},{"en":"Elderly residents may be among the less vocal if they do not attend public meetings.","zh":"如果年長居民不參加公眾會議，他們可能屬於較少發聲的人。"},{"en":"The less vocal can be ignored when decisions follow only the loudest voices.","zh":"當決定只跟隨最大聲的人，較少發聲的人可能被忽視。"},{"en":"A fair city listens to the less vocal as well as the loudest pedestrians.","zh":"公平城市會聆聽較少發聲的人，也會聆聽最大聲的行人。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"few, if any","meaning":"即使有，也少之又少","examples":[{"en":"Few, if any, of us would want such an unfair city.","zh":"即使有，也少之又少人會想要如此不公平的城市。"},{"en":"Few, if any, means almost none, and possibly none at all.","zh":"即使有，也少之又少，意思是幾乎沒有，甚至可能完全沒有。"},{"en":"Few, if any, students want a school where only loud voices matter.","zh":"即使有，也少之又少學生想要一所只有大聲者重要的學校。"},{"en":"This phrase makes a strong point without sounding completely absolute.","zh":"這個短語提出強烈觀點，但不顯得完全絕對。"},{"en":"The writer believes almost nobody truly wants a city where vulnerable people lose.","zh":"作者相信幾乎沒有人真正想要一個弱勢人士總是輸的城市。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"live in a city where","meaning":"生活在一個……的城市","examples":[{"en":"Few of us would want to live in a city where the loudest people always win.","zh":"很少人會想生活在一個最大聲的人總是勝出的城市。"},{"en":"Live in a city where means have daily life in a place with that kind of condition or rule.","zh":"生活在一個……的城市，意思是在具有某種情況或規則的地方過日常生活。"},{"en":"Nobody wants to live in a city where pavements are unsafe for children.","zh":"沒有人想生活在一個行人路對兒童不安全的城市。"},{"en":"This phrase helps readers imagine the real result of a public attitude.","zh":"這個短語幫助讀者想像某種公共態度的真實結果。"},{"en":"The writer warns against living in a city where noise matters more than need.","zh":"作者警告不要生活在一個聲量比需要更重要的城市。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"the loudest pedestrians","meaning":"最大聲的行人","examples":[{"en":"The loudest pedestrians should not always decide public policy.","zh":"最大聲的行人不應總是決定公共政策。"},{"en":"The loudest pedestrians are walkers who complain most strongly or visibly.","zh":"最大聲的行人，是最強烈或最明顯投訴的步行者。"},{"en":"The loudest pedestrians may not represent those who struggle quietly.","zh":"最大聲的行人未必代表默默掙扎的人。"},{"en":"Public policy becomes unfair if only loud complaints are counted.","zh":"如果公共政策只計算大聲投訴，就會變得不公平。"},{"en":"The writer says the loudest pedestrians should not outrank vulnerable users.","zh":"作者說最大聲的行人不應凌駕弱勢使用者。"}],"source":"2013 Q5.pdf","sourcePage":14},{"front":"outrank","meaning":"凌駕於","examples":[{"en":"The loudest pedestrians should not outrank the most vulnerable ones.","zh":"最大聲的行人不應凌駕於最弱勢的人。"},{"en":"To outrank someone means to be treated as more important or more powerful than them.","zh":"凌駕於某人，意思是被視為比他們更重要或更有權力。"},{"en":"In a fair classroom, confident students should not outrank quiet students in attention.","zh":"在公平課室中，自信學生不應在關注上凌駕於安靜學生。"},{"en":"Public design is unfair if convenience outranks basic access.","zh":"如果方便凌駕於基本通行，公共設計就是不公平的。"},{"en":"The writer argues that loud complaints should not outrank vulnerable people’s needs.","zh":"作者認為大聲投訴不應凌駕於弱勢人士的需要。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"vulnerable ones","meaning":"弱勢人士","examples":[{"en":"The most vulnerable ones deserve protection in public space.","zh":"最弱勢的人值得在公共空間中受到保護。"},{"en":"Vulnerable ones are people who are more likely to be harmed, excluded, or ignored.","zh":"弱勢人士，是較容易受傷害、被排斥或被忽視的人。"},{"en":"Elderly residents and wheelchair users may be vulnerable ones in badly designed streets.","zh":"在設計差劣的街道中，年長居民和輪椅使用者可能是弱勢人士。"},{"en":"Vulnerable people need protection because ordinary barriers affect them more deeply.","zh":"弱勢人士需要保護，因為普通障礙對他們影響更深。"},{"en":"Public planning should start by asking how the vulnerable ones will use the space.","zh":"公共規劃應先問弱勢人士會如何使用空間。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"urge residents to","meaning":"敦促居民去","examples":[{"en":"I urge residents to direct their frustration at practical problems.","zh":"我敦促居民把不滿指向實際問題。"},{"en":"To urge residents to do something means to strongly encourage local people to take a particular action.","zh":"敦促居民去做某事，意思是強烈鼓勵本區人士採取某個行動。"},{"en":"A principal may urge students to report safety problems calmly.","zh":"校長可能敦促學生冷靜匯報安全問題。"},{"en":"Urging people can be polite but firm when the issue is important.","zh":"當議題重要時，敦促可以既禮貌又堅定。"},{"en":"The writer urges residents to complain about poor arrangements, not accessibility itself.","zh":"作者敦促居民投訴欠佳安排，而不是無障礙設施本身。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"direct frustration at","meaning":"將不滿指向","examples":[{"en":"Residents should direct their frustration at practical shortcomings.","zh":"居民應將不滿指向實際不足之處。"},{"en":"To direct frustration at something means to aim one’s anger or dissatisfaction at the real problem.","zh":"將不滿指向某事，意思是把憤怒或不滿對準真正問題。"},{"en":"Students should direct frustration at unclear instructions, not at classmates.","zh":"學生應把不滿指向不清晰指示，而不是同學。"},{"en":"Directing frustration correctly helps solve problems instead of creating unfair blame.","zh":"正確將不滿指向問題，有助解決問題，而不是造成不公平責怪。"},{"en":"The writer asks residents to direct frustration at management issues, not at disabled users’ needs.","zh":"作者要求居民把不滿指向管理問題，而不是殘疾使用者的需要。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"practical shortcomings","meaning":"實際不足之處","examples":[{"en":"Residents may criticise practical shortcomings in the temporary route.","zh":"居民可以批評臨時路線中的實際不足之處。"},{"en":"Practical shortcomings are real, specific weaknesses in how something is arranged or carried out.","zh":"實際不足之處，是某事安排或執行上的真實、具體弱點。"},{"en":"A temporary route without clear signs has practical shortcomings.","zh":"沒有清晰標誌的臨時路線有實際不足之處。"},{"en":"Practical shortcomings should be fixed because they affect safety and convenience.","zh":"實際不足之處應被修正，因為它們影響安全和方便。"},{"en":"The writer accepts criticism of practical shortcomings but rejects attacks on accessibility.","zh":"作者接受對實際不足之處的批評，但反對攻擊無障礙設施。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"the principle of accessibility","meaning":"無障礙原則","examples":[{"en":"Residents should not attack the principle of accessibility.","zh":"居民不應攻擊無障礙原則。"},{"en":"The principle of accessibility is the belief that public places should be usable by people with different needs.","zh":"無障礙原則，是相信公共地方應讓有不同需要的人都能使用。"},{"en":"A school follows the principle of accessibility when it provides ramps and clear signs.","zh":"當學校提供斜道和清晰標誌，就是遵守無障礙原則。"},{"en":"Criticising poor management is different from rejecting the principle of accessibility.","zh":"批評管理欠佳不同於否定無障礙原則。"},{"en":"The writer defends the principle of accessibility because it protects dignity and inclusion.","zh":"作者捍衛無障礙原則，因為它保護尊嚴和共融。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"District Office","meaning":"民政事務處","examples":[{"en":"The District Office should communicate clearly.","zh":"民政事務處應清楚溝通。"},{"en":"The District Office is a local government office that deals with district matters and residents’ concerns.","zh":"民政事務處，是處理地區事務和居民關注的地方政府辦事處。"},{"en":"Residents may contact the District Office about traffic, community facilities, or public works.","zh":"居民可能就交通、社區設施或公共工程聯絡民政事務處。"},{"en":"A District Office should explain changes before they affect daily routines.","zh":"民政事務處應在變動影響日常習慣前作出解釋。"},{"en":"The writer wants the District Office to help residents understand the footbridge works.","zh":"作者希望民政事務處幫助居民理解行人天橋工程。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"communicate clearly","meaning":"清楚溝通","examples":[{"en":"The District Office should communicate clearly with residents.","zh":"民政事務處應與居民清楚溝通。"},{"en":"To communicate clearly means to give information in a way people can easily understand.","zh":"清楚溝通，意思是以人們容易理解的方式提供資訊。"},{"en":"A school communicates clearly when it tells parents the date, time, and place of an event.","zh":"學校告訴家長活動日期、時間和地點時，就是清楚溝通。"},{"en":"Clear communication reduces rumours, confusion, and unnecessary anger.","zh":"清楚溝通可以減少謠言、混亂和不必要憤怒。"},{"en":"The District Office should communicate clearly about routes, dates, and reasons for the works.","zh":"民政事務處應就路線、日期和工程原因清楚溝通。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"complete the works responsibly","meaning":"負責任地完成工程","examples":[{"en":"The government should complete the works responsibly.","zh":"政府應負責任地完成工程。"},{"en":"To complete the works responsibly means to finish the project with care for safety, time, communication, and public needs.","zh":"負責任地完成工程，意思是顧及安全、時間、溝通和公眾需要來完成項目。"},{"en":"A school should complete repairs responsibly by warning students about blocked areas.","zh":"學校應透過提醒學生哪些地方被阻塞來負責任地完成維修。"},{"en":"Responsible completion reduces inconvenience while keeping the project’s purpose.","zh":"負責任完成工程可以減少不便，同時保留工程目的。"},{"en":"The writer supports completing the works responsibly rather than cancelling them.","zh":"作者支持負責任地完成工程，而不是取消它。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, citizens should give the project room to succeed.","zh":"與此同時，市民應給予工程成功的空間。"},{"en":"Meanwhile means at the same time or while another action is happening.","zh":"與此同時，意思是在同一時間，或在另一行動發生期間。"},{"en":"The school can repair the hall; meanwhile, students can use another room.","zh":"學校可以維修禮堂；與此同時，學生可以使用另一間房。"},{"en":"Writers use meanwhile to show what another group should do at the same time.","zh":"作者使用「與此同時」來顯示另一群人同時應做甚麼。"},{"en":"The authorities should improve management; meanwhile, citizens should show patience.","zh":"當局應改善管理；與此同時，市民應表現耐性。"}],"source":"2013 Q5.pdf","sourcePage":15},{"front":"give the project room to succeed","meaning":"給予工程成功的空間","examples":[{"en":"Citizens should give the project room to succeed.","zh":"市民應給予工程成功的空間。"},{"en":"To give the project room to succeed means to allow enough time, patience, and support for it to work.","zh":"給予工程成功的空間，意思是給它足夠時間、耐性和支持，使它能發揮作用。"},{"en":"A new school rule needs room to succeed before people judge it too quickly.","zh":"新校規需要成功的空間，人們不應太快判斷。"},{"en":"Projects fail when people reject them before they are completed.","zh":"如果人們在工程完成前已拒絕它，工程就容易失敗。"},{"en":"The writer asks citizens to give the accessibility project a fair chance.","zh":"作者請市民給無障礙工程一個公平機會。"}],"source":"2013 Q5.pdf","sourcePage":16},{"front":"not just about speed","meaning":"不只是講求速度","examples":[{"en":"A city is not just about speed.","zh":"一座城市不只是講求速度。"},{"en":"Not just about speed means efficiency is not the only value that matters.","zh":"不只是講求速度，意思是效率不是唯一重要價值。"},{"en":"School life is not just about marks; it is also about growth and care.","zh":"校園生活不只是講求分數；也關乎成長和關心。"},{"en":"A city focused only on speed may forget those who move slowly.","zh":"只重視速度的城市，可能忘記行動較慢的人。"},{"en":"The writer says a city should also care about dignity, safety, and access.","zh":"作者說城市也應關心尊嚴、安全和通行。"}],"source":"2013 Q5.pdf","sourcePage":16},{"front":"move through it with dignity","meaning":"有尊嚴地在其中出行","examples":[{"en":"Different people should be able to move through the city with dignity.","zh":"不同的人應能有尊嚴地在城市中出行。"},{"en":"To move through it with dignity means to travel through a place independently, safely, and without humiliation.","zh":"有尊嚴地在其中出行，意思是能獨立、安全並不受羞辱地穿過某地。"},{"en":"A wheelchair user moves with dignity when they can enter a station without begging for help.","zh":"當輪椅使用者不用求助也能進入車站，就是有尊嚴地出行。"},{"en":"Dignified movement requires public spaces that do not shame people for needing support.","zh":"有尊嚴的出行需要公共空間不因人需要支援而令其難堪。"},{"en":"Accessibility helps citizens move through the city with dignity.","zh":"無障礙設施幫助市民有尊嚴地在城市中出行。"}],"source":"2013 Q5.pdf","sourcePage":16},{"front":"dignity","meaning":"尊嚴","examples":[{"en":"Accessibility allows people to move with dignity.","zh":"無障礙設施讓人有尊嚴地出行。"},{"en":"Dignity means being treated with respect and allowed to keep self-worth.","zh":"尊嚴，意思是受到尊重並能保持自我價值。"},{"en":"A patient has dignity when they can enter a clinic without being carried by strangers.","zh":"當病人不用被陌生人抬起也能進入診所，他就有尊嚴。"},{"en":"Public design protects dignity when it allows people to do ordinary things independently.","zh":"當公共設計讓人獨立完成普通事情，它就保護尊嚴。"},{"en":"The lift protects dignity by giving users a safe and normal way to cross.","zh":"升降機透過提供安全而正常的過橋方式來保護尊嚴。"}],"source":"2013 Q5.pdf","sourcePage":16},{"front":"soon be forgotten","meaning":"很快被忘記","examples":[{"en":"A short detour will soon be forgotten.","zh":"短暫繞路很快會被忘記。"},{"en":"Soon be forgotten means people will stop remembering or caring about it after a short time.","zh":"很快被忘記，意思是人們不久後就不再記得或在意它。"},{"en":"A small delay before a school concert may soon be forgotten once the show begins.","zh":"學校音樂會前的小延誤，演出開始後可能很快被忘記。"},{"en":"Temporary inconvenience is often forgotten when the long-term benefit remains.","zh":"當長遠好處留下來，暫時不便常會被忘記。"},{"en":"The writer says the detour will soon be forgotten, but the lift will keep helping people.","zh":"作者說繞路很快會被忘記，但升降機會繼續幫助人。"}],"source":"2013 Q5.pdf","sourcePage":16},{"front":"restore someone’s independence","meaning":"恢復某人的獨立能力","examples":[{"en":"A lift can restore someone’s independence.","zh":"升降機可以恢復某人的獨立能力。"},{"en":"To restore someone’s independence means to give back their ability to do things without relying on others.","zh":"恢復某人的獨立能力，意思是讓他重新能夠不依賴別人完成事情。"},{"en":"A ramp can restore independence to a person who cannot climb stairs.","zh":"斜道可以恢復不能爬樓梯人士的獨立能力。"},{"en":"Independence matters because people should not need help for every ordinary journey.","zh":"獨立能力重要，因為人們不應每次普通出行都需要求助。"},{"en":"The new lift may restore independence to residents who have avoided the footbridge.","zh":"新升降機可能恢復一直避開天橋居民的獨立能力。"}],"source":"2013 Q5.pdf","sourcePage":16},{"front":"change a life","meaning":"改變一生","examples":[{"en":"A lift that restores independence may change a life.","zh":"一部恢復獨立能力的升降機可能改變一生。"},{"en":"To change a life means to make a deep and lasting difference to someone’s daily experience.","zh":"改變一生，意思是對某人的日常經驗造成深遠而持久的改變。"},{"en":"A hearing aid can change a life by helping someone join conversations again.","zh":"助聽器可以幫助某人重新參與對話，從而改變一生。"},{"en":"Small public facilities can change lives when they remove daily barriers.","zh":"當小型公共設施移除日常障礙，它們可以改變人生。"},{"en":"The lift may change a life by making medical visits, shopping, and travel easier.","zh":"升降機可能透過令覆診、購物和出行更容易而改變一生。"}],"source":"2013 Q5.pdf","sourcePage":16},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"The letter ends with “Yours faithfully.”","zh":"這封信以「Yours faithfully」結束。"},{"en":"Yours faithfully is a formal closing used at the end of a letter, especially when writing formally to someone not personally known.","zh":"「Yours faithfully」是正式書信結尾用語，特別用於正式寫給不熟悉的人。"},{"en":"A reader may end a formal letter to an editor with “Yours faithfully.”","zh":"讀者可能以「Yours faithfully」結束寫給編輯的正式信件。"},{"en":"This closing keeps the tone polite and serious.","zh":"這個結尾保持禮貌和嚴肅語氣。"},{"en":"“Yours faithfully” fits this letter because it is a formal public response.","zh":"「Yours faithfully」適合這封信，因為它是一封正式的公開回應。"}],"source":"2013 Q5.pdf","sourcePage":16}],"dse/writing/part-b/2013/Q6":[{"front":"leaving late","meaning":"遲下班","examples":[{"en":"Leaving late should not become normal in the workplace.","zh":"遲下班不應成為工作場所的常態。"},{"en":"Leaving late means staying at work after the usual finishing time.","zh":"遲下班意思是在正常下班時間後仍留在工作場所。"},{"en":"An employee may be leaving late if they are still typing reports at 8 p.m.","zh":"如果員工晚上八點仍在撰寫報告，就是在遲下班。"},{"en":"Leaving late too often can reduce sleep, family time, and concentration.","zh":"太常遲下班會減少睡眠、家庭時間和專注力。"},{"en":"A healthy workplace treats leaving late as a warning sign, not a badge of loyalty.","zh":"健康的工作場所會把遲下班視為警號，而不是忠誠的標誌。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"become our normal","meaning":"成為我們的常態","examples":[{"en":"Overtime should not become our normal.","zh":"加班不應成為我們的常態。"},{"en":"To become our normal means to turn into something people accept as usual.","zh":"成為我們的常態意思是變成人們接受為平常的事情。"},{"en":"Replying to emails at midnight should not become our normal.","zh":"凌晨回覆電郵不應成為我們的常態。"},{"en":"When unhealthy habits become normal, people may stop questioning them.","zh":"當不健康習慣成為常態，人們可能不再質疑它們。"},{"en":"A company should act early before late departures become everyone’s normal.","zh":"公司應及早行動，避免遲下班成為所有人的常態。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"wind down","meaning":"逐漸安靜下來；準備收工","examples":[{"en":"At 7:30 in the evening, the office should be winding down.","zh":"晚上七點半，辦公室應該逐漸安靜下來、準備收工。"},{"en":"To wind down means to become quieter and prepare to stop working.","zh":"逐漸安靜下來或準備收工意思是變得較安靜，並準備停止工作。"},{"en":"A school winds down after the last lesson when students pack their bags.","zh":"最後一課後，學生收拾書包時，學校便逐漸安靜下來。"},{"en":"An office that never winds down may make staff feel constantly under pressure.","zh":"如果辦公室從不準備收工，員工可能會感到長期受壓。"},{"en":"Winding down at the end of the day helps workers leave calmly.","zh":"一天結束時逐漸收工，有助員工平靜地離開。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"rows of computer screens","meaning":"一排排電腦屏幕","examples":[{"en":"Rows of computer screens were still glowing in the office.","zh":"辦公室裏一排排電腦屏幕仍然亮著。"},{"en":"Rows of computer screens means many screens arranged in lines across desks.","zh":"一排排電腦屏幕是指許多屏幕整齊排列在辦公桌上。"},{"en":"Rows of computer screens can make an office look busy even late at night.","zh":"一排排電腦屏幕會令辦公室即使深夜仍看起來忙碌。"},{"en":"If screens are still glowing after hours, staff may still be working.","zh":"如果辦公時間後屏幕仍然亮著，員工可能仍在工作。"},{"en":"This image shows overtime as something visible across the whole office.","zh":"這個意象把加班變成整個辦公室都看得見的情況。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"still be glowing","meaning":"仍然亮著","examples":[{"en":"The computer screens were still glowing late in the evening.","zh":"深夜時，電腦屏幕仍然亮著。"},{"en":"Still be glowing means continuing to give off light after people would expect work to stop.","zh":"仍然亮著意思是在本應停止工作後仍繼續發光。"},{"en":"A classroom screen may still be glowing after a long online meeting.","zh":"長時間網上會議後，課室屏幕可能仍然亮著。"},{"en":"Glowing screens late at night can suggest unfinished work and tired staff.","zh":"深夜仍然亮著的屏幕可以暗示未完成工作和疲倦員工。"},{"en":"The phrase makes overtime feel quiet, cold, and visible.","zh":"這個短語令加班感覺安靜、冰冷而清楚可見。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"type reports","meaning":"撰寫報告","examples":[{"en":"Colleagues were typing reports after office hours.","zh":"同事在辦公時間後仍在撰寫報告。"},{"en":"To type reports means to write formal work documents on a computer.","zh":"撰寫報告意思是在電腦上寫正式工作文件。"},{"en":"A human resources assistant may type reports about staff attendance.","zh":"人力資源助理可能撰寫有關員工出勤的報告。"},{"en":"Typing reports late at night can increase the chance of mistakes.","zh":"深夜撰寫報告可能增加犯錯機會。"},{"en":"Reports should be planned early so staff do not always type them after hours.","zh":"報告應及早規劃，讓員工不用總在下班後撰寫。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"answer emails","meaning":"回覆電郵","examples":[{"en":"Some colleagues were answering emails late in the evening.","zh":"有些同事深夜仍在回覆電郵。"},{"en":"To answer emails means to read and reply to electronic messages.","zh":"回覆電郵意思是閱讀並回應電子郵件。"},{"en":"A manager may answer emails from clients after a meeting.","zh":"經理可能在會議後回覆客戶電郵。"},{"en":"Answering emails late every night can blur the line between work and rest.","zh":"每晚深夜回覆電郵會模糊工作和休息之間的界線。"},{"en":"Non-urgent emails should usually wait until office hours.","zh":"非緊急電郵通常應等到辦公時間才回覆。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"make one last change to","meaning":"對……作最後一次修改","examples":[{"en":"A colleague was making one last change to a proposal.","zh":"一位同事正在對一份建議書作最後一次修改。"},{"en":"To make one last change to something means to adjust it once more before finishing.","zh":"對某物作最後一次修改，意思是在完成前再調整一次。"},{"en":"A designer may make one last change to a poster before sending it.","zh":"設計師可能在寄出海報前作最後一次修改。"},{"en":"“One last change” can easily become many changes if deadlines are unclear.","zh":"如果截止時間不清晰，「最後一次修改」很容易變成多次修改。"},{"en":"Teams should manage revisions so one last change does not always delay leaving.","zh":"團隊應管理修改流程，避免最後一次修改總是延誤下班。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"human resources assistant","meaning":"人力資源助理","examples":[{"en":"The writer works as a human resources assistant.","zh":"作者任職人力資源助理。"},{"en":"A human resources assistant helps with staff records, hiring, leave, training, or workplace policies.","zh":"人力資源助理協助處理員工紀錄、招聘、假期、培訓或工作場所政策。"},{"en":"A human resources assistant may notice patterns in overtime and staff well-being.","zh":"人力資源助理可能注意到加班和員工身心健康的模式。"},{"en":"This role gives the writer a reason to care about working arrangements.","zh":"這個職位令作者有理由關心工作安排。"},{"en":"A human resources assistant can help management understand employee concerns.","zh":"人力資源助理可以幫助管理層理解員工憂慮。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"this observation should concern all of us","meaning":"這個觀察應該令我們所有人關注","examples":[{"en":"This observation should concern all of us in the company.","zh":"這個觀察應該令公司裏的我們所有人關注。"},{"en":"This observation should concern all of us means everyone should pay attention to what has been noticed.","zh":"這個觀察應該令我們所有人關注，意思是每個人都應留意被觀察到的情況。"},{"en":"If many staff leave after 8 p.m., this observation should concern all managers.","zh":"如果許多員工晚上八點後才離開，這個觀察應令所有經理關注。"},{"en":"A workplace problem affects more than the people who stay late.","zh":"工作場所問題影響的不只是遲下班的人。"},{"en":"Shared concern is the first step toward better working arrangements.","zh":"共同關注是改善工作安排的第一步。"}],"source":"2013 Q6.pdf","sourcePage":1},{"front":"prompt management to consider","meaning":"促使管理層考慮","examples":[{"en":"The situation prompted management to consider better working arrangements.","zh":"這個情況促使管理層考慮更好的工作安排。"},{"en":"To prompt management to consider something means to make leaders start thinking seriously about it.","zh":"促使管理層考慮某事，意思是令領導層開始認真思考它。"},{"en":"Rising staff complaints may prompt management to consider clearer overtime rules.","zh":"員工投訴增加可能促使管理層考慮更清晰的加班規則。"},{"en":"A visible problem often pushes managers to review existing habits.","zh":"明顯問題常會推動經理檢討現有習慣。"},{"en":"The aim is to move from noticing the problem to changing policy.","zh":"目標是由注意問題走向改變政策。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"improve our working arrangements","meaning":"改善我們的工作安排","examples":[{"en":"The company should improve its working arrangements.","zh":"公司應改善我們的工作安排。"},{"en":"To improve working arrangements means to make schedules, workloads, and communication healthier and clearer.","zh":"改善工作安排意思是令時間表、工作量和溝通更健康、更清晰。"},{"en":"A company improves working arrangements when it sets realistic deadlines.","zh":"公司設定現實的截止日期時，就是改善工作安排。"},{"en":"Better arrangements can reduce unnecessary overtime and stress.","zh":"更好的安排可以減少不必要加班和壓力。"},{"en":"Improving work arrangements helps both employees and business performance.","zh":"改善工作安排對員工和業務表現都有幫助。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"remain efficient","meaning":"保持效率","examples":[{"en":"Staff should remain efficient without sacrificing their health.","zh":"員工應在不犧牲健康的情況下保持效率。"},{"en":"To remain efficient means to continue working well without wasting time or energy.","zh":"保持效率意思是繼續有效工作，而不浪費時間或精力。"},{"en":"A team remains efficient when tasks are prioritised clearly.","zh":"當任務優先次序清楚時，團隊能保持效率。"},{"en":"Efficiency should not depend on people staying late every night.","zh":"效率不應依賴員工每晚遲下班。"},{"en":"Healthy rest helps employees remain efficient the next day.","zh":"健康休息有助員工翌日保持效率。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"without sacrificing","meaning":"不犧牲……","examples":[{"en":"Employees should work efficiently without sacrificing family life.","zh":"員工應有效工作，而不犧牲家庭生活。"},{"en":"Without sacrificing something means without giving it up or damaging it.","zh":"不犧牲某事意思是不放棄或損害它。"},{"en":"Students should study hard without sacrificing sleep completely.","zh":"學生應努力讀書，而不是完全犧牲睡眠。"},{"en":"A good company achieves results without sacrificing staff well-being.","zh":"好公司能達成成果，同時不犧牲員工身心健康。"},{"en":"Sustainable success means high performance without sacrificing health.","zh":"可持續成功意味著高表現而不犧牲健康。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"health, family life and judgement","meaning":"健康、家庭生活和判斷力","examples":[{"en":"Excessive overtime can harm health, family life and judgement.","zh":"過度加班會損害健康、家庭生活和判斷力。"},{"en":"Health, family life and judgement refer to physical well-being, relationships at home, and decision-making ability.","zh":"健康、家庭生活和判斷力是指身體狀況、家中關係和作決定的能力。"},{"en":"A tired worker may sleep badly, miss dinner with family, and make poor choices.","zh":"疲倦員工可能睡不好、錯過家庭晚飯，並作出差劣判斷。"},{"en":"These three areas matter because work affects the whole person.","zh":"這三方面很重要，因為工作影響整個人。"},{"en":"Protecting health, family life and judgement makes a workplace more sustainable.","zh":"保護健康、家庭生活和判斷力，能令工作場所更可持續。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"overtime","meaning":"加班","examples":[{"en":"Overtime may occasionally be necessary.","zh":"加班偶爾可能是必要的。"},{"en":"Overtime means working beyond normal working hours.","zh":"加班意思是在正常工作時間以外工作。"},{"en":"Employees may do overtime when a deadline or client emergency is unavoidable.","zh":"當期限或客戶緊急情況無法避免時，員工可能要加班。"},{"en":"Occasional overtime is different from a repeated overtime culture.","zh":"偶爾加班與重複出現的加班文化不同。"},{"en":"Overtime should be recorded and managed instead of hidden.","zh":"加班應被記錄和管理，而不是被隱藏。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"occasionally be necessary","meaning":"偶爾是必要的","examples":[{"en":"Overtime may occasionally be necessary during urgent projects.","zh":"在緊急項目期間，加班偶爾是必要的。"},{"en":"Occasionally be necessary means needed sometimes, but not all the time.","zh":"偶爾是必要的意思是有時需要，但不是經常需要。"},{"en":"Staying late may occasionally be necessary when a system suddenly fails.","zh":"當系統突然故障時，遲下班偶爾是必要的。"},{"en":"If something is necessary every day, it is no longer occasional.","zh":"如果某事每天都必要，它就不再是偶爾。"},{"en":"Companies should distinguish occasional necessity from poor planning.","zh":"公司應區分偶爾的必要和規劃不善。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"urgent client projects","meaning":"緊急客戶項目","examples":[{"en":"Staff may need to work late during urgent client projects.","zh":"員工可能需要在緊急客戶項目期間遲下班。"},{"en":"Urgent client projects are customer-related tasks that must be completed quickly.","zh":"緊急客戶項目是必須快速完成、與客戶相關的任務。"},{"en":"A client may need a proposal by the next morning because of a sudden meeting.","zh":"客戶可能因突然會議而需要翌日早上的建議書。"},{"en":"Urgent projects can justify temporary overtime, but not constant late nights.","zh":"緊急項目可以解釋短暫加班，但不能解釋長期深夜工作。"},{"en":"Managers should plan support when urgent client projects arise.","zh":"當緊急客戶項目出現時，經理應規劃支援。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"invisible routine","meaning":"無形的慣例","examples":[{"en":"Overtime should not become an invisible routine.","zh":"加班不應成為無形的慣例。"},{"en":"An invisible routine is a repeated habit that people follow without openly discussing it.","zh":"無形的慣例是人們反覆遵從但沒有公開討論的習慣。"},{"en":"If everyone stays late quietly, overtime becomes an invisible routine.","zh":"如果每個人都默默遲下班，加班就會成為無形的慣例。"},{"en":"Invisible routines are dangerous because people stop questioning them.","zh":"無形慣例很危險，因為人們會停止質疑它們。"},{"en":"Naming the routine is the first step to changing it.","zh":"說出這個慣例，是改變它的第一步。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"be caused by laziness","meaning":"由懶惰造成","examples":[{"en":"The overtime problem is not caused by laziness.","zh":"加班問題不是由懶惰造成的。"},{"en":"Be caused by laziness means happen because people are unwilling to work hard.","zh":"由懶惰造成意思是因人不願努力工作而發生。"},{"en":"Late work may be caused by unclear deadlines, not laziness.","zh":"遲下班可能由截止時間不清造成，而不是由懶惰造成。"},{"en":"Blaming laziness can hide deeper problems in planning and staffing.","zh":"責怪懶惰可能掩蓋規劃和人手方面更深層問題。"},{"en":"A fair analysis looks at systems, not only personal effort.","zh":"公平分析會看制度，而不只看個人努力。"}],"source":"2013 Q6.pdf","sourcePage":2},{"front":"be treated as","meaning":"被視為","examples":[{"en":"The situation should not be treated as a simple personal choice.","zh":"這個情況不應被視為簡單的個人選擇。"},{"en":"To be treated as something means to be regarded or handled in that way.","zh":"被視為某事意思是被當作那樣東西來看待或處理。"},{"en":"Repeated overtime should be treated as a management issue, not only a worker’s habit.","zh":"重複加班應被視為管理問題，而不只是員工習慣。"},{"en":"If stress is treated as weakness, employees may hide problems.","zh":"如果壓力被視為軟弱，員工可能會隱藏問題。"},{"en":"How a problem is treated affects whether it can be solved.","zh":"一個問題如何被看待，會影響它能否被解決。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"a simple matter of personal choice","meaning":"簡單的個人選擇問題","examples":[{"en":"Working late is not always a simple matter of personal choice.","zh":"遲下班不一定是簡單的個人選擇問題。"},{"en":"A simple matter of personal choice means something depends only on what one person wants.","zh":"簡單的個人選擇問題意思是某事只取決於個人想法。"},{"en":"Leaving late may look like personal choice, but team pressure can shape it.","zh":"遲下班看似個人選擇，但團隊壓力也會塑造它。"},{"en":"If deadlines arrive at 5 p.m., staying late is not truly voluntary.","zh":"如果截止任務在下午五時才到來，遲下班就不是真正自願。"},{"en":"The phrase helps show that overtime often has structural causes.","zh":"這個短語幫助顯示加班常有結構性原因。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"arrive late in the afternoon","meaning":"在下午較遲時間才到來","examples":[{"en":"Many tasks arrive late in the afternoon.","zh":"許多任務在下午較遲時間才到來。"},{"en":"To arrive late in the afternoon means to come near the end of the workday.","zh":"在下午較遲時間才到來，意思是接近工作日結束時才出現。"},{"en":"A manager may send a task at 5:15 p.m., leaving little time to finish it.","zh":"經理可能在下午五點十五分派任務，令員工幾乎沒有時間完成。"},{"en":"Late-arriving tasks often push employees beyond office hours.","zh":"較遲才到來的任務常把員工推到辦公時間以外。"},{"en":"Teams should clarify whether afternoon tasks truly need same-day completion.","zh":"團隊應澄清下午才來的任務是否真的需要即日完成。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"occupy the most productive hours","meaning":"佔據最高效的工作時段","examples":[{"en":"Meetings often occupy the most productive hours.","zh":"會議常佔據最高效的工作時段。"},{"en":"To occupy the most productive hours means to take up the time when people work best.","zh":"佔據最高效的工作時段意思是用掉人們工作狀態最好的時間。"},{"en":"Long morning meetings may occupy the hours when staff are most focused.","zh":"漫長早會可能佔據員工最專注的時間。"},{"en":"If meetings take the best hours, real work may be pushed into the evening.","zh":"如果會議佔去最好時段，真正工作可能被推到晚上。"},{"en":"Better scheduling protects productive time and reduces overtime.","zh":"更好排程能保護高效時間並減少加班。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"deadlines are unclear","meaning":"截止時間不清晰","examples":[{"en":"Deadlines are sometimes unclear until the day is almost over.","zh":"截止時間有時直到一天快要結束時才清晰。"},{"en":"Deadlines are unclear means people do not know exactly when work must be finished.","zh":"截止時間不清晰意思是人們不知道工作準確需要何時完成。"},{"en":"A task becomes stressful when the deadline is only explained at the last minute.","zh":"如果最後一刻才解釋截止時間，任務會變得有壓力。"},{"en":"Unclear deadlines make employees unsure whether they can leave on time.","zh":"不清晰的截止時間令員工不知道能否準時下班。"},{"en":"Clear deadlines help teams plan work and rest more fairly.","zh":"清晰截止時間幫助團隊更公平地規劃工作和休息。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"until the day is almost over","meaning":"直到一天快要結束時","examples":[{"en":"Some deadlines remain unclear until the day is almost over.","zh":"有些截止時間直到一天快要結束時仍不清晰。"},{"en":"Until the day is almost over means until the workday is nearly finished.","zh":"直到一天快要結束時，意思是直到工作日差不多完成時。"},{"en":"If instructions arrive only when the day is almost over, staff may have to stay late.","zh":"如果指示到一天快要結束時才出現，員工可能要遲下班。"},{"en":"Late clarity creates avoidable pressure and rushed decisions.","zh":"太遲才清楚會製造可避免的壓力和倉促決定。"},{"en":"Managers should clarify priorities before the day is almost over.","zh":"經理應在一天快要結束前澄清優先次序。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"month-end reporting","meaning":"月結報告","examples":[{"en":"Staying late may be understandable during month-end reporting.","zh":"在月結報告期間遲下班或許可以理解。"},{"en":"Month-end reporting is the process of preparing business or financial reports at the end of a month.","zh":"月結報告是在月尾準備業務或財務報告的過程。"},{"en":"Finance teams may be busier during month-end reporting because figures must be checked.","zh":"財務團隊在月結報告期間可能更忙，因為數字必須核對。"},{"en":"Temporary overtime may happen when reports are legally or commercially urgent.","zh":"當報告在法律或商業上緊急時，短暫加班可能會出現。"},{"en":"Even month-end reporting should be planned so overtime does not become excessive.","zh":"即使是月結報告，也應妥善規劃，避免過度加班。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"product launches","meaning":"產品發布","examples":[{"en":"Employees may work late during product launches.","zh":"員工可能在產品發布期間遲下班。"},{"en":"Product launches are events or periods when a company introduces new products to customers.","zh":"產品發布是公司向顧客推出新產品的活動或時期。"},{"en":"Marketing staff may prepare messages and materials before a product launch.","zh":"市場推廣員工可能在產品發布前準備訊息和材料。"},{"en":"Launch periods can be busy because many teams must coordinate quickly.","zh":"發布期間可以很忙，因為多個團隊必須快速協調。"},{"en":"Product launches may require extra effort, but rest should still be protected.","zh":"產品發布可能需要額外努力，但休息仍應受到保護。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"staying late may be understandable","meaning":"遲下班或許可以理解","examples":[{"en":"Staying late may be understandable during urgent periods.","zh":"在緊急時期，遲下班或許可以理解。"},{"en":"Staying late may be understandable means people can reasonably accept it in special situations.","zh":"遲下班或許可以理解，意思是在特殊情況下人們可以合理接受它。"},{"en":"Staying late may be understandable when a client’s system fails suddenly.","zh":"當客戶系統突然故障時，遲下班或許可以理解。"},{"en":"However, what is understandable once should not become normal every week.","zh":"然而，一次可以理解的事不應每週都變成常態。"},{"en":"This phrase allows exceptions while still criticising repeated overtime.","zh":"這個短語容許例外，同時仍批評重複加班。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"repeated pattern","meaning":"重複出現的模式","examples":[{"en":"The real problem is the repeated pattern of overtime.","zh":"真正問題是加班重複出現的模式。"},{"en":"A repeated pattern is something that happens again and again in a similar way.","zh":"重複出現的模式是以相似方式一再發生的事情。"},{"en":"If the same team stays late every Friday, that is a repeated pattern.","zh":"如果同一團隊每逢星期五都遲下班，那就是重複出現的模式。"},{"en":"Repeated patterns reveal workplace culture, not just isolated accidents.","zh":"重複模式揭示工作文化，而不只是個別意外。"},{"en":"Management should fix repeated overtime patterns before morale falls.","zh":"管理層應在士氣下降前處理重複加班模式。"}],"source":"2013 Q6.pdf","sourcePage":3},{"front":"postpone dinner","meaning":"延遲吃晚飯","examples":[{"en":"Some staff postpone dinner because of overtime.","zh":"有些員工因加班而延遲吃晚飯。"},{"en":"To postpone dinner means to delay eating the evening meal.","zh":"延遲吃晚飯意思是把晚餐時間推遲。"},{"en":"An employee may postpone dinner when a report must be finished before leaving.","zh":"當報告必須在離開前完成，員工可能延遲吃晚飯。"},{"en":"Postponing dinner often harms family time and physical health.","zh":"延遲晚飯常會傷害家庭時間和身體健康。"},{"en":"A job should not require people to postpone dinner every night.","zh":"工作不應要求人每晚都延遲吃晚飯。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"reply to messages on the train","meaning":"在火車上回覆訊息","examples":[{"en":"Some staff reply to messages on the train after work.","zh":"有些員工下班後在火車上回覆訊息。"},{"en":"To reply to messages on the train means to answer work texts while travelling home.","zh":"在火車上回覆訊息意思是在回家途中回覆工作短訊。"},{"en":"A worker may reply to messages on the train because they fear being judged.","zh":"工作者可能因害怕被批評而在火車上回覆訊息。"},{"en":"This habit turns commuting time into unpaid work time.","zh":"這個習慣把通勤時間變成無薪工作時間。"},{"en":"After-hours messages should be limited so journeys home can be real rest.","zh":"非辦公時間訊息應受限制，讓回家路程成為真正休息。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"junior colleagues","meaning":"初級同事","examples":[{"en":"Junior colleagues may copy the behaviour of senior staff.","zh":"初級同事可能模仿資深職員的行為。"},{"en":"Junior colleagues are employees with less experience or lower positions.","zh":"初級同事是經驗較少或職位較低的員工。"},{"en":"Junior colleagues may feel nervous about leaving before managers do.","zh":"初級同事可能對比經理早離開感到不安。"},{"en":"They often learn workplace culture by watching senior staff.","zh":"他們常透過觀察資深職員來學習工作文化。"},{"en":"Managers should remember that junior colleagues copy signals, not only instructions.","zh":"經理應記住，初級同事會模仿訊號，而不只是聽指示。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"senior staff","meaning":"資深職員","examples":[{"en":"Senior staff often set the tone for workplace habits.","zh":"資深職員常為工作場所習慣定下基調。"},{"en":"Senior staff are experienced employees or managers with more responsibility.","zh":"資深職員是經驗較多或責任較大的員工或經理。"},{"en":"If senior staff stay late every night, younger workers may think they must do the same.","zh":"如果資深職員每晚遲下班，年輕員工可能以為自己也必須這樣做。"},{"en":"Senior staff influence culture through their visible behaviour.","zh":"資深職員透過可見行為影響文化。"},{"en":"Leaving on time where possible is one way senior staff can model healthy boundaries.","zh":"在可行情況下準時下班，是資深職員示範健康界線的一種方式。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"remain at their desks","meaning":"留在辦公桌前","examples":[{"en":"Junior colleagues see senior staff remaining at their desks.","zh":"初級同事看見資深職員留在辦公桌前。"},{"en":"To remain at their desks means to keep sitting or working at the workstation.","zh":"留在辦公桌前意思是繼續坐在或工作於自己的工作位置。"},{"en":"Employees may remain at their desks after hours because everyone else is still there.","zh":"員工可能因其他人仍在場，而在下班後留在辦公桌前。"},{"en":"Staying visible can create pressure even without direct instructions.","zh":"保持可見會製造壓力，即使沒有直接指示。"},{"en":"If managers remain at their desks too long, staff may read it as expectation.","zh":"如果經理太久留在辦公桌前，員工可能把它理解成期望。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"assume they had better do the same","meaning":"以為自己最好也照做","examples":[{"en":"Junior colleagues assume they had better do the same.","zh":"初級同事以為自己最好也照做。"},{"en":"To assume they had better do the same means to think they should copy others for safety.","zh":"以為自己最好也照做，意思是認為為了安全應模仿別人。"},{"en":"A new employee may assume they had better stay late if everyone else does.","zh":"如果所有人都遲下班，新員工可能以為自己最好也留下。"},{"en":"This assumption grows when workplace expectations are not stated clearly.","zh":"當工作期望不清晰時，這種假設會增加。"},{"en":"Clear rules help employees stop guessing what they had better do.","zh":"清晰規則能幫助員工停止猜測自己最好怎樣做。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"over time","meaning":"隨著時間過去","examples":[{"en":"Over time, dedication can turn into silent expectation.","zh":"隨著時間過去，奉獻可能變成不明言的期望。"},{"en":"Over time means gradually as time passes.","zh":"隨著時間過去意思是時間流逝後逐漸地。"},{"en":"Over time, small habits can become workplace culture.","zh":"隨著時間過去，小習慣可以變成工作文化。"},{"en":"A few late nights may, over time, become an unspoken rule.","zh":"幾個深夜加班可能隨著時間過去變成不成文規則。"},{"en":"This phrase shows how problems grow slowly rather than suddenly.","zh":"這個短語顯示問題是慢慢成長，而不是突然出現。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"what begins as...can turn into...","meaning":"原本是……的事可能變成……","examples":[{"en":"What begins as dedication can turn into silent expectation.","zh":"原本是奉獻的事，可能變成不明言的期望。"},{"en":"This structure shows that something may start positively but later become harmful.","zh":"這個結構顯示某事可能一開始正面，但後來變得有害。"},{"en":"What begins as helping a friend can turn into doing all the work for them.","zh":"原本是幫朋友的事，可能變成替他做所有工作。"},{"en":"In the office, staying late once may turn into pressure to stay late often.","zh":"在辦公室，一次遲下班可能變成經常遲下班的壓力。"},{"en":"The phrase warns that good intentions can create unhealthy patterns.","zh":"這個短語提醒我們，好意也可能造成不健康模式。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"dedication","meaning":"奉獻；投入","examples":[{"en":"Staying late may begin as dedication.","zh":"遲下班可能一開始是奉獻。"},{"en":"Dedication means serious effort, loyalty, and commitment to a task or organisation.","zh":"奉獻或投入意思是對任務或機構付出認真努力、忠誠和承諾。"},{"en":"An employee shows dedication by finishing important work carefully.","zh":"員工仔細完成重要工作時，就是表現投入。"},{"en":"Dedication is valuable, but it should not require constant exhaustion.","zh":"奉獻很有價值，但不應要求人長期疲憊。"},{"en":"True dedication includes doing good work sustainably.","zh":"真正投入包括以可持續方式做好工作。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"silent expectation","meaning":"不明言的期望","examples":[{"en":"Overtime can turn into a silent expectation.","zh":"加班可以變成不明言的期望。"},{"en":"A silent expectation is pressure that is not spoken but still felt.","zh":"不明言的期望是沒有說出口但仍能感受到的壓力。"},{"en":"Staff may sense a silent expectation to stay if no one leaves before the manager.","zh":"如果沒有人比經理早離開，員工可能感到留下的不明言期望。"},{"en":"Silent expectations are unfair because employees must guess what is required.","zh":"不明言期望不公平，因為員工必須猜測要求。"},{"en":"Clear policies can replace silent expectation with open standards.","zh":"清晰政策可以用公開標準取代不明言期望。"}],"source":"2013 Q6.pdf","sourcePage":4},{"front":"treat every delay as an emergency","meaning":"把每次延誤都當成緊急事件","examples":[{"en":"Some teams treat every delay as an emergency.","zh":"有些團隊把每次延誤都當成緊急事件。"},{"en":"To treat every delay as an emergency means to react to all late work as if it is urgent.","zh":"把每次延誤都當成緊急事件，意思是把所有遲了的工作都當作急事處理。"},{"en":"A manager may treat a small report delay like a crisis when it could wait until tomorrow.","zh":"一份小報告延遲本可等到明天，經理卻可能把它當成危機。"},{"en":"When every delay becomes an emergency, real emergencies become harder to identify.","zh":"當每次延誤都成為緊急事件，真正緊急的事反而更難辨認。"},{"en":"Teams should separate urgent work from work that can wait.","zh":"團隊應區分緊急工作和可等待的工作。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"have room to work calmly","meaning":"有空間冷靜工作","examples":[{"en":"When everything feels urgent, no one has room to work calmly.","zh":"當所有事情都感覺緊急，沒有人有空間冷靜工作。"},{"en":"To have room to work calmly means to have enough time and mental space to work carefully.","zh":"有空間冷靜工作意思是有足夠時間和心理空間仔細工作。"},{"en":"Employees need room to work calmly when checking numbers or writing reports.","zh":"員工核對數字或撰寫報告時，需要有空間冷靜工作。"},{"en":"Constant urgency removes calm and increases mistakes.","zh":"持續緊急會奪走冷靜，並增加錯誤。"},{"en":"Good planning gives people room to work calmly instead of rushing every task.","zh":"良好規劃給人空間冷靜工作，而不是匆忙處理每項任務。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"negative effect","meaning":"負面影響","examples":[{"en":"The first negative effect is damage to well-being and performance.","zh":"第一個負面影響是損害身心健康和工作表現。"},{"en":"A negative effect is a harmful result caused by an action or situation.","zh":"負面影響是由行動或情況造成的有害結果。"},{"en":"Lack of sleep has a negative effect on memory and mood.","zh":"睡眠不足會對記憶和情緒有負面影響。"},{"en":"Overtime has negative effects when it becomes repeated and unmanaged.","zh":"當加班重複且沒被管理，它就會產生負面影響。"},{"en":"Identifying negative effects helps a company see why change is necessary.","zh":"找出負面影響能幫助公司看見改變的必要。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"excessive overtime","meaning":"過度加班","examples":[{"en":"Excessive overtime damages both well-being and performance.","zh":"過度加班會損害身心健康和工作表現。"},{"en":"Excessive overtime means too much work beyond normal hours.","zh":"過度加班意思是在正常工時以外工作太多。"},{"en":"Working late every night for weeks is excessive overtime.","zh":"連續幾星期每晚遲下班就是過度加班。"},{"en":"Excessive overtime can make employees tired, impatient, and less accurate.","zh":"過度加班會令員工疲倦、缺乏耐性和不夠準確。"},{"en":"A company should measure whether overtime is occasional or excessive.","zh":"公司應衡量加班是偶爾還是過度。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"damage both well-being and performance","meaning":"損害身心健康和工作表現","examples":[{"en":"Excessive overtime can damage both well-being and performance.","zh":"過度加班可以損害身心健康和工作表現。"},{"en":"To damage both well-being and performance means to harm health and reduce work quality at the same time.","zh":"損害身心健康和工作表現意思是同時傷害健康並降低工作質素。"},{"en":"A tired worker may feel anxious and also produce weaker reports.","zh":"疲倦員工可能感到焦慮，也可能寫出較弱的報告。"},{"en":"When rest disappears, personal health and business results both suffer.","zh":"當休息消失，個人健康和業務成果都會受損。"},{"en":"Protecting staff well-being can improve performance instead of weakening it.","zh":"保護員工身心健康可以改善工作表現，而不是削弱它。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"well-being","meaning":"身心健康","examples":[{"en":"Companies should protect employees’ well-being.","zh":"公司應保護員工的身心健康。"},{"en":"Well-being means a person’s physical, mental, and emotional health.","zh":"身心健康是指一個人的身體、心理和情緒健康。"},{"en":"Sufficient rest, manageable workload, and respect help protect well-being.","zh":"足夠休息、可管理的工作量和尊重有助保護身心健康。"},{"en":"Poor well-being can lead to mistakes, illness, and resignations.","zh":"身心健康欠佳可能導致錯誤、疾病和辭職。"},{"en":"A responsible company treats well-being as part of performance.","zh":"負責任的公司會把身心健康視為工作表現的一部分。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"performance","meaning":"工作表現","examples":[{"en":"Lack of rest can reduce work performance.","zh":"缺乏休息會降低工作表現。"},{"en":"Performance means how well a person or team does a task.","zh":"工作表現是指個人或團隊完成任務的質素。"},{"en":"A tired employee’s performance may drop even if they stay in the office longer.","zh":"即使員工在辦公室待更久，疲倦也可能令工作表現下降。"},{"en":"Good performance depends on focus, judgement, and energy.","zh":"良好工作表現取決於專注力、判斷力和精力。"},{"en":"Better rest can improve performance more than unnecessary overtime.","zh":"更好休息比不必要加班更能改善工作表現。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"be present","meaning":"身在場","examples":[{"en":"A tired employee may still be present in the office.","zh":"疲倦員工可能仍身在辦公室。"},{"en":"To be present means to be physically there.","zh":"身在場意思是身體上在某個地方。"},{"en":"A worker can be present at a meeting but too tired to contribute well.","zh":"工作者可能身在會議中，卻太疲倦而無法好好貢獻。"},{"en":"Being present does not always mean being productive or focused.","zh":"身在場不一定代表有生產力或專注。"},{"en":"Companies should value useful work more than simple presence.","zh":"公司應重視有用工作，而不是單純在場。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"presence is not the same as productivity","meaning":"在場不等於有生產力","examples":[{"en":"Presence is not the same as productivity.","zh":"在場不等於有生產力。"},{"en":"This sentence means being physically at work does not automatically mean useful work is being done.","zh":"這句話意思是身體在工作場所，不會自動代表正在完成有用工作。"},{"en":"An employee may sit at a desk for hours while too tired to think clearly.","zh":"員工可能在辦公桌坐了數小時，卻太累而不能清楚思考。"},{"en":"Measuring presence instead of results encourages unhealthy overtime.","zh":"衡量在場而不是成果，會鼓勵不健康加班。"},{"en":"A good workplace judges output and quality, not only who stays latest.","zh":"好工作場所會按產出和質素判斷，而不只是看誰留得最遲。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"productivity","meaning":"生產力","examples":[{"en":"Overtime does not always improve productivity.","zh":"加班不一定提高生產力。"},{"en":"Productivity means the amount and quality of useful work completed.","zh":"生產力是指完成有用工作的數量和質素。"},{"en":"A rested employee may finish more in six focused hours than in ten tired hours.","zh":"休息充足的員工，可能在六小時專注工作中完成比十小時疲倦工作更多的事。"},{"en":"Productivity falls when people lose concentration and repeat mistakes.","zh":"當人失去專注並重複犯錯時，生產力會下降。"},{"en":"Clear priorities can improve productivity without lengthening the workday.","zh":"清晰優先次序可以改善生產力，而不用延長工作日。"}],"source":"2013 Q6.pdf","sourcePage":5},{"front":"sufficient rest","meaning":"足夠休息","examples":[{"en":"Employees need sufficient rest to work well.","zh":"員工需要足夠休息才能好好工作。"},{"en":"Sufficient rest means enough sleep, breaks, and recovery time.","zh":"足夠休息意思是有足夠睡眠、休息時間和恢復時間。"},{"en":"A finance colleague needs sufficient rest before checking important spreadsheets.","zh":"財務部同事在檢查重要試算表前需要足夠休息。"},{"en":"Without sufficient rest, people lose patience and accuracy.","zh":"沒有足夠休息，人會失去耐性和準確度。"},{"en":"Rest is not laziness; it is part of good performance.","zh":"休息不是懶惰，而是良好表現的一部分。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"lose concentration","meaning":"失去專注力","examples":[{"en":"Without sufficient rest, people lose concentration.","zh":"沒有足夠休息，人們會失去專注力。"},{"en":"To lose concentration means to stop focusing clearly on the task.","zh":"失去專注力意思是無法清楚集中於任務。"},{"en":"A tired worker may lose concentration while checking numbers.","zh":"疲倦員工在核對數字時可能失去專注力。"},{"en":"Losing concentration can lead to careless mistakes and slower work.","zh":"失去專注力會導致粗心錯誤和工作變慢。"},{"en":"Shorter, focused work may be better than long hours without concentration.","zh":"較短但專注的工作，可能比沒有專注力的長工時更好。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"communicate less patiently","meaning":"溝通時較沒耐性","examples":[{"en":"Tired employees may communicate less patiently.","zh":"疲倦員工溝通時可能較沒耐性。"},{"en":"To communicate less patiently means to speak or write with less calm and tolerance.","zh":"溝通時較沒耐性意思是說話或寫訊息時較不冷靜和包容。"},{"en":"A tired customer service worker may reply too sharply to a simple question.","zh":"疲倦的客服員工可能對簡單問題回覆得太尖銳。"},{"en":"Poor patience can damage relationships with colleagues and customers.","zh":"缺乏耐性會損害同事和客戶關係。"},{"en":"Rest helps employees communicate more kindly and clearly.","zh":"休息有助員工更友善和清晰地溝通。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"make mistakes","meaning":"犯錯","examples":[{"en":"Tired people are more likely to make mistakes.","zh":"疲倦的人更有可能犯錯。"},{"en":"To make mistakes means to do something incorrectly.","zh":"犯錯意思是做錯某事。"},{"en":"A tired employee may type the wrong number in a report.","zh":"疲倦員工可能在報告中打錯數字。"},{"en":"Mistakes increase when people work too long without rest.","zh":"當人長時間工作而沒有休息時，錯誤會增加。"},{"en":"Preventing mistakes often requires better planning, not longer hours.","zh":"防止犯錯常需要更好規劃，而不是更長工時。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"require more correction","meaning":"需要更多修正","examples":[{"en":"Mistakes made at night may require more correction later.","zh":"晚上犯下的錯誤之後可能需要更多修正。"},{"en":"To require more correction means to need extra time to fix errors.","zh":"需要更多修正意思是需要額外時間改正錯誤。"},{"en":"A spreadsheet prepared when tired may require more correction the next morning.","zh":"疲倦時準備的試算表，翌日早上可能需要更多修正。"},{"en":"Late-night mistakes can waste the time overtime was supposed to save.","zh":"深夜錯誤可能浪費原本想靠加班節省的時間。"},{"en":"Careful daytime work may require less correction than rushed night work.","zh":"白天仔細工作可能比晚上倉促工作需要更少修正。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"finance colleague","meaning":"財務部同事","examples":[{"en":"A finance colleague may make mistakes after ten hours of work.","zh":"財務部同事工作十小時後可能犯錯。"},{"en":"A finance colleague is a co-worker who handles money, accounts, budgets, or financial reports.","zh":"財務部同事是處理金錢、帳目、預算或財務報告的同事。"},{"en":"A finance colleague may check invoices, spreadsheets, and monthly figures.","zh":"財務部同事可能核對發票、試算表和月結數字。"},{"en":"Accuracy is especially important in finance because small errors can affect whole reports.","zh":"準確度在財務工作中尤其重要，因為小錯誤可以影響整份報告。"},{"en":"Finance colleagues need enough rest to protect both numbers and decisions.","zh":"財務部同事需要足夠休息，以保護數字和決策。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"check a spreadsheet","meaning":"檢查試算表","examples":[{"en":"A finance colleague may check a spreadsheet after ten hours of work.","zh":"財務部同事可能在工作十小時後檢查試算表。"},{"en":"To check a spreadsheet means to review rows, numbers, formulas, and data for accuracy.","zh":"檢查試算表意思是核對行列、數字、公式和資料是否準確。"},{"en":"An employee checks a spreadsheet before sending a budget report.","zh":"員工寄出預算報告前會檢查試算表。"},{"en":"Spreadsheet checking requires concentration because one wrong formula can spread errors.","zh":"檢查試算表需要專注，因為一個錯誤公式可以擴散錯誤。"},{"en":"Tired employees should not be forced to check critical spreadsheets late at night.","zh":"不應強迫疲倦員工深夜檢查重要試算表。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"after ten hours of work","meaning":"工作十小時後","examples":[{"en":"Accuracy often drops after ten hours of work.","zh":"工作十小時後，準確度常會下降。"},{"en":"After ten hours of work means after spending a very long workday on tasks.","zh":"工作十小時後意思是在任務上花了非常長的工作日之後。"},{"en":"After ten hours of work, even careful employees may feel mentally slow.","zh":"工作十小時後，即使謹慎員工也可能感到頭腦變慢。"},{"en":"Long hours reduce accuracy because the brain needs recovery.","zh":"長工時會降低準確度，因為大腦需要恢復。"},{"en":"Important checking should not routinely happen after ten hours of work.","zh":"重要核對不應經常安排在工作十小時後進行。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"careless formula","meaning":"粗心大意的公式","examples":[{"en":"One careless formula can delay an entire report.","zh":"一個粗心大意的公式可以延誤整份報告。"},{"en":"A careless formula is a spreadsheet formula entered without enough attention.","zh":"粗心大意的公式是沒有足夠注意而輸入的試算表公式。"},{"en":"A tired employee may copy a formula into the wrong row.","zh":"疲倦員工可能把公式複製到錯誤行列。"},{"en":"One careless formula can change totals and mislead the whole team.","zh":"一個粗心公式可以改變總數並誤導整個團隊。"},{"en":"Careless formulas are more likely when people work late and rush.","zh":"當人深夜趕工時，更容易出現粗心大意的公式。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"delay an entire report","meaning":"延誤整份報告","examples":[{"en":"A spreadsheet mistake can delay an entire report.","zh":"試算表錯誤可以延誤整份報告。"},{"en":"To delay an entire report means to make the whole report late.","zh":"延誤整份報告意思是令整份報告遲交。"},{"en":"One missing figure can delay an entire report if every section depends on it.","zh":"如果每一部分都依賴某個數字，少了一個數字也可以延誤整份報告。"},{"en":"Errors made during overtime may create delays the next day.","zh":"加班時犯下的錯誤可能造成翌日延誤。"},{"en":"Careful planning prevents small mistakes from delaying entire reports.","zh":"仔細規劃能防止小錯誤延誤整份報告。"}],"source":"2013 Q6.pdf","sourcePage":6},{"front":"the same applies to","meaning":"同樣適用於","examples":[{"en":"The same applies to customer service.","zh":"同樣適用於客戶服務。"},{"en":"The same applies to means the same idea is true in another situation.","zh":"同樣適用於意思是同一想法在另一情況中也成立。"},{"en":"Rest matters for finance; the same applies to customer service.","zh":"休息對財務部很重要；同樣適用於客戶服務。"},{"en":"This phrase helps writers extend an argument to a new example.","zh":"這個短語幫助作者把論點延伸到新例子。"},{"en":"It shows that overtime harms more than one department.","zh":"它顯示加班傷害的不止一個部門。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"customer service","meaning":"客戶服務","examples":[{"en":"Customer service requires patience and clear communication.","zh":"客戶服務需要耐性和清晰溝通。"},{"en":"Customer service is the work of helping customers before, during, or after buying something.","zh":"客戶服務是在顧客購買前、期間或之後提供幫助的工作。"},{"en":"Customer service staff answer questions, solve complaints, and explain policies.","zh":"客戶服務員工會回答問題、處理投訴和解釋政策。"},{"en":"Tired customer service workers may sound cold even when trying to help.","zh":"疲倦的客服員工即使想幫忙，也可能聽起來冷淡。"},{"en":"Good customer service depends on both information and emotional control.","zh":"良好客戶服務取決於資訊和情緒控制。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"exhausted reply","meaning":"疲憊狀態下的回覆","examples":[{"en":"An exhausted reply can sound cold to a customer.","zh":"疲憊狀態下的回覆可能令顧客覺得冷淡。"},{"en":"An exhausted reply is a message written or spoken when someone is very tired.","zh":"疲憊狀態下的回覆，是人在非常疲倦時寫出或說出的訊息。"},{"en":"A late-night email may become an exhausted reply with short and blunt wording.","zh":"深夜電郵可能變成用字簡短生硬的疲憊回覆。"},{"en":"Exhausted replies can damage customer relationships even without bad intention.","zh":"疲憊回覆即使沒有惡意，也可能損害客戶關係。"},{"en":"Rested employees usually reply more clearly and warmly.","zh":"休息充足的員工通常能更清晰和溫暖地回覆。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"sound cold","meaning":"聽起來冷淡","examples":[{"en":"An exhausted reply can sound cold even if the intention is helpful.","zh":"疲憊狀態下的回覆即使原意是想幫忙，也可能聽起來冷淡。"},{"en":"To sound cold means to seem unfriendly, distant, or lacking warmth.","zh":"聽起來冷淡意思是顯得不友善、疏離或缺乏溫度。"},{"en":"A short email may sound cold if it contains no greeting or explanation.","zh":"如果電郵沒有問候或解釋，簡短回覆可能聽起來冷淡。"},{"en":"Tired people may sound cold because they have little patience left.","zh":"疲倦的人可能因耐性所剩不多而聽起來冷淡。"},{"en":"Clear boundaries help employees avoid sending replies that sound cold.","zh":"清晰界線幫助員工避免發出聽起來冷淡的回覆。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"the intention is helpful","meaning":"原意是想幫忙","examples":[{"en":"The intention may be helpful, but the tone may sound cold.","zh":"原意可能是想幫忙，但語氣可能聽起來冷淡。"},{"en":"The intention is helpful means the person wants to assist, not harm.","zh":"原意是想幫忙意思是那個人想提供協助，而不是傷害。"},{"en":"A manager may give quick advice with helpful intention, but tired wording may seem harsh.","zh":"經理可能原意是想快速給建議，但疲倦的措辭可能顯得嚴厲。"},{"en":"Good intentions can be misunderstood when communication happens under exhaustion.","zh":"當溝通在疲憊中發生，好意也可能被誤解。"},{"en":"Rest improves not only work speed but also tone.","zh":"休息改善的不只是工作速度，也包括語氣。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"long hours","meaning":"長時間工作","examples":[{"en":"Long hours eat into exercise, sleep and family time.","zh":"長時間工作會侵佔運動、睡眠和家庭時間。"},{"en":"Long hours mean working for a very extended period.","zh":"長時間工作意思是工作很長一段時間。"},{"en":"Long hours may leave employees too tired to cook, exercise, or talk to family.","zh":"長時間工作可能令員工太累，無法煮飯、運動或與家人聊天。"},{"en":"Regular long hours can damage health and relationships.","zh":"經常長時間工作會損害健康和關係。"},{"en":"A sustainable workplace should not depend on long hours every week.","zh":"可持續的工作場所不應每週依賴長時間工作。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"eat into","meaning":"侵佔；佔用","examples":[{"en":"Overtime can eat into sleep and family time.","zh":"加班會侵佔睡眠和家庭時間。"},{"en":"To eat into something means to gradually use up time, money, or energy meant for something else.","zh":"侵佔某物意思是逐漸用掉原本屬於其他用途的時間、金錢或精力。"},{"en":"Long meetings can eat into the afternoon’s most productive hours.","zh":"漫長會議會侵佔下午最高效的工作時段。"},{"en":"When work eats into rest, employees cannot recover properly.","zh":"當工作侵佔休息，員工無法好好恢復。"},{"en":"Good boundaries stop work from eating into every part of life.","zh":"良好界線能阻止工作侵佔生活每一部分。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"family time","meaning":"家庭時間","examples":[{"en":"Long hours can reduce family time.","zh":"長時間工作會減少家庭時間。"},{"en":"Family time is time spent with family members, usually for meals, conversation, or care.","zh":"家庭時間是與家人共處的時間，通常用於吃飯、聊天或照顧。"},{"en":"A parent who leaves late may miss family time with children.","zh":"遲下班的父母可能錯過與孩子相處的家庭時間。"},{"en":"Losing family time can create stress outside the workplace.","zh":"失去家庭時間會在工作場所外造成壓力。"},{"en":"Companies should respect family time as part of employee well-being.","zh":"公司應尊重家庭時間，視之為員工身心健康的一部分。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"little room to recover","meaning":"幾乎沒有恢復空間","examples":[{"en":"Long hours leave colleagues with little room to recover.","zh":"長時間工作令同事幾乎沒有恢復空間。"},{"en":"Little room to recover means not enough time or energy to rest and regain strength.","zh":"幾乎沒有恢復空間意思是沒有足夠時間或精力休息和重新蓄力。"},{"en":"A worker has little room to recover if they leave late and return early the next day.","zh":"如果員工遲下班翌日又早回公司，就幾乎沒有恢復空間。"},{"en":"Without recovery, tiredness builds up and performance falls.","zh":"沒有恢復，疲倦會累積，工作表現會下降。"},{"en":"Staff need real breaks, not just short gaps between long shifts.","zh":"員工需要真正休息，而不是長班之間的短暫空隙。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, overtime may create tomorrow’s problems.","zh":"換句話說，加班可能製造明天的問題。"},{"en":"In other words introduces the same idea in a clearer or simpler way.","zh":"換句話說用來以更清楚或更簡單的方式重新表達同一想法。"},{"en":"In other words, staying late tonight may cause mistakes tomorrow.","zh":"換句話說，今晚遲下班可能導致明天犯錯。"},{"en":"Writers use this phrase to restate an important point.","zh":"作者使用這個短語來重述重要觀點。"},{"en":"It helps readers understand the consequence of repeated overtime.","zh":"它幫助讀者理解重複加班的後果。"}],"source":"2013 Q6.pdf","sourcePage":7},{"front":"appear to save time","meaning":"看似節省時間","examples":[{"en":"Overtime may appear to save time tonight.","zh":"加班今晚可能看似節省時間。"},{"en":"To appear to save time means to seem quicker or more efficient at first.","zh":"看似節省時間意思是一開始似乎較快或較有效率。"},{"en":"Rushing a report may appear to save time, but errors may need fixing later.","zh":"匆忙完成報告可能看似節省時間，但錯誤之後可能要修正。"},{"en":"What looks efficient tonight can create extra work tomorrow.","zh":"今晚看似有效率的事，明天可能製造額外工作。"},{"en":"Teams should ask whether overtime truly saves time or only moves the problem.","zh":"團隊應詢問加班是否真正節省時間，還是只把問題推後。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"tomorrow’s errors","meaning":"明天的錯誤","examples":[{"en":"Overtime tonight may create tomorrow’s errors.","zh":"今晚加班可能製造明天的錯誤。"},{"en":"Tomorrow’s errors are mistakes that appear later because of tired work today.","zh":"明天的錯誤是因今天疲倦工作而稍後出現的錯誤。"},{"en":"A late-night spreadsheet may contain tomorrow’s errors if formulas are unchecked.","zh":"如果公式沒有核對，深夜做的試算表可能包含明天的錯誤。"},{"en":"Errors created by exhaustion often cost more time than rest would have cost.","zh":"由疲憊造成的錯誤，常比休息本身耗費更多時間。"},{"en":"Avoiding tomorrow’s errors requires better planning today.","zh":"避免明天的錯誤需要今天更好規劃。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"absences and resignations","meaning":"缺勤和辭職","examples":[{"en":"Excessive overtime can lead to absences and resignations.","zh":"過度加班可能導致缺勤和辭職。"},{"en":"Absences and resignations mean staff missing work and staff leaving the company.","zh":"缺勤和辭職是指員工不上班以及員工離開公司。"},{"en":"Employees may take sick leave more often if long hours damage health.","zh":"如果長工時損害健康，員工可能更常請病假。"},{"en":"Resignations may increase when staff feel the workplace is unsustainable.","zh":"當員工覺得工作場所不可持續，辭職可能增加。"},{"en":"Reducing excessive overtime can help keep employees healthier and more willing to stay.","zh":"減少過度加班可以幫助員工更健康，也更願意留下。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"cultural effect","meaning":"文化上的影響","examples":[{"en":"The second effect of overtime is cultural.","zh":"加班的第二個影響是文化上的。"},{"en":"A cultural effect is a change in shared habits, beliefs, or expectations.","zh":"文化上的影響是共同習慣、信念或期望的改變。"},{"en":"Overtime has a cultural effect when people think leaving on time is irresponsible.","zh":"當人們認為準時下班是不負責任時，加班就有文化上的影響。"},{"en":"Workplace culture shapes behaviour even without written rules.","zh":"工作文化即使沒有文字規則，也會塑造行為。"},{"en":"Fixing overtime requires changing culture, not only schedules.","zh":"處理加班需要改變文化，而不只是改時間表。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"badge of loyalty","meaning":"忠誠的標誌","examples":[{"en":"Leaving late can become a badge of loyalty.","zh":"遲下班可以變成忠誠的標誌。"},{"en":"A badge of loyalty is a visible sign people use to prove commitment.","zh":"忠誠的標誌是人們用來證明投入的可見訊號。"},{"en":"Staying at a desk after hours may wrongly become a badge of loyalty.","zh":"下班後仍留在辦公桌前，可能被錯誤地視為忠誠的標誌。"},{"en":"This belief is harmful because it rewards appearance more than results.","zh":"這種信念有害，因為它獎勵外表多於成果。"},{"en":"Real loyalty should be shown through responsible, high-quality work.","zh":"真正忠誠應透過負責任而高質素的工作顯示。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"commitment is measured by","meaning":"投入程度以……衡量","examples":[{"en":"Commitment should not be measured by visibility.","zh":"投入程度不應以能見度衡量。"},{"en":"Commitment is measured by something means that thing is used to judge dedication.","zh":"投入程度以某事衡量，意思是用該事物來判斷投入。"},{"en":"If commitment is measured by late leaving, parents and caregivers may be unfairly judged.","zh":"如果投入程度以遲下班衡量，父母和照顧者可能被不公平判斷。"},{"en":"Measuring commitment by results is fairer than measuring it by time spent in the office.","zh":"以成果衡量投入程度，比以留在辦公室的時間衡量更公平。"},{"en":"Clear standards prevent commitment from being measured by the wrong signal.","zh":"清晰標準能防止投入程度以錯誤訊號衡量。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"visibility rather than results","meaning":"能見度而非成果","examples":[{"en":"Commitment is sometimes measured by visibility rather than results.","zh":"投入程度有時以能見度而非成果衡量。"},{"en":"Visibility rather than results means being seen matters more than actual work quality.","zh":"能見度而非成果意思是被看見比實際工作質素更重要。"},{"en":"Staff may stay at desks to look committed, even after useful work is done.","zh":"即使有用工作已完成，員工可能仍留在辦公桌前以顯得投入。"},{"en":"This culture encourages performance of effort instead of real effectiveness.","zh":"這種文化鼓勵表演努力，而不是真正有效。"},{"en":"A healthy company values results rather than simple visibility.","zh":"健康公司重視成果，而不是單純能見度。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"few, if any","meaning":"即使有也很少","examples":[{"en":"Few, if any, colleagues want to be the first to leave.","zh":"即使有，也很少同事想成為第一個離開的人。"},{"en":"Few, if any means almost none or possibly none at all.","zh":"即使有也很少意思是幾乎沒有，或可能完全沒有。"},{"en":"Few, if any, employees enjoy staying late every night.","zh":"即使有，也很少員工喜歡每晚遲下班。"},{"en":"This phrase shows that a behaviour is rare or unlikely.","zh":"這個短語顯示某行為很少見或不太可能。"},{"en":"Few, if any, workers want to appear irresponsible in front of managers.","zh":"即使有，也很少工作者想在經理面前顯得不負責任。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"pack up","meaning":"收拾東西準備離開","examples":[{"en":"Few colleagues want to be the first to pack up.","zh":"很少同事想成為第一個收拾東西準備離開的人。"},{"en":"To pack up means to put things away and prepare to leave.","zh":"收拾東西準備離開意思是把物品收好並準備下班。"},{"en":"An employee may pack up by closing files, shutting down the computer, and taking their bag.","zh":"員工可能透過關閉文件、關掉電腦和拿起手袋來收拾離開。"},{"en":"People may delay packing up if they fear being judged.","zh":"如果害怕被批評，人們可能延遲收拾東西。"},{"en":"In a healthy office, packing up on time should feel normal.","zh":"在健康辦公室中，準時收拾東西準備離開應是正常的。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"as a result","meaning":"因此","examples":[{"en":"As a result, some staff stay late unnecessarily.","zh":"因此，有些員工不必要地遲下班。"},{"en":"As a result means because of what was just described.","zh":"因此意思是由於剛才描述的事情。"},{"en":"The manager stays late every day; as a result, junior staff feel pressure to remain.","zh":"經理每天遲下班；因此，初級員工感到留下的壓力。"},{"en":"This phrase connects a cause with its consequence.","zh":"這個短語把原因和後果連接起來。"},{"en":"It helps show how culture produces unnecessary overtime.","zh":"它幫助顯示文化如何製造不必要加班。"}],"source":"2013 Q6.pdf","sourcePage":8},{"front":"not because...but because...","meaning":"不是因為……而是因為……","examples":[{"en":"Some staff stay not because the work requires it, but because they fear judgement.","zh":"有些員工留下來，不是因為工作需要，而是因為害怕被批評。"},{"en":"This structure contrasts a false reason with the real reason.","zh":"這個結構把錯誤原因和真正原因作對比。"},{"en":"An employee may stay late not because a task is urgent, but because others are watching.","zh":"員工可能遲下班，不是因為任務緊急，而是因為別人在看。"},{"en":"The phrase helps reveal hidden pressure behind visible behaviour.","zh":"這個短語幫助揭示可見行為背後的隱藏壓力。"},{"en":"It shows that overtime can come from fear, not real need.","zh":"它顯示加班可能來自恐懼，而不是真正需要。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"look irresponsible","meaning":"看起來不負責任","examples":[{"en":"Some staff stay late because they do not want to look irresponsible.","zh":"有些員工遲下班，因為他們不想看起來不負責任。"},{"en":"To look irresponsible means to appear careless or unwilling to do one’s duty.","zh":"看起來不負責任意思是顯得粗心或不願履行責任。"},{"en":"A parent may leave on time for childcare but fear looking irresponsible.","zh":"父母可能因照顧孩子而準時離開，卻害怕看起來不負責任。"},{"en":"Judging responsibility by leaving time is unfair and inaccurate.","zh":"以離開時間判斷責任感是不公平也不準確的。"},{"en":"Clear expectations help staff stop worrying about looking irresponsible.","zh":"清晰期望能幫助員工停止擔心自己看起來不負責任。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"such pressure","meaning":"這種壓力","examples":[{"en":"Such pressure is unfair to many employees.","zh":"這種壓力對許多員工不公平。"},{"en":"Such pressure means the kind of pressure just mentioned.","zh":"這種壓力意思是剛才提到的那類壓力。"},{"en":"Pressure to stay late affects people with families, long journeys, or health needs.","zh":"遲下班壓力會影響有家庭、回家路遠或有健康需要的人。"},{"en":"Such pressure can make workers feel guilty for protecting their own lives.","zh":"這種壓力可能令員工因保護自己生活而感到內疚。"},{"en":"Management should reduce such pressure through clear policies.","zh":"管理層應透過清晰政策減少這種壓力。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"be unfair to","meaning":"對……不公平","examples":[{"en":"The pressure to stay late is unfair to parents and caregivers.","zh":"遲下班的壓力對父母和照顧者不公平。"},{"en":"To be unfair to someone means to treat them in an unreasonable or unequal way.","zh":"對某人不公平意思是以不合理或不平等方式對待他們。"},{"en":"A rule that rewards only late leaving is unfair to workers with family duties.","zh":"只獎勵遲下班的規則，對有家庭責任的工作者不公平。"},{"en":"Unfair pressure damages trust because people feel judged for real responsibilities.","zh":"不公平壓力會損害信任，因為人們因真實責任而被評判。"},{"en":"Fair workplaces recognise different lives outside the office.","zh":"公平工作場所會承認辦公室外不同人的生活。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"parents and caregivers","meaning":"父母和照顧者","examples":[{"en":"Parents and caregivers may find overtime especially difficult.","zh":"父母和照顧者可能覺得加班尤其困難。"},{"en":"Parents and caregivers are people who look after children, elderly relatives, or others who need support.","zh":"父母和照顧者是照顧孩子、年長親人或其他需要支援者的人。"},{"en":"A caregiver may need to leave on time to take a parent to a medical appointment.","zh":"照顧者可能需要準時下班，帶父母覆診。"},{"en":"Overtime pressure can be unfair because care responsibilities are not optional.","zh":"加班壓力可能不公平，因為照顧責任不是可有可無。"},{"en":"Healthy policies help parents and caregivers stay employed without constant guilt.","zh":"健康政策幫助父母和照顧者繼續工作，而不用長期內疚。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"long journeys home","meaning":"漫長回家路程","examples":[{"en":"Overtime is hard for colleagues with long journeys home.","zh":"加班對有漫長回家路程的同事很困難。"},{"en":"Long journeys home are lengthy trips from the workplace back to where people live.","zh":"漫長回家路程是指由工作場所回到住所的長途旅程。"},{"en":"A colleague may need ninety minutes to travel home after work.","zh":"同事下班後可能需要九十分鐘才到家。"},{"en":"Leaving late makes long journeys more tiring and may reduce sleep.","zh":"遲下班令漫長回家路程更疲累，也可能減少睡眠。"},{"en":"Managers should consider commuting time when judging overtime pressure.","zh":"經理判斷加班壓力時，應考慮通勤時間。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"damage trust","meaning":"損害信任","examples":[{"en":"Repeated overtime can damage trust in management.","zh":"重複加班會損害員工對管理層的信任。"},{"en":"To damage trust means to make people believe less in someone’s honesty or ability.","zh":"損害信任意思是令人較不相信某人的誠信或能力。"},{"en":"Staff may lose trust if managers praise overtime but ignore poor planning.","zh":"如果經理稱讚加班卻忽略規劃不善，員工可能失去信任。"},{"en":"Trust is damaged when employees feel their health is not valued.","zh":"當員工覺得自己的健康不被重視，信任就會受損。"},{"en":"Clear workload planning helps rebuild trust.","zh":"清晰工作量規劃有助重建信任。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"start wondering whether","meaning":"開始懷疑是否","examples":[{"en":"Staff may start wondering whether poor planning is being hidden.","zh":"員工可能開始懷疑是否有人在隱藏規劃不善。"},{"en":"To start wondering whether means to begin asking oneself if something is true.","zh":"開始懷疑是否意思是開始問自己某事是否真實。"},{"en":"Employees start wondering whether management is listening when complaints are ignored.","zh":"當投訴被忽視，員工會開始懷疑管理層是否有聆聽。"},{"en":"Repeated overtime makes people question the real cause of pressure.","zh":"重複加班令人質疑壓力的真正原因。"},{"en":"Open communication prevents staff from wondering whether problems are being hidden.","zh":"開放溝通能防止員工懷疑問題是否被隱藏。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"poor planning","meaning":"規劃不善","examples":[{"en":"Staff may blame overtime on poor planning.","zh":"員工可能把加班歸咎於規劃不善。"},{"en":"Poor planning means weak organisation of time, people, tasks, or deadlines.","zh":"規劃不善是指時間、人手、任務或截止日期安排得不好。"},{"en":"Assigning major work at 5 p.m. can show poor planning.","zh":"下午五點才分派重大工作，可能顯示規劃不善。"},{"en":"Poor planning often creates emergencies that could have been avoided.","zh":"規劃不善常製造本可避免的緊急情況。"},{"en":"Better planning reduces overtime more effectively than asking people to try harder.","zh":"更好規劃比要求人更努力更能有效減少加班。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"understaffing","meaning":"人手不足","examples":[{"en":"Understaffing may be disguised as team spirit.","zh":"人手不足可能被包裝成團隊精神。"},{"en":"Understaffing means not having enough workers to do the work properly.","zh":"人手不足意思是沒有足夠員工妥善完成工作。"},{"en":"A department is understaffed if five people must do the work of eight.","zh":"如果五個人要做八個人的工作，部門就是人手不足。"},{"en":"Understaffing leads to overtime because the workload is bigger than the team.","zh":"人手不足會導致加班，因為工作量大過團隊能力。"},{"en":"Calling understaffing “team spirit” hides the real problem.","zh":"把人手不足稱為「團隊精神」會隱藏真正問題。"}],"source":"2013 Q6.pdf","sourcePage":9},{"front":"unrealistic expectations","meaning":"不切實際的期望","examples":[{"en":"Unrealistic expectations can lead to unnecessary overtime.","zh":"不切實際的期望會導致不必要加班。"},{"en":"Unrealistic expectations are demands that cannot reasonably be met with available time or resources.","zh":"不切實際的期望是無法以現有時間或資源合理達成的要求。"},{"en":"Asking a small team to finish a large project overnight is unrealistic.","zh":"要求小團隊一晚完成大型項目是不切實際的。"},{"en":"Unrealistic expectations make employees feel they are always failing.","zh":"不切實際的期望會令員工覺得自己總是在失敗。"},{"en":"Good managers set challenging but achievable expectations.","zh":"好經理會設定有挑戰但可達成的期望。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"be disguised as","meaning":"被包裝成；被偽裝成","examples":[{"en":"Poor planning should not be disguised as team spirit.","zh":"規劃不善不應被包裝成團隊精神。"},{"en":"To be disguised as something means to be presented as something better or different from what it really is.","zh":"被包裝成某事，意思是被呈現為比真相更好或不同的東西。"},{"en":"Unpaid overtime may be disguised as dedication.","zh":"無薪加班可能被包裝成奉獻。"},{"en":"When problems are disguised, employees cannot discuss them honestly.","zh":"當問題被偽裝，員工就無法誠實討論它們。"},{"en":"Naming the real issue is fairer than disguising it with positive words.","zh":"說出真正問題，比用正面字眼包裝它更公平。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"team spirit","meaning":"團隊精神","examples":[{"en":"Unpaid overtime should not be praised as team spirit.","zh":"無薪加班不應被讚揚為團隊精神。"},{"en":"Team spirit means a shared willingness to support one another and work together.","zh":"團隊精神是共同願意互相支持和合作的態度。"},{"en":"Real team spirit includes helping colleagues, not silently accepting unfair workloads.","zh":"真正團隊精神包括幫助同事，而不是沉默接受不公平工作量。"},{"en":"Calling exhaustion team spirit can pressure people to ignore their health.","zh":"把疲憊稱為團隊精神，會迫使人忽視健康。"},{"en":"A healthy team shows spirit through cooperation and respect for boundaries.","zh":"健康團隊透過合作和尊重界線來顯示團隊精神。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"once that belief spreads","meaning":"一旦這種信念傳開","examples":[{"en":"Once that belief spreads, morale is difficult to rebuild.","zh":"一旦這種信念傳開，士氣就難以重建。"},{"en":"Once that belief spreads means after that idea becomes widely accepted.","zh":"一旦這種信念傳開意思是當那個想法被廣泛接受之後。"},{"en":"Once staff believe overtime hides poor planning, trust will fall.","zh":"一旦員工相信加班掩蓋規劃不善，信任就會下降。"},{"en":"Beliefs spread through repeated experiences and office conversations.","zh":"信念透過重複經驗和辦公室對話傳開。"},{"en":"Management should act before harmful beliefs spread across the company.","zh":"管理層應在有害信念傳遍公司前行動。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"morale","meaning":"士氣","examples":[{"en":"Morale is difficult to rebuild after trust is damaged.","zh":"信任受損後，士氣難以重建。"},{"en":"Morale means the confidence, energy, and positive feeling of a group.","zh":"士氣是指群體的信心、能量和正面情緒。"},{"en":"Team morale falls when employees feel ignored and exhausted.","zh":"當員工感到被忽視和疲憊時，團隊士氣會下降。"},{"en":"Good communication and fair workloads can improve morale.","zh":"良好溝通和公平工作量可以改善士氣。"},{"en":"High morale helps people work better without fear or resentment.","zh":"高士氣幫助人們在沒有恐懼或怨氣下更好工作。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"difficult to rebuild","meaning":"難以重建","examples":[{"en":"Trust is difficult to rebuild once morale falls.","zh":"一旦士氣下降，信任就難以重建。"},{"en":"Difficult to rebuild means hard to repair after being damaged.","zh":"難以重建意思是在受損後很難修復。"},{"en":"A team’s confidence is difficult to rebuild after months of unfair overtime.","zh":"經歷數月不公平加班後，團隊信心難以重建。"},{"en":"Rebuilding trust takes longer than losing it.","zh":"重建信任所需時間比失去信任更長。"},{"en":"Preventing damage is easier than rebuilding morale later.","zh":"預防傷害比日後重建士氣更容易。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"practical steps","meaning":"實際措施","examples":[{"en":"Two practical steps should be introduced.","zh":"應引入兩項實際措施。"},{"en":"Practical steps are realistic actions that can be taken to solve a problem.","zh":"實際措施是可以採取來解決問題的現實行動。"},{"en":"A workload check and communication policy are practical steps against overtime.","zh":"工作量檢查和溝通政策都是處理加班的實際措施。"},{"en":"Practical steps matter because complaints alone do not change habits.","zh":"實際措施很重要，因為單靠抱怨不能改變習慣。"},{"en":"Good solutions should be specific, manageable, and easy to follow.","zh":"好解決方案應具體、可管理並容易遵循。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"be introduced","meaning":"被引入；被推行","examples":[{"en":"A healthier communication policy should be introduced.","zh":"應推行更健康的溝通政策。"},{"en":"To be introduced means to be officially started or put into use.","zh":"被引入或被推行意思是正式開始或投入使用。"},{"en":"A company may introduce a new leave system next month.","zh":"公司可能下月推行新的假期制度。"},{"en":"Introducing a policy makes expectations clearer for everyone.","zh":"推行政策能令每個人的期望更清晰。"},{"en":"New rules should be explained carefully when they are introduced.","zh":"新規則被推行時應仔細解釋。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"each department","meaning":"每個部門","examples":[{"en":"Each department should hold a weekly workload check.","zh":"每個部門應進行每週工作量檢查。"},{"en":"Each department means every team or section within a company.","zh":"每個部門意思是公司內每一個團隊或分部。"},{"en":"Finance, marketing, customer service, and human resources are departments.","zh":"財務、市場推廣、客戶服務和人力資源都是部門。"},{"en":"Each department may face different overtime causes.","zh":"每個部門可能面對不同加班原因。"},{"en":"Department-level checks make solutions more specific and useful.","zh":"部門層面的檢查令解決方法更具體和有用。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"weekly workload check","meaning":"每週工作量檢查","examples":[{"en":"A weekly workload check would help teams set priorities.","zh":"每週工作量檢查有助團隊設定優先次序。"},{"en":"A weekly workload check is a regular review of tasks, deadlines, and staff capacity.","zh":"每週工作量檢查是定期檢視任務、截止日期和員工承受能力。"},{"en":"Managers can use a workload check to see who is overloaded.","zh":"經理可以用工作量檢查看見誰工作過重。"},{"en":"Weekly checks help prevent last-minute pressure from building unnoticed.","zh":"每週檢查有助防止臨時壓力在無人察覺下累積。"},{"en":"A workload check turns overtime from a private problem into a team issue.","zh":"工作量檢查把加班由私人問題變成團隊問題。"}],"source":"2013 Q6.pdf","sourcePage":10},{"front":"separate urgent work from work that can wait","meaning":"區分緊急工作和可等待的工作","examples":[{"en":"Teams should separate urgent work from work that can wait.","zh":"團隊應區分緊急工作和可等待的工作。"},{"en":"This means deciding which tasks truly need immediate action and which do not.","zh":"這意思是決定哪些任務真正需要立即處理，哪些不需要。"},{"en":"A client crisis may be urgent, while a routine update can wait until tomorrow.","zh":"客戶危機可能緊急，而例行更新可以等到明天。"},{"en":"Clear separation prevents every task from feeling like an emergency.","zh":"清楚區分能防止每項任務都感覺像緊急事件。"},{"en":"Better priority setting helps staff leave on time more often.","zh":"更好的優先次序設定有助員工更常準時下班。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"be grouped into","meaning":"被分成","examples":[{"en":"Tasks should be grouped into clear categories.","zh":"任務應被分成清晰類別。"},{"en":"To be grouped into means to be sorted into different sets.","zh":"被分成意思是被分類到不同組別中。"},{"en":"Work can be grouped into urgent, weekly, and postponed tasks.","zh":"工作可以被分成緊急、本週內和可延後任務。"},{"en":"Grouping tasks helps people understand what matters first.","zh":"分類任務幫助人們理解甚麼最重要。"},{"en":"Clear groups reduce confusion and unnecessary overtime.","zh":"清晰分類能減少混亂和不必要加班。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"must finish today","meaning":"今日必須完成","examples":[{"en":"Some tasks must finish today.","zh":"有些任務今日必須完成。"},{"en":"Must finish today means the task has to be completed before the day ends.","zh":"今日必須完成意思是任務必須在當日結束前完成。"},{"en":"A legal filing or urgent client reply may have to finish today.","zh":"法律文件提交或緊急客戶回覆可能今日必須完成。"},{"en":"Clear “must finish today” tasks help employees focus on real deadlines.","zh":"清楚列出今日必須完成的任務，有助員工專注真正期限。"},{"en":"Not every task should be placed in this category.","zh":"不是每項任務都應放入這個類別。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"can finish this week","meaning":"本週內可完成","examples":[{"en":"Some tasks can finish this week.","zh":"有些任務本週內可完成。"},{"en":"Can finish this week means the task should be completed within the week, not necessarily today.","zh":"本週內可完成意思是任務應在本週完成，但不一定今天完成。"},{"en":"A routine report may finish this week if it is not urgent.","zh":"如果例行報告不緊急，就可以本週內完成。"},{"en":"This category reduces pressure by separating weekly work from immediate work.","zh":"這個類別透過區分本週工作和即時工作來減少壓力。"},{"en":"Staff can plan better when they know what can finish this week.","zh":"當員工知道甚麼本週內可完成，他們能更好規劃。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"can be postponed","meaning":"可以延後","examples":[{"en":"Some tasks can be postponed.","zh":"有些任務可以延後。"},{"en":"Can be postponed means can be delayed until a later time.","zh":"可以延後意思是可以推遲到較後時間處理。"},{"en":"A non-urgent design update can be postponed until the next working day.","zh":"非緊急設計更新可以延後到下一個工作天。"},{"en":"Postponing low-priority work protects time for urgent tasks and rest.","zh":"延後低優先次序工作能保護緊急任務和休息的時間。"},{"en":"Clear permission to postpone helps employees avoid unnecessary overtime.","zh":"清楚容許延後，有助員工避免不必要加班。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"be assigned after 5 p.m.","meaning":"下午五時後被分派","examples":[{"en":"If a task is assigned after 5 p.m., its urgency should be clarified.","zh":"如果任務在下午五時後被分派，應澄清其緊急程度。"},{"en":"Assigned after 5 p.m. means given to someone near the end of the workday.","zh":"下午五時後被分派意思是在工作日接近結束時才交給某人。"},{"en":"A task assigned after 5 p.m. may force overtime if no priority is explained.","zh":"如果下午五時後被分派的任務沒有說明優先次序，可能迫使員工加班。"},{"en":"Late tasks should come with clear instructions about whether they can wait.","zh":"較遲分派的任務應附有清晰指示，說明是否可以等待。"},{"en":"This rule protects staff from unnecessary evening pressure.","zh":"這條規則保護員工免受不必要的晚上壓力。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"clarify whether","meaning":"澄清是否","examples":[{"en":"The manager should clarify whether the task is genuinely urgent.","zh":"經理應澄清任務是否真正緊急。"},{"en":"To clarify whether means to make it clear if something is true or not.","zh":"澄清是否意思是清楚說明某事是否真實或成立。"},{"en":"A supervisor should clarify whether a report is needed tonight or tomorrow morning.","zh":"主管應澄清報告是今晚需要，還是明早需要。"},{"en":"Clarifying urgency prevents staff from guessing and staying late unnecessarily.","zh":"澄清緊急程度能防止員工猜測並不必要地遲下班。"},{"en":"Clear communication saves time and reduces stress.","zh":"清晰溝通能節省時間並減少壓力。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"genuinely urgent","meaning":"真正緊急","examples":[{"en":"Not every late task is genuinely urgent.","zh":"不是每項遲來的任務都真正緊急。"},{"en":"Genuinely urgent means truly needing immediate attention.","zh":"真正緊急意思是確實需要立即處理。"},{"en":"A system failure may be genuinely urgent, but a routine update may not be.","zh":"系統故障可能真正緊急，但例行更新未必如此。"},{"en":"Calling everything urgent weakens people’s ability to identify real emergencies.","zh":"把所有事情都稱為緊急，會削弱人辨認真正緊急事件的能力。"},{"en":"Managers should label tasks genuinely urgent only when they truly are.","zh":"經理只應在任務確實如此時，才把它標為真正緊急。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"otherwise","meaning":"否則","examples":[{"en":"Otherwise, the task should be scheduled for the next working day.","zh":"否則，任務應安排在下一個工作天處理。"},{"en":"Otherwise means if not or in the other situation.","zh":"否則意思是如果不是這樣，或在另一種情況下。"},{"en":"If the task is not urgent, otherwise it should wait until tomorrow.","zh":"如果任務不緊急，否則它應等到明天。"},{"en":"This word helps separate one condition from another result.","zh":"這個詞幫助區分一個條件和另一個結果。"},{"en":"Otherwise gives staff permission not to treat every late task as an emergency.","zh":"否則給員工空間，不必把每項遲來任務都當成緊急事件。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"the next working day","meaning":"下一個工作天","examples":[{"en":"Non-urgent tasks should wait until the next working day.","zh":"非緊急任務應等到下一個工作天。"},{"en":"The next working day means the next day when people normally work.","zh":"下一個工作天意思是下一個正常工作的日子。"},{"en":"A Friday evening email may wait until Monday if the next working day is Monday.","zh":"如果下一個工作天是星期一，星期五晚上的電郵可以等到星期一。"},{"en":"Scheduling non-urgent work for the next working day protects rest time.","zh":"把非緊急工作安排到下一個工作天，可以保護休息時間。"},{"en":"Clear use of the next working day reduces after-hours pressure.","zh":"清楚使用下一個工作天的安排，能減少非辦公時間壓力。"}],"source":"2013 Q6.pdf","sourcePage":11},{"front":"plan ahead","meaning":"預先計劃","examples":[{"en":"A workload check helps teams plan ahead.","zh":"工作量檢查幫助團隊預先計劃。"},{"en":"To plan ahead means to prepare before problems or deadlines arrive.","zh":"預先計劃意思是在問題或截止日期到來前準備。"},{"en":"Managers plan ahead when they assign tasks before the final afternoon.","zh":"經理在最後一個下午前分派任務，就是預先計劃。"},{"en":"Planning ahead reduces last-minute pressure and unnecessary overtime.","zh":"預先計劃能減少臨時壓力和不必要加班。"},{"en":"Teams work more calmly when they plan ahead together.","zh":"團隊一起預先計劃時，工作會更冷靜。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"distribute work fairly","meaning":"公平分配工作","examples":[{"en":"Managers should distribute work fairly across the team.","zh":"經理應在團隊中公平分配工作。"},{"en":"To distribute work fairly means to share tasks in a balanced and reasonable way.","zh":"公平分配工作意思是以平衡和合理方式分擔任務。"},{"en":"A manager should not give every urgent task to the same reliable employee.","zh":"經理不應把每項緊急任務都交給同一位可靠員工。"},{"en":"Fair distribution prevents burnout and resentment.","zh":"公平分配能防止倦怠和不滿。"},{"en":"Workload checks help managers distribute work fairly before pressure builds.","zh":"工作量檢查幫助經理在壓力累積前公平分配工作。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"prevent last-minute pressure","meaning":"防止臨時壓力","examples":[{"en":"Better planning can prevent last-minute pressure.","zh":"更好規劃可以防止臨時壓力。"},{"en":"To prevent last-minute pressure means to stop stress from appearing just before a deadline.","zh":"防止臨時壓力意思是阻止壓力在截止時間前才突然出現。"},{"en":"Sending instructions early prevents staff from rushing at 6 p.m.","zh":"及早發出指示可以防止員工在晚上六點匆忙趕工。"},{"en":"Last-minute pressure often causes mistakes and unnecessary overtime.","zh":"臨時壓力常造成錯誤和不必要加班。"},{"en":"Teams prevent it by setting priorities before the day is almost over.","zh":"團隊透過在一天快結束前設定優先次序來防止它。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"fall on the same people","meaning":"落在同一批人身上","examples":[{"en":"Last-minute pressure should not fall on the same people again and again.","zh":"臨時壓力不應一再落在同一批人身上。"},{"en":"To fall on the same people means to repeatedly become the responsibility of the same group.","zh":"落在同一批人身上意思是反覆成為同一群人的責任。"},{"en":"Urgent work may fall on the most reliable staff if managers do not distribute tasks fairly.","zh":"如果經理沒有公平分配工作，緊急工作可能落在最可靠的員工身上。"},{"en":"This pattern creates resentment because some people carry more burden than others.","zh":"這種模式會造成不滿，因為有些人承擔更多負擔。"},{"en":"Fair planning stops overtime from falling on the same employees.","zh":"公平規劃能防止加班總落在同一批員工身上。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"again and again","meaning":"一再；反覆地","examples":[{"en":"The same people should not be asked to stay late again and again.","zh":"不應一再要求同一批人遲下班。"},{"en":"Again and again means repeatedly or many times.","zh":"一再或反覆地意思是重複很多次。"},{"en":"If one colleague fixes every urgent problem again and again, they may burn out.","zh":"如果同一位同事反覆處理每個緊急問題，他可能會倦怠。"},{"en":"Repeated pressure feels unfair even when each request seems small.","zh":"即使每次要求看似細小，重複壓力也會令人覺得不公平。"},{"en":"A healthy team shares responsibility instead of asking the same people again and again.","zh":"健康團隊會分擔責任，而不是一再要求同一批人承受。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"after-hours communication policy","meaning":"非辦公時間溝通政策","examples":[{"en":"The company should create an after-hours communication policy.","zh":"公司應制定非辦公時間溝通政策。"},{"en":"An after-hours communication policy sets rules for messages outside normal working time.","zh":"非辦公時間溝通政策為正常工作時間以外的訊息設定規則。"},{"en":"Such a policy may say non-urgent emails do not require evening replies.","zh":"這類政策可能說明非緊急電郵不要求晚上回覆。"},{"en":"It protects rest by clarifying when staff must respond and when they need not.","zh":"它透過澄清員工何時必須回應、何時不必回應來保護休息。"},{"en":"A clear policy reduces guilt, guessing, and silent pressure.","zh":"清晰政策能減少內疚、猜測和不明言壓力。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"unless there is a real emergency","meaning":"除非有真正緊急情況","examples":[{"en":"Unless there is a real emergency, staff should not need to reply after hours.","zh":"除非有真正緊急情況，員工不應需要在非辦公時間回覆。"},{"en":"Unless there is a real emergency means except when a truly urgent problem happens.","zh":"除非有真正緊急情況意思是只有在真正急事發生時例外。"},{"en":"A client system failure may be a real emergency; a routine update is not.","zh":"客戶系統故障可能是真正緊急情況；例行更新不是。"},{"en":"This condition protects staff while still allowing urgent action.","zh":"這個條件保護員工，同時仍容許緊急行動。"},{"en":"Clear emergency rules prevent every message from feeling urgent.","zh":"清晰緊急規則能防止每則訊息都感覺緊急。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"non-urgent emails and messages","meaning":"非緊急電郵和訊息","examples":[{"en":"Non-urgent emails and messages should wait until office hours.","zh":"非緊急電郵和訊息應等到辦公時間處理。"},{"en":"Non-urgent emails and messages are communications that do not need immediate action.","zh":"非緊急電郵和訊息是不需要立即行動的溝通。"},{"en":"A routine meeting reminder is usually non-urgent.","zh":"例行會議提醒通常是非緊急訊息。"},{"en":"Waiting until office hours protects employees’ evenings and sleep.","zh":"等到辦公時間能保護員工晚間時間和睡眠。"},{"en":"Teams should label urgent messages clearly so non-urgent ones can wait.","zh":"團隊應清楚標示緊急訊息，讓非緊急訊息可以等待。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"require replies after office hours","meaning":"要求在辦公時間後回覆","examples":[{"en":"Non-urgent messages should not require replies after office hours.","zh":"非緊急訊息不應要求在辦公時間後回覆。"},{"en":"To require replies after office hours means to expect people to answer after normal work time.","zh":"要求在辦公時間後回覆，意思是期望人在正常工作時間後作答。"},{"en":"A late email should not require a reply at night if it can wait until morning.","zh":"如果深夜電郵可以等到早上，就不應要求晚上回覆。"},{"en":"Requiring replies after hours turns rest time into work time.","zh":"要求下班後回覆會把休息時間變成工作時間。"},{"en":"A clear policy can stop non-urgent messages from demanding instant replies.","zh":"清晰政策可以防止非緊急訊息要求即時回覆。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"office hours","meaning":"辦公時間","examples":[{"en":"Staff should not be expected to reply after office hours.","zh":"不應期望員工在辦公時間後回覆。"},{"en":"Office hours are the usual hours during which people are expected to work.","zh":"辦公時間是人們通常被期望工作的時段。"},{"en":"For many offices, office hours may run from morning to early evening.","zh":"對許多辦公室來說，辦公時間可能由早上到傍晚。"},{"en":"Messages outside office hours should be handled carefully to protect rest.","zh":"辦公時間外的訊息應謹慎處理，以保護休息。"},{"en":"Respecting office hours helps create healthier boundaries.","zh":"尊重辦公時間有助建立更健康界線。"}],"source":"2013 Q6.pdf","sourcePage":12},{"front":"model this","meaning":"以身作則示範這一點","examples":[{"en":"Managers should model this behaviour by leaving on time.","zh":"經理應透過準時下班以身作則示範這一點。"},{"en":"To model this means to show the behaviour as an example for others to follow.","zh":"以身作則示範這一點意思是把某種行為展示出來，讓別人跟隨。"},{"en":"A manager models healthy boundaries when they schedule emails instead of sending them at midnight.","zh":"經理安排電郵翌日發送而不是午夜發出，就是示範健康界線。"},{"en":"Staff learn more from what leaders do than from policy words alone.","zh":"員工從領導者行為學到的，比單靠政策文字更多。"},{"en":"Managers must model this if they want employees to believe the change is real.","zh":"如果經理想員工相信改變是真的，就必須以身作則。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"leave on time","meaning":"準時下班","examples":[{"en":"Managers should leave on time where possible.","zh":"經理應在可行情況下準時下班。"},{"en":"To leave on time means to finish work and go home at the expected time.","zh":"準時下班意思是在預期時間完成工作並回家。"},{"en":"A team leader who leaves on time shows that rest is acceptable.","zh":"準時下班的團隊主管顯示休息是可接受的。"},{"en":"Leaving on time should not be treated as lack of commitment.","zh":"準時下班不應被視為缺乏投入。"},{"en":"When leaders leave on time, junior staff feel safer doing the same.","zh":"當領導者準時下班，初級員工也會更安心照做。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"where possible","meaning":"在可行情況下","examples":[{"en":"Managers should leave on time where possible.","zh":"經理應在可行情況下準時下班。"},{"en":"Where possible means whenever the situation allows it.","zh":"在可行情況下意思是在情況容許時。"},{"en":"Staff should schedule non-urgent messages for the next morning where possible.","zh":"在可行情況下，員工應安排非緊急訊息翌日早上發出。"},{"en":"This phrase is realistic because some urgent work cannot be avoided.","zh":"這個短語很現實，因為有些緊急工作無法避免。"},{"en":"Where possible, healthy habits should be practised by leaders first.","zh":"在可行情況下，健康習慣應由領導者先實踐。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"schedule emails for the next morning","meaning":"安排電郵於翌日早上發送","examples":[{"en":"Managers can schedule emails for the next morning.","zh":"經理可以安排電郵於翌日早上發送。"},{"en":"To schedule emails for the next morning means to set emails to be sent the following morning instead of immediately.","zh":"安排電郵於翌日早上發送，意思是設定電郵在第二天早上才發出，而不是立即發出。"},{"en":"A manager may write an email at night but schedule it for 9 a.m.","zh":"經理可能晚上寫電郵，但安排它早上九點發送。"},{"en":"This practice reduces pressure on staff to reply after hours.","zh":"這種做法能減少員工下班後回覆的壓力。"},{"en":"Scheduled emails show respect for boundaries while keeping work organised.","zh":"預設發送電郵顯示尊重界線，同時保持工作有序。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"late work is unavoidable","meaning":"加班無法避免","examples":[{"en":"Where late work is unavoidable, staff should record it.","zh":"在加班無法避免的情況下，員工應記錄下來。"},{"en":"Late work is unavoidable means working after hours cannot reasonably be avoided in that situation.","zh":"加班無法避免意思是在該情況下，下班後工作不能合理避免。"},{"en":"A sudden client emergency may make late work unavoidable.","zh":"突發客戶緊急情況可能令加班無法避免。"},{"en":"Unavoidable overtime should be recorded so it does not disappear into silence.","zh":"無法避免的加班應被記錄，避免它在沉默中消失。"},{"en":"Recording unavoidable late work helps companies provide fair compensation or recovery time.","zh":"記錄無法避免的加班，有助公司提供公平補償或恢復時間。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"record it","meaning":"記錄下來","examples":[{"en":"Staff should record unavoidable late work.","zh":"員工應把無法避免的加班記錄下來。"},{"en":"To record it means to write it down or enter it into a system.","zh":"記錄下來意思是寫低或輸入系統。"},{"en":"An employee may record late work by noting the date, hours, and reason.","zh":"員工可以記錄日期、時數和原因來記錄加班。"},{"en":"Recording overtime helps management see repeated patterns.","zh":"記錄加班有助管理層看見重複模式。"},{"en":"If late work is not recorded, the problem becomes invisible.","zh":"如果加班沒有被記錄，問題就會變得看不見。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"time off in lieu","meaning":"補假","examples":[{"en":"Staff should receive time off in lieu for late work.","zh":"員工應因遲下班而獲得補假。"},{"en":"Time off in lieu means paid time away from work given instead of extra pay for overtime.","zh":"補假是指以有薪休息時間代替加班額外薪酬。"},{"en":"An employee who works three extra hours may receive three hours off later.","zh":"員工額外工作三小時，之後可能獲得三小時補假。"},{"en":"Time off in lieu recognises that extra work uses personal time.","zh":"補假承認額外工作使用了個人時間。"},{"en":"This arrangement helps late work remain fair and sustainable.","zh":"這種安排有助令加班保持公平和可持續。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"adjusted deadlines","meaning":"調整後的截止日期","examples":[{"en":"Staff may receive adjusted deadlines after unavoidable overtime.","zh":"員工在無法避免的加班後，可能獲得調整後的截止日期。"},{"en":"Adjusted deadlines are new deadlines changed to reflect extra work or new circumstances.","zh":"調整後的截止日期是因額外工作或新情況而改變的新期限。"},{"en":"If an employee worked late on Monday, Tuesday’s deadline may be adjusted.","zh":"如果員工星期一遲下班，星期二的截止日期可能需要調整。"},{"en":"Adjusted deadlines help workers recover instead of being punished for helping.","zh":"調整後的期限幫助工作者恢復，而不是因幫忙而被懲罰。"},{"en":"Deadlines should change when workload and rest needs change.","zh":"當工作量和休息需要改變，截止日期也應改變。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"lowering standards","meaning":"降低標準","examples":[{"en":"This policy is not about lowering standards.","zh":"這項政策並不是關於降低標準。"},{"en":"Lowering standards means reducing the expected quality or level of work.","zh":"降低標準意思是降低預期的工作質素或水平。"},{"en":"Leaving on time does not mean lowering standards if priorities are clear.","zh":"如果優先次序清晰，準時下班不代表降低標準。"},{"en":"A company can protect rest while still demanding careful work.","zh":"公司可以保護休息，同時仍要求仔細工作。"},{"en":"The goal is not lower standards, but sustainable high standards.","zh":"目標不是降低標準，而是令高標準可持續。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"high standards","meaning":"高標準","examples":[{"en":"The company can keep high standards without excessive overtime.","zh":"公司可以在沒有過度加班的情況下保持高標準。"},{"en":"High standards are strong expectations for quality, accuracy, and responsibility.","zh":"高標準是對質素、準確度和責任的高要求。"},{"en":"A team with high standards checks work carefully and communicates clearly.","zh":"有高標準的團隊會仔細檢查工作並清楚溝通。"},{"en":"High standards fail when employees are too tired to meet them.","zh":"當員工太疲倦而無法達到要求時，高標準就會失效。"},{"en":"Sustainable systems help staff maintain high standards over time.","zh":"可持續制度幫助員工長期保持高標準。"}],"source":"2013 Q6.pdf","sourcePage":13},{"front":"make high standards sustainable","meaning":"令高標準可以持續","examples":[{"en":"The aim is to make high standards sustainable.","zh":"目標是令高標準可以持續。"},{"en":"To make high standards sustainable means to keep quality high without exhausting people.","zh":"令高標準可以持續意思是在不耗盡人的情況下保持高質素。"},{"en":"Better planning makes high standards sustainable by reducing rushed overtime.","zh":"更好規劃透過減少匆忙加班，令高標準可以持續。"},{"en":"Sustainable standards depend on rest, clear priorities, and fair workloads.","zh":"可持續標準取決於休息、清晰優先次序和公平工作量。"},{"en":"A company succeeds when excellence can continue without burning people out.","zh":"當卓越表現能持續而不令人倦怠，公司才算成功。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, late departures should be treated as a warning sign.","zh":"總括而言，遲下班應被視為警號。"},{"en":"All things considered means after thinking about all important points together.","zh":"總括而言意思是在一起考慮所有重要觀點後。"},{"en":"All things considered, constant overtime harms both people and performance.","zh":"總括而言，長期加班會傷害人和工作表現。"},{"en":"Writers use this phrase to introduce a final balanced judgement.","zh":"作者使用這個短語來引出平衡的最終判斷。"},{"en":"It shows that the conclusion considers efficiency, culture, and health.","zh":"它顯示結論考慮了效率、文化和健康。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"the time has come to","meaning":"是時候","examples":[{"en":"The time has come to review our overtime culture.","zh":"是時候檢討我們的加班文化了。"},{"en":"The time has come to means now is the right moment to do something.","zh":"是時候做某事，意思是現在是做某事的合適時刻。"},{"en":"The time has come to set clear rules about after-hours messages.","zh":"是時候就非辦公時間訊息制定清晰規則了。"},{"en":"This phrase creates a sense of urgency and responsibility.","zh":"這個短語營造迫切感和責任感。"},{"en":"It suggests that waiting longer would allow the problem to deepen.","zh":"它暗示再等待只會令問題加深。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"late departures","meaning":"遲下班","examples":[{"en":"Late departures should not become a trophy.","zh":"遲下班不應變成值得炫耀的獎盃。"},{"en":"Late departures are occasions when employees leave work after the normal finishing time.","zh":"遲下班是員工在正常下班時間後才離開工作的情況。"},{"en":"Many late departures in one department may show a workload problem.","zh":"一個部門經常遲下班，可能顯示工作量問題。"},{"en":"Late departures should be recorded and reviewed, not celebrated.","zh":"遲下班應被記錄和檢討，而不是被慶祝。"},{"en":"A company should ask why departures are late before praising dedication.","zh":"公司在稱讚投入前，應先問為何大家遲下班。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"warning sign","meaning":"警號","examples":[{"en":"Repeated overtime is a warning sign.","zh":"重複加班是一個警號。"},{"en":"A warning sign is something that shows a possible problem before it becomes worse.","zh":"警號是在問題惡化前顯示可能有問題的跡象。"},{"en":"Staff leaving late every night is a warning sign of poor workload planning.","zh":"員工每晚遲下班，是工作量規劃不善的警號。"},{"en":"Warning signs should be investigated, not ignored.","zh":"警號應被調查，而不是忽視。"},{"en":"Treating overtime as a warning sign helps protect people before damage grows.","zh":"把加班視為警號，有助在傷害擴大前保護人。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"not a trophy","meaning":"不是值得炫耀的獎盃","examples":[{"en":"Leaving late should be treated as a warning sign, not a trophy.","zh":"遲下班應被視為警號，而不是值得炫耀的獎盃。"},{"en":"Not a trophy means not something to celebrate, admire, or display proudly.","zh":"不是值得炫耀的獎盃，意思是不是應被慶祝、欣賞或自豪展示的事。"},{"en":"Staying until midnight is not a trophy if it damages health and accuracy.","zh":"如果損害健康和準確度，留到午夜也不是值得炫耀的獎盃。"},{"en":"Praising late departures can make harmful habits look successful.","zh":"稱讚遲下班會令有害習慣看似成功。"},{"en":"A healthy workplace celebrates good results, not unnecessary exhaustion.","zh":"健康工作場所慶祝好成果，而不是不必要疲憊。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"clearer priorities","meaning":"更清晰的優先次序","examples":[{"en":"Clearer priorities can reduce unnecessary overtime.","zh":"更清晰的優先次序可以減少不必要加班。"},{"en":"Clearer priorities are better-defined decisions about what matters most.","zh":"更清晰的優先次序是更明確地決定甚麼最重要。"},{"en":"A team with clearer priorities knows which tasks must finish today.","zh":"有更清晰優先次序的團隊知道哪些任務今日必須完成。"},{"en":"Unclear priorities make employees treat every task as urgent.","zh":"不清晰的優先次序會令員工把每項任務都當成緊急。"},{"en":"Clear priorities help people work calmly and leave on time.","zh":"清晰優先次序幫助人冷靜工作並準時下班。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"healthier boundaries","meaning":"更健康的界線","examples":[{"en":"Healthier boundaries can protect staff well-being.","zh":"更健康的界線可以保護員工身心健康。"},{"en":"Healthier boundaries are clearer limits between work time and personal time.","zh":"更健康的界線是工作時間和私人時間之間更清晰的限制。"},{"en":"A rule against non-urgent night messages creates healthier boundaries.","zh":"禁止非緊急夜間訊息的規則能建立更健康界線。"},{"en":"Boundaries protect people from feeling always available.","zh":"界線保護人們，避免他們覺得自己永遠要待命。"},{"en":"Healthier boundaries make long-term performance more possible.","zh":"更健康界線令長遠工作表現更有可能維持。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"build a workplace where","meaning":"建立一個……的工作場所","examples":[{"en":"The company should build a workplace where commitment is measured by results.","zh":"公司應建立一個以成果衡量投入程度的工作場所。"},{"en":"To build a workplace where something happens means to create a work culture with that quality.","zh":"建立一個某事會發生的工作場所，意思是創造具有該特質的工作文化。"},{"en":"A company can build a workplace where people leave on time without guilt.","zh":"公司可以建立一個人們準時下班而不內疚的工作場所。"},{"en":"Building such a workplace requires rules, leadership, and daily examples.","zh":"建立這樣的工作場所需要規則、領導和日常示範。"},{"en":"A better workplace measures contribution fairly and protects human limits.","zh":"更好的工作場所會公平衡量貢獻，並保護人的限制。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"measured not by...but by...","meaning":"不是以……而是以……衡量","examples":[{"en":"Commitment should be measured not by the hour people leave, but by work quality.","zh":"投入程度不是以人們幾點離開衡量，而是以工作質素衡量。"},{"en":"This structure contrasts the wrong standard with the better standard.","zh":"這個結構把錯誤標準和更好標準作對比。"},{"en":"A student’s effort should be measured not by study hours alone, but by understanding.","zh":"學生的努力不應只以溫習時間衡量，而應以理解程度衡量。"},{"en":"In the workplace, leaving time is a poor measure of real contribution.","zh":"在工作場所，離開時間是衡量真正貢獻的差劣標準。"},{"en":"This phrase helps argue for results instead of visibility.","zh":"這個短語幫助主張重視成果，而不是能見度。"}],"source":"2013 Q6.pdf","sourcePage":14},{"front":"the quality of the work","meaning":"工作質素","examples":[{"en":"Commitment should be measured by the quality of the work.","zh":"投入程度應以工作質素衡量。"},{"en":"The quality of the work means how accurate, useful, careful, and effective the work is.","zh":"工作質素是指工作有多準確、有用、仔細和有效。"},{"en":"A short report can show high quality if it is clear and well researched.","zh":"如果報告清晰並有充分研究，即使簡短也可以有高工作質素。"},{"en":"Work quality often falls when employees are exhausted.","zh":"當員工疲憊時，工作質素常會下降。"},{"en":"Measuring quality encourages smarter work rather than longer presence.","zh":"衡量工作質素會鼓勵更聰明地工作，而不是更長時間在場。"}],"source":"2013 Q6.pdf","sourcePage":15},{"front":"be able to do","meaning":"能夠做到","examples":[{"en":"Staff do better work when they are able to rest properly.","zh":"當員工能夠好好休息時，他們會做出更好的工作。"},{"en":"Be able to do something means to have the chance, ability, or conditions to do it.","zh":"能夠做到某事，意思是有機會、能力或條件去做它。"},{"en":"Employees are able to focus better when meetings do not fill the whole day.","zh":"當會議沒有佔滿整天，員工就能夠更好地專注。"},{"en":"People cannot do their best work if they are not able to recover.","zh":"如果人們不能夠恢復，他們就無法做到最佳表現。"},{"en":"A good workplace helps staff be able to work well and live well.","zh":"好工作場所幫助員工既能夠好好工作，也能夠好好生活。"}],"source":"2013 Q6.pdf","sourcePage":15}],"dse/writing/part-b/2013/Q7":[{"front":"local screens","meaning":"本地螢幕","examples":[{"en":"Asian stars have moved from local screens to global stages.","zh":"亞洲明星已從本地螢幕走上全球舞台。"},{"en":"“Local screens” refers to television, cinema or online media mainly watched within one country or region.","zh":"「local screens」指主要由某個國家或地區觀眾觀看的電視、電影或網上媒體。"},{"en":"An actor may first become famous on local screens before international audiences discover them.","zh":"一位演員可能先在本地螢幕成名，之後才被國際觀眾發現。"},{"en":"Streaming platforms help performers move beyond local screens more quickly than before.","zh":"串流平台令表演者比以前更快突破本地螢幕的限制。"},{"en":"Success on local screens can become the first step towards a global career.","zh":"在本地螢幕取得成功，可以成為走向全球事業的第一步。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"global stages","meaning":"全球舞台","examples":[{"en":"Asian stars are now appearing on global stages.","zh":"亞洲明星現在正出現在全球舞台。"},{"en":"“Global stages” refers to international platforms, events and media where performers reach audiences around the world.","zh":"「global stages」指能讓表演者接觸世界各地觀眾的國際平台、活動和媒體。"},{"en":"A singer may move from small local concerts to global stages such as major award shows.","zh":"歌手可能由本地小型演唱會走上大型頒獎禮等全球舞台。"},{"en":"Streaming and social media have made global stages more accessible to artists from different countries.","zh":"串流和社交媒體令不同國家的藝人更容易走上全球舞台。"},{"en":"Appearing on global stages means an artist’s work is no longer limited to one national audience.","zh":"走上全球舞台表示藝人的作品不再局限於單一國家的觀眾。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"win Western hearts","meaning":"贏得西方觀眾的心","examples":[{"en":"Asian stars are winning Western hearts.","zh":"亞洲明星正在贏得西方觀眾的心。"},{"en":"To win Western hearts means to become loved, admired or emotionally accepted by audiences in Western countries.","zh":"贏得西方觀眾的心表示受到西方國家觀眾喜愛、欣賞和情感上的接受。"},{"en":"A moving performance can win Western hearts even when the language is unfamiliar.","zh":"即使語言陌生，一場感人的演出仍可以贏得西方觀眾的心。"},{"en":"Asian stars win Western hearts through memorable stories, music and personalities.","zh":"亞洲明星透過難忘的故事、音樂和個人魅力贏得西方觀眾的心。"},{"en":"Winning people’s hearts involves emotional connection, not just becoming famous.","zh":"贏得人心關乎情感連結，而不只是變得有名。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"in recent years","meaning":"近年","examples":[{"en":"In recent years, Asian entertainment has become popular in Western countries.","zh":"近年，亞洲娛樂在西方國家變得受歡迎。"},{"en":"“In recent years” means during the last several years leading up to the present.","zh":"「in recent years」表示由過去數年至現在這段時間。"},{"en":"In recent years, more students have used online platforms for learning.","zh":"近年，更多學生使用網上平台學習。"},{"en":"In recent years, international audiences have gained easier access to Asian films and music.","zh":"近年，國際觀眾更容易接觸亞洲電影和音樂。"},{"en":"This phrase is useful when describing a relatively new trend that has developed over time.","zh":"這個片語適合描述近年逐步形成的新趨勢。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"it has become normal for","meaning":"……已變得平常","examples":[{"en":"It has become normal for a student in London to hum a Korean chorus.","zh":"倫敦學生哼唱韓文副歌已變得平常。"},{"en":"“It has become normal for” means something that once seemed unusual is now common and socially ordinary.","zh":"「it has become normal for」表示以前看似不尋常的事情，現在已變得常見和普通。"},{"en":"It has become normal for office workers to attend meetings online.","zh":"上班族參加網上會議已變得平常。"},{"en":"It has become normal for Western teenagers to know songs in languages they do not speak.","zh":"西方青少年熟悉自己不會說的語言歌曲，現在已變得平常。"},{"en":"This structure highlights how social habits and expectations have changed.","zh":"這個句式突出社會習慣和期望如何改變。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"hum a Korean chorus","meaning":"哼唱韓文副歌","examples":[{"en":"A student in London may hum a Korean chorus.","zh":"倫敦的學生可能會哼唱韓文副歌。"},{"en":"To hum a Korean chorus means to quietly sing the tune of the repeated section of a Korean song without necessarily saying all the words clearly.","zh":"哼唱韓文副歌是指輕聲哼出韓文歌曲中重複部分的旋律，不一定清楚唱出所有歌詞。"},{"en":"She hummed the chorus while walking to school because the melody was stuck in her head.","zh":"那段旋律一直留在她腦海，所以她上學途中不斷哼副歌。"},{"en":"A listener may hum a Korean chorus even without understanding every word.","zh":"即使不明白每個字，聽眾也可以哼唱韓文副歌。"},{"en":"Humming a foreign-language song shows how music can cross language barriers.","zh":"哼唱外語歌曲顯示音樂可以跨越語言障礙。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"Korean chorus","meaning":"韓文副歌","examples":[{"en":"A Korean chorus may be familiar to Western teenagers.","zh":"韓文副歌對西方青少年來說可能很熟悉。"},{"en":"A Korean chorus is the repeated main section of a song sung partly or entirely in Korean.","zh":"韓文副歌是歌曲中重複出現、部分或全部以韓文演唱的主要段落。"},{"en":"The Korean chorus was easy to remember because of its strong rhythm.","zh":"那段韓文副歌節奏強烈，所以很容易記住。"},{"en":"Fans may learn a Korean chorus before understanding the verses.","zh":"粉絲可能先學會韓文副歌，之後才理解主歌內容。"},{"en":"Repeated exposure can make a foreign-language chorus feel familiar.","zh":"反覆接觸可以令外語副歌變得熟悉。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"Japanese animation","meaning":"日本動畫","examples":[{"en":"An American family may discuss Japanese animation.","zh":"一個美國家庭可能會討論日本動畫。"},{"en":"Japanese animation refers to animated films and television works created in Japan, often called anime internationally.","zh":"日本動畫是指在日本製作的動畫電影和電視作品，在國際上常稱為anime。"},{"en":"Japanese animation includes many genres, from children’s stories to science fiction and drama.","zh":"日本動畫包括很多類型，由兒童故事到科幻和劇情作品都有。"},{"en":"Families may watch Japanese animation because the stories appeal to both children and adults.","zh":"家庭可能觀看日本動畫，因為有些故事同時吸引兒童和成人。"},{"en":"Its international popularity shows that animation can travel across cultural and language boundaries.","zh":"它的國際受歡迎程度顯示動畫可以跨越文化和語言界線。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"quote a line from","meaning":"引用……的一句對白","examples":[{"en":"A French teenager may quote a line from a Korean drama.","zh":"一位法國青少年可能會引用韓劇中的一句對白。"},{"en":"To quote a line from something means to repeat exactly or nearly exactly a sentence spoken or written in that work.","zh":"「quote a line from」表示把某作品中說過或寫過的一句話完全或幾乎原樣重複。"},{"en":"Students often quote a line from a poem when explaining its meaning.","zh":"學生解釋詩歌意思時常引用其中一句。"},{"en":"Fans may quote memorable dialogue from a favourite drama in conversation.","zh":"粉絲在談話中可能引用自己喜歡劇集的難忘對白。"},{"en":"When audiences quote lines from foreign works, it shows those works have entered everyday culture.","zh":"當觀眾會引用外國作品的對白，表示那些作品已進入日常文化。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"Korean drama","meaning":"韓劇","examples":[{"en":"A French teenager may quote a line from a Korean drama.","zh":"一位法國青少年可能會引用韓劇中的一句對白。"},{"en":"A Korean drama is a television or streaming drama series produced in South Korea.","zh":"韓劇是在南韓製作的電視或串流劇集。"},{"en":"Korean dramas often combine romance, family conflict, comedy and social issues.","zh":"韓劇常融合愛情、家庭衝突、喜劇和社會議題。"},{"en":"Streaming platforms have made Korean dramas easier for international audiences to watch.","zh":"串流平台令國際觀眾更容易觀看韓劇。"},{"en":"A popular drama can introduce foreign viewers to Korean language, food and social customs.","zh":"受歡迎的韓劇可以向外國觀眾介紹韓語、食物和社會習俗。"}],"source":"2013 Q7.pdf","sourcePage":1},{"front":"cultural shift","meaning":"文化轉變","examples":[{"en":"This cultural shift has changed Western ideas about entertainment.","zh":"這種文化轉變改變了西方對娛樂的看法。"},{"en":"A cultural shift is a noticeable change in a society’s habits, values, tastes or attitudes.","zh":"文化轉變是社會習慣、價值、品味或態度出現明顯變化。"},{"en":"The growth of online learning represents a cultural shift in education.","zh":"網上學習的增長代表教育上的文化轉變。"},{"en":"Asian entertainment becoming mainstream reflects a cultural shift in what Western audiences accept and enjoy.","zh":"亞洲娛樂進入主流，反映西方觀眾接受和喜愛的內容出現文化轉變。"},{"en":"Cultural shifts usually develop gradually as people encounter new ideas repeatedly.","zh":"文化轉變通常在人們反覆接觸新觀念後逐步形成。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"Western audiences","meaning":"西方觀眾","examples":[{"en":"Western audiences are paying more attention to Asian stars.","zh":"西方觀眾正更加留意亞洲明星。"},{"en":"Western audiences are viewers or listeners mainly from Europe, North America and other societies commonly described as Western.","zh":"西方觀眾主要指來自歐洲、北美和其他通常被視為西方社會的觀眾或聽眾。"},{"en":"Western audiences now encounter more Asian music and films through streaming.","zh":"西方觀眾現在透過串流接觸更多亞洲音樂和電影。"},{"en":"A work may succeed with Western audiences even when it was created in another language.","zh":"即使作品以另一種語言創作，也可以受到西方觀眾歡迎。"},{"en":"Audience tastes are not fixed and can change through greater exposure.","zh":"觀眾品味並非固定，增加接觸後也可以改變。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"reconsider","meaning":"重新思考","examples":[{"en":"This cultural shift has made Western audiences reconsider mainstream entertainment.","zh":"這種文化轉變令西方觀眾重新思考主流娛樂。"},{"en":"To reconsider means to think about something again, often because new information or experience has challenged an earlier belief.","zh":"「reconsider」表示因新資料或經驗挑戰原有看法，而再次思考某件事。"},{"en":"The new evidence made the committee reconsider its decision.","zh":"新證據令委員會重新思考原本的決定。"},{"en":"Exposure to Asian entertainment may make viewers reconsider what counts as mainstream.","zh":"接觸亞洲娛樂可能令觀眾重新思考甚麼才算主流。"},{"en":"Reconsidering an idea does not always mean rejecting it; it means examining it again more carefully.","zh":"重新思考不一定代表否定，而是再次更仔細檢視。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"mainstream entertainment","meaning":"主流娛樂","examples":[{"en":"Audiences are reconsidering what mainstream entertainment means.","zh":"觀眾正在重新思考主流娛樂是甚麼意思。"},{"en":"Mainstream entertainment is media that is widely popular, commercially visible and accepted by large audiences.","zh":"主流娛樂是廣受歡迎、商業曝光高，而且被大量觀眾接受的媒體內容。"},{"en":"Big-budget films and popular television shows are often considered mainstream entertainment.","zh":"大型製作電影和熱門電視節目常被視為主流娛樂。"},{"en":"Streaming has broadened mainstream entertainment by bringing more international works to large audiences.","zh":"串流把更多國際作品帶給大量觀眾，擴闊了主流娛樂的範圍。"},{"en":"What counts as mainstream can change as audience tastes become more diverse.","zh":"隨着觀眾品味更多元，甚麼算主流也可以改變。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"no longer controlled only by","meaning":"不再只由……控制","examples":[{"en":"Fame is no longer controlled only by Hollywood studios.","zh":"名氣不再只由荷里活片廠控制。"},{"en":"“No longer controlled only by” means one group has lost its exclusive power over something.","zh":"「no longer controlled only by」表示某個群體已失去對某件事的獨有控制權。"},{"en":"News is no longer controlled only by printed newspapers.","zh":"新聞不再只由印刷報紙控制。"},{"en":"Online platforms mean global fame is no longer controlled only by traditional Western media companies.","zh":"網上平台令全球名氣不再只由傳統西方傳媒公司控制。"},{"en":"When control becomes more distributed, new voices can reach audiences directly.","zh":"當控制權分散，新的聲音便可以直接接觸觀眾。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"Hollywood studios","meaning":"荷里活片廠","examples":[{"en":"Fame is no longer controlled only by Hollywood studios.","zh":"名氣不再只由荷里活片廠控制。"},{"en":"Hollywood studios are major film production companies based in or strongly associated with the American film industry in Hollywood.","zh":"荷里活片廠是位於或與美國荷里活電影業密切相關的大型電影製作公司。"},{"en":"Hollywood studios have historically distributed films to audiences worldwide.","zh":"荷里活片廠長期以來把電影發行給世界各地觀眾。"},{"en":"Streaming allows international producers to reach viewers without depending entirely on Hollywood studios.","zh":"串流令國際製作人不用完全依賴荷里活片廠也能接觸觀眾。"},{"en":"The global film market now includes more influential production centres outside Hollywood.","zh":"現在全球電影市場包括更多荷里活以外有影響力的製作中心。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"English-language radio stations","meaning":"英語電台","examples":[{"en":"Fame is no longer controlled only by English-language radio stations.","zh":"名氣不再只由英語電台控制。"},{"en":"English-language radio stations are broadcasters that mainly play or present content in English.","zh":"英語電台是主要播放或提供英語內容的廣播機構。"},{"en":"In the past, radio stations had great influence over which songs became widely known.","zh":"過去，電台對哪些歌曲會廣為人知有很大影響。"},{"en":"Online platforms let non-English songs become popular without heavy radio play.","zh":"網上平台令非英語歌曲不用大量在電台播放也能走紅。"},{"en":"Digital distribution has reduced the power of traditional broadcasting as the only route to music fame.","zh":"數碼發行減低了傳統廣播作為音樂成名唯一途徑的力量。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"fresher voices","meaning":"更新鮮的聲音","examples":[{"en":"Viewers are looking for fresher voices in entertainment.","zh":"觀眾正在娛樂內容中尋找更新鮮的聲音。"},{"en":"“Fresher voices” means new perspectives, styles or creators that feel less familiar and more original.","zh":"「fresher voices」表示較新、較原創，而且不那麼熟悉的觀點、風格或創作者。"},{"en":"Young readers may look for fresher voices that describe experiences rarely seen in older books.","zh":"年輕讀者可能尋找能描述舊作品較少呈現經歷的更新鮮聲音。"},{"en":"International entertainment offers fresher voices by introducing different languages and cultural viewpoints.","zh":"國際娛樂透過不同語言和文化觀點提供更新鮮的聲音。"},{"en":"Audiences often become interested in new creators when familiar formulas start to feel repetitive.","zh":"當熟悉公式開始顯得重複，觀眾往往會對新創作者產生興趣。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"stronger stories","meaning":"更有力的故事","examples":[{"en":"Asian films and dramas often offer stronger stories.","zh":"亞洲電影和劇集常提供更有力的故事。"},{"en":"“Stronger stories” means narratives that feel more engaging, emotionally powerful or carefully developed.","zh":"「stronger stories」表示更吸引、更有情感力量或發展得更完整的故事。"},{"en":"A film with complex characters may offer a stronger story than one depending only on special effects.","zh":"有複雜人物的電影可能比只依賴特技的作品有更有力的故事。"},{"en":"Viewers may turn to foreign dramas because they find the stories more surprising or emotionally rich.","zh":"觀眾可能轉向外國劇集，因為覺得故事更意外或情感更豐富。"},{"en":"Strong storytelling can overcome language barriers when audiences connect with the characters and conflict.","zh":"當觀眾與角色和衝突產生共鳴，強而有力的故事可以跨越語言障礙。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"adventurous performances","meaning":"更具冒險精神的演出","examples":[{"en":"Viewers are drawn to more adventurous performances.","zh":"觀眾被更具冒險精神的演出吸引。"},{"en":"Adventurous performances are bold, creative or unusual performances that take artistic risks.","zh":"更具冒險精神的演出是大膽、有創意或不尋常，而且願意承擔藝術風險的表演。"},{"en":"The actor gave an adventurous performance by playing a very different kind of character.","zh":"那位演員飾演一個與以往完全不同的角色，帶來很有冒險精神的演出。"},{"en":"Audiences may enjoy adventurous performances because they feel less predictable.","zh":"觀眾可能喜歡這類演出，因為感覺較難預測。"},{"en":"Artistic risk can make a performance memorable when it is supported by skill.","zh":"如果有技巧支持，藝術上的冒險可以令演出更難忘。"}],"source":"2013 Q7.pdf","sourcePage":2},{"front":"turn to","meaning":"轉向","examples":[{"en":"Viewers are turning to Asian singers and movie stars.","zh":"觀眾正在轉向亞洲歌手和電影明星。"},{"en":"To turn to someone or something means to begin choosing or relying on them instead of previous options.","zh":"「turn to」表示開始選擇或依靠某人或某事，而不是原本的選擇。"},{"en":"More shoppers are turning to online stores for convenience.","zh":"更多消費者為了方便而轉向網上商店。"},{"en":"Viewers may turn to Asian entertainment when familiar Western content feels repetitive.","zh":"當熟悉的西方內容顯得重複，觀眾可能轉向亞洲娛樂。"},{"en":"A shift in preference happens when people turn towards new sources of value or interest.","zh":"當人開始尋找新的價值或興趣來源，喜好便會出現轉變。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"movie stars","meaning":"電影明星","examples":[{"en":"Asian movie stars are gaining popularity in Western countries.","zh":"亞洲電影明星在西方國家越來越受歡迎。"},{"en":"Movie stars are well-known actors who are famous for appearing in films.","zh":"電影明星是因演出電影而廣為人知的著名演員。"},{"en":"Major award wins can make movie stars known to new international audiences.","zh":"在大型頒獎禮獲獎，可以令電影明星被新的國際觀眾認識。"},{"en":"Asian movie stars increasingly work in both local and global productions.","zh":"亞洲電影明星越來越多同時參與本地和國際製作。"},{"en":"A movie star’s appeal often depends on acting skill, screen presence and memorable roles.","zh":"電影明星的吸引力常來自演技、銀幕魅力和難忘角色。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"popularity in Western countries","meaning":"在西方國家的受歡迎程度","examples":[{"en":"The article explains their popularity in Western countries.","zh":"文章解釋他們在西方國家的受歡迎程度。"},{"en":"“Popularity in Western countries” means the degree to which people in Western societies know, like and follow someone or something.","zh":"「popularity in Western countries」表示某人或某事在西方社會有多被認識、喜愛和追隨。"},{"en":"The singer’s popularity in Western countries increased after a viral performance.","zh":"那位歌手一次爆紅演出後，在西方國家的受歡迎程度上升。"},{"en":"Streaming can rapidly increase an artist’s popularity in Western countries.","zh":"串流可以迅速提升藝人在西方國家的受歡迎程度。"},{"en":"Popularity in a new region usually grows through repeated exposure and positive audience response.","zh":"在新地區建立受歡迎程度，通常需要反覆曝光和正面觀眾反應。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"be driven by","meaning":"由……推動","examples":[{"en":"Their popularity is driven by digital access and artistic distinctiveness.","zh":"他們的受歡迎程度由數碼接觸渠道和藝術特色推動。"},{"en":"To be driven by something means to be mainly caused, strengthened or pushed forward by it.","zh":"「be driven by」表示某件事主要由某因素造成、加強或向前推動。"},{"en":"Online shopping growth is driven by convenience and lower delivery costs.","zh":"網上購物增長由方便和較低送貨成本推動。"},{"en":"International popularity can be driven by both technology and strong creative work.","zh":"國際受歡迎程度可以同時由科技和優秀創作推動。"},{"en":"This phrase identifies the main forces behind a trend or change.","zh":"這個片語用來指出一項趨勢或改變背後的主要力量。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"digital access","meaning":"數碼接觸渠道","examples":[{"en":"Digital access has helped Asian stars reach Western audiences.","zh":"數碼接觸渠道幫助亞洲明星接觸西方觀眾。"},{"en":"Digital access means the ability to reach media, information or services through the internet and digital devices.","zh":"數碼接觸渠道是指透過互聯網和數碼裝置接觸媒體、資訊或服務的能力。"},{"en":"Digital access allows students to read materials without visiting a library.","zh":"數碼接觸讓學生不用去圖書館也能閱讀資料。"},{"en":"Streaming and social media provide digital access to films and songs from other countries.","zh":"串流和社交媒體提供接觸其他國家電影和歌曲的數碼渠道。"},{"en":"Easier digital access reduces the importance of physical distance between creators and audiences.","zh":"數碼接觸越容易，創作者與觀眾之間的地理距離便越不重要。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"artistic distinctiveness","meaning":"藝術特色","examples":[{"en":"Asian stars are popular partly because of their artistic distinctiveness.","zh":"亞洲明星受歡迎，部分原因是他們具有藝術特色。"},{"en":"Artistic distinctiveness is the quality of having a recognisable creative style that differs from others.","zh":"藝術特色是擁有容易辨認、並與其他人不同的創作風格。"},{"en":"The director’s unusual use of colour gives her films artistic distinctiveness.","zh":"那位導演不尋常的用色令她的電影具有藝術特色。"},{"en":"Cultural influences can give performers artistic distinctiveness in a crowded global market.","zh":"文化影響可以令表演者在擠迫的全球市場中具有藝術特色。"},{"en":"Artists become memorable when audiences can recognise what makes their work different.","zh":"當觀眾能清楚辨認作品有甚麼不同，藝人便更容易令人記住。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"a new hunger for representation","meaning":"對代表性的新增渴求","examples":[{"en":"There is a new hunger for representation among audiences.","zh":"觀眾之間出現了對代表性的新增渴求。"},{"en":"“A hunger for representation” means a strong desire to see people and experiences like one’s own fairly shown in media.","zh":"「a hunger for representation」表示強烈希望媒體公平呈現與自己相似的人和經歷。"},{"en":"Young viewers may have a hunger for representation if people from their background rarely appear on screen.","zh":"如果自己背景的人很少出現在螢幕上，年輕觀眾可能會更渴望代表性。"},{"en":"More diverse societies have increased demand for stories about different communities.","zh":"社會越多元，對不同社群故事的需求便越大。"},{"en":"Representation matters because audiences often want entertainment to reflect the world they actually live in.","zh":"代表性重要，因為觀眾往往希望娛樂內容反映自己真正生活的世界。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"gain attention","meaning":"獲得關注","examples":[{"en":"Asian stars are gaining attention because technology has removed barriers.","zh":"科技消除障礙，因此亞洲明星正在獲得關注。"},{"en":"To gain attention means to become increasingly noticed or discussed by people.","zh":"「gain attention」表示越來越被人留意或討論。"},{"en":"The small business gained attention after a customer shared its product online.","zh":"顧客在網上分享產品後，那間小企業獲得了關注。"},{"en":"Asian performers gain attention when clips, interviews and songs circulate internationally.","zh":"亞洲表演者的片段、訪問和歌曲在國際流傳時，便會獲得關注。"},{"en":"Attention is often the first step before wider recognition and popularity.","zh":"獲得關注往往是廣泛認知和受歡迎之前的第一步。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"removed barriers","meaning":"消除障礙","examples":[{"en":"Technology has removed many old barriers between cultures.","zh":"科技已消除很多文化之間的舊障礙。"},{"en":"To remove barriers means to eliminate obstacles that make communication, access or participation difficult.","zh":"消除障礙表示移除令溝通、接觸或參與變困難的阻礙。"},{"en":"Subtitles remove language barriers for many viewers.","zh":"字幕可以為很多觀眾消除語言障礙。"},{"en":"Streaming has removed distribution barriers that once kept foreign films out of some markets.","zh":"串流消除了以前令外國電影難以進入部分市場的發行障礙。"},{"en":"When barriers are removed, people can discover ideas and creators they rarely encountered before.","zh":"當障礙被消除，人們便能發現以前很少接觸的想法和創作者。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"barriers between cultures","meaning":"文化之間的障礙","examples":[{"en":"Technology has reduced barriers between cultures.","zh":"科技已減少文化之間的障礙。"},{"en":"Barriers between cultures are obstacles that make it difficult for people from different cultural backgrounds to understand or access one another’s ideas and media.","zh":"文化之間的障礙是令不同文化背景的人難以理解或接觸彼此想法和媒體的阻礙。"},{"en":"Language differences can create barriers between cultures.","zh":"語言差異可以形成文化之間的障礙。"},{"en":"Translation and streaming help reduce barriers between cultures.","zh":"翻譯和串流有助減少文化之間的障礙。"},{"en":"Greater contact can make unfamiliar customs and stories easier to understand.","zh":"增加接觸可以令陌生習俗和故事更容易理解。"}],"source":"2013 Q7.pdf","sourcePage":3},{"front":"Gone are the days when","meaning":"……的日子已經過去","examples":[{"en":"Gone are the days when a film had to be shown in a local cinema first.","zh":"電影必須先在本地戲院上映的日子已經過去。"},{"en":"“Gone are the days when” means an old situation or rule is no longer normal today.","zh":"「Gone are the days when」表示以前的情況或規則如今已不再正常。"},{"en":"Gone are the days when students had to use only printed dictionaries.","zh":"學生只能使用印刷字典的日子已經過去。"},{"en":"Gone are the days when international fame depended entirely on traditional media.","zh":"國際名氣完全依賴傳統媒體的日子已經過去。"},{"en":"This expression strongly emphasises how much circumstances have changed.","zh":"這個表達強烈突出環境已經改變很多。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"local cinema","meaning":"本地戲院","examples":[{"en":"A film no longer has to be shown in a local cinema before becoming popular.","zh":"電影現在不用先在本地戲院上映才可以走紅。"},{"en":"A local cinema is a movie theatre serving audiences in a particular town, city or region.","zh":"本地戲院是服務某個城鎮、城市或地區觀眾的電影院。"},{"en":"Families often visited the local cinema at weekends.","zh":"家庭以前常在週末去本地戲院。"},{"en":"In the past, local cinemas were important places for discovering new films.","zh":"過去，本地戲院是發現新電影的重要地方。"},{"en":"Online distribution means popularity can now grow before a film reaches every local cinema.","zh":"網上發行令電影在進入每一間本地戲院前也可以先建立人氣。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"played on Western radio","meaning":"在西方電台播放","examples":[{"en":"A song no longer has to be played on Western radio to become popular.","zh":"歌曲現在不用在西方電台播放也能變得受歡迎。"},{"en":"To be played on Western radio means to be broadcast by radio stations in Western countries.","zh":"「be played on Western radio」表示歌曲由西方國家的電台播放。"},{"en":"In the past, songs often needed heavy radio play to reach large audiences.","zh":"過去，歌曲往往需要大量電台播放才能接觸大批觀眾。"},{"en":"A song can now become globally successful through social media before being played on Western radio.","zh":"現在歌曲可以先透過社交媒體在全球走紅，之後才在西方電台播放。"},{"en":"Digital platforms have created alternative routes to music popularity.","zh":"數碼平台創造了其他成為熱門歌曲的途徑。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"become popular","meaning":"變得受歡迎","examples":[{"en":"A song can become popular through online platforms.","zh":"一首歌可以透過網上平台變得受歡迎。"},{"en":"To become popular means to grow widely liked, known or followed by many people.","zh":"「become popular」表示逐漸被很多人喜愛、認識或追隨。"},{"en":"A small café became popular after several positive online reviews.","zh":"那間小咖啡店在幾篇正面網上評價後變得受歡迎。"},{"en":"Songs can become popular rapidly when users share them repeatedly.","zh":"當使用者不斷分享歌曲，它可以迅速變得受歡迎。"},{"en":"Popularity grows when exposure and positive response reinforce each other.","zh":"當曝光和正面反應互相加強，受歡迎程度便會上升。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"discover a Thai actor","meaning":"發現一位泰國演員","examples":[{"en":"A fan can discover a Thai actor through a short clip.","zh":"粉絲可以透過短片發現一位泰國演員。"},{"en":"To discover a Thai actor means to encounter and become interested in an actor from Thailand for the first time.","zh":"發現一位泰國演員表示第一次接觸並開始對一位泰國演員產生興趣。"},{"en":"She discovered a new singer through a video shared by a friend.","zh":"她透過朋友分享的影片發現了一位新歌手。"},{"en":"Short clips can introduce Thai actors to viewers who have never watched Thai dramas.","zh":"短片可以把泰國演員介紹給從未看過泰劇的觀眾。"},{"en":"Online discovery can turn a stranger into a favourite performer very quickly.","zh":"網上發現新藝人的速度可以很快，陌生人可能很快變成最喜歡的表演者。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"through a short clip","meaning":"透過短片","examples":[{"en":"A fan can discover an actor through a short clip.","zh":"粉絲可以透過短片發現一位演員。"},{"en":"“Through a short clip” means by watching a brief piece of video content.","zh":"「through a short clip」表示透過觀看一小段影片內容。"},{"en":"I discovered the documentary through a short clip shared online.","zh":"我透過網上分享的一段短片發現那套紀錄片。"},{"en":"A few seconds of an interesting performance can encourage viewers to search for the full work.","zh":"幾秒有趣的表演可以鼓勵觀眾尋找完整作品。"},{"en":"Short clips act as gateways to longer films, songs and television series.","zh":"短片可以成為通往較長電影、歌曲和劇集的入口。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"learn the lyrics of","meaning":"學會……的歌詞","examples":[{"en":"A fan can learn the lyrics of a Korean song through subtitles.","zh":"粉絲可以透過字幕學會韓文歌曲的歌詞。"},{"en":"To learn the lyrics of a song means to become able to understand, remember or sing its words.","zh":"學會一首歌的歌詞表示能理解、記住或唱出其中的文字。"},{"en":"She learned the lyrics of her favourite song by listening repeatedly.","zh":"她透過反覆聆聽學會自己最喜歡歌曲的歌詞。"},{"en":"Subtitles and lyric videos help international fans learn the lyrics of songs in unfamiliar languages.","zh":"字幕和歌詞影片幫助國際粉絲學會陌生語言歌曲的歌詞。"},{"en":"Learning lyrics can deepen a listener’s connection with a song.","zh":"學會歌詞可以加深聽眾與歌曲的連結。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"through subtitles","meaning":"透過字幕","examples":[{"en":"A fan can learn Korean lyrics through subtitles.","zh":"粉絲可以透過字幕學習韓文歌詞。"},{"en":"“Through subtitles” means with the help of written words or translations displayed on a screen.","zh":"「through subtitles」表示借助螢幕上顯示的文字或翻譯。"},{"en":"Students can understand a foreign documentary through subtitles.","zh":"學生可以透過字幕理解外語紀錄片。"},{"en":"Subtitles let viewers follow stories even when they do not speak the original language.","zh":"即使不懂原本語言，字幕仍能讓觀眾跟上故事。"},{"en":"Translation tools make cultural content easier to access across language boundaries.","zh":"翻譯工具令文化內容更容易跨越語言界線。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"share a Japanese trailer","meaning":"分享日本電影預告片","examples":[{"en":"A fan can share a Japanese trailer within seconds.","zh":"粉絲可以在數秒內分享日本電影預告片。"},{"en":"To share a Japanese trailer means to send or repost a promotional video for a Japanese film or programme to other people.","zh":"分享日本電影預告片表示把日本電影或節目的宣傳影片傳送或轉發給其他人。"},{"en":"She shared the trailer in a group chat because she wanted friends to watch the film.","zh":"她在群組聊天中分享預告片，希望朋友去看那套電影。"},{"en":"Social platforms allow fans to spread trailers internationally with almost no delay.","zh":"社交平台令粉絲幾乎不用等待便能把預告片傳到國際。"},{"en":"Sharing turns individual discovery into wider exposure.","zh":"分享可以把個人發現變成更廣泛曝光。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"within seconds","meaning":"在數秒之內","examples":[{"en":"A trailer can be shared within seconds.","zh":"預告片可以在數秒之內被分享。"},{"en":"“Within seconds” means in only a few seconds or before several seconds have passed.","zh":"「within seconds」表示只需幾秒，或在數秒過去之前。"},{"en":"News can spread worldwide within seconds on social media.","zh":"新聞可以透過社交媒體在數秒之內傳遍世界。"},{"en":"A fan can send a video to hundreds of people within seconds.","zh":"粉絲可以在數秒內把影片傳給數百人。"},{"en":"Such speed helps cultural trends spread much faster than before.","zh":"這種速度令文化潮流比以前傳播得快得多。"}],"source":"2013 Q7.pdf","sourcePage":4},{"front":"algorithms recommend","meaning":"演算法推薦","examples":[{"en":"Algorithms recommend Asian content to more viewers.","zh":"演算法向更多觀眾推薦亞洲內容。"},{"en":"“Algorithms recommend” means computer systems automatically suggest content based on data such as viewing habits or interests.","zh":"「algorithms recommend」表示電腦系統根據觀看習慣或興趣等資料，自動建議內容。"},{"en":"Streaming algorithms recommend films similar to ones a user already enjoyed.","zh":"串流演算法會推薦與使用者以前喜歡作品相似的電影。"},{"en":"Recommendation systems can introduce audiences to creators they did not search for themselves.","zh":"推薦系統可以把觀眾介紹給他們原本沒有主動搜尋的創作者。"},{"en":"Algorithmic recommendations can greatly increase exposure for international content.","zh":"演算法推薦可以大幅增加國際內容的曝光。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"such content","meaning":"這類內容","examples":[{"en":"Algorithms recommend such content more often.","zh":"演算法會更常推薦這類內容。"},{"en":"“Such content” refers to the type of material already mentioned, in this case Asian films, music or performances.","zh":"「such content」指前面已提到的那一類材料，在這裏即亞洲電影、音樂或表演。"},{"en":"Once a user watches several science videos, the platform may recommend such content more frequently.","zh":"使用者看過幾段科學影片後，平台可能更常推薦這類內容。"},{"en":"Repeated recommendation of such content increases the chance of discovery.","zh":"反覆推薦這類內容會增加被發現的機會。"},{"en":"The phrase avoids repeating a long description that readers already understand.","zh":"這個片語可以避免重複讀者已明白的長篇描述。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"Asian faces","meaning":"亞洲面孔","examples":[{"en":"Asian faces become more familiar to Western audiences.","zh":"亞洲面孔對西方觀眾變得更熟悉。"},{"en":"“Asian faces” refers to Asian performers and public figures as visible representatives in media.","zh":"「Asian faces」指媒體中作為可見代表的亞洲表演者和公眾人物。"},{"en":"Seeing more Asian faces in international films can broaden ideas about who belongs on screen.","zh":"在國際電影看到更多亞洲面孔，可以擴闊人們對誰可以出現在銀幕上的想像。"},{"en":"Repeated exposure makes previously unfamiliar performers easier to recognise.","zh":"反覆曝光令以前陌生的表演者更容易被認出。"},{"en":"Visibility matters because familiar faces are often more easily accepted by audiences.","zh":"可見度很重要，因為熟悉的面孔通常較容易被觀眾接受。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"become familiar","meaning":"變得熟悉","examples":[{"en":"The more viewers see Asian stars, the more familiar they become.","zh":"觀眾越多看到亞洲明星，他們就越變得熟悉。"},{"en":"To become familiar means to change from being unknown or strange to being recognised and comfortable.","zh":"「become familiar」表示由陌生或未知變成容易認出和感覺習慣。"},{"en":"A new neighbourhood becomes familiar after you walk through it every day.","zh":"每天走過一個新社區後，它會逐漸變得熟悉。"},{"en":"Repeated exposure helps foreign actors become familiar to international audiences.","zh":"反覆曝光幫助外國演員對國際觀眾變得熟悉。"},{"en":"Familiarity can reduce the sense that another culture is distant or unusual.","zh":"熟悉感可以減少人覺得另一種文化遙遠或奇怪的感覺。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"this matters because","meaning":"這很重要，因為","examples":[{"en":"This matters because audiences rarely love what they never meet.","zh":"這很重要，因為觀眾很少會喜愛自己從未接觸過的事物。"},{"en":"“This matters because” introduces the reason why the previous point is important.","zh":"「this matters because」用來解釋上一個重點為甚麼重要。"},{"en":"Regular sleep is important; this matters because tired students learn less effectively.","zh":"定時睡眠很重要；這很重要，因為疲倦學生學習效率較低。"},{"en":"Greater exposure matters because people need contact before they can develop interest.","zh":"增加曝光很重要，因為人需要先接觸才可能產生興趣。"},{"en":"This phrase links an observation to its wider significance.","zh":"這個片語把觀察與更廣泛的重要性連接起來。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"rarely","meaning":"很少","examples":[{"en":"Audiences rarely love what they never meet.","zh":"觀眾很少會喜愛自己從未接觸過的事物。"},{"en":"Rarely means not often or only in uncommon situations.","zh":"「rarely」表示不常發生，或只有在不常見情況下發生。"},{"en":"She rarely watches television because she is usually busy.","zh":"她很少看電視，因為通常都很忙。"},{"en":"People rarely become fans of artists they have never encountered.","zh":"人很少會成為從未接觸藝人的粉絲。"},{"en":"“Rarely” indicates that something is possible but uncommon.","zh":"「rarely」表示某件事不是不可能，只是不常發生。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"what they never meet","meaning":"從未接觸過的事物","examples":[{"en":"Audiences rarely love what they never meet.","zh":"觀眾很少會喜愛自己從未接觸過的事物。"},{"en":"“What they never meet” means people, cultures or content audiences have never encountered or experienced.","zh":"「what they never meet」表示觀眾從未遇見、接觸或經歷過的人、文化或內容。"},{"en":"Students may fear what they never meet because unfamiliarity can create uncertainty.","zh":"學生可能害怕從未接觸的事物，因為陌生會帶來不確定。"},{"en":"Digital platforms reduce the amount of cultural content audiences never encounter.","zh":"數碼平台減少了觀眾完全無法接觸的文化內容。"},{"en":"Meeting something through media can be the first step towards understanding it.","zh":"透過媒體接觸某件事，可以成為理解它的第一步。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"for instance","meaning":"例如","examples":[{"en":"BTS’s “Dynamite”, for instance, topped the Billboard Hot 100.","zh":"例如，BTS的《Dynamite》曾登上Billboard Hot 100榜首。"},{"en":"“For instance” introduces a specific example supporting a general point.","zh":"「for instance」用來帶出支持一般觀點的具體例子。"},{"en":"Some cities use creative transport policies; for instance, they offer free bicycle parking.","zh":"一些城市採用有創意的交通政策；例如提供免費單車泊位。"},{"en":"International success can be measured in many ways; for instance, chart performance provides one clear example.","zh":"國際成功可以用很多方式衡量；例如排行榜成績就是清楚例子。"},{"en":"This phrase makes an argument easier to understand by adding concrete evidence.","zh":"這個片語透過加入具體證據，令論點更容易理解。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"topped the Billboard Hot 100","meaning":"登上 Billboard Hot 100 榜首","examples":[{"en":"BTS’s “Dynamite” topped the Billboard Hot 100 in 2020.","zh":"BTS的《Dynamite》在2020年登上Billboard Hot 100榜首。"},{"en":"To top a chart means to reach the number-one position on that ranking.","zh":"登上排行榜榜首表示在該排名中到達第一位。"},{"en":"The singer’s new single topped the national music chart.","zh":"那位歌手的新單曲登上全國音樂排行榜榜首。"},{"en":"Reaching the top of a major chart shows strong popularity during that period.","zh":"登上大型排行榜第一位，顯示作品在該時期很受歡迎。"},{"en":"Chart success can provide visible evidence that a song has reached a large audience.","zh":"排行榜成績可以成為歌曲接觸大量觀眾的明顯證據。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"Billboard Hot 100","meaning":"Billboard 百大單曲榜","examples":[{"en":"“Dynamite” topped the Billboard Hot 100.","zh":"《Dynamite》登上Billboard Hot 100榜首。"},{"en":"The Billboard Hot 100 is a well-known United States chart ranking popular songs.","zh":"Billboard Hot 100是美國著名的熱門歌曲排行榜。"},{"en":"Artists often celebrate when a song enters the Billboard Hot 100.","zh":"歌曲進入Billboard Hot 100時，藝人常會慶祝。"},{"en":"A high position on the Billboard Hot 100 can increase international media attention.","zh":"在Billboard Hot 100取得高排名，可以增加國際媒體關注。"},{"en":"Major charts are often used as one indicator of commercial music popularity.","zh":"大型排行榜常被用作衡量商業音樂受歡迎程度的其中一項指標。"}],"source":"2013 Q7.pdf","sourcePage":5},{"front":"Netflix lists","meaning":"Netflix 列出","examples":[{"en":"Netflix lists Squid Game: Season 1 as a very popular non-English TV show.","zh":"Netflix列出《魷魚遊戲》第一季為非常受歡迎的非英語電視節目。"},{"en":"“Netflix lists” means the platform includes or ranks a title in a particular category or record.","zh":"「Netflix lists」表示該平台把某作品列入特定類別、記錄或排名。"},{"en":"The website lists the film among its most watched titles.","zh":"網站把那套電影列為最多人觀看的作品之一。"},{"en":"Streaming services can list programmes by language, genre or popularity.","zh":"串流服務可以按語言、類型或受歡迎程度列出節目。"},{"en":"Lists make audience trends easier to see and compare.","zh":"排名和清單令觀眾趨勢更容易被看見和比較。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"Squid Game: Season 1","meaning":"《魷魚遊戲》第一季","examples":[{"en":"Squid Game: Season 1 became hugely popular worldwide.","zh":"《魷魚遊戲》第一季在全球非常受歡迎。"},{"en":"Squid Game: Season 1 is the first season of the South Korean television drama series Squid Game.","zh":"《魷魚遊戲》第一季是南韓電視劇《魷魚遊戲》的第一季。"},{"en":"Many international viewers discovered Squid Game: Season 1 through streaming.","zh":"很多國際觀眾透過串流發現《魷魚遊戲》第一季。"},{"en":"Its success showed that a Korean-language series could attract a very large global audience.","zh":"它的成功顯示韓語劇集也可以吸引非常龐大的全球觀眾。"},{"en":"A locally produced story can become globally familiar when distribution is wide enough.","zh":"當發行足夠廣泛，本地製作的故事也可以在全球變得熟悉。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"non-English TV show","meaning":"非英語電視節目","examples":[{"en":"Squid Game: Season 1 is a popular non-English TV show.","zh":"《魷魚遊戲》第一季是一套受歡迎的非英語電視節目。"},{"en":"A non-English TV show is a television or streaming programme whose main spoken language is not English.","zh":"非英語電視節目是主要口頭語言不是英語的電視或串流節目。"},{"en":"Subtitles help non-English TV shows reach international viewers.","zh":"字幕幫助非英語電視節目接觸國際觀眾。"},{"en":"Audiences increasingly watch non-English TV shows when stories are strong.","zh":"當故事有吸引力，觀眾越來越願意觀看非英語電視節目。"},{"en":"Language is becoming less of a barrier to television success than before.","zh":"與以前相比，語言已較少成為電視作品成功的障礙。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"by views","meaning":"按觀看次數計","examples":[{"en":"Netflix measures popularity by views.","zh":"Netflix按觀看次數衡量受歡迎程度。"},{"en":"“By views” means according to the number of times or amount of time content has been watched, depending on the measurement used.","zh":"「by views」表示按照內容被觀看的次數或觀看量來衡量，實際方法視平台而定。"},{"en":"Online videos are often compared by views, likes and shares.","zh":"網上影片常按觀看次數、讚好和分享來比較。"},{"en":"A programme with many views has reached a large amount of audience attention.","zh":"有很多觀看次數的節目代表得到大量觀眾注意。"},{"en":"Different platforms may measure views in different ways, so the method matters.","zh":"不同平台計算觀看的方法可能不同，所以衡量方式很重要。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"put simply","meaning":"簡單來說","examples":[{"en":"Put simply, the screen has become a passport.","zh":"簡單來說，螢幕已成為一張通行證。"},{"en":"“Put simply” means expressed in an easy and direct way after a more complicated explanation.","zh":"「put simply」表示在較複雜解釋後，用直接容易明白的方法表達。"},{"en":"Put simply, the problem is that demand has fallen.","zh":"簡單來說，問題就是需求下降。"},{"en":"After discussing technology and access, the writer uses “put simply” to give the main idea.","zh":"討論科技和接觸渠道後，作者用「put simply」帶出主要概念。"},{"en":"This phrase helps readers grasp the basic conclusion quickly.","zh":"這個片語幫助讀者迅速掌握基本結論。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"the screen has become a passport","meaning":"螢幕成了通往其他文化的通行證","examples":[{"en":"The screen has become a passport to other cultures.","zh":"螢幕成了通往其他文化的通行證。"},{"en":"“The screen has become a passport” is a metaphor meaning digital devices give people access to cultures beyond their own location.","zh":"「the screen has become a passport」是一個比喻，表示數碼裝置讓人接觸自己所在地以外的文化。"},{"en":"A phone can introduce someone to music, films and traditions from another country.","zh":"手機可以把另一個國家的音樂、電影和傳統介紹給一個人。"},{"en":"Unlike a real passport, a screen lets people cross cultural boundaries without travelling physically.","zh":"與真正護照不同，螢幕讓人不用親身旅行也能跨越文化界線。"},{"en":"The metaphor emphasises how media opens doors to unfamiliar worlds.","zh":"這個比喻強調媒體如何打開通往陌生世界的大門。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"once access becomes easy","meaning":"一旦接觸變得容易","examples":[{"en":"Once access becomes easy, curiosity can become loyalty.","zh":"一旦接觸變得容易，好奇便可以變成忠誠支持。"},{"en":"“Once access becomes easy” means after people can reach something conveniently and with few barriers.","zh":"「once access becomes easy」表示當人們可以方便而少障礙地接觸某事之後。"},{"en":"Once public transport becomes easy to use, more residents may leave their cars at home.","zh":"一旦公共交通變得容易使用，更多居民可能把私家車留在家。"},{"en":"Easy streaming access allows casual curiosity about foreign content to develop further.","zh":"串流接觸方便，令對外國內容的短暫好奇有機會進一步發展。"},{"en":"People are more likely to explore something repeatedly when access requires little effort.","zh":"當接觸不需要太多精力，人會更可能反覆探索。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"curiosity can become loyalty","meaning":"好奇可以變成忠誠支持","examples":[{"en":"Curiosity can quickly become loyalty.","zh":"好奇可以很快變成忠誠支持。"},{"en":"“Curiosity can become loyalty” means initial interest can develop into lasting support or fandom.","zh":"「curiosity can become loyalty」表示最初的興趣可以發展成長期支持或粉絲忠誠。"},{"en":"A viewer may watch one episode out of curiosity and later become a loyal fan of the series.","zh":"觀眾可能因好奇看一集，之後變成整套劇的忠實粉絲。"},{"en":"Repeated positive experiences can turn casual interest into long-term support.","zh":"反覆良好體驗可以把短暫興趣轉化成長期支持。"},{"en":"Easy access gives curiosity enough opportunities to deepen into attachment.","zh":"容易接觸令好奇有足夠機會深化成依附和支持。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"appeal to","meaning":"吸引","examples":[{"en":"Asian stars appeal to Western audiences.","zh":"亞洲明星吸引西方觀眾。"},{"en":"To appeal to someone means to attract, interest or please them.","zh":"「appeal to」表示吸引某人、令某人感興趣或喜歡。"},{"en":"Simple design appeals to customers who dislike complicated products.","zh":"簡單設計吸引不喜歡複雜產品的顧客。"},{"en":"Strong stories can appeal to viewers even when the cultural setting is unfamiliar.","zh":"即使文化背景陌生，有力的故事仍可以吸引觀眾。"},{"en":"Different aspects of a performer may appeal to different audiences.","zh":"表演者不同方面可以吸引不同觀眾。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"emotionally universal","meaning":"情感上具有普世性","examples":[{"en":"Asian stars offer stories that feel emotionally universal.","zh":"亞洲明星帶來情感上具有普世性的故事。"},{"en":"Emotionally universal means expressing feelings that people from many cultures can recognise and understand.","zh":"情感上具有普世性表示表達很多文化背景的人都能認出和理解的感受。"},{"en":"Grief after losing a loved one is emotionally universal even though cultures express it differently.","zh":"失去親人的悲傷在情感上具有普世性，即使不同文化表達方式不同。"},{"en":"Stories about family, ambition and fear can feel emotionally universal across languages.","zh":"關於家庭、抱負和恐懼的故事可以跨語言具有普世情感。"},{"en":"Universal emotion helps audiences connect with culturally specific stories.","zh":"普世情感幫助觀眾與文化背景很具體的故事產生連結。"}],"source":"2013 Q7.pdf","sourcePage":6},{"front":"what makes someone memorable","meaning":"令某人難忘的原因","examples":[{"en":"What makes many Asian stars memorable is their cultural identity.","zh":"令很多亞洲明星難忘的原因，是他們的文化身份。"},{"en":"“What makes someone memorable” means the quality that causes people to remember that person strongly.","zh":"「what makes someone memorable」表示令某人深深留在人們記憶中的特質。"},{"en":"Her unusual voice is what makes the singer memorable.","zh":"她獨特的聲音是令那位歌手難忘的原因。"},{"en":"Distinct cultural style can make an artist more memorable than copying familiar formulas.","zh":"鮮明文化風格可以比模仿熟悉公式更令人記住藝人。"},{"en":"Memorable performers usually have something audiences can clearly identify as their own.","zh":"難忘的表演者通常有一些觀眾能清楚認作其個人特色的東西。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"copy Western styles","meaning":"模仿西方風格","examples":[{"en":"Many Asian stars do not simply copy Western styles.","zh":"很多亞洲明星並不只是模仿西方風格。"},{"en":"To copy Western styles means to imitate artistic, fashion or performance traditions associated with Western countries.","zh":"模仿西方風格表示仿效與西方國家相關的藝術、時尚或表演傳統。"},{"en":"A local singer may learn from American pop without copying Western styles completely.","zh":"本地歌手可以向美國流行音樂學習，而不完全模仿西方風格。"},{"en":"Artists become more distinctive when they adapt influences rather than simply copying them.","zh":"藝人如果吸收而不是單純複製外來影響，會更有特色。"},{"en":"International success does not require abandoning local cultural identity.","zh":"國際成功並不需要放棄本地文化身份。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"combine local cultural identity with","meaning":"把本地文化身份與……結合","examples":[{"en":"They combine local cultural identity with universal feelings.","zh":"他們把本地文化身份與普世感受結合。"},{"en":"To combine local cultural identity with something means to join specific cultural features with another quality.","zh":"把本地文化身份與某物結合，表示把具體文化特色與另一種特質放在一起。"},{"en":"A film can combine local history with a universal story about family.","zh":"電影可以把本地歷史與普世家庭故事結合。"},{"en":"Artists can remain culturally specific while expressing emotions understood worldwide.","zh":"藝人可以保留具體文化特色，同時表達全世界都能理解的情感。"},{"en":"Successful cross-cultural work often balances difference with familiarity.","zh":"成功的跨文化作品往往在差異和熟悉感之間取得平衡。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"local cultural identity","meaning":"本地文化身份","examples":[{"en":"Asian performers often keep a strong local cultural identity.","zh":"亞洲表演者常保留強烈的本地文化身份。"},{"en":"Local cultural identity is the sense of belonging and distinctiveness connected with a particular place, language, history and tradition.","zh":"本地文化身份是與某個地方、語言、歷史和傳統相連的歸屬感和獨特性。"},{"en":"A director may express local cultural identity through dialect, food and familiar neighbourhoods.","zh":"導演可以透過方言、食物和熟悉社區表達本地文化身份。"},{"en":"Keeping local cultural identity can make international work feel more authentic rather than generic.","zh":"保留本地文化身份可以令國際作品感覺更真實，而不是千篇一律。"},{"en":"Global success and strong local identity do not have to contradict each other.","zh":"全球成功和強烈本地身份並不一定互相矛盾。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"feelings everyone can recognise","meaning":"人人都能理解的感受","examples":[{"en":"Their stories express feelings everyone can recognise.","zh":"他們的故事表達人人都能理解的感受。"},{"en":"“Feelings everyone can recognise” means emotions that are familiar to people regardless of cultural background.","zh":"「feelings everyone can recognise」表示不論文化背景，人都熟悉的情感。"},{"en":"Fear of disappointing family is a feeling many people can recognise.","zh":"害怕令家人失望，是很多人都能理解的感受。"},{"en":"Stories become easier to connect with when they express emotions audiences already know personally.","zh":"當故事表達觀眾自己熟悉的情緒，就更容易產生共鳴。"},{"en":"Recognisable feelings can help culturally specific stories travel internationally.","zh":"人人都能理解的感受，可以幫助文化背景具體的故事走向國際。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"K-pop","meaning":"韓國流行音樂","examples":[{"en":"K-pop is known for disciplined choreography.","zh":"韓國流行音樂以嚴謹的舞蹈編排聞名。"},{"en":"K-pop is a broad term for popular music from South Korea, often combining music, dance, visual styling and performance.","zh":"韓國流行音樂泛指南韓的流行音樂，常結合音樂、舞蹈、視覺造型和表演。"},{"en":"K-pop groups often release highly produced music videos.","zh":"韓國流行音樂組合常推出製作精良的音樂影片。"},{"en":"International fans may follow K-pop for its music, dance and group personalities.","zh":"國際粉絲可能因音樂、舞蹈和成員個性而追隨韓國流行音樂。"},{"en":"Its global popularity shows how a locally rooted music industry can develop international influence.","zh":"它的全球受歡迎程度顯示本地扎根的音樂產業也能產生國際影響。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"be known for","meaning":"以……聞名","examples":[{"en":"K-pop is known for disciplined choreography and sharp styling.","zh":"韓國流行音樂以嚴謹舞蹈編排和鮮明利落造型聞名。"},{"en":"To be known for something means to be widely recognised because of a particular quality or feature.","zh":"「be known for」表示因某項特質或特色而廣為人知。"},{"en":"The city is known for its efficient public transport.","zh":"這個城市以高效率公共交通聞名。"},{"en":"A performer may become known for powerful live vocals.","zh":"表演者可能以強勁現場歌唱能力聞名。"},{"en":"What someone is known for often becomes part of their public identity.","zh":"一個人以甚麼聞名，常會成為其公眾身份的一部分。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"disciplined choreography","meaning":"嚴謹的舞蹈編排","examples":[{"en":"K-pop is known for disciplined choreography.","zh":"韓國流行音樂以嚴謹的舞蹈編排聞名。"},{"en":"Disciplined choreography is carefully organised dance movement performed with strong timing, control and repeated practice.","zh":"嚴謹的舞蹈編排是經仔細設計，而且講求節奏、控制和反覆練習的舞蹈動作。"},{"en":"The dancers practised for months to achieve disciplined choreography.","zh":"舞者練習了幾個月，才能做到嚴謹的舞蹈編排。"},{"en":"Group performances look powerful when every member follows precise movement together.","zh":"當每位成員精準同步動作，團體表演便會很有力量。"},{"en":"Disciplined choreography reveals the training behind performances that may look effortless.","zh":"嚴謹舞蹈編排顯示看似毫不費力的演出背後其實有大量訓練。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"sharp styling","meaning":"鮮明利落的造型","examples":[{"en":"K-pop groups often have sharp styling.","zh":"韓國流行音樂組合常有鮮明利落的造型。"},{"en":"Sharp styling means a clean, striking and carefully coordinated visual appearance.","zh":"鮮明利落的造型是整潔、突出，而且經仔細配搭的視覺形象。"},{"en":"The performers wore sharp styling with matching black suits and simple accessories.","zh":"表演者穿配搭一致的黑色西裝和簡單飾物，造型非常利落。"},{"en":"Hair, clothing and makeup all contribute to sharp styling.","zh":"髮型、服裝和化妝都會形成鮮明利落的造型。"},{"en":"Strong styling helps performers create a recognisable visual identity.","zh":"強烈造型有助表演者建立容易辨認的視覺身份。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"carefully built group chemistry","meaning":"精心建立的團隊默契","examples":[{"en":"K-pop groups often show carefully built group chemistry.","zh":"韓國流行音樂組合常展現精心建立的團隊默契。"},{"en":"Carefully built group chemistry means a sense of connection and teamwork deliberately developed through training and shared experience.","zh":"精心建立的團隊默契，是透過訓練和共同經驗刻意培養的連結和合作感。"},{"en":"Months of rehearsing together helped the cast build strong group chemistry.","zh":"幾個月一起排練，幫助演員建立強烈團隊默契。"},{"en":"Audiences notice group chemistry when performers respond naturally to one another.","zh":"當表演者自然回應彼此，觀眾便能感受到團隊默契。"},{"en":"Chemistry may look spontaneous even though it often develops through long practice.","zh":"默契可以看似自然即興，但其實常來自長時間練習。"}],"source":"2013 Q7.pdf","sourcePage":7},{"front":"group chemistry","meaning":"團隊默契","examples":[{"en":"Strong group chemistry helps performers connect with audiences.","zh":"強烈的團隊默契幫助表演者與觀眾建立連結。"},{"en":"Group chemistry is the natural-looking connection, trust and energy between members of a group.","zh":"團隊默契是小組成員之間看起來自然的連結、信任和能量。"},{"en":"Good group chemistry can make a team discussion feel lively and comfortable.","zh":"良好團隊默契可以令小組討論顯得有活力又舒服。"},{"en":"Performers with strong chemistry make audiences believe in their relationships on stage.","zh":"默契強的表演者會令觀眾相信舞台上的彼此關係。"},{"en":"Technical skill matters, but group chemistry can make a performance feel warmer and more engaging.","zh":"技巧很重要，但團隊默契可以令演出更溫暖和吸引。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"Korean films","meaning":"韓國電影","examples":[{"en":"Korean films often mix humour, suspense and social criticism.","zh":"韓國電影常融合幽默、懸疑和社會批判。"},{"en":"Korean films are movies produced in South Korea or within the South Korean film industry.","zh":"韓國電影是在南韓或南韓電影產業內製作的電影。"},{"en":"Korean films include many genres, from romance and comedy to thrillers and historical drama.","zh":"韓國電影包括很多類型，由愛情和喜劇到驚慄和歷史劇都有。"},{"en":"International audiences often appreciate Korean films for their unexpected changes in tone.","zh":"國際觀眾常欣賞韓國電影難以預料的情緒轉變。"},{"en":"Strong local industries can create films that are culturally specific yet globally successful.","zh":"強大的本地電影業可以創造既有文化特色又能全球成功的作品。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"mix humour, suspense and social criticism","meaning":"融合幽默、懸疑和社會批判","examples":[{"en":"Korean films often mix humour, suspense and social criticism.","zh":"韓國電影常融合幽默、懸疑和社會批判。"},{"en":"To mix humour, suspense and social criticism means to combine comedy, tension and commentary about society in one work.","zh":"融合幽默、懸疑和社會批判，表示在同一作品結合喜劇、緊張感和對社會的評論。"},{"en":"A film may make viewers laugh in one scene and feel anxious in the next.","zh":"一套電影可以上一幕令觀眾發笑，下一幕又令人緊張。"},{"en":"Combining several tones can make stories feel less predictable.","zh":"結合幾種不同情緒可以令故事更難預測。"},{"en":"Social messages can become more engaging when they are woven into entertaining storytelling.","zh":"社會訊息如果融入娛樂性強的故事，會更吸引人。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"suspense","meaning":"懸疑","examples":[{"en":"Korean films often use suspense in unpredictable ways.","zh":"韓國電影常以難以預料的方式運用懸疑。"},{"en":"Suspense is a feeling of tension or uncertainty about what will happen next.","zh":"懸疑是對下一步會發生甚麼感到緊張或不確定。"},{"en":"The director created suspense by hiding who was behind the door.","zh":"導演不讓觀眾知道門後是誰，營造懸疑。"},{"en":"Suspense keeps viewers watching because they want answers.","zh":"懸疑令觀眾想知道答案，因此繼續觀看。"},{"en":"A story can create suspense without action scenes simply by delaying important information.","zh":"故事不用動作場面，也可以透過延遲重要資訊製造懸疑。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"social criticism","meaning":"社會批判","examples":[{"en":"Korean films often include social criticism.","zh":"韓國電影常包含社會批判。"},{"en":"Social criticism is the examination or criticism of problems, inequalities or unfair practices in society.","zh":"社會批判是對社會問題、不平等或不公平做法作出分析或批評。"},{"en":"A novel may use one family’s story to offer social criticism about poverty.","zh":"小說可以透過一個家庭故事對貧窮作出社會批判。"},{"en":"Films can include social criticism without becoming formal political speeches.","zh":"電影可以包含社會批判，而不用變成正式政治演說。"},{"en":"Storytelling can make social criticism emotionally powerful by showing how problems affect individuals.","zh":"故事透過展示問題如何影響個人，可以令社會批判更有情感力量。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"in unpredictable ways","meaning":"以難以預料的方式","examples":[{"en":"Korean films combine different elements in unpredictable ways.","zh":"韓國電影以難以預料的方式結合不同元素。"},{"en":"“In unpredictable ways” means in forms or patterns audiences cannot easily guess in advance.","zh":"「in unpredictable ways」表示以觀眾事先不容易猜到的形式或模式發展。"},{"en":"The weather changed in unpredictable ways throughout the day.","zh":"那天天氣以難以預料的方式不斷變化。"},{"en":"A film can shift from comedy to danger in unpredictable ways.","zh":"電影可以以難以預料的方式由喜劇突然轉向危險。"},{"en":"Unpredictability can keep audiences alert because familiar formulas do not tell them what comes next.","zh":"難以預測可以保持觀眾警覺，因為熟悉公式無法告訴他們下一步是甚麼。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"turn something into something poetic","meaning":"把……化成詩意的事物","examples":[{"en":"Japanese animation can turn childhood memory into something poetic.","zh":"日本動畫可以把童年回憶化成富有詩意的事物。"},{"en":"To turn something into something poetic means to present an ordinary experience in a beautiful, emotional or imaginative way.","zh":"把某件事化成詩意的事物，是指把普通經歷以美麗、感性或富想像力的方式呈現。"},{"en":"The photographer turned a rainy street into something poetic through light and colour.","zh":"攝影師透過光線和顏色，把下雨街道化成很有詩意的畫面。"},{"en":"Animation can transform a simple childhood moment into a powerful emotional image.","zh":"動畫可以把簡單童年時刻轉化成有情感力量的影像。"},{"en":"Art becomes poetic when familiar experiences are presented with deeper feeling or symbolism.","zh":"當熟悉經歷被賦予更深感受或象徵，藝術便會有詩意。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"childhood memory","meaning":"童年回憶","examples":[{"en":"Japanese animation can make childhood memory feel poetic.","zh":"日本動畫可以令童年回憶變得富有詩意。"},{"en":"A childhood memory is something a person remembers from when they were a child.","zh":"童年回憶是人記得自己兒童時期發生過的事情。"},{"en":"The smell of school lunch brought back a childhood memory.","zh":"學校午餐的味道勾起了一段童年回憶。"},{"en":"Films often use childhood memory to explore family, loss or growing up.","zh":"電影常利用童年回憶探討家庭、失去或成長。"},{"en":"Ordinary childhood memories can become emotionally powerful when people look back as adults.","zh":"成年後回望時，普通的童年回憶也可以變得很有情感力量。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"take Parasite, for example","meaning":"以《上流寄生族》為例","examples":[{"en":"Take Parasite, for example: its story can be understood anywhere.","zh":"以《上流寄生族》為例：它的故事在任何地方都能被理解。"},{"en":"“Take X, for example” introduces a specific case used to support a broader point.","zh":"「take X, for example」用來帶出支持較廣泛論點的具體個案。"},{"en":"Take public transport, for example: one improvement can affect thousands of commuters.","zh":"以公共交通為例：一次改善可以影響數以千計通勤者。"},{"en":"Parasite provides a clear example of a locally rooted story with global appeal.","zh":"《上流寄生族》清楚展示一個扎根本地而具有全球吸引力的故事。"},{"en":"Using a specific example makes an abstract argument easier to understand.","zh":"使用具體例子可以令抽象論點更容易理解。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"deeply Korean in its setting","meaning":"場景設定深具韓國特色","examples":[{"en":"Parasite is deeply Korean in its setting.","zh":"《上流寄生族》的場景設定深具韓國特色。"},{"en":"“Deeply Korean in its setting” means the locations, social conditions and details are strongly rooted in South Korean life.","zh":"「deeply Korean in its setting」表示地點、社會環境和細節強烈扎根於南韓生活。"},{"en":"A story can be deeply local in its setting while dealing with universal emotions.","zh":"故事可以在場景設定上非常本地化，同時處理普世情感。"},{"en":"Specific homes, neighbourhoods and class conditions make the film’s setting culturally distinctive.","zh":"具體住宅、社區和階級環境令電影背景具有鮮明文化特色。"},{"en":"Local detail can strengthen rather than limit international storytelling.","zh":"本地細節可以加強，而不是限制國際敘事。"}],"source":"2013 Q7.pdf","sourcePage":8},{"front":"setting","meaning":"背景設定","examples":[{"en":"Parasite is Korean in its setting.","zh":"《上流寄生族》的背景設定具有韓國特色。"},{"en":"Setting is the place, time and social environment in which a story happens.","zh":"背景設定是故事發生的地方、時間和社會環境。"},{"en":"The novel’s setting is a small coastal town in the 1950s.","zh":"那本小說的背景設定是1950年代一個海邊小鎮。"},{"en":"A strong setting can influence characters, conflict and atmosphere.","zh":"有力的背景設定可以影響角色、衝突和氣氛。"},{"en":"Audiences can understand universal themes even when the setting is culturally unfamiliar.","zh":"即使背景文化陌生，觀眾仍可以理解普世主題。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"class inequality","meaning":"階級不平等","examples":[{"en":"Parasite tells a story about class inequality.","zh":"《上流寄生族》講述一個關於階級不平等的故事。"},{"en":"Class inequality is the unequal distribution of money, opportunities and social power between economic or social classes.","zh":"階級不平等是不同經濟或社會階層之間在金錢、機會和社會權力上的不平等。"},{"en":"Housing quality can reveal class inequality in a city.","zh":"住屋質素可以反映一個城市的階級不平等。"},{"en":"Films about rich and poor families can show how class inequality affects daily choices.","zh":"關於富裕和貧窮家庭的電影可以展示階級不平等如何影響日常選擇。"},{"en":"Class inequality becomes easier to understand when stories show its effects on real people.","zh":"當故事展示它對真實人物的影響，階級不平等會更容易理解。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"family pressure","meaning":"家庭壓力","examples":[{"en":"The film explores family pressure.","zh":"那套電影探討家庭壓力。"},{"en":"Family pressure is stress or expectation created by responsibilities, demands or relationships within a family.","zh":"家庭壓力是家庭責任、要求或關係所帶來的壓力和期望。"},{"en":"A teenager may feel family pressure to achieve high examination results.","zh":"青少年可能因家人期望高考試成績而感到家庭壓力。"},{"en":"Financial problems can increase family pressure because each member depends on the others.","zh":"經濟問題可以增加家庭壓力，因為每個成員都互相依賴。"},{"en":"Family pressure becomes dramatic in stories when love and responsibility pull characters in different directions.","zh":"當愛和責任把角色拉向不同方向，家庭壓力就會成為強烈戲劇元素。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"moral compromise","meaning":"道德妥協","examples":[{"en":"Parasite also explores moral compromise.","zh":"《上流寄生族》也探討道德妥協。"},{"en":"Moral compromise means accepting or doing something that conflicts with your principles because of pressure or advantage.","zh":"道德妥協是因壓力或利益而接受或做出與自己原則有衝突的事情。"},{"en":"An employee may face moral compromise if a manager asks them to hide important information.","zh":"如果經理要求員工隱瞞重要資訊，員工可能面對道德妥協。"},{"en":"Poverty or ambition can push characters towards moral compromise.","zh":"貧窮或野心可以把角色推向道德妥協。"},{"en":"Stories about moral compromise are powerful because audiences must ask what they themselves would do.","zh":"道德妥協故事很有力量，因為觀眾會問自己在同樣情況會怎樣做。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"be understood anywhere","meaning":"在任何地方都能被理解","examples":[{"en":"The story can be understood anywhere.","zh":"這個故事在任何地方都能被理解。"},{"en":"To be understood anywhere means people from many different places can recognise the main emotions or issues.","zh":"「be understood anywhere」表示來自很多不同地方的人都能認出主要情緒或問題。"},{"en":"A story about family conflict can be understood anywhere because most cultures know such tension.","zh":"家庭衝突故事在任何地方都能被理解，因為大部分文化都知道這種張力。"},{"en":"Cultural details may differ while the central emotional problem remains familiar.","zh":"文化細節可以不同，但核心情感問題仍然熟悉。"},{"en":"Universal understanding allows local stories to travel internationally.","zh":"普世理解令本地故事可以走向國際。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"non-English-language film","meaning":"非英語電影","examples":[{"en":"Parasite became the first non-English-language film to win Best Picture.","zh":"《上流寄生族》成為第一套贏得最佳電影獎的非英語電影。"},{"en":"A non-English-language film is a film whose main spoken language is not English.","zh":"非英語電影是主要口頭語言不是英語的電影。"},{"en":"Subtitles help non-English-language films reach wider audiences.","zh":"字幕幫助非英語電影接觸更廣泛觀眾。"},{"en":"Award recognition can encourage viewers to try films in unfamiliar languages.","zh":"獎項認可可以鼓勵觀眾嘗試觀看陌生語言電影。"},{"en":"The success of non-English-language films shows that language does not limit artistic quality.","zh":"非英語電影的成功顯示語言不會限制藝術質素。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"win the Oscar for Best Picture","meaning":"贏得奧斯卡最佳電影獎","examples":[{"en":"Parasite won the Oscar for Best Picture.","zh":"《上流寄生族》贏得奧斯卡最佳電影獎。"},{"en":"To win the Oscar for Best Picture means to receive the Academy Award given to the film judged Best Picture that year.","zh":"贏得奧斯卡最佳電影獎表示獲得當年頒給最佳電影的美國電影學院獎。"},{"en":"Winning a major award can introduce a film to audiences who had not noticed it before.","zh":"贏得大型獎項可以把電影介紹給原本沒有留意它的觀眾。"},{"en":"Such recognition can symbolise wider acceptance of international cinema.","zh":"這類認可可以象徵國際電影得到更廣泛接受。"},{"en":"Awards do not create artistic value, but they can greatly increase visibility.","zh":"獎項不會創造藝術價值，但可以大幅增加曝光。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"Oscar for Best Picture","meaning":"奧斯卡最佳電影獎","examples":[{"en":"Parasite won the Oscar for Best Picture.","zh":"《上流寄生族》贏得奧斯卡最佳電影獎。"},{"en":"The Oscar for Best Picture is a major Academy Award presented to a film as the year’s Best Picture.","zh":"奧斯卡最佳電影獎是美國電影學院頒發給年度最佳電影的重要獎項。"},{"en":"Winning Best Picture often brings strong international attention.","zh":"贏得最佳電影獎通常會帶來強烈國際關注。"},{"en":"The award can become a symbolic moment for the wider film industry.","zh":"這個獎項可以成為整個電影業具有象徵意義的時刻。"},{"en":"Major awards influence visibility, even though audience taste and artistic judgment can differ.","zh":"大型獎項會影響曝光，即使觀眾品味和藝術判斷可以不同。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"train for years","meaning":"訓練多年","examples":[{"en":"Asian celebrities often train for years.","zh":"亞洲藝人常訓練多年。"},{"en":"To train for years means to spend a long period repeatedly practising and developing professional skills.","zh":"訓練多年表示長時間反覆練習和發展專業技能。"},{"en":"Ballet dancers may train for years before joining a professional company.","zh":"芭蕾舞者可能訓練多年才加入專業舞團。"},{"en":"Singers and performers train for years to improve movement, voice and stage confidence.","zh":"歌手和表演者訓練多年改善動作、聲音和舞台信心。"},{"en":"Long training can make difficult performance skills look natural.","zh":"長期訓練可以令困難表演技巧看起來很自然。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"thereby producing","meaning":"從而產生","examples":[{"en":"They train for years, thereby producing polished performances.","zh":"他們訓練多年，從而產生精緻成熟的演出。"},{"en":"“Thereby producing” means causing a result through the action just mentioned.","zh":"「thereby producing」表示前面所說的行動造成某個結果。"},{"en":"The company simplified its process, thereby reducing waiting times.","zh":"公司簡化流程，從而縮短等候時間。"},{"en":"Years of rehearsal improve precision, thereby producing smoother performances.","zh":"多年排練提高精準度，從而產生更流暢演出。"},{"en":"“Thereby” clearly connects an action with the outcome it creates.","zh":"「thereby」清楚把行動與造成的結果連接起來。"}],"source":"2013 Q7.pdf","sourcePage":9},{"front":"look effortless","meaning":"看起來毫不費力","examples":[{"en":"Their performances may look effortless.","zh":"他們的演出可能看起來毫不費力。"},{"en":"To look effortless means to appear easy and natural even though significant skill or preparation may be required.","zh":"「look effortless」表示表面看來很容易和自然，即使背後其實需要大量技巧或準備。"},{"en":"The experienced pianist made the difficult piece look effortless.","zh":"那位有經驗的鋼琴家令困難樂曲看起來毫不費力。"},{"en":"Professional performers can look effortless because practice has made their movements controlled.","zh":"專業表演者因練習令動作受控制，所以可以看起來很輕鬆。"},{"en":"An effortless appearance often hides the amount of work behind the performance.","zh":"毫不費力的外表往往掩蓋背後大量工作。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"anything but casual","meaning":"絕非隨意","examples":[{"en":"Their performances look effortless but are anything but casual.","zh":"他們的演出看起來毫不費力，但絕非隨意。"},{"en":"“Anything but casual” means definitely not relaxed, unplanned or careless.","zh":"「anything but casual」表示絕對不是輕鬆、沒有計劃或隨便。"},{"en":"The meeting looked friendly but was anything but casual; every detail had been prepared.","zh":"會議看起來友善，但絕非隨意；每個細節都已準備。"},{"en":"A polished stage performance may seem spontaneous but actually involve strict rehearsal.","zh":"精緻舞台演出可以看似即興，實際上有嚴格排練。"},{"en":"This phrase strongly corrects an impression that something is simple or unplanned.","zh":"這個片語強烈修正某件事很簡單或沒有計劃的印象。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"be attracted by","meaning":"被……吸引","examples":[{"en":"Western viewers may first be attracted by the novelty.","zh":"西方觀眾最初可能被新鮮感吸引。"},{"en":"To be attracted by something means to become interested because a particular feature catches your attention.","zh":"「be attracted by」表示某項特色抓住注意，令人產生興趣。"},{"en":"Tourists may be attracted by the bright night markets.","zh":"遊客可能被明亮的夜市吸引。"},{"en":"New audiences may first be attracted by unfamiliar sounds or visual styles.","zh":"新觀眾最初可能被陌生聲音或視覺風格吸引。"},{"en":"Initial attraction can begin interest, but lasting loyalty usually needs deeper value.","zh":"最初吸引可以開始興趣，但長期支持通常需要更深價值。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"novelty","meaning":"新鮮感","examples":[{"en":"Viewers may first be attracted by the novelty.","zh":"觀眾最初可能被新鮮感吸引。"},{"en":"Novelty is the quality of being new, unusual or different from what someone normally experiences.","zh":"新鮮感是某件事因新、不同尋常或與平常經歷不同而產生的感覺。"},{"en":"The novelty of using a new device may disappear after a few weeks.","zh":"使用新裝置的新鮮感可能幾星期後便消失。"},{"en":"Foreign entertainment can attract viewers through novelty at first.","zh":"外國娛樂最初可以透過新鮮感吸引觀眾。"},{"en":"Novelty creates curiosity, but quality is usually needed to keep audiences interested.","zh":"新鮮感產生好奇，但通常需要質素才能保持觀眾興趣。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"stay for the craft","meaning":"因技藝而留下","examples":[{"en":"Viewers may arrive for the novelty, but they stay for the craft.","zh":"觀眾可能因新鮮感而來，但因技藝而留下。"},{"en":"“Stay for the craft” means continue following because they admire the skill and quality behind the work.","zh":"「stay for the craft」表示因欣賞作品背後的技巧和質素而繼續支持。"},{"en":"Customers may visit a bakery because it looks trendy but return for the baking skill.","zh":"顧客可能因麵包店看起來很潮而第一次到訪，但因烘焙技術而再來。"},{"en":"Novelty can attract attention, but strong acting, music or storytelling keeps fans.","zh":"新鮮感可以吸引注意，但優秀演技、音樂或故事才能留住粉絲。"},{"en":"Long-term popularity depends more on quality than on being different for a short time.","zh":"長期受歡迎更依賴質素，而不是短暫與眾不同。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"the craft","meaning":"技藝；手藝","examples":[{"en":"Western viewers stay for the craft behind the performances.","zh":"西方觀眾因演出背後的技藝而留下。"},{"en":"“The craft” means the developed skill, technique and careful work required to create something well.","zh":"「the craft」表示把事情做好所需要的成熟技巧、技術和仔細工作。"},{"en":"The craft of film editing is often invisible to ordinary viewers.","zh":"電影剪接的技藝對普通觀眾往往看不見。"},{"en":"Fans may admire the craft behind choreography, acting or production design.","zh":"粉絲可能欣賞舞蹈編排、演技或美術設計背後的技藝。"},{"en":"Craft develops through study, practice and attention to detail.","zh":"技藝透過學習、練習和留意細節建立。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, the appeal lies in storytelling.","zh":"換句話說，吸引力在於故事敘述。"},{"en":"“In other words” introduces the same idea again in a clearer or simpler form.","zh":"「in other words」用更清楚或簡單的方法重新表達同一想法。"},{"en":"The bus is unreliable; in other words, you cannot depend on it arriving on time.","zh":"巴士不可靠；換句話說，你不能指望它準時到達。"},{"en":"After explaining several artistic features, the writer uses “in other words” to summarise the point.","zh":"解釋幾項藝術特色後，作者用「in other words」總結重點。"},{"en":"This phrase is useful when readers may benefit from a clearer restatement.","zh":"當讀者需要更清楚的重述時，這個片語很有用。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"the appeal lies in","meaning":"吸引力在於","examples":[{"en":"The appeal lies in storytelling with heart and precision.","zh":"吸引力在於有真情而精準的故事敘述。"},{"en":"“The appeal lies in” means the main reason something is attractive can be found in a particular quality.","zh":"「the appeal lies in」表示某件事最主要的吸引原因存在於某項特質。"},{"en":"The restaurant’s appeal lies in its warm service rather than its decoration.","zh":"那間餐廳的吸引力在於溫暖服務，而不是裝飾。"},{"en":"A performer’s appeal may lie in honesty and skill rather than fame.","zh":"表演者的吸引力可能在於真誠和技巧，而不是名氣。"},{"en":"This structure identifies the deeper source of attraction.","zh":"這個句式用來指出吸引力更深層的來源。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"exotic decoration","meaning":"異國情調的裝飾","examples":[{"en":"The appeal lies not in exotic decoration, but in storytelling.","zh":"吸引力不在於異國情調的裝飾，而在於故事敘述。"},{"en":"Exotic decoration means unusual cultural details used mainly to create an attractive sense of foreignness.","zh":"異國情調的裝飾是主要用來營造吸引人外國感覺的不尋常文化細節。"},{"en":"A restaurant should not depend only on exotic decoration if the food is poor.","zh":"如果食物差，餐廳不能只依賴異國情調的裝飾。"},{"en":"Audiences may enjoy cultural difference, but surface decoration alone does not create strong art.","zh":"觀眾可以喜歡文化差異，但表面裝飾本身不能創造優秀藝術。"},{"en":"The phrase contrasts shallow foreign-looking features with deeper artistic quality.","zh":"這個片語把表面的異國特色與更深的藝術質素作對比。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"storytelling with heart","meaning":"有真情的故事敘述","examples":[{"en":"Audiences enjoy storytelling with heart, precision and personality.","zh":"觀眾喜歡有真情、精準而有個性的故事敘述。"},{"en":"Storytelling with heart means telling stories with genuine emotion, warmth and human feeling.","zh":"有真情的故事敘述表示以真實情感、溫度和人性去講故事。"},{"en":"A simple family story can be powerful when it is told with heart.","zh":"一個簡單家庭故事如果有真情，也可以很有力量。"},{"en":"Technical perfection alone may feel cold if storytelling lacks emotional sincerity.","zh":"如果故事缺乏情感真誠，單靠技術完美可能顯得冰冷。"},{"en":"Stories told with heart often stay with audiences because they feel human rather than mechanical.","zh":"有真情的故事常留在觀眾心中，因為感覺有人性而不是機械化。"}],"source":"2013 Q7.pdf","sourcePage":10},{"front":"precision and personality","meaning":"精準和個性","examples":[{"en":"Asian entertainment often offers precision and personality.","zh":"亞洲娛樂常提供精準和個性。"},{"en":"“Precision and personality” means careful technical control combined with a distinctive human or artistic character.","zh":"「precision and personality」表示仔細技術控制與鮮明人性或藝術特色的結合。"},{"en":"Good design needs both precision and personality to avoid looking careless or generic.","zh":"良好設計需要精準和個性，才不會顯得隨便或千篇一律。"},{"en":"A performance can be technically exact while still showing individual personality.","zh":"表演可以技術上非常準確，同時仍展示個人特色。"},{"en":"Combining skill with character helps work feel both professional and memorable.","zh":"把技巧與個性結合，可以令作品既專業又難忘。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"the rise of","meaning":"……的崛起","examples":[{"en":"The rise of Asian stars reflects changing attitudes.","zh":"亞洲明星的崛起反映態度改變。"},{"en":"“The rise of” means the increasing importance, popularity or success of someone or something.","zh":"「the rise of」表示某人或某事的重要性、受歡迎程度或成功不斷增加。"},{"en":"The rise of online shopping changed retail habits.","zh":"網上購物的崛起改變零售習慣。"},{"en":"The rise of Asian stars can be seen in awards, charts and international audiences.","zh":"亞洲明星的崛起可以從獎項、排行榜和國際觀眾中看見。"},{"en":"A rise usually develops through several causes rather than one single event.","zh":"一項崛起通常由幾個原因逐步形成，而不是單一事件。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"reflects changing attitudes","meaning":"反映態度轉變","examples":[{"en":"The rise of Asian stars reflects changing attitudes in Western societies.","zh":"亞洲明星的崛起反映西方社會的態度轉變。"},{"en":"To reflect changing attitudes means to show that people’s opinions or values are becoming different.","zh":"反映態度轉變表示顯示人們的意見或價值觀正在變得不同。"},{"en":"Flexible workplaces reflect changing attitudes towards work-life balance.","zh":"彈性工作場所反映人們對工作與生活平衡的態度轉變。"},{"en":"Greater acceptance of non-English entertainment reflects changing attitudes towards cultural difference.","zh":"非英語娛樂得到更多接受，反映人們對文化差異的態度轉變。"},{"en":"Popular culture often reveals social changes before formal institutions do.","zh":"流行文化往往比正式制度更早顯示社會變化。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"Western societies","meaning":"西方社會","examples":[{"en":"Western societies are becoming more multicultural.","zh":"西方社會正變得更多元文化。"},{"en":"Western societies generally refers to societies in Europe, North America and related cultural contexts commonly described as Western.","zh":"西方社會一般指歐洲、北美及其他通常被描述為西方文化背景的社會。"},{"en":"Western societies contain many communities with different languages and cultural backgrounds.","zh":"西方社會包含很多不同語言和文化背景的社群。"},{"en":"Migration and global media have increased cultural diversity in many Western societies.","zh":"移民和全球媒體增加了很多西方社會的文化多樣性。"},{"en":"Broad labels such as “Western societies” include considerable internal difference.","zh":"「西方社會」這種廣泛稱呼之內，其實也有很大內部差異。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"multicultural","meaning":"多元文化的","examples":[{"en":"Many Western countries are now more multicultural than before.","zh":"很多西方國家現在比以前更多元文化。"},{"en":"Multicultural means including people, traditions and influences from several different cultures.","zh":"「multicultural」表示包含幾種不同文化的人、傳統和影響。"},{"en":"A multicultural school may celebrate festivals from many communities.","zh":"多元文化學校可能會慶祝多個社群的節日。"},{"en":"Multicultural societies usually encounter a wider range of food, languages and media.","zh":"多元文化社會通常會接觸更多不同食物、語言和媒體。"},{"en":"Greater cultural diversity can increase demand for more varied representation.","zh":"更大的文化多樣性可以增加對更多元代表性的需求。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"Asian communities","meaning":"亞洲社群","examples":[{"en":"Asian communities contribute to schools, workplaces and popular culture.","zh":"亞洲社群為學校、工作場所和流行文化作出貢獻。"},{"en":"Asian communities are groups of people with family, cultural or national connections to different parts of Asia.","zh":"亞洲社群是與亞洲不同地區有家庭、文化或國家聯繫的人群。"},{"en":"Asian communities may maintain traditions while also shaping the wider society around them.","zh":"亞洲社群可以保留傳統，同時影響周圍更廣泛的社會。"},{"en":"Businesses, schools and arts organisations can all be influenced by Asian communities.","zh":"企業、學校和藝術機構都可以受到亞洲社群影響。"},{"en":"Community contributions help make national culture more diverse.","zh":"社群作出的貢獻令國家文化更多元。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"contributing to","meaning":"為……作出貢獻","examples":[{"en":"Asian communities are contributing to many parts of Western life.","zh":"亞洲社群正為西方生活很多方面作出貢獻。"},{"en":"To contribute to something means to help create, support or improve it.","zh":"「contribute to」表示幫助創造、支持或改善某件事。"},{"en":"Volunteers contribute to the community by giving time and skills.","zh":"義工透過提供時間和技能為社區作出貢獻。"},{"en":"Migrant communities contribute to food, business, education and culture.","zh":"移民社群為飲食、商業、教育和文化作出貢獻。"},{"en":"Contribution can be social and cultural as well as economic.","zh":"貢獻可以是社會和文化上的，也可以是經濟上的。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"workplaces","meaning":"工作場所","examples":[{"en":"Asian communities contribute to schools and workplaces.","zh":"亞洲社群為學校和工作場所作出貢獻。"},{"en":"Workplaces are places or organisations where people do their jobs.","zh":"工作場所是人們進行工作的地方或機構。"},{"en":"Modern workplaces often include employees from many cultural backgrounds.","zh":"現代工作場所常包括來自多種文化背景的員工。"},{"en":"Different experiences can bring new ideas into workplaces.","zh":"不同經歷可以把新想法帶進工作場所。"},{"en":"Inclusive workplaces allow people from different communities to participate fully.","zh":"包容的工作場所讓不同社群的人都能充分參與。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"popular culture","meaning":"流行文化","examples":[{"en":"Asian communities contribute to popular culture.","zh":"亞洲社群為流行文化作出貢獻。"},{"en":"Popular culture includes widely shared music, films, fashion, media, language and entertainment.","zh":"流行文化包括廣泛共享的音樂、電影、時尚、媒體、語言和娛樂。"},{"en":"Social media trends are an important part of popular culture.","zh":"社交媒體潮流是流行文化重要一部分。"},{"en":"Immigrant communities can influence popular culture through food, music and storytelling.","zh":"移民社群可以透過食物、音樂和故事影響流行文化。"},{"en":"Popular culture constantly changes as new groups and ideas gain visibility.","zh":"隨着新群體和想法得到曝光，流行文化會不斷改變。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"for young people whose families come from Asia","meaning":"對於家庭來自亞洲的年輕人來說","examples":[{"en":"For young people whose families come from Asia, representation matters.","zh":"對於家庭來自亞洲的年輕人來說，代表性很重要。"},{"en":"This phrase refers to young people living elsewhere whose family backgrounds are connected to Asian countries or cultures.","zh":"這個片語指生活在其他地方、但家庭背景與亞洲國家或文化有關的年輕人。"},{"en":"Young people with migrant family backgrounds may grow up between several cultural influences.","zh":"有移民家庭背景的年輕人可能在幾種文化影響之間成長。"},{"en":"Seeing successful people who share part of their background can feel personally meaningful.","zh":"看見與自己部分背景相似的人取得成功，可以具有個人意義。"},{"en":"Representation can affect whether young people feel their identity belongs in public culture.","zh":"代表性可以影響年輕人是否覺得自己的身份屬於公共文化的一部分。"}],"source":"2013 Q7.pdf","sourcePage":11},{"front":"seeing someone succeed internationally","meaning":"看見某人在國際上成功","examples":[{"en":"Seeing Asian stars succeed internationally can be meaningful.","zh":"看見亞洲明星在國際上成功可以很有意義。"},{"en":"“Seeing someone succeed internationally” means witnessing a person gain recognition or achievement across different countries.","zh":"「seeing someone succeed internationally」表示看見某人在不同國家獲得認可或成就。"},{"en":"A young athlete may feel inspired by seeing someone from their hometown succeed internationally.","zh":"年輕運動員看見來自家鄉的人在國際上成功，可能會受到鼓舞。"},{"en":"International success can challenge assumptions about who belongs at the highest level.","zh":"國際成功可以挑戰人們對誰屬於最高層次舞台的假設。"},{"en":"Visible success can become symbolic for people who share a similar background.","zh":"可見的成功可以對擁有相似背景的人具有象徵意義。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"more than entertainment","meaning":"不只是娛樂","examples":[{"en":"Representation can be more than entertainment.","zh":"代表性可以不只是娛樂。"},{"en":"“More than entertainment” means something has social, emotional or cultural importance beyond simply amusing audiences.","zh":"「more than entertainment」表示某件事除了娛樂觀眾，還具有社會、情感或文化重要性。"},{"en":"A historical film can be more than entertainment if it starts public discussion.","zh":"歷史電影如果引發公共討論，就可以不只是娛樂。"},{"en":"Seeing people like yourself on screen can affect identity and confidence.","zh":"在螢幕上看見與自己相似的人，可以影響身份認同和自信。"},{"en":"Popular media can entertain while also shaping how societies see different groups.","zh":"流行媒體既能娛樂，也會塑造社會如何看待不同群體。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"a quiet form of recognition","meaning":"一種默默的認同","examples":[{"en":"Seeing Asian stars succeed can be a quiet form of recognition.","zh":"看見亞洲明星成功，可以是一種默默的認同。"},{"en":"A quiet form of recognition is a subtle feeling that your identity or background is being acknowledged and valued.","zh":"默默的認同是一種細微感覺，表示自己的身份或背景得到承認和重視。"},{"en":"Seeing your home language in a public sign can feel like a quiet form of recognition.","zh":"在公共告示看到自己的家庭語言，可以帶來一種默默的認同。"},{"en":"Representation does not always need a direct message to make people feel seen.","zh":"代表性不一定需要直接說明，也能令人覺得自己被看見。"},{"en":"Small symbols of inclusion can have deep emotional importance.","zh":"細小的包容象徵可以有很深的情感重要性。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"non-Asian viewers","meaning":"非亞洲觀眾","examples":[{"en":"Non-Asian viewers can see the world through different eyes.","zh":"非亞洲觀眾可以用不同眼光看世界。"},{"en":"Non-Asian viewers are audience members whose backgrounds are not Asian.","zh":"非亞洲觀眾是背景並非亞洲的觀眾。"},{"en":"Non-Asian viewers may discover unfamiliar family customs through Asian dramas.","zh":"非亞洲觀眾可以透過亞洲劇集發現陌生的家庭習俗。"},{"en":"Exposure to different stories can broaden what non-Asian viewers know about everyday life elsewhere.","zh":"接觸不同故事可以擴闊非亞洲觀眾對其他地方日常生活的了解。"},{"en":"Cultural media can offer perspective without requiring audiences to have the same background.","zh":"文化媒體可以提供新視角，而不要求觀眾擁有相同背景。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"meanwhile","meaning":"同時；另一方面","examples":[{"en":"For non-Asian viewers, meanwhile, these stars offer a different view.","zh":"對非亞洲觀眾來說，另一方面，這些明星提供不同視角。"},{"en":"“Meanwhile” introduces another related situation or group that should also be considered.","zh":"「meanwhile」用來帶出另一個也需要考慮的相關情況或群體。"},{"en":"Local residents benefit from the project; meanwhile, tourists gain a better experience too.","zh":"本地居民受惠於計劃；同時，遊客也得到更好體驗。"},{"en":"Representation helps Asian audiences; meanwhile, it can broaden non-Asian viewers’ perspectives.","zh":"代表性幫助亞洲觀眾；另一方面，也可以擴闊非亞洲觀眾的視野。"},{"en":"This word allows a writer to shift attention while keeping the ideas connected.","zh":"這個詞讓作者在保持觀點連繫的同時轉移注意。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"provide a chance to","meaning":"提供機會去","examples":[{"en":"These stars provide a chance to see the world differently.","zh":"這些明星提供機會去以不同方法看世界。"},{"en":"To provide a chance to do something means to create an opportunity for that action or experience.","zh":"「provide a chance to」表示創造一個可以進行某項行動或經歷的機會。"},{"en":"Travel provides a chance to practise a language in real situations.","zh":"旅行提供機會在真實情況練習語言。"},{"en":"Foreign films provide a chance to encounter unfamiliar values and habits.","zh":"外國電影提供機會接觸陌生價值觀和習慣。"},{"en":"Opportunities to see different perspectives can reduce narrow assumptions.","zh":"接觸不同視角的機會可以減少狹窄假設。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"see the world through different eyes","meaning":"以不同眼光看世界","examples":[{"en":"Asian stars help viewers see the world through different eyes.","zh":"亞洲明星幫助觀眾以不同眼光看世界。"},{"en":"To see the world through different eyes means to understand life from a perspective different from your usual one.","zh":"以不同眼光看世界表示從與自己平常不同的角度理解生活。"},{"en":"Reading a refugee’s memoir can help students see the world through different eyes.","zh":"閱讀難民回憶錄可以幫助學生以不同眼光看世界。"},{"en":"Films from another culture can challenge assumptions about what is normal.","zh":"另一種文化的電影可以挑戰人對甚麼算正常的假設。"},{"en":"Seeing through different eyes does not require abandoning your own view; it means understanding another one.","zh":"以不同眼光看世界不代表放棄自己的觀點，而是理解另一種觀點。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"Michelle Yeoh’s Oscar win","meaning":"楊紫瓊奧斯卡獲獎","examples":[{"en":"Michelle Yeoh’s Oscar win mattered for representation.","zh":"楊紫瓊奧斯卡獲獎對代表性具有意義。"},{"en":"“Michelle Yeoh’s Oscar win” refers to her receiving an Academy Award, a moment that carried significance beyond personal success.","zh":"「Michelle Yeoh’s Oscar win」指她獲得奧斯卡獎，而這一刻的意義超越個人成就。"},{"en":"A major award win can become symbolic when the winner comes from a group rarely recognised before.","zh":"當得獎者來自以前很少獲認可的群體，大型獎項可以具有象徵意義。"},{"en":"Her success gave greater visibility to Asian women in international cinema.","zh":"她的成功增加亞洲女性在國際電影中的可見度。"},{"en":"Individual achievements can influence wider ideas about who belongs in leading roles.","zh":"個人成就可以影響更廣泛社會對誰應擔任主角的想法。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"superb performance","meaning":"出色演出","examples":[{"en":"Michelle Yeoh gave a superb performance.","zh":"楊紫瓊帶來了出色演出。"},{"en":"A superb performance is an exceptionally skilled, impressive and effective piece of acting or performing.","zh":"出色演出是技巧非常高、令人印象深刻而且有效的表演。"},{"en":"The actor received praise for a superb performance in the final scene.","zh":"那位演員因最後一幕的出色演出獲得讚賞。"},{"en":"A superb performance combines technical ability with emotional truth.","zh":"出色演出把技術能力與真實情感結合。"},{"en":"Awards may recognise excellence, but audiences can value a superb performance even without prizes.","zh":"獎項可以認可優秀表現，但即使沒有獎項，觀眾也可以欣賞出色演出。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"challenged the old belief","meaning":"挑戰舊有觀念","examples":[{"en":"Her win challenged the old belief about Asian women in cinema.","zh":"她的獲獎挑戰了電影中關於亞洲女性的舊有觀念。"},{"en":"To challenge an old belief means to provide evidence or an example that questions a long-held assumption.","zh":"挑戰舊有觀念表示用證據或例子質疑長期存在的假設。"},{"en":"The successful project challenged the old belief that older workers cannot learn new technology.","zh":"成功的項目挑戰了年長員工不能學新科技的舊有觀念。"},{"en":"Visible success can challenge stereotypes by showing that earlier limits were artificial.","zh":"可見的成功可以證明以前的限制是人為的，從而挑戰刻板印象。"},{"en":"Beliefs often change when reality provides clear counterexamples.","zh":"當現實提供清楚反例，觀念往往會改變。"}],"source":"2013 Q7.pdf","sourcePage":12},{"front":"old belief","meaning":"舊有觀念","examples":[{"en":"The old belief limited Asian women to side characters.","zh":"舊有觀念把亞洲女性限制在配角位置。"},{"en":"An old belief is an idea or assumption that has existed for a long time, even if it may no longer be accurate.","zh":"舊有觀念是存在很長時間的想法或假設，即使它可能已不準確。"},{"en":"The old belief that only men should lead companies has been challenged widely.","zh":"只有男性應領導公司的舊有觀念已受到廣泛挑戰。"},{"en":"Media can preserve old beliefs by repeating the same kinds of roles.","zh":"媒體如果反覆安排相同角色，可以延續舊有觀念。"},{"en":"Old beliefs become weaker when new examples show more possibilities.","zh":"當新例子展示更多可能，舊有觀念便會變弱。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"remain side characters","meaning":"一直做配角","examples":[{"en":"Asian women should not have to remain side characters.","zh":"亞洲女性不應被迫一直做配角。"},{"en":"To remain side characters means to continue being given only secondary roles rather than central ones.","zh":"一直做配角表示持續只被安排次要角色，而不是中心角色。"},{"en":"Talented actors should not remain side characters simply because of stereotypes.","zh":"有才能的演員不應只因刻板印象而一直做配角。"},{"en":"Greater representation allows performers from minority groups to take leading roles.","zh":"更多代表性讓少數群體表演者有機會擔任主角。"},{"en":"Moving beyond side characters changes whose stories audiences are invited to follow.","zh":"走出配角位置，會改變觀眾被邀請跟隨誰的故事。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"global cinema","meaning":"全球電影","examples":[{"en":"The role of Asian women in global cinema is changing.","zh":"亞洲女性在全球電影中的角色正在改變。"},{"en":"Global cinema refers to the international world of film production, distribution and audiences across many countries.","zh":"全球電影指跨越多個國家的國際電影製作、發行和觀眾世界。"},{"en":"Film festivals connect local directors with global cinema.","zh":"電影節把本地導演與全球電影連結。"},{"en":"Streaming has made global cinema more visible to ordinary viewers.","zh":"串流令普通觀眾更容易接觸全球電影。"},{"en":"Global cinema becomes richer when stories and creators come from many regions.","zh":"當故事和創作者來自更多地區，全球電影會更豐富。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"representation","meaning":"代表性；呈現","examples":[{"en":"Representation is not only about fairness.","zh":"代表性不只是關乎公平。"},{"en":"Representation is the way different people, identities and communities are shown and included in media or public life.","zh":"代表性是不同人物、身份和社群如何在媒體或公共生活中被呈現和包括。"},{"en":"Representation matters when children rarely see people like themselves in books or films.","zh":"當孩子很少在書本或電影看到與自己相似的人，代表性便很重要。"},{"en":"Good representation includes varied roles rather than repeating narrow stereotypes.","zh":"良好代表性包括多樣角色，而不是反覆狹窄刻板印象。"},{"en":"Representation affects both who feels recognised and what audiences learn about others.","zh":"代表性既影響誰感到被認同，也影響觀眾如何認識其他人。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"not only about fairness","meaning":"不只是關乎公平","examples":[{"en":"Representation is not only about fairness.","zh":"代表性不只是關乎公平。"},{"en":"“Not only about fairness” means the issue has other important benefits or meanings beyond equal treatment.","zh":"「not only about fairness」表示除了公平對待外，問題還有其他重要好處或意義。"},{"en":"Education is not only about examination results; it also develops judgement and confidence.","zh":"教育不只是關乎考試成績，也會發展判斷力和自信。"},{"en":"Representation can make stories richer as well as improve fairness.","zh":"代表性除了改善公平，也可以令故事更豐富。"},{"en":"This structure signals that the argument will go beyond the most obvious moral reason.","zh":"這個句式表示論點會超越最明顯的道德理由。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"makes entertainment richer","meaning":"令娛樂內容更豐富","examples":[{"en":"Representation makes entertainment richer.","zh":"代表性令娛樂內容更豐富。"},{"en":"To make entertainment richer means to increase its variety, depth, perspectives and creative possibilities.","zh":"令娛樂內容更豐富表示增加多樣性、深度、視角和創作可能。"},{"en":"More writers from different backgrounds can make television drama richer.","zh":"更多不同背景的編劇可以令電視劇內容更豐富。"},{"en":"New cultural perspectives bring unfamiliar conflicts, humour and images into entertainment.","zh":"新文化視角把陌生衝突、幽默和畫面帶入娛樂內容。"},{"en":"Variety can improve creativity because creators are not forced to repeat the same stories.","zh":"多樣性可以提升創意，因為創作者不用不停重複相同故事。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"with more cultures come more stories","meaning":"文化越多，故事也越多","examples":[{"en":"With more cultures come more stories and emotions.","zh":"文化越多，故事和情感也越多。"},{"en":"“With more cultures come more stories” means greater cultural diversity naturally brings a wider range of narratives and experiences.","zh":"「with more cultures come more stories」表示文化多樣性越高，自然會帶來更多不同故事和經歷。"},{"en":"With more voices in the classroom come more ideas about the same problem.","zh":"課室裏聲音越多，對同一個問題的想法也越多。"},{"en":"Different cultural histories create different characters, conflicts and memories.","zh":"不同文化歷史會產生不同角色、衝突和回憶。"},{"en":"Diversity increases creative possibilities rather than simply changing who appears on screen.","zh":"多樣性增加的不只是螢幕上出現誰，也增加創作可能。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"images to remember","meaning":"令人記住的畫面","examples":[{"en":"More cultures bring more images to remember.","zh":"更多文化會帶來更多令人記住的畫面。"},{"en":"“Images to remember” means distinctive visual moments that stay in audiences’ memories.","zh":"「images to remember」表示會長久留在觀眾記憶中的獨特視覺時刻。"},{"en":"The film created several powerful images to remember long after the story ended.","zh":"電影創造了幾個在故事結束很久後仍令人記住的有力畫面。"},{"en":"Different cultural traditions can introduce new colours, places and symbols to cinema.","zh":"不同文化傳統可以把新顏色、地方和象徵帶進電影。"},{"en":"Memorable images help stories stay emotionally present after viewing.","zh":"難忘畫面幫助故事在觀看後仍保持情感存在感。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"slowly but surely","meaning":"慢慢但確定地","examples":[{"en":"Slowly but surely, Asian stars are entering global youth culture.","zh":"慢慢但確定地，亞洲明星正在進入全球青年文化。"},{"en":"“Slowly but surely” means gradually but steadily and with clear progress.","zh":"「slowly but surely」表示逐漸但穩定地取得清楚進展。"},{"en":"Slowly but surely, the shy student became more comfortable speaking in class.","zh":"慢慢但確定地，那個害羞學生變得更自在在課堂發言。"},{"en":"Cultural change may be gradual, but repeated exposure makes it increasingly established.","zh":"文化轉變可以很漸進，但反覆接觸會令它越來越穩固。"},{"en":"This phrase emphasises reliable progress rather than sudden change.","zh":"這個片語強調可靠進展，而不是突然改變。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"shared imagination","meaning":"共同想像","examples":[{"en":"Asian stars are becoming part of the shared imagination of global youth.","zh":"亞洲明星正成為全球青年共同想像的一部分。"},{"en":"Shared imagination means the common collection of characters, images, stories and ideas recognised by many people in a group.","zh":"共同想像是某個群體很多人都認識的角色、畫面、故事和想法的共同集合。"},{"en":"Famous superheroes form part of the shared imagination of many children.","zh":"著名超級英雄是很多兒童共同想像的一部分。"},{"en":"Global media allows young people in different countries to recognise the same stars and stories.","zh":"全球媒體令不同國家的年輕人認識相同明星和故事。"},{"en":"Entering shared imagination means becoming part of what a generation commonly knows and references.","zh":"進入共同想像表示成為一代人普遍知道和引用的文化內容。"}],"source":"2013 Q7.pdf","sourcePage":13},{"front":"global youth","meaning":"全球青年","examples":[{"en":"Asian stars are shaping the imagination of global youth.","zh":"亞洲明星正在塑造全球青年的想像。"},{"en":"Global youth refers broadly to young people across many different countries who are increasingly connected through media and culture.","zh":"全球青年廣義指世界不同國家的年輕人，他們越來越透過媒體和文化連結。"},{"en":"Social media gives global youth access to similar music and trends.","zh":"社交媒體讓全球青年接觸相似音樂和潮流。"},{"en":"Global youth may share cultural references despite living thousands of kilometres apart.","zh":"即使相隔數千公里，全球青年也可能共享文化參照。"},{"en":"Digital connection does not erase local differences, but it creates more shared experiences.","zh":"數碼連結不會消除本地差異，但會創造更多共同經歷。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, their popularity is not a passing trend.","zh":"綜合而言，他們的受歡迎並不是短暫潮流。"},{"en":"“All things considered” means after taking the main evidence, causes and different viewpoints into account.","zh":"「all things considered」表示把主要證據、原因和不同觀點都考慮之後。"},{"en":"All things considered, the project achieved more than we expected.","zh":"綜合而言，這個項目取得的成果比預期更多。"},{"en":"After considering access, quality and representation, the writer reaches a broader conclusion.","zh":"考慮接觸渠道、質素和代表性後，作者得出較全面的結論。"},{"en":"This phrase is useful for introducing a balanced final judgement.","zh":"這個片語適合帶出平衡的最終判斷。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"growing popularity","meaning":"日益增長的受歡迎程度","examples":[{"en":"The growing popularity of Asian stars is not a passing trend.","zh":"亞洲明星日益增長的受歡迎程度並不是短暫潮流。"},{"en":"Growing popularity means an increasing level of public interest, recognition and support over time.","zh":"日益增長的受歡迎程度表示公眾興趣、認知和支持隨時間增加。"},{"en":"The growing popularity of cycling has encouraged cities to build more bicycle lanes.","zh":"單車日益受歡迎，鼓勵城市興建更多單車徑。"},{"en":"Repeated international success suggests the popularity of Asian entertainment is continuing to expand.","zh":"反覆取得國際成功，顯示亞洲娛樂的受歡迎程度仍在擴大。"},{"en":"A trend becomes more significant when popularity grows across different regions and age groups.","zh":"當受歡迎程度跨越不同地區和年齡群增長，趨勢便更具重要性。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"not a passing trend","meaning":"不是短暫潮流","examples":[{"en":"The popularity of Asian stars is not a passing trend.","zh":"亞洲明星的受歡迎不是短暫潮流。"},{"en":"“Not a passing trend” means not a temporary fashion that will disappear quickly.","zh":"「not a passing trend」表示不是很快便會消失的暫時風潮。"},{"en":"Online banking is not a passing trend because it has become part of everyday life.","zh":"網上銀行不是短暫潮流，因為它已成為日常生活一部分。"},{"en":"Long-term audience growth suggests Asian entertainment is more than a short-lived curiosity.","zh":"長期觀眾增長顯示亞洲娛樂不只是短暫好奇。"},{"en":"A trend becomes lasting when it is supported by deeper social and technological changes.","zh":"當一股潮流得到更深層社會和科技改變支持，它便較可能持續。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"the result of","meaning":"……的結果","examples":[{"en":"This popularity is the result of easier access and stronger storytelling.","zh":"這種受歡迎是更容易接觸和更有力故事敘述的結果。"},{"en":"“The result of” introduces the cause or causes that produced a particular outcome.","zh":"「the result of」用來帶出造成某個結果的原因。"},{"en":"Better health was the result of regular exercise and improved sleep.","zh":"健康改善是定期運動和睡眠改善的結果。"},{"en":"Global popularity can be the result of several forces working together.","zh":"全球受歡迎可以是幾種力量共同作用的結果。"},{"en":"This phrase is useful when connecting an observable outcome with its underlying causes.","zh":"這個片語適合把可見結果與背後原因連接起來。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"easier access","meaning":"更容易接觸","examples":[{"en":"Easier access has helped Asian stars reach global audiences.","zh":"更容易接觸幫助亞洲明星接觸全球觀眾。"},{"en":"Easier access means fewer difficulties, costs or barriers when trying to reach something.","zh":"更容易接觸表示接近某件事時有更少困難、成本或障礙。"},{"en":"Online booking gives patients easier access to medical appointments.","zh":"網上預約令病人更容易獲得醫療預約。"},{"en":"Streaming provides easier access to foreign films than physical distribution did.","zh":"與實體發行相比，串流令外國電影更容易被接觸。"},{"en":"When access becomes easier, more people can discover and repeatedly engage with content.","zh":"當接觸變得容易，更多人便可以發現並反覆接觸內容。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"cross-cultural storytelling","meaning":"跨文化故事敘述","examples":[{"en":"Cross-cultural storytelling helps Asian entertainment travel.","zh":"跨文化故事敘述幫助亞洲娛樂走向不同地方。"},{"en":"Cross-cultural storytelling is storytelling that connects people from different cultural backgrounds through shared themes while preserving cultural differences.","zh":"跨文化故事敘述是透過共同主題連接不同文化背景的人，同時保留文化差異的敘事。"},{"en":"A local family story can become cross-cultural storytelling when audiences elsewhere recognise the emotions.","zh":"當其他地方觀眾能理解其中情感，本地家庭故事也可以成為跨文化故事。"},{"en":"Translation and universal themes help cross-cultural storytelling reach wider audiences.","zh":"翻譯和普世主題幫助跨文化故事接觸更廣泛觀眾。"},{"en":"Good cross-cultural storytelling balances local detail with emotions others can understand.","zh":"良好的跨文化敘事會在本地細節與他人能理解的情感之間取得平衡。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"wider desire to","meaning":"更廣泛希望去","examples":[{"en":"There is a wider desire to see different lives represented.","zh":"社會有更廣泛希望看到不同人生被呈現。"},{"en":"“A wider desire to” means a wish that is becoming shared by more people or groups.","zh":"「a wider desire to」表示某種願望正由更多人或群體共同擁有。"},{"en":"There is a wider desire to work flexibly among younger employees.","zh":"年輕員工之間有更廣泛希望彈性工作的需求。"},{"en":"More diverse audiences create a wider desire to see different communities on screen.","zh":"更多元觀眾令社會更廣泛希望在銀幕看見不同社群。"},{"en":"A wider social desire can influence what media companies choose to produce.","zh":"更廣泛的社會願望可以影響傳媒公司選擇製作甚麼。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"different lives represented","meaning":"不同人生被呈現","examples":[{"en":"Audiences want to see different lives represented on screen.","zh":"觀眾希望在銀幕上看見不同人生被呈現。"},{"en":"“Different lives represented” means media showing people with varied backgrounds, identities, experiences and ways of living.","zh":"「different lives represented」表示媒體呈現不同背景、身份、經歷和生活方式的人。"},{"en":"Viewers may want rural, migrant or working-class lives represented more accurately.","zh":"觀眾可能希望鄉村、移民或工人階層生活被更準確呈現。"},{"en":"Showing different lives helps entertainment move beyond one narrow picture of society.","zh":"呈現不同人生可以幫助娛樂內容走出對社會單一狹窄的想像。"},{"en":"Varied representation can help audiences understand both differences and shared experiences.","zh":"多樣代表性可以幫助觀眾理解差異和共同經歷。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"on screen and on stage","meaning":"在螢幕上和舞台上","examples":[{"en":"Asian stars are represented on screen and on stage.","zh":"亞洲明星在螢幕上和舞台上都有代表。"},{"en":"“On screen and on stage” means in film or television as well as in live performances.","zh":"「on screen and on stage」表示既在電影或電視，也在現場表演中。"},{"en":"The actor works both on screen and on stage.","zh":"那位演員同時在螢幕上和舞台上工作。"},{"en":"Representation across different media makes visibility broader.","zh":"在不同媒體都有代表，可以令可見度更廣泛。"},{"en":"Success in both recorded and live entertainment shows influence across several parts of culture.","zh":"在錄製和現場娛樂都取得成功，顯示影響力遍及文化不同部分。"}],"source":"2013 Q7.pdf","sourcePage":14},{"front":"media organisations","meaning":"傳媒機構","examples":[{"en":"Media organisations should treat this trend as an opportunity.","zh":"傳媒機構應把這股潮流視為機會。"},{"en":"Media organisations are companies and institutions that produce, distribute or report media content.","zh":"傳媒機構是製作、發行或報道媒體內容的公司和機構。"},{"en":"Television networks, newspapers and streaming companies are media organisations.","zh":"電視台、報紙和串流公司都是傳媒機構。"},{"en":"Media organisations influence which artists and stories receive public attention.","zh":"傳媒機構會影響哪些藝人和故事得到公眾關注。"},{"en":"Greater cultural diversity creates both responsibilities and creative opportunities for media organisations.","zh":"更大的文化多樣性為傳媒機構帶來責任，也帶來創作機會。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"treat this trend as","meaning":"把這股潮流視為","examples":[{"en":"Schools should treat this trend as an opportunity.","zh":"學校應把這股潮流視為一個機會。"},{"en":"To treat a trend as something means to understand and respond to it in that particular way.","zh":"「treat a trend as」表示以某種特定方式理解和回應一股潮流。"},{"en":"Businesses should treat changing customer habits as useful information rather than a threat.","zh":"企業應把顧客習慣改變視為有用資訊，而不是威脅。"},{"en":"Schools can treat international entertainment trends as opportunities for language and cultural learning.","zh":"學校可以把國際娛樂潮流視為語言和文化學習機會。"},{"en":"How people interpret a trend affects how they respond to it.","zh":"人如何理解一股潮流，會影響他如何回應。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"an opportunity rather than a surprise","meaning":"一個機會，而不是驚訝","examples":[{"en":"This trend should be treated as an opportunity rather than a surprise.","zh":"這股潮流應被視為一個機會，而不是只令人驚訝。"},{"en":"“An opportunity rather than a surprise” means something should be used constructively instead of merely being seen as unexpected.","zh":"「an opportunity rather than a surprise」表示應積極利用某件事，而不只是覺得它出乎意料。"},{"en":"New technology should be treated as a learning opportunity rather than a surprise.","zh":"新科技應被視為學習機會，而不是只感到驚訝。"},{"en":"Growing Asian influence gives schools and media useful material to engage with.","zh":"亞洲影響力增加，為學校和媒體提供有用的參與材料。"},{"en":"This contrast encourages action instead of passive amazement.","zh":"這種對比鼓勵人採取行動，而不是被動驚訝。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"beyond their usual languages","meaning":"超越自己平日使用的語言","examples":[{"en":"Students should explore films and songs beyond their usual languages.","zh":"學生應探索超越自己平日使用語言的電影和歌曲。"},{"en":"“Beyond their usual languages” means in languages outside those students normally speak, study or consume media in.","zh":"「beyond their usual languages」表示使用學生平常不說、不學或不常接觸的語言。"},{"en":"A reader can explore books beyond their usual language through translation.","zh":"讀者可以透過翻譯探索自己平常語言以外的書籍。"},{"en":"Subtitles make it easier to explore entertainment beyond familiar languages.","zh":"字幕令人更容易探索熟悉語言以外的娛樂。"},{"en":"Looking beyond usual languages can expose learners to new sounds, ideas and cultures.","zh":"超越平常語言可以讓學習者接觸新聲音、想法和文化。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"critics","meaning":"評論家","examples":[{"en":"Critics should judge Asian works by their quality.","zh":"評論家應按亞洲作品的質素評價它們。"},{"en":"Critics are people who professionally or publicly analyse and evaluate films, music, books or other cultural works.","zh":"評論家是專業或公開分析和評價電影、音樂、書籍或其他文化作品的人。"},{"en":"Film critics often discuss acting, direction, writing and technical quality.","zh":"電影評論家常討論演技、導演、編劇和技術質素。"},{"en":"Good critics explain the reasons behind their judgments rather than simply saying they liked or disliked something.","zh":"好的評論家會解釋判斷理由，而不只是說喜歡或不喜歡。"},{"en":"Critics can influence public attention, especially when audiences are unfamiliar with a work.","zh":"尤其當觀眾不熟悉作品時，評論家可以影響公眾關注。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"judge something by","meaning":"按……評價","examples":[{"en":"Critics should judge Asian works by their quality rather than their origin.","zh":"評論家應按亞洲作品的質素，而不是出身地評價它們。"},{"en":"To judge something by a quality means to evaluate it according to that standard.","zh":"「judge something by」表示按照某項標準評價某件事。"},{"en":"Students should judge information by its evidence rather than by how confidently it is presented.","zh":"學生應按證據評價資訊，而不是按它說得有多自信。"},{"en":"Art should be judged by its execution and impact, not simply where it comes from.","zh":"藝術應按執行和影響評價，而不只是看來自哪裏。"},{"en":"Clear standards help reduce unfair assumptions in evaluation.","zh":"清楚標準有助減少評價中的不公平假設。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"by their quality rather than by their origin","meaning":"按質素而非出身地評價","examples":[{"en":"Asian works should be judged by quality rather than origin.","zh":"亞洲作品應按質素而非出身地評價。"},{"en":"This means evaluation should focus on how good the work is rather than which country or culture produced it.","zh":"這表示評價應集中作品有多好，而不是由哪個國家或文化製作。"},{"en":"A restaurant should be judged by its food and service rather than by whether its cuisine is familiar.","zh":"餐廳應按食物和服務評價，而不是按菜式是否熟悉。"},{"en":"Cultural origin can shape a work without determining its artistic value.","zh":"文化出身可以影響作品，但不會決定其藝術價值。"},{"en":"Fair criticism separates curiosity about difference from judgment of quality.","zh":"公平評論會把對差異的好奇與對質素的判斷分開。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"support artists","meaning":"支持藝人","examples":[{"en":"Fans should support artists respectfully.","zh":"粉絲應以尊重方式支持藝人。"},{"en":"To support artists means to encourage, value or help creators through attention, purchases, attendance or positive engagement.","zh":"支持藝人表示透過關注、購買、出席活動或正面互動鼓勵和重視創作者。"},{"en":"Buying official music is one way to support artists.","zh":"購買官方音樂是支持藝人的其中一種方法。"},{"en":"Fans can support artists without invading their privacy.","zh":"粉絲可以支持藝人，而不用侵犯私隱。"},{"en":"Healthy support respects both the work and the person who created it.","zh":"健康的支持既尊重作品，也尊重創作它的人。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"without reducing them to stereotypes","meaning":"不把他們簡化為刻板印象","examples":[{"en":"Fans should support artists without reducing them to stereotypes.","zh":"粉絲應支持藝人，而不把他們簡化為刻板印象。"},{"en":"To reduce someone to stereotypes means to treat them as a simple fixed image rather than a complex individual.","zh":"把某人簡化為刻板印象，表示把對方看成固定簡單形象，而不是複雜個體。"},{"en":"A student should not be reduced to a stereotype because of their nationality.","zh":"不應只因國籍就把學生簡化成某種刻板印象。"},{"en":"Fans may admire cultural identity without assuming every Asian artist is the same.","zh":"粉絲可以欣賞文化身份，而不用假設每個亞洲藝人都一樣。"},{"en":"Respect requires seeing people as individuals rather than symbols of an entire group.","zh":"尊重需要把人看成獨立個體，而不是整個群體的符號。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"stereotypes","meaning":"刻板印象","examples":[{"en":"Asian artists should not be reduced to stereotypes.","zh":"亞洲藝人不應被簡化為刻板印象。"},{"en":"Stereotypes are oversimplified and fixed beliefs about a group of people.","zh":"刻板印象是對一群人過度簡化而固定的看法。"},{"en":"The stereotype that all quiet students are shy can be inaccurate.","zh":"所有安靜學生都害羞這種刻板印象可以並不準確。"},{"en":"Media stereotypes become harmful when they limit the kinds of roles people are allowed to have.","zh":"當媒體刻板印象限制某群人能擔任甚麼角色，就會造成傷害。"},{"en":"More varied representation helps challenge stereotypes by showing complexity.","zh":"更多元代表性透過展示複雜性，可以挑戰刻板印象。"}],"source":"2013 Q7.pdf","sourcePage":15},{"front":"the world of entertainment","meaning":"娛樂世界","examples":[{"en":"The world of entertainment is changing.","zh":"娛樂世界正在改變。"},{"en":"“The world of entertainment” refers broadly to industries and cultures involving films, music, television, performance and related media.","zh":"「the world of entertainment」廣泛指電影、音樂、電視、表演和相關媒體產業與文化。"},{"en":"Technology has transformed the world of entertainment by changing how people discover content.","zh":"科技改變人們發現內容的方法，從而轉變娛樂世界。"},{"en":"The world of entertainment now includes more global interaction than before.","zh":"現在的娛樂世界比以前有更多全球互動。"},{"en":"Changes in audiences, platforms and creators continually reshape entertainment culture.","zh":"觀眾、平台和創作者的改變會不斷重塑娛樂文化。"}],"source":"2013 Q7.pdf","sourcePage":16},{"front":"there is every reason to believe that","meaning":"完全有理由相信","examples":[{"en":"There is every reason to believe that Asian stars will continue to shine.","zh":"完全有理由相信亞洲明星會繼續發光發亮。"},{"en":"“There is every reason to believe that” means the available evidence strongly supports a particular expectation.","zh":"「there is every reason to believe that」表示現有證據強烈支持某項預期。"},{"en":"There is every reason to believe that demand will grow because applications are increasing each year.","zh":"由於申請人數每年增加，完全有理由相信需求會上升。"},{"en":"Continued awards, audience growth and digital access give strong reasons to expect further success.","zh":"持續獲獎、觀眾增長和數碼接觸提供了相信未來繼續成功的有力理由。"},{"en":"This phrase expresses confidence based on evidence rather than simple hope.","zh":"這個片語表達的是有證據支持的信心，而不只是希望。"}],"source":"2013 Q7.pdf","sourcePage":16},{"front":"continue to shine","meaning":"繼續發光發亮","examples":[{"en":"Asian stars will continue to shine in global culture.","zh":"亞洲明星會在全球文化中繼續發光發亮。"},{"en":"To continue to shine figuratively means to keep succeeding, attracting attention and demonstrating talent.","zh":"「continue to shine」比喻持續成功、吸引注意和展示才能。"},{"en":"The young athlete continued to shine after moving to international competition.","zh":"那位年輕運動員進入國際比賽後仍繼續發光發亮。"},{"en":"Artists continue to shine when strong work keeps audiences interested over time.","zh":"當優秀作品長期保持觀眾興趣，藝人便能繼續發亮。"},{"en":"“Shine” compares success and visibility with bright light.","zh":"「shine」把成功和可見度比作明亮的光。"}],"source":"2013 Q7.pdf","sourcePage":16},{"front":"not as guests in Western culture","meaning":"不是作為西方文化中的客人","examples":[{"en":"Asian stars will shine not as guests in Western culture.","zh":"亞洲明星發光發亮時，不會只是作為西方文化中的客人。"},{"en":"“Not as guests in Western culture” means they should not be treated as temporary outsiders allowed into someone else’s cultural space.","zh":"「not as guests in Western culture」表示不應把他們視為暫時進入別人文化空間的外來者。"},{"en":"Artists from different countries increasingly participate as equal creators rather than occasional visitors.","zh":"不同國家的藝人越來越以平等創作者身份參與，而不是偶爾來訪的人。"},{"en":"Global culture is becoming less centred on one region owning the main stage.","zh":"全球文化正逐漸不再由單一地區擁有主要舞台。"},{"en":"The phrase rejects the idea that Western culture is the permanent host and everyone else merely visits.","zh":"這個說法否定西方文化永遠是主人、其他人只是客人的想法。"}],"source":"2013 Q7.pdf","sourcePage":16},{"front":"creators of global culture","meaning":"全球文化的創造者","examples":[{"en":"Asian stars are becoming creators of global culture.","zh":"亞洲明星正成為全球文化的創造者。"},{"en":"Creators of global culture are people who actively shape the stories, styles, music and ideas shared across countries.","zh":"全球文化的創造者是主動塑造跨國共享故事、風格、音樂和想法的人。"},{"en":"International musicians can become creators of global culture when their work influences audiences far beyond home.","zh":"當國際音樂人的作品影響遠超本國的觀眾，他們可以成為全球文化的創造者。"},{"en":"Asian artists now help shape worldwide fashion, music, film and youth culture rather than simply entering existing Western trends.","zh":"亞洲藝人現在會塑造全球時尚、音樂、電影和青年文化，而不只是加入既有西方潮流。"},{"en":"Being a creator of global culture means contributing to what the world shares, not merely being accepted by it.","zh":"成為全球文化的創造者，表示為全世界共同分享的文化作出貢獻，而不只是被接受。"}],"source":"2013 Q7.pdf","sourcePage":16}],"dse/writing/part-b/2013/Q8":[{"front":"before the song ends","meaning":"在歌曲完結之前","examples":[{"en":"The speech asks graduates to act before the song ends.","zh":"這篇演講呼籲畢業生在歌曲完結之前行動。"},{"en":"Before the song ends means before time or a precious chance runs out.","zh":"before the song ends 的意思是在時間或珍貴機會用完之前。"},{"en":"A student should thank a teacher before the school year ends, not after everyone has left.","zh":"學生應在學年結束前感謝老師，而不是等到大家都離開後。"},{"en":"If we wait too long, the chance to speak, forgive, or begin may disappear.","zh":"如果我們等太久，說話、原諒或開始的機會可能會消失。"},{"en":"This phrase reminds people to act while there is still time.","zh":"這個短語提醒人們趁仍有時間時行動。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"good morning, Principal","meaning":"校長早晨","examples":[{"en":"Good morning, Principal, teachers, parents, and my fellow graduates.","zh":"校長、老師、家長和各位畢業同學早晨。"},{"en":"Good morning, Principal is a polite formal greeting used at the start of a school speech.","zh":"Good morning, Principal 是在校園演講開首使用的禮貌正式問候。"},{"en":"A student speaker may begin with “Good morning, Principal” before addressing teachers and classmates.","zh":"學生演講者可以先說「校長早晨」，再向老師和同學致意。"},{"en":"This greeting shows respect for the head of the school.","zh":"這個問候顯示對學校校長的尊重。"},{"en":"It helps the speech begin in a proper and formal tone.","zh":"它幫助演講以恰當而正式的語氣開始。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"above all","meaning":"最重要的是","examples":[{"en":"Good morning, Principal, teachers, parents, and, above all, my fellow graduates.","zh":"校長、老師、家長，最重要的是各位畢業同學，早晨。"},{"en":"Above all means most importantly, especially compared with the other things mentioned.","zh":"above all 的意思是最重要的是，尤其是與其他已提及的事物相比。"},{"en":"Today we thank our teachers, our families, and, above all, the classmates who walked with us.","zh":"今天我們感謝老師、家人，最重要的是一路同行的同學。"},{"en":"Speakers use above all to show which group or idea matters most in that moment.","zh":"演講者使用 above all 來顯示當刻哪個群體或想法最重要。"},{"en":"This phrase helps give emotional focus to a list.","zh":"這個短語幫助一串名單有情感焦點。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"my fellow graduates","meaning":"各位畢業同學","examples":[{"en":"The speaker addresses his fellow graduates.","zh":"演講者向各位畢業同學致辭。"},{"en":"My fellow graduates means the other students who are graduating with the speaker.","zh":"my fellow graduates 是指與演講者一起畢業的其他學生。"},{"en":"A speaker may say “my fellow graduates” to create a sense of shared experience.","zh":"演講者可以說「各位畢業同學」來營造共同經歷的感覺。"},{"en":"This phrase reminds listeners that they have reached the same milestone together.","zh":"這個短語提醒聽眾，他們一起到達同一個里程碑。"},{"en":"It sounds warm because the speaker speaks as one of the group.","zh":"它聽起來溫暖，因為演講者是以群體一員的身份說話。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"a popular song","meaning":"一首流行歌曲","examples":[{"en":"A popular song tells us that time waits for no one.","zh":"一首流行歌曲告訴我們時間不等人。"},{"en":"A popular song is a song known and liked by many people.","zh":"popular song 是許多人認識和喜歡的歌曲。"},{"en":"A speaker may refer to a popular song because the audience can recognise it easily.","zh":"演講者可以引用一首流行歌曲，因為觀眾容易認出它。"},{"en":"Popular songs can carry simple ideas that feel memorable and emotional.","zh":"流行歌曲可以承載簡單但令人難忘和有情感的想法。"},{"en":"This phrase helps connect a formal speech with shared culture.","zh":"這個短語幫助把正式演講與共同文化連繫起來。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"tells us that","meaning":"告訴我們","examples":[{"en":"A popular song tells us that time waits for no one.","zh":"一首流行歌曲告訴我們時間不等人。"},{"en":"Tells us that means gives us a message, lesson, or idea.","zh":"tells us that 的意思是給我們一個訊息、教訓或想法。"},{"en":"A story tells us that small choices can shape a whole life.","zh":"一個故事告訴我們，小選擇可以塑造整個人生。"},{"en":"When a song tells us something, it may teach through images rather than direct advice.","zh":"當歌曲告訴我們某事時，它可能透過意象而不是直接建議來教導。"},{"en":"This phrase is useful when explaining the meaning behind a text or song.","zh":"當解釋文本或歌曲背後意思時，這個短語很有用。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"time waits for no one","meaning":"時間不等人","examples":[{"en":"A popular song reminds us that time waits for no one.","zh":"一首流行歌曲提醒我們時間不等人。"},{"en":"Time waits for no one means time keeps passing whether people are ready or not.","zh":"time waits for no one 的意思是無論人們是否準備好，時間都會繼續流逝。"},{"en":"A student cannot keep delaying revision because time waits for no one before exams.","zh":"學生不能一直拖延溫習，因為考試前時間不等人。"},{"en":"This idea pushes people to act before chances disappear.","zh":"這個想法推動人們在機會消失前行動。"},{"en":"The phrase reminds us that life moves forward even when we hesitate.","zh":"這個短語提醒我們，即使我們猶豫，人生仍會向前走。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"unforgettable images","meaning":"難忘的意象","examples":[{"en":"The song gives us two unforgettable images.","zh":"這首歌給我們兩個難忘的意象。"},{"en":"Unforgettable images are pictures or ideas that stay strongly in the mind.","zh":"unforgettable images 是強烈留在腦海中的畫面或想法。"},{"en":"A speech may use unforgettable images, such as a clock or a fading song, to make time feel real.","zh":"演講可以使用時鐘或漸漸消散的歌曲等難忘意象，令時間變得真實。"},{"en":"Images become unforgettable when they connect simple pictures with deep feelings.","zh":"當意象把簡單畫面與深層感受連繫起來時，它就變得難忘。"},{"en":"This phrase describes memorable language that helps listeners remember a message.","zh":"這個短語描述幫助聽眾記住訊息的難忘語言。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"reduce buildings to ruins","meaning":"使建築物化為廢墟","examples":[{"en":"Time can reduce even solid buildings to ruins.","zh":"時間甚至可以使堅固的建築物化為廢墟。"},{"en":"To reduce buildings to ruins means to make strong buildings become broken and destroyed over time.","zh":"reduce buildings to ruins 的意思是令堅固建築物隨時間變得破爛和毀壞。"},{"en":"An abandoned school may be reduced to ruins after many years without care.","zh":"一所被荒廢的學校多年無人照料後，可能化為廢墟。"},{"en":"This image shows that even strong things cannot escape time forever.","zh":"這個意象顯示即使強大的東西也不能永遠逃過時間。"},{"en":"The phrase helps listeners understand the power of passing time.","zh":"這個短語幫助聽眾理解時間流逝的力量。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"solid buildings","meaning":"堅固的建築物","examples":[{"en":"Time can reduce even solid buildings to ruins.","zh":"時間甚至可以使堅固的建築物化為廢墟。"},{"en":"Solid buildings are strong buildings that seem stable and lasting.","zh":"solid buildings 是看似穩固而持久的強壯建築物。"},{"en":"A stone school hall may look like one of the solid buildings that will stand forever.","zh":"石造的學校禮堂可能看起來像會永遠屹立的堅固建築物。"},{"en":"Even solid buildings need care because time, weather, and neglect can damage them.","zh":"即使堅固的建築物也需要照料，因為時間、天氣和忽視都會傷害它們。"},{"en":"This phrase helps contrast strength with the power of time.","zh":"這個短語幫助對比堅固與時間力量。"}],"source":"2013 Q8.pdf","sourcePage":1},{"front":"to ruins","meaning":"成為廢墟","examples":[{"en":"Solid buildings may be reduced to ruins by time.","zh":"堅固的建築物可能被時間變成廢墟。"},{"en":"To ruins means into a broken, damaged, or destroyed state.","zh":"to ruins 的意思是變成破爛、受損或被毀的狀態。"},{"en":"An old theatre may fall to ruins if nobody repairs it for decades.","zh":"如果幾十年沒有人維修，一間舊戲院可能成為廢墟。"},{"en":"When something turns to ruins, it shows loss, age, and neglect.","zh":"當某物成為廢墟，它顯示失去、歲月和忽視。"},{"en":"This phrase is often used to describe physical destruction or emotional collapse.","zh":"這個短語常用來描述實體毀壞或情感崩塌。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"as precious as jewels","meaning":"像珠寶一樣珍貴","examples":[{"en":"Our hours are as precious as jewels.","zh":"我們的時光像珠寶一樣珍貴。"},{"en":"As precious as jewels means extremely valuable and worth protecting.","zh":"as precious as jewels 的意思是非常有價值，值得保護。"},{"en":"A final afternoon with classmates can be as precious as jewels after graduation.","zh":"畢業後，與同學共度的最後一個下午可以像珠寶一樣珍貴。"},{"en":"Time feels precious because once an hour passes, we cannot buy it back.","zh":"時間之所以珍貴，是因為一小時過去後，我們不能再買回來。"},{"en":"This phrase uses comparison to show the value of time.","zh":"這個短語用比較來展示時間的價值。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"at first","meaning":"起初","examples":[{"en":"At first, these may sound like gloomy lines from a sad song.","zh":"起初，這些可能聽起來像一首悲傷歌曲中的悲觀歌詞。"},{"en":"At first means in the beginning, before thinking more deeply or learning more.","zh":"at first 的意思是在開始時，還未深入思考或了解更多之前。"},{"en":"At first, graduation may feel like an ending, but later it can feel like a beginning.","zh":"起初，畢業可能感覺像結束，但後來可以感覺像開始。"},{"en":"This phrase helps show how an opinion can change after reflection.","zh":"這個短語幫助顯示看法如何在反思後改變。"},{"en":"It is useful when moving from a first impression to a deeper understanding.","zh":"當由第一印象轉向更深理解時，它很有用。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"gloomy lines","meaning":"悲觀陰沉的歌詞","examples":[{"en":"These may sound like gloomy lines from a sad song.","zh":"這些可能聽起來像一首悲傷歌曲中的悲觀陰沉歌詞。"},{"en":"Gloomy lines are words that sound dark, sad, or pessimistic.","zh":"gloomy lines 是聽起來黑暗、悲傷或悲觀的文字。"},{"en":"A line about buildings turning to ruins may sound gloomy if we hear only the loss in it.","zh":"關於建築物化為廢墟的一句歌詞，如果我們只聽到失去，可能會顯得悲觀。"},{"en":"Gloomy lines can still teach wisdom if they push people to value life.","zh":"悲觀陰沉的歌詞如果推動人們珍惜人生，仍可以教導智慧。"},{"en":"This phrase describes language with a heavy emotional mood.","zh":"這個短語描述帶有沉重情緒氣氛的語言。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"standing here today","meaning":"今天站在這裏","examples":[{"en":"Standing here today, I hear something wiser in the song.","zh":"今天站在這裏，我從歌曲中聽出更有智慧的意思。"},{"en":"Standing here today means speaking from this present moment and place.","zh":"standing here today 的意思是從當下這個時刻和地方發言。"},{"en":"Standing here today as graduates, we understand our school years differently.","zh":"今天作為畢業生站在這裏，我們對校園歲月有不同理解。"},{"en":"This phrase connects the speaker’s reflection to the ceremony happening now.","zh":"這個短語把演講者的反思與正在發生的典禮連繫起來。"},{"en":"It helps make the speech feel immediate and personal.","zh":"它幫助演講感覺即時而個人化。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"wearing the uniform","meaning":"穿着校服","examples":[{"en":"The speaker is wearing the uniform of a student for perhaps one of the last times.","zh":"演講者也許是最後幾次之一穿着學生校服。"},{"en":"Wearing the uniform means having the school’s official clothing on.","zh":"wearing the uniform 的意思是穿着學校的正式服裝。"},{"en":"A graduate may feel emotional when wearing the uniform on the final school day.","zh":"畢業生在最後上學日穿着校服時，可能感到情緒湧現。"},{"en":"The uniform can remind students of years of lessons, friendships, and routines.","zh":"校服可以提醒學生多年的課堂、友誼和日常規律。"},{"en":"This phrase turns ordinary school clothing into a symbol of leaving.","zh":"這個短語把普通校服變成離別的象徵。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"for perhaps one of the last times","meaning":"也許是最後幾次之一","examples":[{"en":"I am wearing the uniform for perhaps one of the last times.","zh":"我也許是最後幾次之一穿着校服。"},{"en":"For perhaps one of the last times means something may happen only a few more times before ending.","zh":"for perhaps one of the last times 的意思是某事可能只會再發生少數幾次便結束。"},{"en":"A graduate may enter the school hall for perhaps one of the last times.","zh":"畢業生也許是最後幾次之一走進學校禮堂。"},{"en":"This phrase makes an ordinary action feel precious because it may soon disappear.","zh":"這個短語令普通行動變得珍貴，因為它可能快將消失。"},{"en":"It expresses uncertainty, nostalgia, and the feeling of farewell.","zh":"它表達不確定、懷念和告別感。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"hear something wiser","meaning":"聽出更有智慧的意思","examples":[{"en":"Standing here today, I hear something wiser.","zh":"今天站在這裏，我聽出更有智慧的意思。"},{"en":"To hear something wiser means to understand a deeper or more thoughtful meaning.","zh":"hear something wiser 的意思是理解到更深或更有思想的含義。"},{"en":"A student may hear something wiser in a teacher’s old advice after graduation.","zh":"畢業後，學生可能從老師昔日的建議中聽出更有智慧的意思。"},{"en":"Time can change how we understand words that once sounded simple.","zh":"時間可以改變我們對曾經聽起來簡單的說話的理解。"},{"en":"This phrase shows growth in understanding.","zh":"這個短語展示理解上的成長。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"asking us to fear time","meaning":"要我們害怕時間","examples":[{"en":"The song is not asking us to fear time.","zh":"這首歌不是要我們害怕時間。"},{"en":"Asking us to fear time means telling us to be afraid of time passing.","zh":"asking us to fear time 的意思是叫我們害怕時間流逝。"},{"en":"A speech should not ask graduates to fear time, but to use it wisely.","zh":"演講不應要畢業生害怕時間，而應要他們明智地運用時間。"},{"en":"Fear of time may make people anxious, while respect for time can make them active.","zh":"害怕時間可能令人焦慮，而尊重時間可以令人行動。"},{"en":"This phrase helps reject a negative interpretation of the song.","zh":"這個短語幫助否定對歌曲的負面解讀。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"asking us to respect it","meaning":"要我們尊重它","examples":[{"en":"The song is asking us to respect time.","zh":"這首歌要我們尊重時間。"},{"en":"Asking us to respect it means urging us to value time and use it carefully.","zh":"asking us to respect it 的意思是敦促我們重視時間並小心運用它。"},{"en":"Graduation asks students to respect time by not wasting chances to learn and love.","zh":"畢業提醒學生尊重時間，不要浪費學習和愛人的機會。"},{"en":"Respecting time does not mean panic; it means living with attention and purpose.","zh":"尊重時間不代表恐慌，而是有專注和目標地生活。"},{"en":"This phrase gives a positive lesson from the song.","zh":"這個短語從歌曲中帶出正面教訓。"}],"source":"2013 Q8.pdf","sourcePage":2},{"front":"President of the Students’ Union","meaning":"學生會主席","examples":[{"en":"As President of the Students’ Union, I have watched us count down to this ceremony.","zh":"作為學生會主席，我看着我們倒數迎接這場典禮。"},{"en":"President of the Students’ Union is the student leader who represents the student body.","zh":"President of the Students’ Union 是代表學生群體的學生領袖。"},{"en":"The President of the Students’ Union may speak at graduation on behalf of classmates.","zh":"學生會主席可以在畢業禮上代表同學發言。"},{"en":"This role gives the speaker a reason to reflect on students’ shared experience.","zh":"這個角色給演講者一個理由去反思學生的共同經歷。"},{"en":"The phrase explains the speaker’s position and responsibility.","zh":"這個短語解釋演講者的身份和責任。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"count down to","meaning":"倒數迎接","examples":[{"en":"We have counted down to examinations, celebrations, and today’s ceremony.","zh":"我們曾倒數迎接考試、慶祝活動和今天的典禮。"},{"en":"To count down to something means to wait for an important event by marking the time left.","zh":"count down to something 的意思是透過計算剩餘時間等待重要事件。"},{"en":"Students may count down to graduation as the final school days pass.","zh":"隨着最後上學日過去，學生可能倒數迎接畢業。"},{"en":"Counting down can make an event feel exciting, frightening, or emotional.","zh":"倒數可以令事件感覺興奮、可怕或充滿情感。"},{"en":"This phrase shows anticipation before a major moment.","zh":"這個短語展示重大時刻前的期待。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"today’s ceremony","meaning":"今天的典禮","examples":[{"en":"We have counted down to today’s ceremony.","zh":"我們曾倒數迎接今天的典禮。"},{"en":"Today’s ceremony means the formal event taking place on this day.","zh":"today’s ceremony 是指今天正在舉行的正式活動。"},{"en":"Today’s ceremony may include speeches, certificates, applause, and farewells.","zh":"今天的典禮可能包括演講、證書、掌聲和告別。"},{"en":"A ceremony matters because it marks a change that students have been moving toward.","zh":"典禮重要，因為它標誌學生一直走向的轉變。"},{"en":"This phrase brings attention to the special occasion happening now.","zh":"這個短語把注意力帶到正在發生的特別場合。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"the graduating class","meaning":"畢業班","examples":[{"en":"This moment has made us, the graduating class, think about the years ahead.","zh":"這一刻令我們這個畢業班思考未來的歲月。"},{"en":"The graduating class is the group of students finishing school or a course together.","zh":"the graduating class 是一起完成學校或課程的一群學生。"},{"en":"The graduating class may feel proud, nervous, and thankful on the same day.","zh":"畢業班可能在同一天感到驕傲、緊張和感恩。"},{"en":"Graduation brings the class together before everyone moves in different directions.","zh":"畢業在大家走向不同方向前把全班聚在一起。"},{"en":"This phrase describes a shared identity at the end of school life.","zh":"這個短語描述校園生活結束時的共同身份。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"the years ahead","meaning":"未來的歲月","examples":[{"en":"Graduates should think carefully about the years ahead.","zh":"畢業生應仔細思考未來的歲月。"},{"en":"The years ahead means the future years that have not yet happened.","zh":"the years ahead 是指尚未發生的未來年份。"},{"en":"The years ahead may include university, work, new friendships, and difficult choices.","zh":"未來的歲月可能包括大學、工作、新友誼和艱難選擇。"},{"en":"Thinking about the years ahead helps graduates use time more wisely now.","zh":"思考未來的歲月幫助畢業生現在更明智地運用時間。"},{"en":"This phrase points from the present ceremony toward the future.","zh":"這個短語由眼前典禮指向未來。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"not merely grow older","meaning":"不只是年紀增長","examples":[{"en":"We should not merely grow older.","zh":"我們不應只是年紀增長。"},{"en":"Not merely grow older means not only let time pass and age increase.","zh":"not merely grow older 的意思是不只是讓時間過去、年齡增加。"},{"en":"A graduate should not merely grow older but also learn from choices and mistakes.","zh":"畢業生不應只是年紀增長，也應從選擇和錯誤中學習。"},{"en":"Growing older happens naturally, but growing wiser requires effort.","zh":"年紀增長會自然發生，但變得更有智慧需要努力。"},{"en":"This phrase separates physical age from real maturity.","zh":"這個短語把實際年齡與真正成熟分開。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"grow deeper, kinder and braver","meaning":"變得更有深度、更仁慈和更勇敢","examples":[{"en":"We should grow deeper, kinder, and braver.","zh":"我們應變得更有深度、更仁慈和更勇敢。"},{"en":"To grow deeper, kinder and braver means to become more thoughtful, caring, and courageous.","zh":"grow deeper, kinder and braver 的意思是變得更有思想、更關懷別人和更有勇氣。"},{"en":"A graduate grows deeper by reflecting, kinder by helping others, and braver by trying difficult things.","zh":"畢業生透過反思變得更有深度，透過幫助別人變得更仁慈，透過嘗試困難事情變得更勇敢。"},{"en":"Time is meaningful when it changes our character for the better.","zh":"當時間令我們的品格變得更好，它才有意義。"},{"en":"This phrase describes moral growth, not only future success.","zh":"這個短語描述道德成長，而不只是未來成功。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"do not wait for life to begin","meaning":"不要等待人生開始","examples":[{"en":"Do not wait for life to begin.","zh":"不要等待人生開始。"},{"en":"Do not wait for life to begin means do not delay action until some perfect future moment.","zh":"do not wait for life to begin 的意思是不要把行動推遲到某個完美的未來時刻。"},{"en":"A graduate should not wait for life to begin after university, a job, or success.","zh":"畢業生不應等到大學、工作或成功之後才覺得人生開始。"},{"en":"Waiting too long can turn dreams into excuses.","zh":"等太久會把夢想變成藉口。"},{"en":"This phrase urges listeners to treat the present as real life already.","zh":"這個短語敦促聽眾把現在就視為真正人生。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"spend your time as if","meaning":"像……般運用時間","examples":[{"en":"Spend your time as if every hour matters.","zh":"像每一小時都重要般運用你的時間。"},{"en":"Spend your time as if means use time in a way that shows you believe something is true.","zh":"spend your time as if 的意思是以顯示你相信某事為真的方式使用時間。"},{"en":"Spend your time as if friendships need care before distance grows.","zh":"像友誼在距離增加前需要珍惜般運用你的時間。"},{"en":"This phrase encourages people to let values shape daily choices.","zh":"這個短語鼓勵人們讓價值觀塑造日常選擇。"},{"en":"It reminds graduates that time should be used with attention, not wasted casually.","zh":"它提醒畢業生應有意識地運用時間，而不是隨意浪費。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"every hour matters","meaning":"每一小時都重要","examples":[{"en":"Every hour matters.","zh":"每一小時都重要。"},{"en":"Every hour matters means each part of our time has value and effect.","zh":"every hour matters 的意思是我們每一部分時間都有價值和影響。"},{"en":"An hour spent helping a friend may become a memory that lasts for years.","zh":"花一小時幫助朋友，可能成為維持多年的回憶。"},{"en":"If every hour matters, small daily choices are more important than they seem.","zh":"如果每一小時都重要，日常小選擇就比看起來更重要。"},{"en":"This phrase teaches respect for ordinary time.","zh":"這個短語教人尊重普通時間。"}],"source":"2013 Q8.pdf","sourcePage":3},{"front":"let time humble us","meaning":"讓時間使我們謙卑","examples":[{"en":"First, let time humble us.","zh":"首先，讓時間使我們謙卑。"},{"en":"Let time humble us means allow the passing of time to remind us that we are not fully in control.","zh":"let time humble us 的意思是讓時間流逝提醒我們，我們並不能完全掌控一切。"},{"en":"Graduation humbles students because years that once felt endless have passed quickly.","zh":"畢業使學生謙卑，因為曾經感覺漫長的歲月很快已過去。"},{"en":"Time humbles us when we realise we cannot keep every moment forever.","zh":"當我們明白不能永遠留住每一刻，時間就使我們謙卑。"},{"en":"This phrase teaches modesty through reflection on time.","zh":"這個短語透過對時間的反思教導謙遜。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"enter this school","meaning":"進入這所學校","examples":[{"en":"When we entered this school, graduation seemed far away.","zh":"當我們進入這所學校時，畢業似乎很遙遠。"},{"en":"To enter this school means to begin studying at this school.","zh":"enter this school 的意思是開始在這所學校讀書。"},{"en":"Students may feel nervous when they first enter this school as juniors.","zh":"學生初入這所學校成為低年級學生時，可能感到緊張。"},{"en":"Entering a school begins a journey of lessons, friendships, and growth.","zh":"進入一所學校展開一段由課堂、友誼和成長組成的旅程。"},{"en":"This phrase points back to the start of the graduates’ shared experience.","zh":"這個短語回望畢業生共同經歷的起點。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"impossibly far away","meaning":"遙不可及","examples":[{"en":"Graduation seemed impossibly far away.","zh":"畢業似乎遙不可及。"},{"en":"Impossibly far away means so distant that it feels almost unreal or unreachable.","zh":"impossibly far away 的意思是遙遠得幾乎不真實或難以到達。"},{"en":"On the first day of secondary school, graduation may seem impossibly far away.","zh":"在中學第一天，畢業可能看似遙不可及。"},{"en":"Time feels strange because what once seemed far away eventually arrives.","zh":"時間很奇妙，因為曾經看似遙遠的事最終會到來。"},{"en":"This phrase captures how young students experience the future.","zh":"這個短語捕捉年輕學生如何感受未來。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"one moment…, the next…","meaning":"前一刻……下一刻……","examples":[{"en":"One moment, we were asking seniors where the hall was; the next, younger students were calling us seniors.","zh":"前一刻，我們還在問師兄師姐禮堂在哪裏；下一刻，低年級學生已稱我們為師兄師姐。"},{"en":"One moment…, the next… shows that time has passed quickly between two contrasting scenes.","zh":"one moment…, the next… 顯示兩個對比場景之間時間過得很快。"},{"en":"One moment, we were new students; the next, we were preparing for graduation.","zh":"前一刻，我們還是新生；下一刻，我們已在準備畢業。"},{"en":"This structure makes change feel sudden and emotional.","zh":"這個結構令改變感覺突然而有情感。"},{"en":"It is useful when comparing the beginning and end of a journey.","zh":"當比較旅程的開始和結束時，它很有用。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"asking seniors","meaning":"向師兄師姐詢問","examples":[{"en":"We were once asking seniors where the hall was.","zh":"我們曾經向師兄師姐詢問禮堂在哪裏。"},{"en":"Asking seniors means seeking help or directions from older students.","zh":"asking seniors 的意思是向高年級學生尋求幫助或指示。"},{"en":"New students may ask seniors how to find classrooms or join clubs.","zh":"新生可以向師兄師姐詢問如何找課室或加入學會。"},{"en":"Asking seniors shows that we once depended on those who knew the school better.","zh":"向師兄師姐詢問顯示我們曾依靠更熟悉學校的人。"},{"en":"This phrase reminds graduates of their first uncertain days.","zh":"這個短語提醒畢業生想起最初不確定的日子。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"calling us seniors","meaning":"稱我們為師兄師姐","examples":[{"en":"Younger students are now calling us seniors.","zh":"低年級學生現在稱我們為師兄師姐。"},{"en":"Calling us seniors means younger students now see us as older, experienced students.","zh":"calling us seniors 的意思是低年級學生現在把我們視為年長、有經驗的學生。"},{"en":"A Form One student may call a graduating student a senior when asking for advice.","zh":"中一學生向畢業生請教時，可能稱他們為師兄師姐。"},{"en":"Being called seniors shows that time has changed our role in the school.","zh":"被稱為師兄師姐顯示時間已改變我們在學校中的角色。"},{"en":"This phrase marks the shift from newcomer to guide.","zh":"這個短語標誌由新生變成引導者的轉變。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"between those two moments","meaning":"在那兩個時刻之間","examples":[{"en":"Between those two moments came thousands of ordinary scenes.","zh":"在那兩個時刻之間，出現了成千上萬個平凡場景。"},{"en":"Between those two moments means during the time separating two important points.","zh":"between those two moments 的意思是在兩個重要時間點之間的時段。"},{"en":"Between entering school and graduation came years of lessons, jokes, tests, and friendships.","zh":"在入學和畢業之間，有多年課堂、玩笑、測驗和友誼。"},{"en":"This phrase reminds us that life is built from what happens between big events.","zh":"這個短語提醒我們，人生由重大事件之間發生的事組成。"},{"en":"It helps turn ordinary memories into something meaningful.","zh":"它幫助把普通回憶變得有意義。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"ordinary scenes","meaning":"平凡場景","examples":[{"en":"Thousands of ordinary scenes became our youth.","zh":"成千上萬個平凡場景成為我們的青春。"},{"en":"Ordinary scenes are simple everyday moments that may not seem important at the time.","zh":"ordinary scenes 是當時看似不重要的簡單日常時刻。"},{"en":"Eating lunch with classmates or waiting outside a classroom can be ordinary scenes.","zh":"與同學吃午飯或在課室外等候都可以是平凡場景。"},{"en":"Ordinary scenes become precious when we realise they formed our school life.","zh":"當我們明白它們組成校園生活時，平凡場景就變得珍貴。"},{"en":"This phrase teaches listeners to value small memories.","zh":"這個短語教聽眾珍惜小回憶。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"morning assembly","meaning":"早會","examples":[{"en":"We rushed to morning assembly during our school years.","zh":"在校園歲月中，我們曾趕去早會。"},{"en":"Morning assembly is a regular school gathering held before lessons begin.","zh":"morning assembly 是上課前舉行的定期學校集會。"},{"en":"Students may sing, listen to announcements, or hear speeches during morning assembly.","zh":"學生可能在早會中唱歌、聽宣布或聽演講。"},{"en":"Rushing to morning assembly can become a shared memory after graduation.","zh":"趕去早會在畢業後可以成為共同回憶。"},{"en":"This phrase describes a familiar routine in school life.","zh":"這個短語描述校園生活中的熟悉日常。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"in the canteen","meaning":"在飯堂","examples":[{"en":"We laughed in the canteen with our classmates.","zh":"我們曾在飯堂與同學一起大笑。"},{"en":"In the canteen means inside the school dining area where students eat or meet.","zh":"in the canteen 的意思是在學生吃飯或聚會的學校用餐地方裏。"},{"en":"Students may share snacks, jokes, and worries in the canteen.","zh":"學生可以在飯堂分享零食、笑話和憂慮。"},{"en":"A canteen can hold many friendships because students gather there every day.","zh":"飯堂可以承載許多友誼，因為學生每天都在那裏聚集。"},{"en":"This phrase gives the speech a warm and ordinary school setting.","zh":"這個短語給演講一個溫暖而日常的校園背景。"}],"source":"2013 Q8.pdf","sourcePage":4},{"front":"stare helplessly at","meaning":"無助地盯着","examples":[{"en":"We stared helplessly at past papers.","zh":"我們曾無助地盯着歷屆試題。"},{"en":"To stare helplessly at something means to look at it with confusion, worry, or no idea what to do.","zh":"stare helplessly at something 的意思是帶着困惑、憂慮或不知所措地看着某物。"},{"en":"A student may stare helplessly at a maths question the night before a test.","zh":"學生可能在測驗前一晚無助地盯着一道數學題。"},{"en":"This phrase shows the honest struggle behind school success.","zh":"這個短語展示校園成功背後真實的掙扎。"},{"en":"It makes the memory humorous and relatable.","zh":"它令回憶帶有幽默感並令人有共鳴。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"past papers","meaning":"歷屆試題","examples":[{"en":"We stared helplessly at past papers before examinations.","zh":"考試前，我們曾無助地盯着歷屆試題。"},{"en":"Past papers are old exam papers used for revision and practice.","zh":"past papers 是用來溫習和練習的舊考試卷。"},{"en":"Students use past papers to understand question types and exam timing.","zh":"學生使用歷屆試題來理解題型和考試時間安排。"},{"en":"Past papers can build confidence, but they can also make exams feel frightening.","zh":"歷屆試題可以建立信心，但也可以令考試感覺可怕。"},{"en":"This phrase describes a common part of student preparation.","zh":"這個短語描述學生備試的常見部分。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"whisper encouragement","meaning":"低聲鼓勵","examples":[{"en":"We whispered encouragement before a competition.","zh":"比賽前，我們曾低聲鼓勵彼此。"},{"en":"To whisper encouragement means to quietly say supportive words to someone.","zh":"whisper encouragement 的意思是輕聲對某人說支持的話。"},{"en":"A teammate may whisper encouragement before a debate, race, or music performance.","zh":"隊友可以在辯論、賽跑或音樂表演前低聲鼓勵。"},{"en":"Quiet support can calm fear even when the pressure is high.","zh":"即使壓力很大，安靜的支持也可以安撫恐懼。"},{"en":"This phrase shows friendship through small words.","zh":"這個短語透過小小的話語展示友誼。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"before a competition","meaning":"比賽前","examples":[{"en":"We whispered encouragement before a competition.","zh":"比賽前，我們曾低聲鼓勵彼此。"},{"en":"Before a competition means in the moments leading up to a contest or performance.","zh":"before a competition 的意思是在比賽或表演前的時刻。"},{"en":"Students may feel nervous before a competition because they want to do well.","zh":"學生比賽前可能感到緊張，因為他們想表現好。"},{"en":"Encouragement before a competition can help teammates feel less alone.","zh":"比賽前的鼓勵可以幫助隊友感到不那麼孤單。"},{"en":"This phrase marks a tense but meaningful moment.","zh":"這個短語標示一個緊張但有意義的時刻。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"feel historic","meaning":"感覺具歷史意義","examples":[{"en":"None of those days felt historic while we were living them.","zh":"當我們正在經歷那些日子時，沒有一天感覺具歷史意義。"},{"en":"Feel historic means seem important enough to become part of memory or history.","zh":"feel historic 的意思是看似重要到足以成為記憶或歷史的一部分。"},{"en":"An ordinary lunch with friends may not feel historic until it becomes the last one.","zh":"與朋友普通吃午飯，直到它成為最後一次，才可能感覺具歷史意義。"},{"en":"Many meaningful days feel normal while they are happening.","zh":"許多有意義的日子在發生時都感覺平常。"},{"en":"This phrase shows how memory changes the value of ordinary time.","zh":"這個短語展示記憶如何改變普通時間的價值。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"while we were living them","meaning":"當我們正在經歷它們時","examples":[{"en":"Those days did not feel historic while we were living them.","zh":"當我們正在經歷那些日子時，它們並不感覺具歷史意義。"},{"en":"While we were living them means during the time we were actually experiencing those days.","zh":"while we were living them 的意思是在我們真正經歷那些日子的時候。"},{"en":"School routines may seem ordinary while we are living them, but precious after they end.","zh":"校園日常在我們經歷時可能看似普通，但結束後卻珍貴。"},{"en":"This phrase contrasts present experience with later memory.","zh":"這個短語對比當下經驗與後來回憶。"},{"en":"It reminds us that meaning is often recognised only afterwards.","zh":"它提醒我們，意義往往是事後才被認出。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"become our youth","meaning":"成為我們的青春","examples":[{"en":"Together, those ordinary days became our youth.","zh":"合起來，那些平凡日子成為我們的青春。"},{"en":"Become our youth means turn into the memories and experiences that define our young years.","zh":"become our youth 的意思是變成定義我們年少歲月的回憶和經歷。"},{"en":"Lessons, canteen talks, and exam stress together become our youth.","zh":"課堂、飯堂談話和考試壓力合起來成為我們的青春。"},{"en":"Youth is often built from ordinary days rather than dramatic events.","zh":"青春常由平凡日子組成，而不是由戲劇性事件組成。"},{"en":"This phrase gives emotional value to daily school life.","zh":"這個短語給日常校園生活情感價值。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"tear down a building","meaning":"拆毀一座建築物","examples":[{"en":"Time can tear down a building.","zh":"時間可以拆毀一座建築物。"},{"en":"To tear down a building means to destroy or take apart a structure.","zh":"tear down a building 的意思是摧毀或拆除一座建築。"},{"en":"Workers may tear down an old block to make way for a new one.","zh":"工人可能拆毀一座舊樓，為新建築讓路。"},{"en":"In a speech, this image shows that time can change even strong things.","zh":"在演講中，這個意象顯示時間甚至可以改變堅固事物。"},{"en":"This phrase makes the power of time easy to imagine.","zh":"這個短語令時間的力量容易想像。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"erase our excuses","meaning":"抹去我們的藉口","examples":[{"en":"Time can erase our excuses.","zh":"時間可以抹去我們的藉口。"},{"en":"To erase our excuses means to remove the reasons we use to delay action.","zh":"erase our excuses 的意思是移除我們用來拖延行動的理由。"},{"en":"Graduation can erase the excuse that we still have plenty of school days left.","zh":"畢業可以抹去「我們還有很多上學日」這個藉口。"},{"en":"When time passes, excuses like “later” may no longer protect us.","zh":"當時間過去，「遲些」這類藉口可能不再保護我們。"},{"en":"This phrase urges people to stop delaying what matters.","zh":"這個短語敦促人們停止拖延重要的事。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"our laziness","meaning":"我們的懶惰","examples":[{"en":"Time can erase our excuses and our laziness.","zh":"時間可以抹去我們的藉口和我們的懶惰。"},{"en":"Our laziness means our unwillingness to act, practise, or make effort.","zh":"our laziness 是指我們不願行動、練習或努力。"},{"en":"A student may regret laziness when exam day arrives and preparation is unfinished.","zh":"當考試日到來而準備未完成時，學生可能後悔自己的懶惰。"},{"en":"Laziness feels harmless at first, but time can reveal its cost.","zh":"懶惰起初看似無害，但時間可以揭示其代價。"},{"en":"This phrase warns that delay and inaction have consequences.","zh":"這個短語提醒人們拖延和不行動有後果。"}],"source":"2013 Q8.pdf","sourcePage":5},{"front":"the illusion that","meaning":"……的錯覺","examples":[{"en":"Time can erase our illusion that later is a safe place.","zh":"時間可以抹去我們「遲些是安全地方」的錯覺。"},{"en":"The illusion that means the false belief that something is true.","zh":"the illusion that 的意思是錯誤地相信某事是真的。"},{"en":"Students may have the illusion that there will always be more time to apologise.","zh":"學生可能有一種錯覺，以為永遠還有更多時間道歉。"},{"en":"This illusion is dangerous because it makes delay feel safe.","zh":"這種錯覺很危險，因為它令拖延感覺安全。"},{"en":"The phrase helps expose a comforting but false idea.","zh":"這個短語幫助揭示一個令人安心但錯誤的想法。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"a safe place to store our dreams","meaning":"存放夢想的安全地方","examples":[{"en":"Later is not a safe place to store our dreams.","zh":"「遲些」不是存放夢想的安全地方。"},{"en":"A safe place to store our dreams means a reliable time or space where hopes can wait without risk.","zh":"safe place to store our dreams 是可以讓希望無風險等待的可靠時間或空間。"},{"en":"“After exams” may seem like a safe place to store our dreams, but chances can fade.","zh":"「考試後」可能看似存放夢想的安全地方，但機會會淡去。"},{"en":"Dreams need action, not only storage in the future.","zh":"夢想需要行動，而不只是被存放在未來。"},{"en":"This phrase warns against hiding ambition inside the word “later”.","zh":"這個短語提醒人們不要把抱負藏在「遲些」之中。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"not until today do we realise","meaning":"直到今天我們才明白","examples":[{"en":"Not until today do we fully realise what our habits have done.","zh":"直到今天，我們才完全明白我們的習慣做了甚麼。"},{"en":"Not until today do we realise means we only understand something now, after a long time.","zh":"not until today do we realise 的意思是經過很長時間後，我們到現在才明白某事。"},{"en":"Not until graduation do we realise how much small routines shaped us.","zh":"直到畢業，我們才明白小小日常如何塑造我們。"},{"en":"This structure gives the sentence a reflective and formal tone.","zh":"這個結構令句子帶有反思和正式語氣。"},{"en":"It shows delayed understanding at an important moment.","zh":"它顯示在重要時刻出現的遲來理解。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"small habits","meaning":"小習慣","examples":[{"en":"The small habits we repeated were quietly writing our character.","zh":"我們重複的小習慣一直在悄悄塑造我們的品格。"},{"en":"Small habits are ordinary actions we do again and again.","zh":"small habits 是我們一次又一次做的普通行動。"},{"en":"Arriving on time, helping classmates, or avoiding hard work can all become small habits.","zh":"準時到達、幫助同學或逃避困難工作都可以變成小習慣。"},{"en":"Small habits matter because they slowly shape who we become.","zh":"小習慣重要，因為它們慢慢塑造我們成為怎樣的人。"},{"en":"This phrase reminds graduates that character is built daily.","zh":"這個短語提醒畢業生，品格是每天建立的。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"quietly writing our character","meaning":"悄悄塑造我們的品格","examples":[{"en":"Our repeated habits were quietly writing our character.","zh":"我們重複的習慣一直在悄悄塑造我們的品格。"},{"en":"Quietly writing our character means slowly shaping who we are without obvious drama.","zh":"quietly writing our character 的意思是在沒有明顯戲劇性的情況下慢慢塑造我們是怎樣的人。"},{"en":"A student’s daily kindness may quietly write a generous character over time.","zh":"學生日常的善意可以隨時間悄悄塑造慷慨的品格。"},{"en":"Habits shape character even when nobody notices them immediately.","zh":"即使沒有人立即注意到，習慣仍會塑造品格。"},{"en":"This phrase turns repeated actions into a powerful moral image.","zh":"這個短語把重複行動變成有力量的道德意象。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"leave with humility","meaning":"帶着謙卑離開","examples":[{"en":"Let us leave with humility.","zh":"讓我們帶着謙卑離開。"},{"en":"To leave with humility means to move on without arrogance, remembering what we have received and still need to learn.","zh":"leave with humility 的意思是帶着不傲慢的心離開，記得自己接受過甚麼，也仍需要學習。"},{"en":"Graduates leave with humility when they thank others and admit they are still growing.","zh":"當畢業生感謝別人並承認自己仍在成長時，就是帶着謙卑離開。"},{"en":"Humility helps people face the future without pretending to know everything.","zh":"謙卑幫助人面對未來，而不假裝自己知道一切。"},{"en":"This phrase gives graduates a respectful attitude for departure.","zh":"這個短語給畢業生一種尊重的離別態度。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"masters of time","meaning":"時間的主人","examples":[{"en":"We are not masters of time.","zh":"我們不是時間的主人。"},{"en":"Masters of time means people who can fully control time, delay it, or command it.","zh":"masters of time 是能完全控制、延遲或命令時間的人。"},{"en":"Students may wish they were masters of time the night before exams.","zh":"考試前一晚，學生可能希望自己是時間的主人。"},{"en":"Realising we are not masters of time can make us use it more carefully.","zh":"明白我們不是時間的主人，可以令我們更小心運用時間。"},{"en":"This phrase teaches humility about human limits.","zh":"這個短語教人謙卑地看待人的限制。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"faithful stewards of","meaning":"忠誠的管理者","examples":[{"en":"We can be faithful stewards of time.","zh":"我們可以成為時間的忠誠管理者。"},{"en":"Faithful stewards of something are people who manage it carefully and responsibly.","zh":"faithful stewards of something 是小心而負責任地管理某物的人。"},{"en":"Students can be faithful stewards of time by using each day for learning, gratitude, and courage.","zh":"學生可以透過把每天用於學習、感恩和勇氣，成為時間的忠誠管理者。"},{"en":"A steward does not own what is given, but takes care of it well.","zh":"管理者不擁有所被給予的東西，而是好好照顧它。"},{"en":"This phrase suggests responsibility without arrogance.","zh":"這個短語暗示責任，而不是傲慢。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"let time teach us gratitude","meaning":"讓時間教會我們感恩","examples":[{"en":"Second, let time teach us gratitude.","zh":"第二，讓時間教會我們感恩。"},{"en":"Let time teach us gratitude means allow passing time to help us appreciate people and moments more deeply.","zh":"let time teach us gratitude 的意思是讓時間流逝幫助我們更深地珍惜人和時刻。"},{"en":"Graduation can teach gratitude because we finally see how many people helped us.","zh":"畢業可以教會我們感恩，因為我們終於看見有多少人幫助過我們。"},{"en":"Time makes ordinary support feel precious after we look back.","zh":"回望之後，時間令普通支持變得珍貴。"},{"en":"This phrase links memory with thankfulness.","zh":"這個短語把回憶與感謝連繫起來。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"valuable not because…, but because…","meaning":"有價值不是因為……而是因為……","examples":[{"en":"A diamond is valuable not because it is large, but because it is rare.","zh":"鑽石有價值不是因為它大，而是因為它稀有。"},{"en":"Valuable not because A, but because B means B is the real reason for value.","zh":"valuable not because A, but because B 的意思是 B 才是真正令某物有價值的原因。"},{"en":"A school memory is valuable not because it was perfect, but because it cannot be repeated.","zh":"校園回憶有價值不是因為它完美，而是因為它不能重來。"},{"en":"This structure corrects a shallow reason and replaces it with a deeper one.","zh":"這個結構修正表面原因，並換成更深層原因。"},{"en":"It is useful when explaining what truly makes something precious.","zh":"當解釋甚麼真正令某物珍貴時，它很有用。"}],"source":"2013 Q8.pdf","sourcePage":6},{"front":"the same is true of","meaning":"……也是如此","examples":[{"en":"The same is true of an afternoon with a friend.","zh":"與朋友共度的下午也是如此。"},{"en":"The same is true of means the same idea also applies to another thing.","zh":"the same is true of 的意思是同一個想法也適用於另一事物。"},{"en":"Time is precious because it is limited; the same is true of school friendships.","zh":"時間因有限而珍貴；校園友誼也是如此。"},{"en":"This phrase helps extend an argument from one example to another.","zh":"這個短語幫助把論點由一個例子延伸到另一個。"},{"en":"It is useful when showing that a principle applies widely.","zh":"當展示某個原則廣泛適用時，它很有用。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"an afternoon with a friend","meaning":"與朋友共度的下午","examples":[{"en":"An afternoon with a friend can be rare and valuable.","zh":"與朋友共度的下午可以稀有而珍貴。"},{"en":"An afternoon with a friend means time spent together in a simple, personal way.","zh":"an afternoon with a friend 是以簡單而個人的方式一起度過的時間。"},{"en":"After graduation, an ordinary afternoon with a friend may become hard to arrange.","zh":"畢業後，與朋友共度一個普通下午可能變得難以安排。"},{"en":"Such time is valuable because friendship needs presence, not only messages.","zh":"這樣的時間珍貴，因為友誼需要陪伴，而不只是訊息。"},{"en":"This phrase reminds us to treasure ordinary companionship.","zh":"這個短語提醒我們珍惜普通陪伴。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"patient advice","meaning":"耐心的建議","examples":[{"en":"A teacher’s patient advice after school is precious.","zh":"老師放學後耐心的建議是珍貴的。"},{"en":"Patient advice is guidance given calmly and kindly, even when the listener needs time to understand.","zh":"patient advice 是即使聽者需要時間理解，仍冷靜而友善給予的指導。"},{"en":"A teacher may give patient advice to a student who has failed an exam.","zh":"老師可以給考試失敗的學生耐心的建議。"},{"en":"Patient advice matters because it helps people grow without feeling judged.","zh":"耐心的建議重要，因為它幫助人成長而不感到被批判。"},{"en":"This phrase describes support that takes time and care.","zh":"這個短語描述需要時間和用心的支持。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"after school","meaning":"放學後","examples":[{"en":"A teacher gave patient advice after school.","zh":"老師在放學後給予耐心的建議。"},{"en":"After school means during the time after regular lessons have ended.","zh":"after school 的意思是在正常課堂結束後的時間。"},{"en":"Students may stay after school for clubs, revision, or talks with teachers.","zh":"學生可能放學後留校參加學會、溫習或與老師談話。"},{"en":"After-school moments can become important memories because they are often personal.","zh":"放學後的時刻可以成為重要回憶，因為它們常很個人化。"},{"en":"This phrase describes a familiar time outside normal lessons.","zh":"這個短語描述正常課堂以外的熟悉時間。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"family dinner","meaning":"家庭晚飯","examples":[{"en":"A family dinner waiting at home can be precious.","zh":"家中等待着的家庭晚飯可以很珍貴。"},{"en":"A family dinner is a meal shared with family members, often after a long day.","zh":"family dinner 是與家人一起吃的飯，通常在漫長一天後發生。"},{"en":"A student may not value family dinner until graduation makes home routines feel temporary.","zh":"學生可能直到畢業令家庭日常感覺短暫時，才珍惜家庭晚飯。"},{"en":"Family dinners matter because they offer ordinary care and conversation.","zh":"家庭晚飯重要，因為它提供普通的關懷和對話。"},{"en":"This phrase turns a daily meal into a symbol of love.","zh":"這個短語把日常飯餐變成愛的象徵。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"complain about stress","meaning":"抱怨壓力","examples":[{"en":"We sometimes complained about stress while our family waited for us.","zh":"當家人在等我們時，我們有時抱怨壓力。"},{"en":"To complain about stress means to express unhappiness about pressure or worry.","zh":"complain about stress 的意思是表達對壓力或憂慮的不滿。"},{"en":"Students may complain about stress before exams because they feel tired and afraid.","zh":"學生考試前可能抱怨壓力，因為他們疲累又害怕。"},{"en":"Complaining is human, but gratitude helps us notice those who support us.","zh":"抱怨是人之常情，但感恩幫助我們注意支持我們的人。"},{"en":"This phrase shows a common student reaction to pressure.","zh":"這個短語展示學生面對壓力的常見反應。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"spend years chasing results","meaning":"多年來追逐成績","examples":[{"en":"Many of us have spent the past years chasing results.","zh":"我們許多人過去多年都在追逐成績。"},{"en":"To spend years chasing results means to use a long time working hard for grades, scores, or achievements.","zh":"spend years chasing results 的意思是花很長時間努力追求分數、成績或成就。"},{"en":"Students may spend years chasing results because public exams affect future choices.","zh":"學生可能多年來追逐成績，因為公開考試影響未來選擇。"},{"en":"Chasing results can be reasonable, but it should not make people forget relationships.","zh":"追逐成績可以有道理，但不應令人忘記關係。"},{"en":"This phrase describes a long period focused on measurable success.","zh":"這個短語描述長期專注於可量度成功的時段。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"rightly so","meaning":"這樣做也有道理","examples":[{"en":"Many of us have chased results, and rightly so.","zh":"我們許多人都追逐成績，這樣做也有道理。"},{"en":"Rightly so means this is understandable or justified.","zh":"rightly so 的意思是這樣做可以理解或有合理理由。"},{"en":"Students work hard for exams, and rightly so, because grades may open doors.","zh":"學生努力應付考試，這樣做也有道理，因為成績可能打開機會之門。"},{"en":"This phrase admits that an action has a reasonable reason.","zh":"這個短語承認某個行動有合理原因。"},{"en":"It helps the speaker sound fair before adding a deeper point.","zh":"它幫助演講者在加入更深觀點前顯得公平。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"public examinations matter","meaning":"公開考試很重要","examples":[{"en":"Public examinations matter.","zh":"公開考試很重要。"},{"en":"Public examinations matter means official exams are important and have real effects.","zh":"public examinations matter 的意思是正式考試重要，並有實際影響。"},{"en":"Public examinations may affect university places, scholarships, or training options.","zh":"公開考試可能影響大學學位、獎學金或培訓選擇。"},{"en":"Exams matter, but they should not be the only measure of a person’s value.","zh":"考試重要，但不應是衡量一個人價值的唯一標準。"},{"en":"This phrase recognises pressure while keeping it in perspective.","zh":"這個短語承認壓力，同時保持合理角度。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, grades may open doors.","zh":"誠然，成績可能打開機會之門。"},{"en":"Granted means it is accepted that part of an argument is true.","zh":"granted 的意思是承認某個論點有部分屬實。"},{"en":"Granted, exam results matter, but they do not define our whole life.","zh":"誠然，考試成績重要，但它們不定義我們整個人生。"},{"en":"Speakers use granted to sound fair before giving a larger message.","zh":"演講者使用 granted 來在提出更大訊息前顯得公平。"},{"en":"This word helps balance agreement with a deeper argument.","zh":"這個詞幫助在同意與更深論點之間取得平衡。"}],"source":"2013 Q8.pdf","sourcePage":7},{"front":"open doors","meaning":"打開機會之門","examples":[{"en":"Grades may open doors.","zh":"成績可能打開機會之門。"},{"en":"To open doors means to create chances or opportunities.","zh":"open doors 的意思是創造機會。"},{"en":"Good results may open doors to university, scholarships, or interviews.","zh":"好成績可能打開通往大學、獎學金或面試的機會之門。"},{"en":"However, opened doors still need courage, wisdom, and people to give them meaning.","zh":"然而，被打開的門仍需要勇氣、智慧和人去賦予意義。"},{"en":"This phrase describes opportunity created by achievement.","zh":"這個短語描述成就帶來的機會。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"give those doors meaning","meaning":"賦予那些機會意義","examples":[{"en":"People give those doors meaning.","zh":"人賦予那些機會意義。"},{"en":"To give those doors meaning means to make opportunities worthwhile through relationships, purpose, and values.","zh":"give those doors meaning 的意思是透過關係、目標和價值令機會值得擁有。"},{"en":"A university place gains meaning when a student uses it to learn and serve others.","zh":"當學生用大學學位去學習和服務他人時，那個機會就有了意義。"},{"en":"Opportunities alone are empty if people enter them without gratitude or purpose.","zh":"如果人們沒有感恩或目標地走進機會，機會本身是空洞的。"},{"en":"This phrase shows that success needs human meaning.","zh":"這個短語顯示成功需要人的意義。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"what use is","meaning":"……有甚麼用","examples":[{"en":"What use is a bright future if we enter it alone?","zh":"如果我們獨自走進光明的未來，那又有甚麼用？"},{"en":"What use is asks whether something is truly valuable if an important condition is missing.","zh":"what use is 用來詢問如果缺少重要條件，某事是否真正有價值。"},{"en":"What use is a prize if we lose every friendship while chasing it?","zh":"如果我們在追逐獎項時失去所有友誼，獎項又有甚麼用？"},{"en":"This question challenges listeners to think beyond achievement.","zh":"這個問題挑戰聽眾思考成就以外的事。"},{"en":"It is useful in speeches because it sounds reflective and powerful.","zh":"它在演講中很有用，因為聽起來有反思性和力量。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"a bright future","meaning":"光明的未來","examples":[{"en":"A bright future means little if we enter it alone.","zh":"如果我們獨自走進光明的未來，它就沒有太大意義。"},{"en":"A bright future is a hopeful future with opportunities, success, or happiness.","zh":"bright future 是充滿機會、成功或快樂的有希望未來。"},{"en":"Graduates may dream of a bright future filled with study, work, and travel.","zh":"畢業生可能夢想一個充滿學習、工作和旅行的光明未來。"},{"en":"A bright future loses warmth if it is reached without gratitude or companionship.","zh":"如果沒有感恩或陪伴地到達，光明的未來會失去溫度。"},{"en":"This phrase describes hope, but also asks what gives hope meaning.","zh":"這個短語描述希望，也詢問甚麼賦予希望意義。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"carrying regret like an unpaid debt","meaning":"帶着像未還債務般的遺憾","examples":[{"en":"We should not enter the future carrying regret like an unpaid debt.","zh":"我們不應帶着像未還債務般的遺憾走進未來。"},{"en":"Carrying regret like an unpaid debt means living with guilt that feels heavy and unfinished.","zh":"carrying regret like an unpaid debt 的意思是帶着沉重而未完成的內疚生活。"},{"en":"A graduate may carry regret like an unpaid debt if he never thanks a teacher who helped him.","zh":"如果畢業生從未感謝幫助過自己的老師，他可能帶着像未還債務般的遺憾。"},{"en":"Regret grows heavier when important words remain unsaid.","zh":"當重要說話仍未說出，遺憾會變得更沉重。"},{"en":"This phrase compares emotional burden to money still owed.","zh":"這個短語把情感負擔比作仍未還清的金錢。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"unpaid debt","meaning":"未還清的債","examples":[{"en":"Regret can feel like an unpaid debt.","zh":"遺憾可以感覺像未還清的債。"},{"en":"An unpaid debt is money or responsibility that has not yet been settled.","zh":"unpaid debt 是尚未清還的金錢或責任。"},{"en":"An apology left unsaid can feel like an unpaid debt after graduation.","zh":"畢業後，未說出口的道歉可以感覺像未還清的債。"},{"en":"Unpaid debts create pressure because they remain unfinished.","zh":"未還清的債會造成壓力，因為它仍未完成。"},{"en":"This phrase helps explain why regret can feel heavy.","zh":"這個短語幫助解釋為何遺憾會感覺沉重。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"scatter to","meaning":"分散到","examples":[{"en":"We will scatter to universities, workplaces, and new cities.","zh":"我們將分散到大學、工作場所和新城市。"},{"en":"To scatter to places means to spread out and go in different directions.","zh":"scatter to places 的意思是分散並走向不同方向。"},{"en":"After graduation, classmates may scatter to different courses and careers.","zh":"畢業後，同學可能分散到不同課程和職業。"},{"en":"Scattering can bring opportunity, but it also makes time together rarer.","zh":"分散可以帶來機會，但也令相聚時間更稀少。"},{"en":"This phrase describes separation after a shared journey.","zh":"這個短語描述共同旅程後的分離。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"universities, workplaces and new cities","meaning":"大學、工作場所和新城市","examples":[{"en":"Graduates will scatter to universities, workplaces, and new cities.","zh":"畢業生將分散到大學、工作場所和新城市。"},{"en":"Universities, workplaces and new cities represent different paths after graduation.","zh":"universities, workplaces and new cities 代表畢業後不同道路。"},{"en":"Some graduates may study, some may start work, and others may move away.","zh":"有些畢業生可能升學，有些開始工作，另一些可能搬到外地。"},{"en":"These destinations show that the class will not remain in one place forever.","zh":"這些目的地顯示全班不會永遠留在同一地方。"},{"en":"This phrase captures the many directions life can take.","zh":"這個短語捕捉人生可能走向的多個方向。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"say what should be said","meaning":"說出該說的話","examples":[{"en":"Before we leave, we should say what should be said.","zh":"在離開之前，我們應說出該說的話。"},{"en":"To say what should be said means to speak important words that should not be delayed.","zh":"say what should be said 的意思是說出不應被延遲的重要說話。"},{"en":"Graduates should say thank you, sorry, or goodbye before distance grows.","zh":"畢業生應在距離增加前說謝謝、對不起或再見。"},{"en":"Words left unsaid can become regret after people separate.","zh":"未說出口的話在人們分離後可能變成遺憾。"},{"en":"This phrase urges honest speech at the right time.","zh":"這個短語敦促人在適當時候坦誠說話。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"believed in you","meaning":"相信你","examples":[{"en":"Thank the teacher who believed in you.","zh":"感謝那位相信你的老師。"},{"en":"Believed in you means had confidence in your ability or worth, even when you doubted yourself.","zh":"believed in you 的意思是相信你的能力或價值，即使你懷疑自己。"},{"en":"A teacher believes in a student when she encourages him after failure.","zh":"當老師在學生失敗後鼓勵他時，就是相信他。"},{"en":"Being believed in can help students try again when they feel weak.","zh":"被人相信可以幫助學生在感到脆弱時再次嘗試。"},{"en":"This phrase shows the power of another person’s trust.","zh":"這個短語展示別人信任的力量。"}],"source":"2013 Q8.pdf","sourcePage":8},{"front":"before you believed in yourself","meaning":"在你相信自己之前","examples":[{"en":"Some teachers believed in us before we believed in ourselves.","zh":"有些老師在我們相信自己之前已經相信我們。"},{"en":"Before you believed in yourself means at a time when you did not yet trust your own ability.","zh":"before you believed in yourself 的意思是在你尚未相信自己能力的時候。"},{"en":"A coach may believe in a nervous player before the player believes in herself.","zh":"教練可能在緊張的球員相信自己之前已經相信她。"},{"en":"Such belief can become the bridge between fear and confidence.","zh":"這種信任可以成為恐懼與信心之間的橋樑。"},{"en":"This phrase expresses gratitude for early encouragement.","zh":"這個短語表達對早期鼓勵的感謝。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"apologise to","meaning":"向……道歉","examples":[{"en":"Apologise to the friend you hurt.","zh":"向你曾傷害的朋友道歉。"},{"en":"To apologise to someone means to say sorry for causing harm or pain.","zh":"apologise to someone 的意思是因造成傷害或痛苦而向某人說對不起。"},{"en":"A graduate may apologise to a classmate after an old argument.","zh":"畢業生可能在舊爭執後向同學道歉。"},{"en":"Apologising can repair trust, especially when the apology is honest and specific.","zh":"道歉可以修復信任，尤其當道歉真誠而具體。"},{"en":"This phrase encourages responsibility in relationships.","zh":"這個短語鼓勵人在關係中承擔責任。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"the friend you hurt","meaning":"你曾傷害的朋友","examples":[{"en":"You should apologise to the friend you hurt.","zh":"你應該向你曾傷害的朋友道歉。"},{"en":"The friend you hurt is someone close to you who was harmed by your words or actions.","zh":"the friend you hurt 是因你的說話或行動而受傷的親近朋友。"},{"en":"A friend may be hurt by a careless joke, broken promise, or long silence.","zh":"朋友可能因粗心玩笑、失約或長久沉默而受傷。"},{"en":"Recognising the friend you hurt is the first step toward repair.","zh":"承認你曾傷害的朋友，是修復關係的第一步。"},{"en":"This phrase makes responsibility personal and direct.","zh":"這個短語令責任變得個人而直接。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"quiet sacrifices","meaning":"默默的犧牲","examples":[{"en":"Tell your parents that their quiet sacrifices were seen.","zh":"告訴父母，他們默默的犧牲被看見了。"},{"en":"Quiet sacrifices are helpful things people give up silently for someone else.","zh":"quiet sacrifices 是人們為別人默默放棄或付出的東西。"},{"en":"Parents make quiet sacrifices when they work late or save money for their child’s education.","zh":"父母加班或為孩子教育儲錢時，就是作出默默的犧牲。"},{"en":"Quiet sacrifices may go unnoticed because they are not dramatic.","zh":"默默的犧牲可能不被注意，因為它們並不戲劇化。"},{"en":"This phrase honours love shown through steady action.","zh":"這個短語尊重透過穩定行動表達的愛。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"were seen","meaning":"被看見","examples":[{"en":"Their quiet sacrifices were seen.","zh":"他們默默的犧牲被看見了。"},{"en":"Were seen means were noticed, recognised, or appreciated.","zh":"were seen 的意思是被注意、被認出或被感激。"},{"en":"A parent may feel comforted when a child says their effort was seen.","zh":"當孩子說父母的努力被看見時，父母可能感到安慰。"},{"en":"Being seen matters because hidden work can feel lonely.","zh":"被看見很重要，因為隱藏的付出可以令人感到孤單。"},{"en":"This phrase gives recognition to care that was not always spoken about.","zh":"這個短語給予那些未必被說出口的關懷認可。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"do it now","meaning":"現在就做","examples":[{"en":"Do it now, before distance grows.","zh":"現在就做，在距離增加之前。"},{"en":"Do it now means take action immediately instead of delaying.","zh":"do it now 的意思是立即行動，而不是拖延。"},{"en":"If you need to thank someone, do it now before graduation separates you.","zh":"如果你需要感謝某人，現在就做，在畢業把你們分開之前。"},{"en":"Delay can turn simple words into lifelong regret.","zh":"拖延可以把簡單說話變成終生遺憾。"},{"en":"This phrase creates urgency and emotional clarity.","zh":"這個短語製造迫切感和情感清晰度。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"tomorrow may come with distance","meaning":"明天可能伴隨距離而來","examples":[{"en":"Tomorrow may come with distance.","zh":"明天可能伴隨距離而來。"},{"en":"Tomorrow may come with distance means the future may separate people physically or emotionally.","zh":"tomorrow may come with distance 的意思是未來可能在身體或情感上把人分開。"},{"en":"After graduation, tomorrow may come with distance as classmates move to different places.","zh":"畢業後，隨着同學前往不同地方，明天可能伴隨距離而來。"},{"en":"Distance can make apologies and gratitude harder to express.","zh":"距離會令道歉和感謝更難表達。"},{"en":"This phrase encourages people to speak before separation grows.","zh":"這個短語鼓勵人在分離增加前說話。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"let time call us to courage","meaning":"讓時間召喚我們拿出勇氣","examples":[{"en":"Finally, let time call us to courage.","zh":"最後，讓時間召喚我們拿出勇氣。"},{"en":"Let time call us to courage means allow the passing of time to push us toward brave action.","zh":"let time call us to courage 的意思是讓時間流逝推動我們走向勇敢行動。"},{"en":"Graduation calls students to courage because the next step cannot be avoided forever.","zh":"畢業召喚學生拿出勇氣，因為下一步不能永遠逃避。"},{"en":"Time can make fear stronger if we delay, but courage grows when we begin.","zh":"如果我們拖延，時間可以令恐懼更強；但當我們開始時，勇氣會成長。"},{"en":"This phrase turns time into a voice urging action.","zh":"這個短語把時間變成催促行動的聲音。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"some…, others…","meaning":"有些人……另一些人……","examples":[{"en":"Some of us are excited; others are terrified.","zh":"有些人感到興奮；另一些人感到非常害怕。"},{"en":"Some…, others… is used to show that different people feel or act differently.","zh":"some…, others… 用來顯示不同人有不同感受或行動。"},{"en":"Some graduates want to leave school quickly; others wish they could stay longer.","zh":"有些畢業生想快點離開學校；另一些人希望可以留久一點。"},{"en":"This structure helps include different experiences within one group.","zh":"這個結構幫助在同一群體中包容不同經驗。"},{"en":"It is useful when speaking to an audience with mixed feelings.","zh":"當向感受混雜的聽眾說話時，它很有用。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"terrified","meaning":"非常害怕","examples":[{"en":"Some graduates are terrified about the future.","zh":"有些畢業生對未來感到非常害怕。"},{"en":"Terrified means extremely frightened.","zh":"terrified 的意思是極度害怕。"},{"en":"A student may feel terrified before leaving the familiar safety of school.","zh":"學生在離開熟悉而安全的學校前，可能感到非常害怕。"},{"en":"Feeling terrified does not mean someone is weak; it often means the next step matters.","zh":"感到非常害怕不代表某人軟弱；它往往代表下一步很重要。"},{"en":"This word describes strong fear before uncertainty.","zh":"這個詞描述面對不確定前的強烈恐懼。"}],"source":"2013 Q8.pdf","sourcePage":9},{"front":"the world beyond these gates","meaning":"校門外的世界","examples":[{"en":"We may wonder whether we are ready for the world beyond these gates.","zh":"我們可能想知道自己是否準備好面對校門外的世界。"},{"en":"The world beyond these gates means life outside the school and its familiar protection.","zh":"the world beyond these gates 的意思是學校及其熟悉保護以外的生活。"},{"en":"The world beyond these gates may include university, work, responsibility, and new people.","zh":"校門外的世界可能包括大學、工作、責任和新的人。"},{"en":"School gates can symbolise the boundary between student life and adult life.","zh":"校門可以象徵學生生活與成人生活之間的界線。"},{"en":"This phrase makes the future feel close and concrete.","zh":"這個短語令未來感覺貼近而具體。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"the honest answer is","meaning":"誠實的答案是","examples":[{"en":"The honest answer is that we are probably not completely ready.","zh":"誠實的答案是，我們可能還未完全準備好。"},{"en":"The honest answer is means the truthful reply, even if it is not the easiest one to hear.","zh":"the honest answer is 的意思是真實答案，即使它不是最容易聽到的答案。"},{"en":"The honest answer is that no graduate knows exactly what will happen next.","zh":"誠實的答案是，沒有畢業生確切知道下一步會發生甚麼。"},{"en":"This phrase creates trust because the speaker does not pretend everything is simple.","zh":"這個短語建立信任，因為演講者沒有假裝一切很簡單。"},{"en":"It prepares listeners for a realistic but hopeful message.","zh":"它為聽眾準備一個現實但有希望的訊息。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"probably not completely","meaning":"可能還未完全","examples":[{"en":"We are probably not completely ready.","zh":"我們可能還未完全準備好。"},{"en":"Probably not completely means likely not fully or perfectly prepared.","zh":"probably not completely 的意思是很可能尚未完全或完美準備好。"},{"en":"A graduate may be probably not completely ready for university, but still ready to begin learning.","zh":"畢業生可能還未完全準備好上大學，但仍準備好開始學習。"},{"en":"This phrase accepts uncertainty without giving up.","zh":"這個短語接受不確定，但並不放棄。"},{"en":"It shows that courage does not require perfect preparation.","zh":"它顯示勇氣不需要完美準備。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"who ever is","meaning":"又有誰完全準備好呢","examples":[{"en":"We may not be completely ready, but who ever is?","zh":"我們可能還未完全準備好，但又有誰完全準備好呢？"},{"en":"Who ever is? means nobody is ever fully ready, so imperfect readiness is normal.","zh":"who ever is? 的意思是沒有人會完全準備好，所以不完美的準備是正常的。"},{"en":"A student may fear starting a new job, but who ever is completely ready for a first day?","zh":"學生可能害怕開始新工作，但又有誰對第一天完全準備好呢？"},{"en":"This question comforts listeners by making fear feel shared.","zh":"這個問題透過顯示恐懼是共同的來安慰聽眾。"},{"en":"It reminds graduates that beginning matters more than perfect certainty.","zh":"它提醒畢業生，開始比完美確定更重要。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"a journey is not completed by","meaning":"一段旅程不是靠……完成的","examples":[{"en":"A journey is not completed by waiting at the starting line.","zh":"一段旅程不是靠在起點線等待完成的。"},{"en":"A journey is not completed by something means that action alone cannot bring progress.","zh":"a journey is not completed by something 的意思是單靠某個行動不能帶來進展。"},{"en":"A dream is not achieved by only imagining it after graduation.","zh":"夢想不是靠畢業後只想像它而實現的。"},{"en":"This phrase teaches that movement, risk, and effort are necessary.","zh":"這個短語教導人們，行動、冒險和努力是必要的。"},{"en":"It is useful when encouraging people to begin instead of delay.","zh":"當鼓勵人們開始而不是拖延時，它很有用。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"waiting at the starting line","meaning":"在起點線等待","examples":[{"en":"A journey is not completed by waiting at the starting line.","zh":"一段旅程不是靠在起點線等待完成的。"},{"en":"Waiting at the starting line means staying at the beginning without moving forward.","zh":"waiting at the starting line 的意思是留在開始位置而不向前走。"},{"en":"A graduate waits at the starting line if he keeps planning but never applies for anything.","zh":"如果畢業生一直計劃卻從不申請任何東西，他就是在起點線等待。"},{"en":"Waiting may feel safe, but it does not create progress.","zh":"等待可能感覺安全，但不會創造進展。"},{"en":"This phrase warns against delay disguised as preparation.","zh":"這個短語提醒人們不要把拖延包裝成準備。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"step by step","meaning":"一步一步地","examples":[{"en":"A journey is completed step by step.","zh":"一段旅程是一步一步地完成的。"},{"en":"Step by step means gradually, one small action at a time.","zh":"step by step 的意思是逐漸地，一次做一個小行動。"},{"en":"A student learns a new skill step by step by practising a little each week.","zh":"學生可以透過每星期練習一點，一步一步地學會新技能。"},{"en":"Big goals become less frightening when they are broken into steps.","zh":"當大目標被分成步驟，它們就沒那麼令人害怕。"},{"en":"This phrase gives hope through steady progress.","zh":"這個短語透過穩定進展給人希望。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"mistake by mistake","meaning":"從一個又一個錯誤中","examples":[{"en":"We learn mistake by mistake.","zh":"我們從一個又一個錯誤中學習。"},{"en":"Mistake by mistake means we learn gradually through each error we make.","zh":"mistake by mistake 的意思是我們透過每個錯誤逐漸學習。"},{"en":"A graduate may learn interview skills mistake by mistake after several attempts.","zh":"畢業生可能在多次嘗試後，從一個又一個錯誤中學會面試技巧。"},{"en":"Mistakes become useful when we reflect and adjust.","zh":"當我們反思和調整時，錯誤就變得有用。"},{"en":"This phrase turns failure into part of growth.","zh":"這個短語把失敗變成成長的一部分。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"lesson by lesson","meaning":"從一課又一課中","examples":[{"en":"We grow lesson by lesson.","zh":"我們從一課又一課中成長。"},{"en":"Lesson by lesson means growth happens gradually through each experience or teaching moment.","zh":"lesson by lesson 的意思是成長透過每次經驗或教導逐步發生。"},{"en":"Students become wiser lesson by lesson as they face success, failure, and advice.","zh":"學生在面對成功、失敗和建議時，從一課又一課中變得更有智慧。"},{"en":"Not every lesson is easy, but each one can shape character.","zh":"不是每一課都容易，但每一課都可以塑造品格。"},{"en":"This phrase shows slow and steady personal development.","zh":"這個短語展示緩慢而穩定的個人成長。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"apply for the course","meaning":"申請課程","examples":[{"en":"Apply for the course you want.","zh":"申請你想讀的課程。"},{"en":"To apply for the course means to formally ask to join a study programme.","zh":"apply for the course 的意思是正式申請加入某個學習課程。"},{"en":"A graduate may apply for a design course if he wants to build creative skills.","zh":"如果畢業生想建立創意技能，他可以申請設計課程。"},{"en":"Applying for a course is a first step from interest to action.","zh":"申請課程是由興趣走向行動的第一步。"},{"en":"This phrase encourages graduates to move toward their chosen path.","zh":"這個短語鼓勵畢業生走向自己選擇的道路。"}],"source":"2013 Q8.pdf","sourcePage":10},{"front":"join the team","meaning":"加入隊伍","examples":[{"en":"Join the team and try something new.","zh":"加入隊伍，嘗試新事物。"},{"en":"To join the team means to become part of a group working, training, or playing together.","zh":"join the team 的意思是成為一起工作、訓練或比賽的群體一員。"},{"en":"A graduate may join a sports team, debate team, or volunteer team to meet new people.","zh":"畢業生可以加入運動隊、辯論隊或義工隊，以認識新朋友。"},{"en":"Joining a team can build confidence because effort is shared.","zh":"加入隊伍可以建立信心，因為努力是共同承擔的。"},{"en":"This phrase encourages participation rather than watching from the side.","zh":"這個短語鼓勵參與，而不是在旁觀看。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"learn the skill","meaning":"學習技能","examples":[{"en":"Learn the skill you need.","zh":"學習你需要的技能。"},{"en":"To learn the skill means to gain an ability through study, practice, or experience.","zh":"learn the skill 的意思是透過學習、練習或經驗獲得某種能力。"},{"en":"A graduate may learn a computer skill before applying for a job.","zh":"畢業生可以在申請工作前學習電腦技能。"},{"en":"Learning one needed skill can make a frightening future more manageable.","zh":"學會一項所需技能可以令令人害怕的未來較容易應付。"},{"en":"This phrase turns a big dream into a practical action.","zh":"這個短語把大夢想變成實際行動。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"serve the community","meaning":"服務社區","examples":[{"en":"Serve the community with courage.","zh":"帶着勇氣服務社區。"},{"en":"To serve the community means to help people in the area or society around you.","zh":"serve the community 的意思是幫助身邊地區或社會中的人。"},{"en":"Graduates can serve the community by tutoring children, visiting elderly neighbours, or joining clean-up work.","zh":"畢業生可以透過為兒童補習、探訪長者鄰居或參加清潔活動服務社區。"},{"en":"Serving others helps young people see that their time can benefit more than themselves.","zh":"服務他人幫助年輕人看見自己的時間可以惠及自己以外的人。"},{"en":"This phrase connects courage with responsibility to others.","zh":"這個短語把勇氣與對他人的責任連繫起來。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"ask for help","meaning":"求助","examples":[{"en":"Ask for help when pride tells you to pretend.","zh":"當自尊叫你假裝沒事時，要開口求助。"},{"en":"To ask for help means to tell someone you need support, advice, or assistance.","zh":"ask for help 的意思是告訴某人你需要支持、建議或協助。"},{"en":"A graduate should ask for help if university work or job pressure becomes too heavy.","zh":"如果大學功課或工作壓力變得太沉重，畢業生應該求助。"},{"en":"Asking for help is not weakness; it is a wise response to difficulty.","zh":"求助不是軟弱，而是面對困難的明智回應。"},{"en":"This phrase encourages honesty instead of silent struggle.","zh":"這個短語鼓勵誠實，而不是沉默掙扎。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"pride tells you to pretend","meaning":"自尊叫你假裝沒事","examples":[{"en":"Ask for help when pride tells you to pretend.","zh":"當自尊叫你假裝沒事時，要開口求助。"},{"en":"Pride tells you to pretend means your ego makes you hide pain or difficulty to look strong.","zh":"pride tells you to pretend 的意思是自尊心令你隱藏痛苦或困難，以顯得堅強。"},{"en":"A student may pretend everything is fine because pride stops him from admitting fear.","zh":"學生可能假裝一切沒事，因為自尊阻止他承認恐懼。"},{"en":"Pride can isolate people when it prevents honest requests for support.","zh":"當自尊阻止人誠實求助時，它可以令人孤立。"},{"en":"This phrase warns that appearing strong can become dangerous.","zh":"這個短語提醒人們，表面堅強可以變得危險。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"even if failure comes","meaning":"即使失敗來臨","examples":[{"en":"Even if failure comes, let it make you wiser.","zh":"即使失敗來臨，也讓它令你更有智慧。"},{"en":"Even if failure comes means even when something does not succeed or goes wrong.","zh":"even if failure comes 的意思是即使某事不成功或出錯。"},{"en":"Even if failure comes after an application, a graduate can learn how to improve next time.","zh":"即使申請後失敗來臨，畢業生也可以學會下次如何改善。"},{"en":"This phrase prepares listeners for difficulty without removing hope.","zh":"這個短語讓聽眾準備面對困難，同時不消除希望。"},{"en":"It shows that failure can be part of progress.","zh":"它顯示失敗可以是進步的一部分。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"make you wiser rather than smaller","meaning":"令你更有智慧，而不是更渺小","examples":[{"en":"Failure should make you wiser rather than smaller.","zh":"失敗應令你更有智慧，而不是更渺小。"},{"en":"Make you wiser rather than smaller means help you learn instead of making you feel worthless.","zh":"make you wiser rather than smaller 的意思是幫助你學習，而不是令你覺得自己沒有價值。"},{"en":"A failed interview can make a graduate wiser if he asks what to improve.","zh":"如果畢業生詢問自己可如何改善，一次失敗面試可以令他更有智慧。"},{"en":"Failure makes people smaller only when they let shame define them.","zh":"只有當人們讓羞恥定義自己時，失敗才會令他們更渺小。"},{"en":"This phrase encourages a healthy response to setbacks.","zh":"這個短語鼓勵健康地回應挫折。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"postpone our courage","meaning":"延後拿出勇氣","examples":[{"en":"The more we postpone our courage, the more fear becomes a habit.","zh":"我們越延後拿出勇氣，恐懼就越會變成習慣。"},{"en":"To postpone our courage means to delay doing the brave thing we know we should do.","zh":"postpone our courage 的意思是推遲去做我們知道應該做的勇敢事情。"},{"en":"A student postpones courage when he keeps avoiding a difficult apology.","zh":"當學生一直逃避困難的道歉時，就是延後拿出勇氣。"},{"en":"Delayed courage can make fear feel normal over time.","zh":"被拖延的勇氣會令恐懼隨時間變得正常。"},{"en":"This phrase warns that bravery must be practised before fear grows stronger.","zh":"這個短語提醒人們，勇氣必須在恐懼變強前練習。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"fear becomes a habit","meaning":"恐懼變成習慣","examples":[{"en":"If we postpone courage, fear becomes a habit.","zh":"如果我們延後勇氣，恐懼就會變成習慣。"},{"en":"Fear becomes a habit means avoiding difficult things becomes a repeated way of living.","zh":"fear becomes a habit 的意思是逃避困難事情變成重複的生活方式。"},{"en":"A graduate who avoids every interview may find fear becoming a habit.","zh":"一直逃避每次面試的畢業生，可能發現恐懼變成習慣。"},{"en":"Habits grow through repetition, so repeated avoidance makes fear stronger.","zh":"習慣透過重複成長，所以重複逃避會令恐懼更強。"},{"en":"This phrase shows how emotion can become behaviour.","zh":"這個短語顯示情緒如何變成行為。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"begin to take shape","meaning":"開始成形","examples":[{"en":"The sooner we begin, the sooner our future begins to take shape.","zh":"我們越早開始，未來就越早開始成形。"},{"en":"Begin to take shape means start to become clearer, more real, or more formed.","zh":"begin to take shape 的意思是開始變得更清楚、更真實或更有形。"},{"en":"A graduate’s future begins to take shape when she chooses a course and starts practising.","zh":"當畢業生選擇課程並開始練習時，她的未來就開始成形。"},{"en":"Plans become clearer through action, not endless waiting.","zh":"計劃是透過行動變得清楚，而不是透過無盡等待。"},{"en":"This phrase shows how beginnings create direction.","zh":"這個短語展示開始如何創造方向。"}],"source":"2013 Q8.pdf","sourcePage":11},{"front":"the clock does not stop","meaning":"時鐘不會停下","examples":[{"en":"Today the clock does not stop for us.","zh":"今天，時鐘不會為我們停下。"},{"en":"The clock does not stop means time continues even during important or emotional moments.","zh":"the clock does not stop 的意思是即使在重要或情緒化時刻，時間仍會繼續。"},{"en":"The clock does not stop after graduation, so choices must still be made.","zh":"畢業後時鐘不會停下，所以選擇仍必須作出。"},{"en":"This phrase reminds listeners that ceremonies mark time but do not pause it.","zh":"這個短語提醒聽眾，典禮標記時間，但不會暫停時間。"},{"en":"It creates urgency without panic.","zh":"它製造迫切感，但不是恐慌。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"the applause will fade","meaning":"掌聲會漸漸消散","examples":[{"en":"The applause will fade after the ceremony.","zh":"典禮後，掌聲會漸漸消散。"},{"en":"The applause will fade means praise and celebration will gradually become quieter or end.","zh":"the applause will fade 的意思是讚美和慶祝會逐漸變小聲或結束。"},{"en":"After prizes are given, the applause will fade and ordinary life will continue.","zh":"頒獎後，掌聲會漸漸消散，普通生活會繼續。"},{"en":"This phrase reminds graduates not to depend only on public celebration.","zh":"這個短語提醒畢業生不要只依賴公開慶祝。"},{"en":"It shows that what we do after praise matters most.","zh":"它顯示在掌聲之後我們做甚麼最重要。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"be cleared away","meaning":"被清走","examples":[{"en":"The chairs in this hall will be cleared away.","zh":"這個禮堂中的椅子會被清走。"},{"en":"Be cleared away means be removed or put away after an event.","zh":"be cleared away 的意思是在活動後被移走或收起。"},{"en":"After graduation, decorations and chairs will be cleared away from the hall.","zh":"畢業禮後，裝飾和椅子會從禮堂被清走。"},{"en":"This detail shows that even meaningful ceremonies are temporary.","zh":"這個細節顯示即使有意義的典禮也是短暫的。"},{"en":"The phrase makes passing time visible through a simple action.","zh":"這個短語透過簡單行動令時間流逝變得可見。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"turn passing time into lasting meaning","meaning":"把流逝的時間化為長久的意義","examples":[{"en":"What we do next can turn passing time into lasting meaning.","zh":"我們接下來做的事可以把流逝的時間化為長久的意義。"},{"en":"To turn passing time into lasting meaning means to make temporary moments valuable through action.","zh":"turn passing time into lasting meaning 的意思是透過行動令短暫時刻變得有價值。"},{"en":"A graduate can turn passing time into lasting meaning by serving others or learning bravely.","zh":"畢業生可以透過服務他人或勇敢學習，把流逝的時間化為長久的意義。"},{"en":"Time passes anyway, but choices decide whether it leaves value behind.","zh":"時間無論如何都會流逝，但選擇決定它是否留下價值。"},{"en":"This phrase gives graduates responsibility for making life meaningful.","zh":"這個短語讓畢業生承擔使人生有意義的責任。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"passing time","meaning":"流逝的時間","examples":[{"en":"We can turn passing time into lasting meaning.","zh":"我們可以把流逝的時間化為長久的意義。"},{"en":"Passing time means time that is moving forward and disappearing as it goes.","zh":"passing time 是正在向前走並一邊消失的時間。"},{"en":"School days are passing time, but friendship can give them lasting value.","zh":"校園日子是流逝的時間，但友誼可以給它們長久價值。"},{"en":"Passing time feels less wasted when it is used with love and purpose.","zh":"當時間被用於愛和目標時，流逝的時間就較不像被浪費。"},{"en":"This phrase reminds us that time is temporary.","zh":"這個短語提醒我們時間是短暫的。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"lasting meaning","meaning":"長久的意義","examples":[{"en":"Our actions can give time lasting meaning.","zh":"我們的行動可以給時間長久的意義。"},{"en":"Lasting meaning is value that remains after the moment has passed.","zh":"lasting meaning 是時刻過去後仍然留下的價值。"},{"en":"A kind word on graduation day can have lasting meaning for a nervous classmate.","zh":"畢業日一句善意說話，可以對緊張同學有長久的意義。"},{"en":"Meaning lasts when actions touch people, shape character, or serve a purpose.","zh":"當行動觸動人、塑造品格或服務目標，意義就會持久。"},{"en":"This phrase describes value that survives beyond the present.","zh":"這個短語描述超越當下仍存在的價值。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"protect our hours","meaning":"珍惜我們的時間","examples":[{"en":"Let us protect our hours.","zh":"讓我們珍惜我們的時間。"},{"en":"To protect our hours means to use time carefully and not let it be wasted carelessly.","zh":"protect our hours 的意思是小心運用時間，不讓它被隨意浪費。"},{"en":"Graduates protect their hours when they choose meaningful work over endless scrolling.","zh":"當畢業生選擇有意義的工作而不是無止境滑手機時，就是珍惜時間。"},{"en":"Protecting time helps people make room for study, rest, relationships, and courage.","zh":"珍惜時間幫助人為學習、休息、關係和勇氣留出空間。"},{"en":"This phrase treats time as something valuable and fragile.","zh":"這個短語把時間視為有價值而脆弱的東西。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"honour our people","meaning":"珍重我們身邊的人","examples":[{"en":"Let us honour our people.","zh":"讓我們珍重我們身邊的人。"},{"en":"To honour our people means to respect, thank, and care for those who have walked with us.","zh":"honour our people 的意思是尊重、感謝和關心一路陪伴我們的人。"},{"en":"Graduates honour their people when they thank parents, teachers, friends, and helpers.","zh":"當畢業生感謝父母、老師、朋友和幫助者時，就是珍重身邊的人。"},{"en":"Honouring people prevents success from becoming lonely or selfish.","zh":"珍重身邊的人可以防止成功變得孤單或自私。"},{"en":"This phrase reminds listeners that relationships deserve action.","zh":"這個短語提醒聽眾，關係值得用行動回應。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"begin our next chapter","meaning":"開展人生下一章","examples":[{"en":"Let us begin our next chapter with courage.","zh":"讓我們帶着勇氣開展人生下一章。"},{"en":"To begin our next chapter means to start a new stage of life.","zh":"begin our next chapter 的意思是開始人生的新階段。"},{"en":"Graduation begins the next chapter of study, work, independence, and growth.","zh":"畢業開展學習、工作、獨立和成長的人生下一章。"},{"en":"A new chapter may feel uncertain, but it also brings space to change.","zh":"新一章可能感覺不確定，但也帶來改變的空間。"},{"en":"This phrase compares life to a story that continues after school.","zh":"這個短語把人生比作離校後仍繼續的故事。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"with courage","meaning":"帶着勇氣","examples":[{"en":"Graduates should begin the next chapter with courage.","zh":"畢業生應帶着勇氣開展下一章。"},{"en":"With courage means with bravery despite fear or uncertainty.","zh":"with courage 的意思是即使害怕或不確定，仍帶着勇敢。"},{"en":"A student applies for a difficult course with courage when she tries even though she is nervous.","zh":"當學生即使緊張仍申請困難課程時，就是帶着勇氣嘗試。"},{"en":"Courage does not remove fear; it helps people move while fear is present.","zh":"勇氣不會消除恐懼；它幫助人在恐懼存在時仍向前走。"},{"en":"This phrase describes the attitude needed for a new beginning.","zh":"這個短語描述新開始所需的態度。"}],"source":"2013 Q8.pdf","sourcePage":12},{"front":"years from now","meaning":"多年以後","examples":[{"en":"Years from now, may we look back with peace.","zh":"多年以後，願我們能平靜地回望。"},{"en":"Years from now means many years in the future.","zh":"years from now 的意思是在未來許多年後。"},{"en":"Years from now, graduates may remember this ceremony more clearly than they expect.","zh":"多年以後，畢業生可能比預期中更清楚記得這場典禮。"},{"en":"This phrase invites listeners to imagine their future selves looking back.","zh":"這個短語邀請聽眾想像未來的自己回望現在。"},{"en":"It gives the speech a reflective and hopeful ending.","zh":"它給演講一個反思而有希望的結尾。"}],"source":"2013 Q8.pdf","sourcePage":13},{"front":"look back","meaning":"回望","examples":[{"en":"May we look back and say that we lived well.","zh":"願我們回望時能說自己好好地活過。"},{"en":"To look back means to remember and think about the past.","zh":"look back 的意思是回憶並思考過去。"},{"en":"Graduates may look back on school life with gratitude after many years.","zh":"多年後，畢業生可能帶着感恩回望校園生活。"},{"en":"Looking back can bring peace when people know they used time well.","zh":"當人們知道自己好好運用時間，回望可以帶來平靜。"},{"en":"This phrase connects memory with judgement and reflection.","zh":"這個短語把記憶與判斷和反思連繫起來。"}],"source":"2013 Q8.pdf","sourcePage":13},{"front":"time slipped away from us","meaning":"時間從我們手中溜走","examples":[{"en":"We should not say that time slipped away from us.","zh":"我們不應說時間從我們手中溜走。"},{"en":"Time slipped away from us means time passed without us noticing or using it well.","zh":"time slipped away from us 的意思是時間在我們沒有注意或沒有好好使用下過去。"},{"en":"A student may feel time slipped away after spending months delaying a dream.","zh":"學生拖延夢想數月後，可能覺得時間從手中溜走。"},{"en":"This phrase carries regret because lost time cannot be recovered.","zh":"這個短語帶有遺憾，因為失去的時間不能取回。"},{"en":"It warns graduates not to live carelessly.","zh":"它提醒畢業生不要隨便生活。"}],"source":"2013 Q8.pdf","sourcePage":13},{"front":"held it carefully","meaning":"小心珍惜它","examples":[{"en":"May we say that we held time carefully.","zh":"願我們能說自己小心珍惜了時間。"},{"en":"Held it carefully means treated time as precious and used it with attention.","zh":"held it carefully 的意思是把時間視為珍貴，並有意識地使用它。"},{"en":"A graduate holds time carefully by choosing meaningful action instead of endless delay.","zh":"畢業生選擇有意義行動而不是無盡拖延，就是小心珍惜時間。"},{"en":"Holding time carefully does not mean controlling time; it means respecting it.","zh":"小心珍惜時間不代表控制時間，而是尊重時間。"},{"en":"This phrase gives a gentle image of responsible living.","zh":"這個短語給負責任生活一個溫柔意象。"}],"source":"2013 Q8.pdf","sourcePage":13},{"front":"spent it generously","meaning":"慷慨地運用它","examples":[{"en":"May we say that we spent time generously.","zh":"願我們能說自己慷慨地運用了時間。"},{"en":"Spent it generously means used time freely and kindly for meaningful people or purposes.","zh":"spent it generously 的意思是為有意義的人或目標自由而仁慈地使用時間。"},{"en":"A graduate spends time generously when he visits family instead of always rushing alone.","zh":"當畢業生探望家人，而不是總是獨自匆忙前行時，就是慷慨地運用時間。"},{"en":"Time spent generously can strengthen friendships, service, and gratitude.","zh":"慷慨運用時間可以加強友誼、服務和感恩。"},{"en":"This phrase suggests that time should not be hoarded selfishly.","zh":"這個短語暗示時間不應被自私地囤積。"}],"source":"2013 Q8.pdf","sourcePage":13},{"front":"lived it well","meaning":"好好地活過","examples":[{"en":"May we say that we lived it well.","zh":"願我們能說自己好好地活過。"},{"en":"Lived it well means used one’s time or life with purpose, courage, kindness, and gratitude.","zh":"lived it well 的意思是帶着目標、勇氣、善意和感恩去使用時間或生命。"},{"en":"A person lives time well when daily choices match what truly matters.","zh":"當一個人的日常選擇符合真正重要的事，他就是好好地活過。"},{"en":"Living well does not require a perfect life, but it requires honest effort.","zh":"好好生活不需要完美人生，但需要真誠努力。"},{"en":"This phrase gives a hopeful measure of success beyond grades.","zh":"這個短語給成績以外的成功一個有希望的衡量。"}],"source":"2013 Q8.pdf","sourcePage":13},{"front":"congratulations to","meaning":"恭喜……","examples":[{"en":"Congratulations to the graduating classes.","zh":"恭喜各畢業班。"},{"en":"Congratulations to means expressing happiness and praise for someone’s achievement.","zh":"congratulations to 的意思是為某人的成就表達高興和讚賞。"},{"en":"A teacher may say congratulations to students who have completed their school journey.","zh":"老師可以向完成校園旅程的學生說恭喜。"},{"en":"Congratulations recognise effort, growth, and the importance of the moment.","zh":"恭喜承認努力、成長和當刻的重要性。"},{"en":"This phrase is a warm way to close a graduation speech.","zh":"這個短語是結束畢業演講的溫暖方式。"}],"source":"2013 Q8.pdf","sourcePage":13},{"front":"graduating classes","meaning":"各畢業班","examples":[{"en":"Congratulations to the graduating classes.","zh":"恭喜各畢業班。"},{"en":"Graduating classes are the groups of students who are finishing school in the same year.","zh":"graduating classes 是同一年完成學業的一批批學生。"},{"en":"The graduating classes may include several forms, classes, or programmes.","zh":"各畢業班可以包括不同班別、級別或課程。"},{"en":"They share the same milestone even if they will follow different paths afterwards.","zh":"即使之後會走向不同道路，他們仍共享同一里程碑。"},{"en":"This phrase honours all students completing this stage together.","zh":"這個短語向所有一起完成這個階段的學生致意。"}],"source":"2013 Q8.pdf","sourcePage":13}],"dse/writing/part-b/2013/Q9":[{"front":"conservation room","meaning":"文物修復室","examples":[{"en":"When we entered the conservation room, Kelvin was scrubbing his hands.","zh":"當我們進入文物修復室時，Kelvin 正在用力洗手。"},{"en":"A conservation room is a special room where damaged artworks or historical objects are cleaned, studied, and repaired.","zh":"conservation room 指專門清潔、研究和修復受損藝術品或歷史物件的房間。"},{"en":"Museum workers wear gloves in a conservation room to protect fragile objects from oil and dirt.","zh":"博物館工作人員在文物修復室會戴手套，以保護脆弱物件免受油脂和污垢影響。"},{"en":"A conservation room should be clean and controlled because one careless action can damage old materials.","zh":"文物修復室應保持清潔和受控，因為一個粗心動作也可能損壞舊物料。"},{"en":"In the story, the conservation room becomes the place where the truth about the painting begins to appear.","zh":"在故事中，文物修復室成為畫作真相開始浮現的地方。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"scrub his hands","meaning":"用力洗手","examples":[{"en":"Kelvin was scrubbing his hands although he was wearing gloves.","zh":"Kelvin 明明戴着手套，卻仍在用力洗手。"},{"en":"To scrub his hands means to wash his hands hard and carefully, often because he feels dirty or anxious.","zh":"scrub his hands 指用力而仔細地洗手，常因覺得骯髒或焦慮。"},{"en":"A doctor may scrub his hands before surgery to remove germs.","zh":"醫生在手術前可能會用力洗手，以去除細菌。"},{"en":"Kelvin scrubs his hands even with gloves on, which suggests guilt rather than cleanliness.","zh":"Kelvin 戴着手套仍用力洗手，暗示的不是潔淨，而是內疚。"},{"en":"This phrase shows nervous behaviour through a simple physical action.","zh":"這個短語透過簡單身體動作顯示緊張行為。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"wearing gloves","meaning":"戴着手套","examples":[{"en":"Kelvin was wearing gloves in the conservation room.","zh":"Kelvin 在文物修復室裏戴着手套。"},{"en":"Wearing gloves means having gloves on the hands to protect oneself or the object being handled.","zh":"wearing gloves 指手上戴着手套，以保護自己或正在處理的物件。"},{"en":"Museum staff wear gloves when touching old paper, paintings, or metal objects.","zh":"博物館職員觸碰舊紙張、畫作或金屬物件時會戴着手套。"},{"en":"Wearing gloves can prevent fingerprints, sweat, and oil from damaging valuable items.","zh":"戴手套可以防止指紋、汗水和油脂損壞貴重物件。"},{"en":"In the story, the gloves make Kelvin look careful, but they cannot hide what he has done.","zh":"在故事中，手套令 Kelvin 看起來小心，但不能掩蓋他做過的事。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"reversible black pigment","meaning":"可逆黑色顏料","examples":[{"en":"On the table lay reversible black pigment.","zh":"桌上放着可逆黑色顏料。"},{"en":"Reversible black pigment is black colouring that can be removed or undone during restoration.","zh":"reversible black pigment 指可在修復過程中移除或還原的黑色顏料。"},{"en":"Conservators may use reversible pigment so future experts can correct or change the repair.","zh":"修復師可能使用可逆顏料，讓日後專家可以修正或改動修復。"},{"en":"If a pigment is not reversible, it may permanently alter an artwork.","zh":"如果顏料不可逆，它可能永久改變藝術品。"},{"en":"In the story, the reversible pigment suggests Kelvin was preparing something that could later be hidden or removed.","zh":"在故事中，可逆黑色顏料暗示 Kelvin 正準備一些日後可被隱藏或移除的東西。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"a cutter with a blade","meaning":"一把有刀片的 刀","examples":[{"en":"On the table lay a cutter with a blade thinner than a fingernail.","zh":"桌上放着一把有刀片的 刀，刀片比指甲還薄。"},{"en":"A cutter with a blade is a sharp tool used for cutting paper, canvas, tape, or other materials.","zh":"cutter with a blade 指用來切割紙張、畫布、膠帶或其他物料的鋒利工具。"},{"en":"A museum worker may use a cutter with a blade to trim protective backing very carefully.","zh":"博物館工作人員可能用有刀片的 刀小心修剪保護背板。"},{"en":"A cutter with a blade can be useful, but it can also damage an artwork if used wrongly.","zh":"有刀片的 刀可以很有用，但如果用錯，也可能損壞藝術品。"},{"en":"In the story, the cutter makes Kelvin’s work look suspicious.","zh":"在故事中， 刀令 Kelvin 的工作看起來可疑。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"thinner than a fingernail","meaning":"比指甲還薄","examples":[{"en":"The blade was thinner than a fingernail.","zh":"那塊刀片比指甲還薄。"},{"en":"Thinner than a fingernail means extremely thin and delicate.","zh":"thinner than a fingernail 指極薄而精細。"},{"en":"The paper was thinner than a fingernail, so the librarian turned each page slowly.","zh":"那張紙比指甲還薄，所以圖書館員慢慢翻每一頁。"},{"en":"A blade thinner than a fingernail can make very precise cuts.","zh":"比指甲還薄的刀片可以切出非常精準的痕跡。"},{"en":"This phrase helps readers imagine how careful and controlled the damage may have been.","zh":"這個短語幫助讀者想像損壞可能是多麼小心和受控制。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"smiled too quickly","meaning":"笑得太快；笑得不自然","examples":[{"en":"Kelvin smiled too quickly when the inspector entered.","zh":"督察進來時，Kelvin 笑得太快。"},{"en":"Smiled too quickly means smiled so fast that the expression seemed unnatural or nervous.","zh":"smiled too quickly 指笑容出現得太快，令人覺得不自然或緊張。"},{"en":"The student smiled too quickly when the teacher asked about the missing homework.","zh":"老師問起失蹤功課時，學生笑得太快。"},{"en":"A quick smile can look polite, but it may also hide fear.","zh":"快速的笑容可以看似有禮，但也可能隱藏恐懼。"},{"en":"In the story, Kelvin’s smile suggests he is trying too hard to look innocent.","zh":"在故事中，Kelvin 的笑容暗示他太努力裝作無辜。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"prepare restoration materials","meaning":"準備修復材料","examples":[{"en":"Kelvin said he was preparing restoration materials.","zh":"Kelvin 說自己正在準備修復材料。"},{"en":"To prepare restoration materials means to get tools, chemicals, papers, or pigments ready for repairing an artwork.","zh":"prepare restoration materials 指準備修復藝術品所需的工具、化學品、紙張或顏料。"},{"en":"Before fixing an old painting, conservators prepare restoration materials carefully.","zh":"修補舊畫前，修復師會仔細準備修復材料。"},{"en":"Preparing restoration materials can sound professional, but Kelvin may be using the phrase as an excuse.","zh":"準備修復材料聽起來很專業，但 Kelvin 可能把這說法當作藉口。"},{"en":"This phrase shows how technical language can hide suspicious action.","zh":"這個短語顯示技術語言如何掩蓋可疑行動。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"restoration materials","meaning":"修復材料","examples":[{"en":"The museum needed restoration materials after the damage.","zh":"損壞後，博物館需要修復材料。"},{"en":"Restoration materials are the substances and tools used to repair or preserve damaged objects.","zh":"restoration materials 指用來修復或保存受損物件的材料和工具。"},{"en":"Brushes, special paper, gentle solvents, and pigments can be restoration materials.","zh":"畫筆、特製紙張、溫和溶劑和顏料都可以是修復材料。"},{"en":"Good restoration materials should protect the original artwork rather than cover up mistakes.","zh":"好的修復材料應保護原作，而不是掩蓋錯誤。"},{"en":"In the story, the materials become part of the question: repair or concealment?","zh":"在故事中，這些材料成為問題的一部分：是修復，還是隱瞞？"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"act fast","meaning":"迅速行動","examples":[{"en":"Kelvin claimed that the museum had to act fast.","zh":"Kelvin 聲稱博物館必須迅速行動。"},{"en":"Act fast means respond quickly to a problem or emergency.","zh":"act fast 指快速回應問題或緊急情況。"},{"en":"A school must act fast if a student is injured during sports day.","zh":"如果學生在運動會受傷，學校必須迅速行動。"},{"en":"Museums may need to act fast when water, smoke, or heat threatens an artwork.","zh":"當水、煙或熱力威脅藝術品時，博物館可能需要迅速行動。"},{"en":"In the story, Kelvin says they must act fast, but speed may be covering up the truth.","zh":"在故事中，Kelvin 說他們必須迅速行動，但速度可能是在掩蓋真相。"}],"source":"2013 Q9.pdf","sourcePage":1},{"front":"lifted the report","meaning":"舉起報告","examples":[{"en":"Lam lifted the report and questioned Kelvin.","zh":"Lam 舉起報告並質問 Kelvin。"},{"en":"Lifted the report means raised the document so others could see or notice it.","zh":"lifted the report 指把文件舉起，讓別人看見或注意到。"},{"en":"The teacher lifted the report before asking who had signed it.","zh":"老師舉起報告，然後問是誰簽署的。"},{"en":"Lifting the report turns a paper document into visible evidence.","zh":"舉起報告把紙本文書變成可見證據。"},{"en":"In the story, Inspector Lam uses the report to challenge Kelvin’s story.","zh":"在故事中，Lam 督察用報告挑戰 Kelvin 的說法。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"signed this yesterday","meaning":"昨天簽署這份文件","examples":[{"en":"Lam asked Kelvin whether he had signed the report the day before.","zh":"Lam 問 Kelvin 是否昨天簽署了這份報告。"},{"en":"Signed this yesterday means put one’s name on this document on the previous day.","zh":"signed this yesterday 指在前一天把自己的名字簽在這份文件上。"},{"en":"If you signed this yesterday, you cannot pretend you never saw it.","zh":"如果你昨天簽署這份文件，就不能假裝從未看過它。"},{"en":"A signed report can prove what someone knew at a certain time.","zh":"已簽署的報告可以證明某人在某個時間知道甚麼。"},{"en":"In the story, the signature shows Kelvin knew the painting’s condition before the fake crime.","zh":"在故事中，簽名顯示 Kelvin 在假罪案前已知道畫作狀況。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"the painting’s real condition","meaning":"畫作的真實狀況","examples":[{"en":"Kelvin knew the painting’s real condition.","zh":"Kelvin 知道畫作的真實狀況。"},{"en":"The painting’s real condition means the true physical state of the artwork, including any damage.","zh":"the painting’s real condition 指藝術品真正的物理狀態，包括任何損壞。"},{"en":"A conservator records a painting’s real condition before starting repairs.","zh":"修復師在開始修復前會記錄畫作的真實狀況。"},{"en":"If someone hides the painting’s real condition, buyers and museums may be misled.","zh":"如果有人隱瞞畫作的真實狀況，買家和博物館可能被誤導。"},{"en":"In the story, knowing the real condition makes Kelvin responsible for the cover-up.","zh":"在故事中，知道真實狀況令 Kelvin 對掩飾行為負有責任。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"blinked","meaning":"眨眼","examples":[{"en":"Kelvin blinked when Lam mentioned the report.","zh":"Lam 提到報告時，Kelvin 眨了眨眼。"},{"en":"Blinked means quickly closed and opened the eyes.","zh":"blinked 指快速閉上再張開眼睛。"},{"en":"The student blinked when the teacher named the missing file.","zh":"老師提到失蹤文件時，學生眨了眨眼。"},{"en":"A sudden blink can show surprise, fear, or a moment of panic.","zh":"突然眨眼可以顯示驚訝、恐懼或一刻慌亂。"},{"en":"In the story, Kelvin’s blink suggests the report has touched a hidden truth.","zh":"在故事中，Kelvin 的眨眼暗示報告觸及隱藏真相。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"TRUTH HAS A PRICE","meaning":"真相是有代價的","examples":[{"en":"The words on the painting said “TRUTH HAS A PRICE”.","zh":"畫上的字寫着：「真相是有代價的。」"},{"en":"“Truth has a price” means revealing the truth may cost someone money, reputation, comfort, or safety.","zh":"Truth has a price 指揭示真相可能令人付出金錢、名聲、舒適或安全的代價。"},{"en":"A journalist learns that truth has a price when honest reporting brings powerful enemies.","zh":"記者誠實報道而得罪有權勢的人時，就會明白真相是有代價的。"},{"en":"In Kelvin’s case, truth has a price because honesty could damage his career and the museum’s image.","zh":"對 Kelvin 來說，真相是有代價的，因為誠實可能損害他的事業和博物館形象。"},{"en":"This phrase gives the fake message an ironic meaning because Kelvin is hiding the real truth.","zh":"這個短語令假訊息帶有諷刺意味，因為 Kelvin 正在隱藏真正的真相。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"already damaged","meaning":"已經受損","examples":[{"en":"The Returning Junk was already damaged before last night.","zh":"《歸來的帆船》在昨晚之前已經受損。"},{"en":"Already damaged means it had been harmed before the time people are talking about.","zh":"already damaged 指在大家正在談論的時間之前已經受到損害。"},{"en":"The phone was already damaged before it fell from the table today.","zh":"那部電話今天從桌上跌下前已經受損。"},{"en":"If the painting was already damaged, last night’s crime cannot be the original cause.","zh":"如果畫作已經受損，昨晚的罪案就不可能是最初原因。"},{"en":"This phrase changes the investigation by moving the damage earlier in time.","zh":"這個短語把損壞時間推前，改變了調查方向。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"before last night","meaning":"在昨晚之前","examples":[{"en":"The painting had already been damaged before last night.","zh":"那幅畫在昨晚之前已經受損。"},{"en":"Before last night means earlier than the previous night.","zh":"before last night 指早於昨晚。"},{"en":"The window was cracked before last night, so the storm did not cause it.","zh":"窗戶在昨晚之前已經裂開，所以不是暴風造成的。"},{"en":"Placing the damage before last night proves the staged crime came later.","zh":"把損壞放在昨晚之前，證明被製造的罪案是後來才發生的。"},{"en":"This phrase is important because timing can reveal a lie.","zh":"這個短語很重要，因為時間可以揭穿謊言。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"wasn’t it?","meaning":"不是嗎？","examples":[{"en":"The inspector asked, “It was already damaged, wasn’t it?”","zh":"督察問：「它早已受損，不是嗎？」"},{"en":"Wasn’t it? is a question tag used to check or pressure someone to confirm a statement.","zh":"wasn’t it? 是附加問句，用來確認或迫使某人承認前面的說法。"},{"en":"You signed the form yesterday, wasn’t it? would sound unnatural; we usually say, “didn’t you?”","zh":"“You signed the form yesterday, wasn’t it?” 不自然；通常會說 “didn’t you?”。"},{"en":"“It was already damaged, wasn’t it?” pushes Kelvin toward admitting the truth.","zh":"“It was already damaged, wasn’t it?” 迫使 Kelvin 接近承認真相。"},{"en":"This question form can make an accusation sound calm but firm.","zh":"這種問句可以令指控聽起來冷靜但堅定。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"for once","meaning":"這一次；難得一次","examples":[{"en":"For once, the room went silent.","zh":"這一次，房間變得沉默。"},{"en":"For once means this time, unlike what usually happens.","zh":"for once 指這一次與平常不同。"},{"en":"For once, the noisy classroom became completely quiet.","zh":"難得一次，那個嘈吵的課室變得完全安靜。"},{"en":"In the story, “for once” suggests the usual excuses and explanations have stopped.","zh":"在故事中，for once 暗示平常的藉口和解釋都停止了。"},{"en":"This phrase marks a rare moment when everyone understands the seriousness of the truth.","zh":"這個短語標示一個罕見時刻：所有人都明白真相的嚴重性。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"went silent","meaning":"變得沉默","examples":[{"en":"The room went silent after Lam revealed the truth.","zh":"Lam 揭示真相後，房間變得沉默。"},{"en":"Went silent means became quiet suddenly.","zh":"went silent 指突然安靜下來。"},{"en":"The meeting room went silent when the manager mentioned the missing money.","zh":"經理提到失蹤款項時，會議室變得沉默。"},{"en":"A room may go silent when people are shocked or embarrassed.","zh":"當人們震驚或尷尬時，房間可能會變得沉默。"},{"en":"In the story, the silence shows that Lam’s discovery cannot be easily dismissed.","zh":"在故事中，沉默顯示 Lam 的發現不能被輕易否認。"}],"source":"2013 Q9.pdf","sourcePage":2},{"front":"it turned out that","meaning":"原來","examples":[{"en":"It turned out that the painting had been damaged two nights earlier.","zh":"原來那幅畫早在兩晚前已經受損。"},{"en":"It turned out that means people later discovered the real fact was different from what they first thought.","zh":"it turned out that 指後來發現真相與最初所想不同。"},{"en":"It turned out that the lost wallet had been in the school office all day.","zh":"原來那個遺失的錢包整天都在校務處。"},{"en":"It turned out that the museum’s “vandalism” was hiding an earlier accident.","zh":"原來博物館的「破壞事件」是在掩蓋更早的意外。"},{"en":"This phrase introduces the truth after confusion or suspicion.","zh":"這個短語在混亂或懷疑之後引入真相。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"private preview","meaning":"私人預展","examples":[{"en":"The accident happened during a private preview.","zh":"意外發生在一次私人預展期間。"},{"en":"A private preview is a special showing before the public opening, usually for selected guests.","zh":"private preview 指公開開幕前為特定賓客安排的特別預覽。"},{"en":"Sponsors and collectors may attend a private preview before an exhibition opens.","zh":"贊助人和收藏家可能在展覽開幕前參加私人預展。"},{"en":"A mistake during a private preview can be embarrassing because important guests are present.","zh":"私人預展中出錯會令人尷尬，因為重要賓客在場。"},{"en":"In the story, the private preview explains why the museum wanted to hide the accident.","zh":"在故事中，私人預展解釋了博物館為何想隱瞞意外。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"two nights earlier","meaning":"兩晚前","examples":[{"en":"The accident had happened two nights earlier.","zh":"意外早在兩晚前已經發生。"},{"en":"Two nights earlier means two nights before the time being discussed.","zh":"two nights earlier 指在正在討論的時間之前兩個晚上。"},{"en":"The alarm had first sounded two nights earlier, but nobody checked it.","zh":"警報早在兩晚前第一次響起，但沒有人檢查。"},{"en":"If the accident happened two nights earlier, the public story about last night is false.","zh":"如果意外發生在兩晚前，關於昨晚的公開說法就是假的。"},{"en":"This phrase helps rebuild the true timeline.","zh":"這個短語幫助重建真正時間線。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"sponsor’s child","meaning":"贊助人的孩子","examples":[{"en":"A sponsor’s child had knocked a display light onto the painting.","zh":"一名贊助人的孩子把展示燈撞到畫作上。"},{"en":"A sponsor’s child is the son or daughter of someone who gives money or support to an organisation.","zh":"sponsor’s child 指向機構提供金錢或支持的人的子女。"},{"en":"A museum may treat a sponsor’s child carefully because the sponsor is important.","zh":"博物館可能會小心對待贊助人的孩子，因為贊助人很重要。"},{"en":"If a sponsor’s child causes damage, staff may feel pressure to protect the family’s name.","zh":"如果贊助人的孩子造成損壞，職員可能感到壓力，要保護那家人的名聲。"},{"en":"In the story, the child’s identity explains why the accident became politically and financially sensitive.","zh":"在故事中，孩子的身份解釋了為何意外變得涉及政治和金錢。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"knock something onto","meaning":"把某物撞到……上","examples":[{"en":"The child knocked a display light onto The Returning Junk.","zh":"那孩子把展示燈撞到《歸來的帆船》上。"},{"en":"Knock something onto means hit or push an object so it falls onto another thing.","zh":"knock something onto 指撞到或推動某物，令它跌到另一物上。"},{"en":"A student knocked a cup onto her homework and ruined the page.","zh":"學生把杯子撞到功課上，弄壞了那一頁。"},{"en":"Knocking a display light onto a painting can cause burns, dents, or tears.","zh":"把展示燈撞到畫上，可能造成燒焦、凹痕或撕裂。"},{"en":"This phrase explains the physical cause of the original damage.","zh":"這個短語解釋最初損壞的物理原因。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"display light","meaning":"展示燈","examples":[{"en":"A display light fell onto the painting.","zh":"一盞展示燈跌到畫作上。"},{"en":"A display light is a light used to illuminate an object in an exhibition.","zh":"display light 指展覽中用來照亮展品的燈。"},{"en":"Museums use display lights to help visitors see colour, texture, and detail.","zh":"博物館使用展示燈，讓觀眾看見顏色、質感和細節。"},{"en":"If a display light falls, heat and glass can damage fragile artworks.","zh":"如果展示燈掉下來，熱力和玻璃可能損壞脆弱藝術品。"},{"en":"In the story, the display light causes the real accident before Kelvin stages the fake crime.","zh":"在故事中，展示燈造成真正意外，早於 Kelvin 製造假罪案。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"The Returning Junk","meaning":"《歸來的帆船》","examples":[{"en":"The Returning Junk had already been damaged before the fake crime.","zh":"《歸來的帆船》在假罪案前已經受損。"},{"en":"The Returning Junk is the title of the painting at the centre of the museum case.","zh":"The Returning Junk 是這宗博物館案件中心那幅畫的標題。"},{"en":"A junk is a traditional Chinese sailing boat, so the title may suggest return, harbour, and memory.","zh":"junk 指傳統中國帆船，所以標題可能暗示歸來、海港和記憶。"},{"en":"When The Returning Junk is damaged, the museum’s pride and reputation are threatened.","zh":"當《歸來的帆船》受損，博物館的自豪和名聲都受到威脅。"},{"en":"In the story, the painting is both an artwork and evidence of hidden shame.","zh":"在故事中，這幅畫既是藝術品，也是隱藏醜聞的證據。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"scorch one corner","meaning":"燒焦一角","examples":[{"en":"The display light scorched one corner of the painting.","zh":"展示燈燒焦了畫作的一角。"},{"en":"Scorch one corner means burn or darken one edge or part with heat.","zh":"scorch one corner 指用熱力燒焦或燻黑某物的一角。"},{"en":"A hot lamp can scorch one corner of an old poster if it is placed too close.","zh":"如果熱燈放得太近，可能會燒焦舊海報的一角。"},{"en":"Scorching a corner may look small, but it can seriously damage old paint or paper.","zh":"燒焦一角看似細小，但可以嚴重損壞舊顏料或紙張。"},{"en":"In the story, the scorched corner is the first real injury to the painting.","zh":"在故事中，燒焦的一角是畫作第一次真正受傷。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"be told to","meaning":"被告知要……","examples":[{"en":"Kelvin had been told to hide the accident.","zh":"Kelvin 被告知要隱瞞意外。"},{"en":"Be told to means be instructed or ordered to do something.","zh":"be told to 指被指示或命令去做某事。"},{"en":"The students were told to leave the hall quietly after the ceremony.","zh":"學生被告知要在典禮後安靜離開禮堂。"},{"en":"Being told to hide a mistake does not remove responsibility for hiding it.","zh":"被告知要隱瞞錯誤，並不代表可以免除隱瞞的責任。"},{"en":"In the story, Kelvin follows an order, but then creates a worse lie.","zh":"在故事中，Kelvin 聽從命令，卻製造了更嚴重的謊言。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"hide the accident","meaning":"隱瞞意外","examples":[{"en":"Kelvin had been told to hide the accident.","zh":"Kelvin 被告知要隱瞞意外。"},{"en":"Hide the accident means keep the accident secret so others do not know it happened.","zh":"hide the accident 指把意外保密，令別人不知道它曾發生。"},{"en":"A driver should not hide an accident, even if the damage looks small.","zh":"司機不應隱瞞意外，即使損壞看似細小。"},{"en":"Hiding an accident can turn a mistake into a serious act of dishonesty.","zh":"隱瞞意外可以把錯誤變成嚴重的不誠實行為。"},{"en":"In the story, hiding the accident leads to the fake vandalism.","zh":"在故事中，隱瞞意外導致後來的假破壞事件。"}],"source":"2013 Q9.pdf","sourcePage":3},{"front":"until after","meaning":"直到……之後","examples":[{"en":"The accident was supposed to stay hidden until after the overseas loan.","zh":"那宗意外原本應隱藏到海外借展之後。"},{"en":"Until after means up to a time later than a particular event.","zh":"until after 指一直到某事件之後的時間。"},{"en":"The results stayed secret until after the ceremony.","zh":"結果一直保密到典禮之後。"},{"en":"Hiding damage until after a loan would let the museum avoid immediate embarrassment.","zh":"把損壞隱瞞到借展之後，可以讓博物館暫時避免尷尬。"},{"en":"This phrase shows that the cover-up was planned around timing.","zh":"這個短語顯示掩飾行動是圍繞時間安排的。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"overseas loan","meaning":"海外借展","examples":[{"en":"The museum wanted to hide the damage until after the overseas loan.","zh":"博物館想把損壞隱瞞到海外借展之後。"},{"en":"An overseas loan is an arrangement in which an artwork is lent to an institution in another country or region.","zh":"overseas loan 指把藝術品借給另一國家或地區機構展出的安排。"},{"en":"A museum may send a painting on an overseas loan for an international exhibition.","zh":"博物館可能為國際展覽把畫作送去海外借展。"},{"en":"Damage before an overseas loan can threaten contracts, reputation, and insurance.","zh":"海外借展前出現損壞，可能威脅合約、名聲和保險。"},{"en":"In the story, the overseas loan gives the museum a reason to panic.","zh":"在故事中，海外借展給了博物館恐慌的理由。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"instead of confessing","meaning":"沒有承認，反而……","examples":[{"en":"Instead of confessing, Kelvin staged a louder crime.","zh":"Kelvin 沒有承認，反而製造了一宗更轟動的罪案。"},{"en":"Instead of confessing means not admitting the truth, but doing something else.","zh":"instead of confessing 指沒有承認真相，而是做了另一件事。"},{"en":"Instead of confessing that he broke the vase, the child blamed the dog.","zh":"孩子沒有承認自己打破花瓶，反而怪責狗。"},{"en":"Kelvin avoids confession by creating a new and more dramatic problem.","zh":"Kelvin 透過製造一個更戲劇性的問題來逃避承認。"},{"en":"This phrase contrasts honesty with a worse choice.","zh":"這個短語把誠實與更糟糕的選擇形成對比。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"stage a crime","meaning":"製造一宗罪案","examples":[{"en":"Kelvin staged a louder crime to hide the earlier accident.","zh":"Kelvin 製造了一宗更轟動的罪案，以隱藏較早的意外。"},{"en":"Stage a crime means arrange a fake crime scene to mislead people.","zh":"stage a crime 指布置假的犯罪現場來誤導別人。"},{"en":"A thief might stage a crime to make the police suspect someone else.","zh":"小偷可能製造一宗罪案，令警方懷疑其他人。"},{"en":"Kelvin stages a crime so the public will focus on vandals instead of the accident.","zh":"Kelvin 製造罪案，讓公眾集中在破壞者身上，而不是那宗意外。"},{"en":"This phrase shows deliberate deception, not a simple mistake.","zh":"這個短語顯示有意欺騙，而不是單純錯誤。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"a louder crime","meaning":"更轟動的罪案","examples":[{"en":"Kelvin staged a louder crime to distract the public.","zh":"Kelvin 製造了一宗更轟動的罪案來分散公眾注意。"},{"en":"A louder crime means a more dramatic or attention-grabbing crime.","zh":"louder crime 指更戲劇化、更吸引注意的罪案。"},{"en":"A company scandal may be hidden behind a louder public argument.","zh":"公司醜聞可能被一場更轟動的公開爭論掩蓋。"},{"en":"Kelvin creates a louder crime so the smaller original accident disappears from attention.","zh":"Kelvin 製造更轟動的罪案，令原本較小的意外消失在人們注意之外。"},{"en":"This phrase suggests noise, drama, and deliberate distraction.","zh":"這個短語暗示聲量、戲劇性和刻意分散注意。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"smear two works","meaning":"塗污兩件作品","examples":[{"en":"Kelvin smeared two works to fake a political message.","zh":"Kelvin 塗污了兩件作品來偽造政治訊息。"},{"en":"Smear two works means spread paint, pigment, or dirt across two artworks.","zh":"smear two works 指把顏料、色料或污物塗到兩件藝術品上。"},{"en":"Vandals may smear a wall with paint to make people notice a message.","zh":"破壞者可能把油漆塗在牆上，讓人注意某個訊息。"},{"en":"Smearing artworks damages them and makes the act look aggressive.","zh":"塗污藝術品會造成損害，並令行為看似具攻擊性。"},{"en":"In the story, Kelvin smears two works to make the fake crime seem ideological.","zh":"在故事中，Kelvin 塗污兩件作品，令假罪案看似有政治動機。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"fake a political message","meaning":"偽造政治訊息","examples":[{"en":"Kelvin faked a political message to mislead the public.","zh":"Kelvin 偽造政治訊息來誤導公眾。"},{"en":"Fake a political message means create a false message that appears to express a political belief.","zh":"fake a political message 指製造一段看似表達政治信念的虛假訊息。"},{"en":"Someone may fake a political message to make a simple crime look like a protest.","zh":"有人可能偽造政治訊息，令普通罪案看起來像抗議。"},{"en":"Kelvin uses the message to direct anger away from the museum’s real failure.","zh":"Kelvin 用這段訊息把憤怒從博物館真正失誤上轉移。"},{"en":"This phrase shows how symbols can be used dishonestly.","zh":"這個短語顯示符號可以被不誠實地利用。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"create three minutes of static","meaning":"製造三分鐘雜訊","examples":[{"en":"Kelvin created three minutes of static in the security footage.","zh":"Kelvin 在保安錄像中製造了三分鐘雜訊。"},{"en":"Create three minutes of static means make a video show noisy interference for three minutes.","zh":"create three minutes of static 指令影片出現三分鐘雜訊干擾。"},{"en":"A camera fault can create static that hides what happened in a room.","zh":"攝影機故障可以製造雜訊，遮住房間裏發生的事。"},{"en":"Kelvin creates static to remove the useful part of the security footage.","zh":"Kelvin 製造雜訊，是為了移除保安錄像中有用的部分。"},{"en":"This phrase shows a technical attempt to hide evidence.","zh":"這個短語顯示用技術方式隱藏證據。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"let the public blame","meaning":"讓公眾責怪","examples":[{"en":"Kelvin let the public blame vandals.","zh":"Kelvin 讓公眾責怪破壞公物者。"},{"en":"Let the public blame someone means allow ordinary people to believe that group is responsible.","zh":"let the public blame someone 指讓大眾相信某人或某群體要負責。"},{"en":"A company may let the public blame a worker instead of admitting management failed.","zh":"公司可能讓公眾責怪員工，而不是承認管理失敗。"},{"en":"Kelvin lets the public blame vandals so nobody looks at the private preview.","zh":"Kelvin 讓公眾責怪破壞者，這樣就沒有人查看私人預展。"},{"en":"This phrase shows how blame can be redirected.","zh":"這個短語顯示責任可以被轉移方向。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"vandals","meaning":"破壞公物者","examples":[{"en":"The public was meant to blame vandals.","zh":"公眾原本要責怪破壞公物者。"},{"en":"Vandals are people who deliberately damage public or private property.","zh":"vandals 指故意破壞公共或私人財物的人。"},{"en":"Vandals broke the park benches and painted words on the wall.","zh":"破壞公物者弄壞公園長椅，並在牆上噴字。"},{"en":"If people blame vandals, they may stop asking who inside the museum benefited.","zh":"如果人們責怪破壞者，就可能停止追問博物館內部誰得益。"},{"en":"In the story, the idea of vandals is used as a convenient false enemy.","zh":"在故事中，破壞者這個概念被用作方便的假敵人。"}],"source":"2013 Q9.pdf","sourcePage":4},{"front":"insurance would pay","meaning":"保險會賠償","examples":[{"en":"Kelvin believed that insurance would pay for the damage.","zh":"Kelvin 相信保險會賠償損壞。"},{"en":"Insurance would pay means the insurance company would cover the cost of loss or repair.","zh":"insurance would pay 指保險公司會承擔損失或修復費用。"},{"en":"If a shop fire is covered, insurance may pay for repairs.","zh":"如果商店火災受保障，保險可能會賠償維修費。"},{"en":"Kelvin hopes insurance will pay, so the financial problem will disappear.","zh":"Kelvin 希望保險會賠償，令財務問題消失。"},{"en":"This phrase shows how he thinks money can solve what is actually a moral problem.","zh":"這個短語顯示他以為金錢能解決其實屬於道德的問題。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"the real shame","meaning":"真正的醜聞","examples":[{"en":"The real shame would disappear beneath the invented one.","zh":"真正的醜聞會消失在虛構出來的那件事之下。"},{"en":"The real shame means the actual disgrace or wrongdoing people want to hide.","zh":"the real shame 指人們想隱藏的真正羞恥或錯誤。"},{"en":"The real shame was not the broken window, but the school’s attempt to blame an innocent student.","zh":"真正的醜聞不是破窗，而是學校試圖怪責無辜學生。"},{"en":"In the story, the real shame is the cover-up of the private-preview accident.","zh":"在故事中，真正的醜聞是私人預展意外被掩蓋。"},{"en":"This phrase separates the true scandal from the fake public story.","zh":"這個短語把真正醜聞與假的公開故事分開。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"disappear beneath","meaning":"消失在……之下","examples":[{"en":"The real shame would disappear beneath the invented one.","zh":"真正的醜聞會消失在虛構出來的那件事之下。"},{"en":"Disappear beneath means become hidden under something larger, louder, or more visible.","zh":"disappear beneath 指被更大、更吵或更顯眼的東西遮住。"},{"en":"A small warning may disappear beneath pages of colourful advertising.","zh":"一個細小警告可能消失在一頁頁彩色廣告之下。"},{"en":"Kelvin hopes the real accident will disappear beneath the fake vandalism story.","zh":"Kelvin 希望真正意外會消失在假破壞事件之下。"},{"en":"This phrase shows how one story can bury another.","zh":"這個短語顯示一個故事如何埋掉另一個故事。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"the invented one","meaning":"虛構出來的那件事","examples":[{"en":"The invented crime was meant to hide the real shame.","zh":"虛構出來的罪案原本是為了隱藏真正醜聞。"},{"en":"The invented one means the false event or story that someone created.","zh":"the invented one 指某人製造出來的虛假事件或故事。"},{"en":"The student used an invented excuse to hide the real reason for being late.","zh":"學生用虛構出來的藉口隱藏遲到的真正原因。"},{"en":"Kelvin’s invented crime is louder than the real accident, so people believe it first.","zh":"Kelvin 虛構出來的罪案比真正意外更轟動，所以人們首先相信它。"},{"en":"This phrase points to something artificial made to deceive.","zh":"這個短語指向被人造出來用作欺騙的東西。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"missed the dust","meaning":"忽略了塵埃","examples":[{"en":"Kelvin missed the dust when he staged the crime.","zh":"Kelvin 製造罪案時忽略了塵埃。"},{"en":"Missed the dust means failed to notice the dust that revealed what really happened.","zh":"missed the dust 指沒有留意到揭示真相的塵埃。"},{"en":"A detective may solve a case because someone missed the dust on a shelf.","zh":"偵探可能因有人忽略架上的塵埃而破案。"},{"en":"Dust can show whether an object has recently been moved or damaged.","zh":"塵埃可以顯示物件最近是否被移動或損壞。"},{"en":"In the story, Kelvin’s small oversight exposes his careful plan.","zh":"在故事中，Kelvin 的小疏忽揭穿了他仔細的計劃。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"too careful","meaning":"過於小心","examples":[{"en":"The blade was too careful to look like vandalism.","zh":"那刀痕過於小心，不像破壞公物。"},{"en":"Too careful means so neat or controlled that it seems planned rather than natural.","zh":"too careful 指太整齊或太受控制，以致看起來像有計劃，而非自然發生。"},{"en":"The fake tear in the paper was too careful to look accidental.","zh":"紙上的假裂痕過於小心，不像意外造成。"},{"en":"Real vandalism is often messy, but Kelvin’s cuts were strangely precise.","zh":"真正破壞行為常很凌亂，但 Kelvin 的刀痕卻異常精準。"},{"en":"This phrase shows that excessive neatness can become evidence.","zh":"這個短語顯示過度整齊也可以成為證據。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"whispered","meaning":"低聲說","examples":[{"en":"Kelvin whispered that he was trying to save his career.","zh":"Kelvin 低聲說他只是想保住自己的事業。"},{"en":"Whispered means spoke very quietly, often because of fear, shame, or secrecy.","zh":"whispered 指非常小聲地說話，常因恐懼、羞愧或保密。"},{"en":"The student whispered an apology after the truth came out.","zh":"真相揭開後，學生低聲道歉。"},{"en":"Kelvin whispers because his confidence has collapsed.","zh":"Kelvin 低聲說話，因為他的自信已經崩塌。"},{"en":"This word makes his confession feel small and ashamed.","zh":"這個詞令他的供認顯得渺小而羞愧。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"try to save my career","meaning":"試圖保住事業","examples":[{"en":"Kelvin claimed that he was trying to save his career.","zh":"Kelvin 聲稱自己只是試圖保住事業。"},{"en":"Try to save my career means attempt to protect one’s job, reputation, or professional future.","zh":"try to save my career 指嘗試保護自己的工作、名聲或職業前途。"},{"en":"A manager may lie to save his career after a serious mistake.","zh":"經理在嚴重錯誤後可能說謊來保住事業。"},{"en":"Kelvin says he wanted to save his career, but his actions damaged the art and the truth.","zh":"Kelvin 說他想保住事業，但他的行為傷害了藝術品和真相。"},{"en":"This phrase shows self-protection rather than responsibility.","zh":"這個短語顯示的是自我保護，而不是負責任。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"before I could stop myself","meaning":"我還未能阻止自己便……","examples":[{"en":"I spoke before I could stop myself.","zh":"我還未能阻止自己，便開口說了話。"},{"en":"Before I could stop myself means I said or did something suddenly before controlling the impulse.","zh":"before I could stop myself 指我在控制衝動前已突然說出或做出某事。"},{"en":"I laughed before I could stop myself when my friend made a face.","zh":"朋友做鬼臉時，我還未能阻止自己便笑了出來。"},{"en":"The narrator speaks because Kelvin’s excuse feels too wrong to ignore.","zh":"敘事者開口，是因為 Kelvin 的藉口錯得令人無法忽視。"},{"en":"This phrase shows an honest reaction escaping before caution can stop it.","zh":"這個短語顯示真實反應在謹慎阻止前已流露出來。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"save your name","meaning":"保住名聲","examples":[{"en":"Kelvin was saving his name, not the art.","zh":"Kelvin 是在保住名聲，而不是保護藝術品。"},{"en":"Save your name means protect your reputation or public image.","zh":"save your name 指保護自己的名譽或公眾形象。"},{"en":"A student who deletes messages may be trying to save his name after cheating.","zh":"作弊後刪除訊息的學生可能是在試圖保住名聲。"},{"en":"Kelvin wants to save his name more than he wants to protect the paintings.","zh":"Kelvin 想保住自己的名聲，多於想保護畫作。"},{"en":"This phrase criticises reputation when it becomes more important than truth.","zh":"這個短語批評當名聲變得比真相更重要。"}],"source":"2013 Q9.pdf","sourcePage":5},{"front":"not the art","meaning":"而不是藝術品","examples":[{"en":"Kelvin cared about his reputation, not the art.","zh":"Kelvin 關心的是自己的名聲，而不是藝術品。"},{"en":"Not the art means the artwork was not the real thing he cared about.","zh":"not the art 指藝術品不是他真正關心的東西。"},{"en":"A museum worker should protect the art, not the donor’s pride.","zh":"博物館工作者應保護藝術品，而不是贊助人的面子。"},{"en":"Kelvin says he acted for the museum, but the truth shows he protected himself, not the art.","zh":"Kelvin 說自己是為博物館行動，但真相顯示他保護的是自己，而不是藝術品。"},{"en":"This phrase draws a sharp contrast between duty and selfishness.","zh":"這個短語清楚對比責任與自私。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"by evening","meaning":"到了傍晚","examples":[{"en":"By evening, the harbour lights had returned to the windows.","zh":"到了傍晚，海港燈光已映回窗上。"},{"en":"By evening means when evening arrived, something had already happened or changed.","zh":"by evening 指到傍晚時，某事已經發生或改變。"},{"en":"By evening, the rain had stopped and the streets were dry.","zh":"到了傍晚，雨已停，街道也乾了。"},{"en":"By evening, the museum’s panic had become quiet aftermath.","zh":"到了傍晚，博物館的恐慌已變成安靜的餘波。"},{"en":"This phrase moves the story into a calmer later time.","zh":"這個短語把故事帶到較平靜的稍後時間。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"harbour lights","meaning":"海港燈光","examples":[{"en":"The harbour lights returned to the windows by evening.","zh":"到了傍晚，海港燈光映回窗上。"},{"en":"Harbour lights are lights from buildings, boats, or streets around a harbour.","zh":"harbour lights 指海港周圍建築、船隻或街道的燈光。"},{"en":"Harbour lights can shine on the water after sunset.","zh":"日落後，海港燈光可以照在水面上。"},{"en":"In a city story, harbour lights can make the scene feel beautiful and distant.","zh":"在城市故事中，海港燈光可以令場景感覺美麗而遙遠。"},{"en":"In the story, the harbour lights contrast with the museum’s hidden cracks.","zh":"在故事中，海港燈光與博物館隱藏的裂縫形成對比。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"returned to the windows","meaning":"映回窗上","examples":[{"en":"The harbour lights returned to the windows.","zh":"海港燈光映回窗上。"},{"en":"Returned to the windows means appeared again as reflections or light on the window glass.","zh":"returned to the windows 指燈光再次以倒影或光線形式出現在窗玻璃上。"},{"en":"After sunset, the neon signs returned to the shop windows.","zh":"日落後，霓虹燈映回商店窗上。"},{"en":"Lights returning to windows can show that outside life is continuing.","zh":"燈光映回窗上可以顯示外面的生活仍在繼續。"},{"en":"In the story, this phrase brings ordinary beauty back after the investigation.","zh":"在故事中，這個短語在調查後帶回日常的美。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"masterpieces","meaning":"傑作；名作","examples":[{"en":"The masterpieces were wounded, but not beyond repair.","zh":"那些傑作受創了，但並非無法修復。"},{"en":"Masterpieces are works of art that are considered extremely good or important.","zh":"masterpieces 指被認為極出色或重要的藝術作品。"},{"en":"A museum may protect masterpieces with special lighting, alarms, and careful handling.","zh":"博物館可能用特別燈光、警報和小心處理來保護名作。"},{"en":"When masterpieces are damaged, people feel that culture and memory have also been hurt.","zh":"當傑作受損，人們會覺得文化和記憶也被傷害。"},{"en":"In the story, the masterpieces survive, but their damage reveals human dishonesty.","zh":"在故事中，名作仍能保存，但它們的損傷揭示了人的不誠實。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"wounded","meaning":"受創","examples":[{"en":"The masterpieces were wounded, but not beyond repair.","zh":"那些傑作受創了，但並非無法修復。"},{"en":"Wounded means hurt or damaged, as if the artwork were a living body.","zh":"wounded 指受傷或受損，好像藝術品是有生命的身體。"},{"en":"The old painting looked wounded after smoke darkened its corner.","zh":"煙燻黑一角後，那幅舊畫看起來受創。"},{"en":"Calling artworks wounded makes the damage feel emotional, not only physical.","zh":"把藝術品稱為受創，令損壞感覺不只是物理上的，也有情感上的。"},{"en":"In the story, the word suggests the paintings have been harmed by both accident and lies.","zh":"在故事中，這個詞暗示畫作受到意外和謊言雙重傷害。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"not beyond repair","meaning":"並非無法修復","examples":[{"en":"The paintings were damaged, but not beyond repair.","zh":"那些畫作受損了，但並非無法修復。"},{"en":"Not beyond repair means damaged but still possible to fix.","zh":"not beyond repair 指雖然受損，但仍有可能修好。"},{"en":"The old chair was cracked but not beyond repair.","zh":"那張舊椅子裂了，但並非無法修復。"},{"en":"A damaged painting may be not beyond repair if conservators act carefully.","zh":"如果修復師小心處理，受損畫作可能並非無法修復。"},{"en":"This phrase offers hope after harm.","zh":"這個短語在傷害之後提供希望。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"left in handcuffs","meaning":"戴着手銬離開","examples":[{"en":"Kelvin left in handcuffs.","zh":"Kelvin 戴着手銬離開。"},{"en":"Left in handcuffs means was taken away while wearing metal restraints on the wrists.","zh":"left in handcuffs 指手腕戴着金屬束縛物被帶走。"},{"en":"The suspect left in handcuffs after the police found stolen goods.","zh":"警方找到贓物後，疑犯戴着手銬離開。"},{"en":"Leaving in handcuffs shows that the situation has become a criminal matter.","zh":"戴着手銬離開顯示事情已成為刑事問題。"},{"en":"In the story, Kelvin’s careful plan ends in public disgrace.","zh":"在故事中，Kelvin 仔細的計劃以公開羞辱告終。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"small and ordinary","meaning":"渺小而平凡","examples":[{"en":"Kelvin looked small and ordinary when he left.","zh":"Kelvin 離開時看起來渺小而平凡。"},{"en":"Small and ordinary means not powerful, special, or frightening, but plain and human.","zh":"small and ordinary 指不強大、不特別、不可怕，而是普通而有人性。"},{"en":"The bully looked small and ordinary after the teacher exposed his lies.","zh":"老師揭穿謊言後，那個欺凌者看起來渺小而平凡。"},{"en":"Kelvin no longer looks like a criminal mastermind; he looks weak and ordinary.","zh":"Kelvin 不再像犯罪天才；他看起來軟弱而普通。"},{"en":"This phrase reduces the villain to a frightened person.","zh":"這個短語把反派還原成一個受驚的人。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"in a way that disappointed me","meaning":"以一種令我失望的方式","examples":[{"en":"Kelvin looked ordinary in a way that disappointed me.","zh":"Kelvin 以一種令我失望的方式顯得平凡。"},{"en":"In a way that disappointed me means in a manner that made me feel let down or unsatisfied.","zh":"in a way that disappointed me 指以某種令我失望或不滿足的方式。"},{"en":"The ending was quiet in a way that disappointed me because I expected drama.","zh":"那個結局很安靜，以一種令我失望的方式結束，因為我期待戲劇性。"},{"en":"The narrator expected evil to look grand, but Kelvin’s ordinariness disappoints that expectation.","zh":"敘事者原以為邪惡會很宏大，但 Kelvin 的平凡令這種期待落空。"},{"en":"This phrase shows the speaker’s emotional reaction to reality.","zh":"這個短語顯示說話者對現實的情緒反應。"}],"source":"2013 Q9.pdf","sourcePage":6},{"front":"expected a monster","meaning":"原以為會是個怪物","examples":[{"en":"I had expected a monster.","zh":"我原以為會看見一個怪物。"},{"en":"Expected a monster means thought the guilty person would seem cruel, frightening, or inhuman.","zh":"expected a monster 指以為犯錯者會顯得殘忍、可怕或不像人。"},{"en":"The children expected a monster, but the bully was only a scared boy.","zh":"孩子們原以為會看見怪物，但那個欺凌者只是一個害怕的男孩。"},{"en":"The narrator expects Kelvin to look evil because his actions harmed priceless art.","zh":"敘事者以為 Kelvin 會看起來邪惡，因為他的行為傷害了無價藝術品。"},{"en":"This phrase shows that wrongdoing can come from ordinary fear, not only obvious evil.","zh":"這個短語顯示錯事可以來自普通恐懼，而不只是明顯邪惡。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"instead","meaning":"反而","examples":[{"en":"Instead, I saw a frightened man.","zh":"反而，我看見一個受驚的人。"},{"en":"Instead means in place of what was expected.","zh":"instead 指不是出現預期中的事，而是出現另一件事。"},{"en":"I expected anger; instead, I heard an apology.","zh":"我預期會聽到憤怒；反而，我聽到道歉。"},{"en":"The narrator expects a monster; instead, he sees an ordinary man afraid of losing his name.","zh":"敘事者原以為會看見怪物；反而，他看見一個害怕失去名聲的普通人。"},{"en":"This word marks a sharp contrast between expectation and reality.","zh":"這個詞標示期待和現實之間的強烈對比。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"a frightened man","meaning":"一個受驚的人","examples":[{"en":"I saw a frightened man who had mistaken reputation for truth.","zh":"我看見一個把名聲誤當成真相的受驚的人。"},{"en":"A frightened man is a man who is scared, insecure, or panicking.","zh":"frightened man 指感到害怕、不安或慌亂的男人。"},{"en":"The confident manager became a frightened man when the evidence appeared.","zh":"證據出現時，那個自信經理變成一個受驚的人。"},{"en":"Kelvin is frightening because of what he did, but he himself is also frightened.","zh":"Kelvin 的行為令人害怕，但他自己也是受驚的人。"},{"en":"This phrase makes the guilty person human without excusing him.","zh":"這個短語令犯錯者顯得有人性，但並不替他開脫。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"mistake reputation for truth","meaning":"把名聲誤當成真相","examples":[{"en":"Kelvin had mistaken reputation for truth.","zh":"Kelvin 把名聲誤當成真相。"},{"en":"Mistake reputation for truth means wrongly treat public image as more important or more real than honesty.","zh":"mistake reputation for truth 指錯把公眾形象看得比誠實更重要或更真實。"},{"en":"A school mistakes reputation for truth when it hides bullying to protect its image.","zh":"學校為保護形象而隱瞞欺凌，就是把名聲誤當成真相。"},{"en":"Kelvin protects the museum’s name instead of admitting what really happened.","zh":"Kelvin 保護博物館名聲，而不是承認真正發生的事。"},{"en":"This phrase states the moral failure at the centre of the story.","zh":"這個短語指出故事核心的道德失敗。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"before I went home","meaning":"在我回家之前","examples":[{"en":"Before I went home, Inspector Lam handed me a pair of white gloves.","zh":"在我回家之前，Lam 督察遞給我一雙白手套。"},{"en":"Before I went home means earlier than the moment I left for home.","zh":"before I went home 指在我離開回家之前。"},{"en":"Before I went home, the teacher returned my notebook.","zh":"在我回家之前，老師把筆記本還給我。"},{"en":"This phrase places a meaningful exchange at the end of the day.","zh":"這個短語把一個有意義的交流放在一天結束前。"},{"en":"In the story, the moment before leaving gives the narrator a new sense of purpose.","zh":"在故事中，離開前的一刻給敘事者新的使命感。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"handed me","meaning":"遞給我","examples":[{"en":"Inspector Lam handed me a pair of white gloves.","zh":"Lam 督察遞給我一雙白手套。"},{"en":"Handed me means gave something directly to me by hand.","zh":"handed me 指親手把某物交給我。"},{"en":"The librarian handed me the old book carefully.","zh":"圖書館員小心地把舊書遞給我。"},{"en":"When Lam hands the narrator the gloves, the gesture feels like trust.","zh":"當 Lam 把手套遞給敘事者時，這個動作像是一種信任。"},{"en":"This phrase shows a simple action that carries meaning.","zh":"這個短語顯示一個簡單動作也能承載意義。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"a pair of white gloves","meaning":"一雙白手套","examples":[{"en":"Inspector Lam handed me a pair of white gloves.","zh":"Lam 督察遞給我一雙白手套。"},{"en":"A pair of white gloves means two clean gloves, one for each hand, often used when handling delicate objects.","zh":"a pair of white gloves 指兩隻乾淨白手套，常用於處理脆弱物件。"},{"en":"Museum volunteers wear a pair of white gloves when touching old documents.","zh":"博物館義工觸碰舊文件時會戴一雙白手套。"},{"en":"White gloves suggest care, respect, and responsibility.","zh":"白手套暗示小心、尊重和責任。"},{"en":"In the story, the gloves become a sign that the narrator belongs in the museum world.","zh":"在故事中，手套成為敘事者屬於博物館世界的象徵。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"keep volunteering","meaning":"繼續做義工","examples":[{"en":"Inspector Lam told me to keep volunteering.","zh":"Lam 督察叫我繼續做義工。"},{"en":"Keep volunteering means continue offering help without being paid.","zh":"keep volunteering 指繼續無償提供幫助。"},{"en":"The teacher encouraged students to keep volunteering at the community centre.","zh":"老師鼓勵學生繼續在社區中心做義工。"},{"en":"Lam tells the narrator to keep volunteering because careful attention matters.","zh":"Lam 叫敘事者繼續做義工，因為仔細觀察很重要。"},{"en":"This phrase encourages continued service and growth.","zh":"這個短語鼓勵持續服務和成長。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"people who notice dust","meaning":"會留意塵埃的人","examples":[{"en":"Museums need people who notice dust.","zh":"博物館需要會留意塵埃的人。"},{"en":"People who notice dust are careful observers who see small details others miss.","zh":"people who notice dust 指能看見別人錯過的小細節的細心觀察者。"},{"en":"A person who notices dust may realise an object has been moved recently.","zh":"會留意塵埃的人可能發現某件物品最近被移動過。"},{"en":"Museums need such people because small details can protect art and reveal truth.","zh":"博物館需要這樣的人，因為細節可以保護藝術品並揭示真相。"},{"en":"In the story, noticing dust makes the narrator valuable.","zh":"在故事中，留意塵埃令敘事者變得有價值。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"took them as if","meaning":"像……一樣接過它們","examples":[{"en":"I took the gloves as if they were a badge.","zh":"我像接過徽章一樣接過那雙手套。"},{"en":"Took them as if means accepted them while imagining or treating them like something else.","zh":"took them as if 指接過它們時，把它們想像或看待成另一樣東西。"},{"en":"She took the certificate as if it were proof that she belonged.","zh":"她像接過自己歸屬證明一樣接過證書。"},{"en":"The narrator takes the gloves as if they were a badge because they feel like recognition.","zh":"敘事者像接過徽章一樣接過手套，因為它們像一種認可。"},{"en":"This phrase shows how an ordinary object can become symbolic.","zh":"這個短語顯示普通物件如何變成象徵。"}],"source":"2013 Q9.pdf","sourcePage":7},{"front":"a badge","meaning":"徽章；象徵身份的標誌","examples":[{"en":"I took the white gloves as if they were a badge.","zh":"我像接過徽章一樣接過那雙白手套。"},{"en":"A badge is a small sign, object, or symbol that shows identity, membership, or achievement.","zh":"badge 指顯示身份、成員資格或成就的小標誌、物件或象徵。"},{"en":"A volunteer badge tells visitors whom they can ask for help.","zh":"義工徽章告訴訪客可以向誰求助。"},{"en":"The gloves feel like a badge because they show trust and responsibility.","zh":"手套像徽章，因為它們顯示信任和責任。"},{"en":"In the story, the badge is not metal; it is the right to keep noticing.","zh":"在故事中，徽章不是金屬做的，而是繼續觀察的資格。"}],"source":"2013 Q9.pdf","sourcePage":8},{"front":"the city glittered","meaning":"城市閃閃發亮","examples":[{"en":"Outside, the city glittered.","zh":"外面，城市閃閃發亮。"},{"en":"The city glittered means the city shone with many small bright lights.","zh":"the city glittered 指城市被許多細小亮光照得閃耀。"},{"en":"After rain, the city glittered under street lamps.","zh":"雨後，城市在街燈下閃閃發亮。"},{"en":"A glittering city can look beautiful while still hiding problems inside.","zh":"閃閃發亮的城市可以看起來美麗，同時仍隱藏問題。"},{"en":"In the story, the shining city contrasts with the cracked secrets inside the museum.","zh":"在故事中，閃耀的城市與博物館內裂縫中的秘密形成對比。"}],"source":"2013 Q9.pdf","sourcePage":8},{"front":"flawless","meaning":"完美無瑕的","examples":[{"en":"Outside, the city looked flawless.","zh":"外面，城市看起來完美無瑕。"},{"en":"Flawless means perfect, without visible faults or mistakes.","zh":"flawless 指完美，看不見缺點或錯誤。"},{"en":"The performer gave a flawless speech with no pauses or errors.","zh":"表演者作了一場完美無瑕的演講，沒有停頓或錯誤。"},{"en":"Something may look flawless from far away, but close inspection can reveal cracks.","zh":"某物從遠處看可能完美無瑕，但仔細看會發現裂縫。"},{"en":"In the story, the city looks flawless, but the museum proves appearances can lie.","zh":"在故事中，城市看起來完美無瑕，但博物館證明外表可以說謊。"}],"source":"2013 Q9.pdf","sourcePage":8},{"front":"kept its secrets","meaning":"保守它的秘密","examples":[{"en":"Inside, every masterpiece kept its secrets in the cracks.","zh":"裏面，每件傑作都在裂縫中保守它的秘密。"},{"en":"Kept its secrets means held hidden truths that were not easy to see.","zh":"kept its secrets 指藏着不容易看見的真相。"},{"en":"An old house kept its secrets in locked rooms and faded photographs.","zh":"一間舊屋在上鎖房間和褪色照片中保守它的秘密。"},{"en":"A painting may keep its secrets in tiny marks, repairs, and cracks.","zh":"一幅畫可能在細小痕跡、修復和裂縫中保守它的秘密。"},{"en":"This phrase suggests that careful viewers can discover what surfaces hide.","zh":"這個短語暗示細心觀看者能發現表面隱藏的東西。"}],"source":"2013 Q9.pdf","sourcePage":8},{"front":"in the cracks","meaning":"在裂縫之中","examples":[{"en":"Every masterpiece kept its secrets in the cracks.","zh":"每件傑作都在裂縫之中保守它的秘密。"},{"en":"In the cracks means inside the small breaks, gaps, or damaged lines on a surface.","zh":"in the cracks 指在表面細小破裂、空隙或損壞線條之中。"},{"en":"Dust gathered in the cracks of the old frame.","zh":"塵埃聚集在舊畫框的裂縫之中。"},{"en":"In the cracks of an artwork, conservators may find age, damage, and earlier repairs.","zh":"在藝術品的裂縫之中，修復師可能找到年代、損壞和早期修復痕跡。"},{"en":"In the story, the cracks hold both physical evidence and moral truth.","zh":"在故事中，裂縫之中藏着物理證據，也藏着道德真相。"}],"source":"2013 Q9.pdf","sourcePage":8}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2013_SEED);
